import type { Bilingual } from '../../lib/lesson-types';
import type { MathAssessment, MathAuthorFile, MathExercise, MathLevel, MathRubric, MathSkill, MathTheorem, MathWeek } from '../../lib/math-curriculum-types';

const B = (en: string, vi: string): Bilingual => ({ en, vi });
const wid = (w: number) => `m2-w${String(w).padStart(3, '0')}`;
const tid = (w: number) => `${wid(w)}-t1`;
const eid = (w: number, i: number) => `${wid(w)}-e${i}`;
type RawExercise = { title: Bilingual; skills: MathSkill[]; prompt: Bilingual; hints: Bilingual[]; solution: Bilingual[]; rubric: MathRubric[]; commonErrors: Bilingual[]; remediation?: number[] };
type RawWeek = { week: number; title: Bilingual; level: MathLevel; prerequisites: number[]; outcomes: Bilingual[]; definitions: Bilingual; theoremTitle: Bilingual; statement: Bilingual; proof: Bilingual; proofStatus?: MathTheorem['proofStatus']; sourceId: string; section: string; workedExample: Bilingual; failureCase: Bilingual; exercises: RawExercise[]; topic: string; readingSection: string };
const R = (points: number, en: string, vi: string, critical = false): MathRubric => ({ points, criterion: B(en, vi), ...(critical ? { critical: true } : {}) });
const E = (title: Bilingual, skills: MathSkill[], prompt: Bilingual, hints: Bilingual[], solution: Bilingual[], rubric: MathRubric[], commonErrors: Bilingual[]): RawExercise => ({ title, skills, prompt, hints, solution, rubric, commonErrors });

