function exercise(w: number, i: number, raw: RawExercise): MathExercise {
  return { id: eid(w, i), revision: 1, ...raw, remediation: raw.remediation ?? [Math.max(1, w - 1)] };
}
function makeWeek(raw: RawWeek): MathWeek {
  const theorem: MathTheorem = { id: tid(raw.week), title: raw.theoremTitle, statement: raw.statement, proofStatus: raw.proofStatus ?? 'proved', proof: raw.proof, sourceId: raw.sourceId, sourceSection: raw.section };
  const exercises = raw.exercises.map((e, i) => exercise(raw.week, i + 1, e));
  const sessions = exercises.map((e, i) => ({
    title: B(`Session ${i + 1}: ${e.title.en}`, `Buổi ${i + 1}: ${e.title.vi}`),
    exerciseIds: [e.id], theoremIds: [theorem.id],
    actions: [
      B(`60 min — Reconstruct “${raw.theoremTitle.en}” from its hypotheses; annotate the exact line that uses each hypothesis.`, `60 phút — Tự dựng lại “${raw.theoremTitle.vi}” từ giả thiết; đánh dấu dòng dùng từng giả thiết.`),
      B(`100 min — Solve ${e.title.en} closed-book; write definitions before manipulating the stated objects.`, `100 phút — Giải ${e.title.vi} khi đóng tài liệu; viết định nghĩa trước khi biến đổi các đối tượng đã nêu.`),
      B(`50 min — Test the result against this week's failure case and one changed assumption in ${e.title.en}; identify which implication breaks.`, `50 phút — Đối chiếu kết quả với trường hợp thất bại của tuần và một giả thiết bị đổi trong ${e.title.vi}; chỉ rõ suy luận nào hỏng.`),
      B(`30 min — Redo the key derivation from memory and submit the stated deliverable with a missing-assumption check.`, `30 phút — Viết lại suy dẫn chính từ trí nhớ và nộp sản phẩm đã nêu, kèm kiểm tra giả thiết bị thiếu.`),
    ] as [Bilingual, Bilingual, Bilingual, Bilingual],
    deliverable: B(`A checked solution to ${e.title.en}, plus a two-sentence note naming its decisive assumption.`, `Lời giải đã kiểm tra cho ${e.title.vi}, kèm ghi chú hai câu nêu giả thiết quyết định.`),
  }));
  return {
    week: raw.week, revision: 1, title: raw.title, level: raw.level, prerequisites: raw.prerequisites,
    outcomes: raw.outcomes, definitions: raw.definitions, theorems: [theorem], workedExample: raw.workedExample,
    failureCase: raw.failureCase, exercises, sessions,
    reading: [{ sourceId: raw.sourceId, section: raw.readingSection, purpose: B('Use the named sections as a reference after the self-contained derivation; all scheduled work is stated below.', 'Dùng mục đã ghi làm tài liệu đối chiếu sau phần suy dẫn tự đủ; toàn bộ việc học trong lịch được nêu bên dưới.'), required: false }],
    errorChecklist: [B('State domains, dimensions, regularity and quantifiers before invoking the theorem.', 'Nêu miền, số chiều, tính chính quy và lượng từ trước khi dùng định lý.'), B('Separate a necessary condition from a sufficient one; check equality and boundary cases.', 'Phân biệt điều kiện cần với điều kiện đủ; kiểm tra dấu bằng và trường hợp biên.'), B('Keep statistical assumptions separate from numerical approximations or empirical evidence.', 'Tách giả thiết thống kê khỏi xấp xỉ số hoặc bằng chứng thực nghiệm.')],
    coverage: [{ topic: raw.topic, status: 'taught', evidence: `${theorem.id}: theorem statement and proof; ${exercises.map(x => x.id).join(', ')}: scheduled distinct tasks with worked solutions and pointwise rubrics.` }],
  };
}

const Q = (title: Bilingual, skills: MathSkill[], prompt: Bilingual, hint: Bilingual, solution: Bilingual, r1: Bilingual, r2: Bilingual, r3: Bilingual, error: Bilingual): RawExercise =>
  E(title, skills, prompt, [hint], [solution], [{ points: 1, criterion: r1 }, { points: 2, criterion: r2 }, { points: 1, criterion: r3 }], [error]);

const laterWeeks: RawWeek[] = [
  {
    week: 84, title: B("Dependence gate: HAC and non-IID inference","Cổng phụ thuộc: HAC và suy luận không IID"), level: "graduate core", prerequisites: [73,76,77,78,83],
    outcomes: [B("Derive Bartlett PSD and paired-mean variance.","Suy ra PSD Bartlett và phương sai paired mean."),B("Separate stationary from unit-root inference.","Phân biệt suy luận dừng với unit root.")],
    definitions: B("For centered scores z_t, Γ_h=E[z_tz_{t−h}ᵀ], Ω=Σ_hΓ_h when absolutely summable. Bartlett weights w_h=(1−|h|/(L+1))_+. PSD is algebraic; consistency needs bandwidth and dependence assumptions.","Với score z_t đã trừ mean, Γ_h=E[z_tz_{t−h}ᵀ], Ω=Σ_hΓ_h nếu khả tổng tuyệt đối. Bartlett dùng w_h=(1−|h|/(L+1))_+. PSD là đại số; nhất quán cần giả thiết bandwidth và phụ thuộc."),
    theoremTitle: B("Bartlett lag-window covariance is PSD","Covariance lag-window Bartlett là PSD"),
    statement: B("For every finite vector sequence z_1,…,z_n and L≥0, zero-padded Bartlett lag-window covariance is symmetric PSD. This alone is not a consistency result.","Với mọi dãy vector hữu hạn z_1,…,z_n, L≥0, covariance Bartlett zero-padding đối xứng PSD. Điều này tự nó không chứng minh nhất quán."),
    proof: B("Let b_s=Σ_{j=0}^L z_{s−j}, with z_t=0 outside 1,…,n. Expand [n(L+1)]⁻¹Σ_s b_sb_sᵀ. Each pair z_tz_uᵀ occurs (L+1−|t−u|)_+ times; division by n(L+1) yields the sample autocovariance normalized by n and its Bartlett weight. Each outer product is PSD, so the sum is PSD.","Đặt b_s=Σ_{j=0}^L z_{s−j}, z_t=0 ngoài 1,…,n. Khai triển [n(L+1)]⁻¹Σ_s b_sb_sᵀ. Mỗi z_tz_uᵀ xuất hiện (L+1−|t−u|)_+ lần; chia n(L+1) cho covariance tự mẫu chuẩn hóa theo n và trọng số Bartlett. Mỗi tích ngoài PSD nên tổng PSD."),
    sourceId: "o-neweywest", section: "Theorem 1 (positive semidefiniteness); moving-window proof derived here.",
    workedExample: B("For z=(1,−1,2), L=1, zero-padded adjacent-window sums have a sum of squares, hence a nonnegative quadratic form.","Với z=(1,−1,2), L=1, tổng cửa sổ kề zero-padding cho tổng bình phương, do đó dạng toàn phương không âm."),
    failureCase: B("PSD is not consistency. Fixed bandwidth misses long lags; unit-root levels are not stationary mixing inputs; blocks crossing a break mix regimes. Pairing does not remove serial dependence.","PSD không phải nhất quán. Bandwidth cố định bỏ sót lag xa; mức unit-root không dừng mixing; block qua break trộn chế độ. Ghép cặp không xóa phụ thuộc chuỗi."),
    topic: "dependence gate; HAC; overlap; unit root; breaks", readingSection: "Newey–West Theorem 1; MIT Notes 2–3, 9, 17–19; CMU Ch. 27",
    exercises: [
      Q(B("Overlapping-return covariance","Covariance return chồng lấn"),["computation"],B("For IID ε with variance 1 and R_t=ε_t+ε_{t+1}, find γ(0), γ(1), Ω and n_eff for n=200.","Với ε IID phương sai 1 và R_t=ε_t+ε_{t+1}, tìm γ(0), γ(1), Ω và n_eff khi n=200."),B("Count the shared innovation.","Đếm innovation chung."),B("γ(0)=2, γ(1)=1, higher lags 0; Ω=4, twice marginal variance, so n_eff≈100 under this model.","γ(0)=2, γ(1)=1, lag cao hơn 0; Ω=4, gấp đôi phương sai biên, nên n_eff≈100 theo mô hình này."),B("Computes marginal variance.","Tính phương sai biên."),B("Computes covariance and LRV.","Tính covariance và LRV."),B("Qualifies effective n.","Giới hạn n hiệu dụng."),B("Treats overlap as independence.","Coi chồng lấn là độc lập.")),
      Q(B("Prove Bartlett PSD","Chứng minh Bartlett PSD"),["proof"],B("Use b_s=Σ_{j=0}^L z_{s−j} and zero padding to prove positivity.","Dùng b_s=Σ_{j=0}^L z_{s−j} và zero-padding chứng minh tính dương."),B("Expand outer products and count common windows, keeping the 1/n covariance normalization.","Khai triển tích ngoài và đếm cửa sổ chung, giữ hệ số chuẩn hóa covariance 1/n."),B("The estimator is [n(L+1)]⁻¹Σ_s b_sb_sᵀ. Each pair appears (L+1−|t−u|)_+ times, recovering n⁻¹(1−|t−u|/(L+1))_+. For every a, aᵀb_sb_sᵀa=(aᵀb_s)²≥0; the sum is PSD.","Ước lượng là [n(L+1)]⁻¹Σ_s b_sb_sᵀ. Mỗi cặp xuất hiện (L+1−|t−u|)_+ lần, khôi phục n⁻¹(1−|t−u|/(L+1))_+. Với mọi a, aᵀb_sb_sᵀa=(aᵀb_s)²≥0 nên tổng PSD."),B("Expands windows with the n(L+1) denominator.","Khai triển cửa sổ với mẫu số n(L+1)."),B("Recovers Bartlett weights and sample covariance normalization.","Thu được trọng số Bartlett và chuẩn hóa covariance mẫu."),B("Concludes positivity for every quadratic form.","Kết luận dương với mọi dạng toàn phương."),B("Drops the 1/n factor or confuses PSD with consistency.","Bỏ hệ số 1/n hoặc nhầm PSD với nhất quán.")),
      Q(B("Derive paired-mean variance","Suy phương sai paired mean"),["proof","derivation"],B("For centered weakly stationary d_t derive Var(d̄_n)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ(h) and its LRV limit.","Với d_t dừng yếu đã trừ mean, suy Var(d̄_n)=n⁻¹Σ_{|h|<n}(1−|h|/n)γ(h) và giới hạn LRV."),B("Expand the covariance double sum and count pairs at signed lag h.","Khai triển tổng kép và đếm cặp theo lag h có dấu."),B("Var(d̄_n)=n⁻²Σ_{s,t}γ(s−t), with n−|h| pairs at lag h. Multiply by n; absolute summability and dominated convergence yield nVar→Ω=Σ_hγ(h).","Var(d̄_n)=n⁻²Σ_{s,t}γ(s−t), có n−|h| cặp tại lag h. Nhân n; khả tổng tuyệt đối và hội tụ bị chặn cho nVar→Ω=Σ_hγ(h)."),B("Writes double sum.","Viết tổng kép."),B("Counts lag pairs.","Đếm cặp theo lag."),B("Uses summability for limit.","Dùng khả tổng cho giới hạn."),B("Drops negative lags without accounting for them.","Bỏ lag âm không tính đến.")),
      Q(B("Transfer: bootstrap within regime","Chuyển giao: bootstrap trong chế độ"),["application","transfer"],B("Paired five-day forecast losses overlap and volatility breaks halfway through. Propose a regime-specific resampling plan and scope.","Loss dự báo năm ngày ghép cặp chồng lấn, volatility break giữa mẫu. Đề xuất bootstrap theo chế độ và phạm vi."),B("Keep pairs together and blocks inside one prespecified regime.","Giữ cặp cùng nhau và block trong chế độ định trước."),B("Resample paired loss-difference blocks within a stable regime under stated stationarity, weak-dependence and block-length assumptions; never cross the break. Inference is conditional on that regime, not one law for both.","Lấy block chênh loss paired trong chế độ ổn định với giả thiết dừng, phụ thuộc yếu, độ dài block; không băng break. Suy luận có điều kiện theo chế độ, không phải một luật cho cả hai."),B("Preserves pairing.","Giữ ghép cặp."),B("Respects regime and dependence.","Tôn trọng chế độ và phụ thuộc."),B("Limits estimand.","Giới hạn estimand."),B("Resamples methods separately or crosses break.","Lấy mẫu riêng phương pháp hoặc băng break.")),
      Q(B("Counterexample: random walk defeats stationary CLT","Phản ví dụ: random walk làm sai CLT dừng"),["counterexample","transfer"],B("For x_t=x_{t−1}+ε_t with IID variance σ², explain why stationary LRV CLT fails for levels and give a valid target.","Với x_t=x_{t−1}+ε_t, ε IID phương sai σ², giải thích vì sao CLT LRV dừng sai cho mức và nêu target hợp lệ."),B("Compute Var(x_t), then difference.","Tính Var(x_t), rồi sai phân."),B("x_t=Σ_{j≤t}ε_j gives Var(x_t)=tσ², violating weak stationarity; Δx_t=ε_t is IID and has the usual finite-variance mean CLT.","x_t=Σ_{j≤t}ε_j cho Var(x_t)=tσ², vi phạm dừng yếu; Δx_t=ε_t IID và có CLT mean thông thường nếu phương sai hữu hạn."),B("Writes random-walk representation.","Viết biểu diễn random walk."),B("Shows time-varying variance.","Chỉ ra phương sai đổi theo thời gian."),B("Gives valid differenced target.","Nêu target sai phân hợp lệ."),B("Claims robust SE fixes unit roots automatically.","Cho robust SE tự sửa unit root.")),
    ],
  },
  {
    week: 85, title: B("ERM and finite-class generalization","ERM và tổng quát hóa lớp hữu hạn"), level: "graduate core", prerequisites: [44,58,60,84],
    outcomes: [B("Separate approximation, estimation and optimization errors.","Tách lỗi xấp xỉ, ước lượng, tối ưu."),B("Prove a finite-class Hoeffding bound.","Chứng minh cận Hoeffding lớp hữu hạn.")],
    definitions: B("For IID Z, R(f)=Eℓ(f,Z), R̂=n⁻¹Σℓ(f,Z_i); ERM minimizes R̂ over finite F. Excess risk splits into best-in-class approximation plus estimation; an inexact optimizer adds optimization error.","Với Z IID, R(f)=Eℓ(f,Z), R̂=n⁻¹Σℓ(f,Z_i); ERM tối thiểu R̂ trên F hữu hạn. Excess risk tách xấp xỉ tốt nhất trong lớp và ước lượng; optimizer xấp xỉ thêm lỗi tối ưu."),
    theoremTitle: B("Finite-class ERM bound","Cận ERM lớp hữu hạn"),
    statement: B("If |F|=M, Z_i IID and 0≤ℓ≤1, then P(sup_F|R̂−R|>ε)≤2M exp(−2nε²). With probability 1−δ, ERM excess over best in F is ≤2√(log(2M/δ)/(2n)).","Nếu |F|=M, Z_i IID, 0≤ℓ≤1 thì P(sup_F|R̂−R|>ε)≤2M exp(−2nε²). Với xác suất 1−δ, excess ERM so với tốt nhất F ≤2√(log(2M/δ)/(2n))."),
    proof: B("For each fixed f, two-sided Hoeffding gives 2exp(−2nε²); union over M proves uniform deviation. On that event, R(f̂)≤R̂(f̂)+ε≤R̂(f*_F)+ε≤R(f*_F)+2ε. Set 2Mexp(−2nε²)=δ.","Với f cố định, Hoeffding hai phía cho 2exp(−2nε²); union trên M chứng minh lệch đều. Trên biến cố đó, R(f̂)≤R̂(f̂)+ε≤R̂(f*_F)+ε≤R(f*_F)+2ε. Đặt 2Mexp(−2nε²)=δ."),
    sourceId: "o-cmu705", section: "Lectures 2–5, concentration/generalization; proof derived here.",
    workedExample: B("For M=1000,n=10000,δ=.05, ε≈.0231, hence ERM excess over F≤.0462 with probability .95; approximation error is separate.","Với M=1000,n=10000,δ=.05, ε≈.0231 nên excess ERM so với F≤.0462 xác suất .95; lỗi xấp xỉ là riêng."),
    failureCase: B("Overlapping labels violate IID; replacing n with informal n_eff is not a proof. Small training loss does not bound approximation error.","Nhãn chồng lấn vi phạm IID; thay n bằng n_eff tùy tiện không phải chứng minh. Training loss nhỏ không chặn lỗi xấp xỉ."),
    topic: "ERM; excess risk; finite-class generalization", readingSection: "CMU 36-705 Lectures 2–5",
    exercises: [
      Q(B("Three-term error accounting","Hạch toán lỗi ba hạng"),["computation"],B("R*=.10, best-in-class=.16, ERM=.21, returned iterate=.24. Compute approximation, estimation and optimization gaps.","R*=.10, tốt nhất lớp=.16, ERM=.21, iterate=.24. Tính gap xấp xỉ, ước lượng, tối ưu."),B("Subtract adjacent risks.","Lấy hiệu risk liền kề."),B("Gaps are .06,.05,.03; sum=.14=.24−.10.","Gap .06,.05,.03; tổng=.14=.24−.10."),B("Computes approximation.","Tính xấp xỉ."),B("Computes estimation.","Tính ước lượng."),B("Computes optimization and checks sum.","Tính tối ưu và kiểm tổng."),B("Folds optimization into estimation.","Gộp tối ưu vào ước lượng.")),
      Q(B("Prove finite-class radius","Chứng minh bán kính lớp hữu hạn"),["proof"],B("Derive ε from fixed-f Hoeffding and a union bound.","Suy ε từ Hoeffding f cố định và union bound."),B("Fix f first; then sum failure probabilities.","Cố định f trước rồi cộng xác suất lỗi."),B("Union probability is 2Mexp(−2nε²). Setting it ≤δ yields ε=√(log(2M/δ)/(2n)).","Xác suất union là 2Mexp(−2nε²). Đặt ≤δ được ε=√(log(2M/δ)/(2n))."),B("States fixed-f bound.","Nêu cận f cố định."),B("Uses union bound.","Dùng union bound."),B("Solves ε.","Giải ε."),B("Uses M rather than log M.","Dùng M thay log M.")),
      Q(B("Derive ERM excess inequality","Suy bất đẳng thức excess ERM"),["proof","derivation"],B("On sup_F|R̂−R|≤ε show excess ERM≤2ε.","Trên sup_F|R̂−R|≤ε chứng minh excess ERM≤2ε."),B("Insert empirical risks between population risks.","Chèn empirical risk giữa population risk."),B("R(f̂)≤R̂(f̂)+ε≤R̂(f*_F)+ε≤R(f*_F)+2ε; the middle step is ERM.","R(f̂)≤R̂(f̂)+ε≤R̂(f*_F)+ε≤R(f*_F)+2ε; bước giữa là ERM."),B("Uses first deviation.","Dùng độ lệch đầu."),B("Uses ERM ordering.","Dùng thứ tự ERM."),B("Uses final deviation.","Dùng độ lệch cuối."),B("Assumes empirical and population minimizers coincide.","Giả sử nghiệm empirical/population trùng.")),
      Q(B("Transfer: search multiplicity","Chuyển giao: bội số tìm kiếm"),["application","transfer"],B("Compare model families M=20 and M=2²⁰ at the same n,δ using the leading radius.","So họ mô hình M=20 và M=2²⁰ cùng n,δ theo bán kính chính."),B("Radius scales as √log M.","Bán kính tỷ lệ √log M."),B("Ratio=√(20log2/log20)≈2.07. A uniform guarantee covers all searched models, not just the selected winner.","Tỷ số=√(20log2/log20)≈2.07. Bảo đảm đều bao mọi model đã tìm, không chỉ model thắng."),B("Finds cardinalities.","Tìm lực lượng."),B("Computes ratio.","Tính tỷ số."),B("Explains selection.","Giải thích chọn."),B("Treats winner as prespecified.","Coi winner như định trước.")),
      Q(B("Counterexample: overlapping labels","Phản ví dụ: nhãn chồng lấn"),["counterexample","transfer"],B("For 1000 origins with 20-day overlapping labels explain IID failure and give two valid routes.","Với 1000 origin, nhãn chồng lấn 20 ngày, giải thích IID sai và nêu hai hướng hợp lệ."),B("Adjacent windows share future returns.","Cửa sổ kề chia sẻ return tương lai."),B("Dependence breaks Hoeffding's product argument. Use justified nonoverlap/gaps, or prove a uniform bound for specified mixing data; informal n_eff substitution is insufficient.","Phụ thuộc phá lập luận tích Hoeffding. Dùng không chồng lấn/gap có biện minh hoặc chứng minh cận đều cho dữ liệu mixing cụ thể; thay n_eff tùy tiện chưa đủ."),B("Identifies dependence.","Nhận diện phụ thuộc."),B("Gives two routes.","Nêu hai hướng."),B("Rejects informal substitution.","Bác thay tùy tiện."),B("Claims pairing creates independence.","Cho ghép cặp tạo độc lập.")),
    ],
  },
  {
    week: 86, title: B("Symmetrization and uniform laws","Symmetrization và luật đều"), level: "graduate core", prerequisites: [85],
    outcomes: [B("Prove ghost-sample symmetrization under IID.","Chứng minh symmetrization mẫu phụ dưới IID."),B("Distinguish pointwise from uniform convergence.","Phân biệt hội tụ từng điểm và đều.")],
    definitions: B("For measurable f:Z→[0,1], uniform deviation is E sup_f|P_nf−Pf|. An independent ghost sample and Rademacher signs turn population deviations into empirical fluctuations; supremum measurability/separability is assumed.","Với f:Z→[0,1] đo được, độ lệch đều E sup_f|P_nf−Pf|. Mẫu phụ độc lập và dấu Rademacher biến lệch population thành dao động empirical; giả sử supremum đo được/khả phân."),
    theoremTitle: B("Expected symmetrization inequality","Bất đẳng thức symmetrization kỳ vọng"),
    statement: B("For IID observations and an independent ghost sample, E sup_f|P_nf−Pf|≤E sup_f|P_nf−P′_nf|≤2E sup_f|n⁻¹Σσ_if(Z_i)|.","Với quan sát IID và mẫu phụ độc lập, E sup_f|P_nf−Pf|≤E sup_f|P_nf−P′_nf|≤2E sup_f|n⁻¹Σσ_if(Z_i)|."),
    proof: B("Condition on Z: Pf=E[P′_nf|Z], so Jensen proves the first inequality. Each pair (Z_i,Z′_i) is exchangeable; swapping flips its difference, permitting σ_i. Split into two signed sums; triangle inequality and identical laws give factor 2.","Điều kiện theo Z: Pf=E[P′_nf|Z], Jensen chứng minh bất đẳng thức đầu. Cặp (Z_i,Z′_i) hoán đổi được; đổi chỗ lật hiệu, cho phép σ_i. Tách thành hai tổng có dấu; tam giác và cùng luật cho hệ số 2."),
    sourceId: "o-cmu705", section: "Lectures 4–5 (uniform convergence and symmetrization); proof specialized here.",
    workedExample: B("For a singleton class the inequality holds but may be loose; it becomes useful when class Rademacher complexity is controlled.","Với lớp đơn bất đẳng thức đúng nhưng có thể lỏng; hữu ích khi complexity Rademacher được kiểm soát."),
    failureCase: B("Pointwise convergence need not be uniform over a rich class. Dependence invalidates pairwise IID swapping without a dependence-aware replacement.","Hội tụ từng điểm không nhất thiết đều trên lớp phong phú. Phụ thuộc làm sai hoán đổi cặp IID nếu thiếu thay thế có xét phụ thuộc."),
    topic: "ghost sample; symmetrization; uniform law; IID boundary", readingSection: "CMU 36-705 Lectures 4–5",
    exercises: [
      Q(B("Prove the ghost Jensen step","Chứng minh bước Jensen mẫu phụ"),["proof"],B("Condition on Z and prove the first inequality, stating the measurability condition.","Điều kiện theo Z, chứng minh bất đẳng thức đầu và nêu đo được."),B("Write Pf=E[P′_nf|Z].","Viết Pf=E[P′_nf|Z]."),B("Jensen gives |P_nf−Pf|≤E[|P_nf−P′_nf||Z]. Take supremum and expectation for a measurable/separable class.","Jensen cho |P_nf−Pf|≤E[|P_nf−P′_nf||Z]. Lấy supremum và kỳ vọng với lớp đo được/khả phân."),B("Identifies conditional mean.","Nhận diện mean điều kiện."),B("Applies Jensen.","Áp Jensen."),B("States measurability.","Nêu đo được."),B("Treats ghost data as pointwise equal to its mean.","Coi mẫu phụ bằng mean từng điểm.")),
      Q(B("Derive sign-swapping factor","Suy hệ số hoán đổi dấu"),["proof","derivation"],B("Show pair swaps preserve law and derive the factor 2.","Chỉ ra hoán đổi cặp giữ luật và suy hệ số 2."),B("Swap Z_i with Z′_i independently.","Đổi độc lập Z_i với Z′_i."),B("Exchangeability allows σ_i multiplication. Split signed difference into two sums; triangle inequality and identical laws give two equal suprema.","Hoán đổi được cho phép nhân σ_i. Tách hiệu có dấu thành hai tổng; tam giác và cùng luật cho hai supremum bằng nhau."),B("Uses exchangeability.","Dùng hoán đổi được."),B("Splits terms.","Tách hạng."),B("Obtains 2.","Suy hệ số 2."),B("Uses one global sign for all pairs.","Dùng một dấu chung mọi cặp.")),
      Q(B("Compute a small empirical complexity","Tính complexity empirical nhỏ"),["computation"],B("F contains zero and (1,1,1,1). Compute n⁻¹Eσ sup_fΣσ_if(Z_i).","F gồm zero và (1,1,1,1). Tính n⁻¹Eσ sup_fΣσ_if(Z_i)."),B("The supremum is max(0,Σσ_i).","Supremum max(0,Σσ_i)."),B("For four signs E max(0,Σσ_i)=1 by binomial enumeration; divide by four to get 1/4.","Với bốn dấu kỳ vọng max(0,Σσ_i)=1 theo phân phối nhị thức; chia bốn được 1/4."),B("Writes supremum.","Viết supremum."),B("Computes expectation.","Tính kỳ vọng."),B("Normalizes.","Chuẩn hóa."),B("Adds absolute value to a one-sided definition.","Thêm trị tuyệt đối vào định nghĩa một phía.")),
      Q(B("Transfer: data-selected parameter","Chuyển giao: tham số chọn theo dữ liệu"),["application","transfer"],B("Risk converges for every fixed θ, but learner selects θ from an expanding grid after seeing data. What extra result is needed?","Risk hội tụ với từng θ, nhưng learner chọn θ trên lưới mở rộng sau khi xem dữ liệu. Cần kết quả gì?" ),B("Selection is data dependent.","Lựa chọn phụ thuộc dữ liệu."),B("A uniform law over the search class, or a complexity-controlled sieve with approximation argument, under stated sampling assumptions.","Luật đều trên lớp tìm kiếm hoặc sieve có complexity kiểm soát và lập luận xấp xỉ, theo giả thiết lấy mẫu."),B("Recognizes selection.","Nhận diện chọn."),B("Names uniform/sieve control.","Nêu kiểm soát đều/sieve."),B("States assumptions.","Nêu giả thiết."),B("Assumes pointwise convergence is uniform.","Giả sử hội tụ từng điểm là đều.")),
      Q(B("Counterexample: memorize training labels","Phản ví dụ: ghi nhớ nhãn train"),["counterexample","transfer"],B("With fair IID binary labels construct zero training error but fresh-label error 1/2.","Với nhãn nhị phân IID công bằng, dựng lỗi train 0 nhưng lỗi nhãn mới 1/2."),B("Memorize observed pairs; predict zero elsewhere.","Ghi nhớ cặp quan sát; dự đoán 0 nơi khác."),B("Fit all observed labels and output 0 on unseen inputs. Training error is zero; a fresh independent fair label is wrong with probability 1/2. Uniform capacity control is absent.","Fit mọi nhãn đã thấy và xuất 0 input mới. Lỗi train 0; nhãn công bằng độc lập mới sai xác suất 1/2. Thiếu kiểm soát capacity đều."),B("Defines predictor.","Định nghĩa predictor."),B("Computes fresh error.","Tính lỗi mới."),B("Names missing control.","Nêu kiểm soát thiếu."),B("Infers zero population error from zero training error.","Suy lỗi population 0 từ train 0.")),
    ],
  },
  {
    week: 87, title: B("Rademacher complexity and excess risk","Độ phức tạp Rademacher và excess risk"), level: "graduate core", prerequisites: [85,86],
    outcomes: [B("Bound ERM risk using loss-class complexity.","Chặn risk ERM bằng complexity lớp loss."),B("State the domain and Lipschitz hypotheses for contraction.","Nêu miền và giả thiết Lipschitz của contraction.")],
    definitions: B("For a measurable loss class G={z↦ℓ(f,z)}, define absolute empirical Rademacher complexity R̂_abs(G)=Eσ sup_{g∈G}|n⁻¹Σσ_i g(Z_i)|. Symmetrization controls estimation; contraction additionally needs a Lipschitz loss on the prediction range.","Với lớp loss đo được G={z↦ℓ(f,z)}, định nghĩa độ phức tạp Rademacher thực nghiệm trị tuyệt đối R̂_abs(G)=Eσ sup_{g∈G}|n⁻¹Σσ_i g(Z_i)|. Symmetrization kiểm soát ước lượng; contraction cần loss Lipschitz trên miền dự báo."),
    theoremTitle: B("ERM expectation bound via Rademacher complexity","Cận kỳ vọng ERM qua Rademacher"),
    statement: B("For IID Z_i, measurable F and integrable losses, For IID Z_i and a measurable loss class with finite expected suprema, E[R(f̂)−inf_F R]≤2E sup_F|R̂−R|≤4E R̂_abs(L∘F). No population minimizer need exist: use ε-minimizers and let ε↓0. This is expectation, not a tail guarantee.","Với Z_i IID, F đo được, loss khả tích, Với Z_i IID và lớp loss đo được có kỳ vọng supremum hữu hạn, E[R(f̂)−inf_F R]≤2E sup_F|R̂−R|≤4E R̂_abs(L∘F). Không cần nghiệm population đạt được: dùng ε-minimizer rồi cho ε↓0. Đây là kỳ vọng, không phải cận đuôi."),
    proof: B("For any ε>0 choose f_ε with R(f_ε)≤inf_F R+ε. Add and subtract P_n g_f̂ and P_n g_fε; ERM makes their difference nonpositive, so excess≤2 sup_g|(P_n−P)g|+ε. Let ε↓0. Taking expectations and applying W86 absolute symmetrization gives the factor 4. The displayed bound is in expectation; no tail statement follows without concentration.","Với ε>0 chọn f_ε sao cho R(f_ε)≤inf_F R+ε. Cộng trừ P_n g_f̂ và P_n g_fε; ERM làm hiệu empirical không dương, nên excess≤2 sup_g|(P_n−P)g|+ε. Cho ε↓0. Lấy kỳ vọng và áp symmetrization tuyệt đối W86 được hệ số 4. Đây là cận kỳ vọng; chưa có cận đuôi nếu thiếu concentration."),
    sourceId: "o-cmu705", section: "Lectures 4–5, 9 (Rademacher complexity); derivation supplied here.",
    workedExample: B("For ||w||₂≤B and ||x_i||₂≤R, linear prediction complexity≤BR/√n by Cauchy–Schwarz and the sign second moment. Lipschitz bounded-range loss yields O(BR/√n), plus approximation error.","Với ||w||₂≤B, ||x_i||₂≤R, complexity tuyến tính ≤BR/√n theo Cauchy–Schwarz và moment hai dấu. Loss Lipschitz bị chặn cho O(BR/√n), cộng lỗi xấp xỉ."),
    failureCase: B("Squared loss is not globally Lipschitz for unbounded predictions. State feature bounds or keep the sample-dependent complexity.","Squared loss không Lipschitz toàn cục nếu prediction không chặn. Nêu bound feature hoặc giữ complexity phụ thuộc mẫu."),
    topic: "Rademacher; contraction; approximation and estimation", readingSection: "CMU 36-705 Lectures 4–5, 9",
    exercises: [
      Q(B("Bound linear complexity","Chặn complexity tuyến tính"),["derivation"],B("For ||w||≤3, ||x_i||≤2, n=100 bound Rademacher complexity.","Với ||w||≤3, ||x_i||≤2, n=100 chặn complexity Rademacher."),B("Dual norm bounds the supremum.","Chuẩn đối ngẫu chặn supremum."),B("R̂≤3E||Σσ_ix_i||/100≤3√Σ||x_i||²/100≤.6.","R̂≤3E||Σσ_ix_i||/100≤3√Σ||x_i||²/100≤.6."),B("Uses dual norm.","Dùng chuẩn đối ngẫu."),B("Bounds second moment.","Chặn moment hai."),B("Substitutes constants.","Thế hằng số."),B("Uses n instead of √n.","Dùng n thay √n.")),
      Q(B("Prove ERM decomposition","Chứng minh phân rã ERM"),["proof"],B("Show ERM excess≤2 uniform deviation.","Chứng minh excess ERM≤2 độ lệch đều."),B("Insert empirical risks; middle term≤0.","Chèn empirical risk; hạng giữa≤0."),B("R(f̂)−R(f*)=(R−R̂)(f̂)+(R̂(f̂)−R̂(f*))+(R̂−R)(f*)≤2sup|R̂−R|.","R(f̂)−R(f*)=(R−R̂)(f̂)+(R̂(f̂)−R̂(f*))+(R̂−R)(f*)≤2sup|R̂−R|."),B("Adds terms.","Cộng hạng."),B("Uses ERM.","Dùng ERM."),B("Bounds outer terms.","Chặn hạng ngoài."),B("Reports ε rather than 2ε.","Báo ε thay 2ε.")),
      Q(B("Squared-loss Lipschitz check","Kiểm Lipschitz loss bình phương"),["derivation"],B("For ℓ(u,y)=(u−y)² with |u|≤2,|y|≤1 find a Lipschitz constant in u.","Với ℓ(u,y)=(u−y)², |u|≤2,|y|≤1 tìm hằng số Lipschitz theo u."),B("Bound derivative 2(u−y).","Chặn đạo hàm 2(u−y)."),B("|∂ℓ/∂u|≤6, so mean-value theorem gives 6-Lipschitz on that range; unbounded u has no global constant.","|∂ℓ/∂u|≤6 nên định lý giá trị trung bình cho Lipschitz 6 trên miền; u không chặn không có hằng số toàn cục."),B("Differentiates.","Lấy đạo hàm."),B("Bounds derivative.","Chặn đạo hàm."),B("States domain.","Nêu miền."),B("Calls squared loss globally Lipschitz.","Cho squared loss Lipschitz toàn cục.")),
      Q(B("Transfer: capacity versus approximation","Chuyển giao: capacity và xấp xỉ"),["application","transfer"],B("A richer nested class improves estimation bound. What follows for approximation and total excess?","Lớp lồng phong phú hơn cải thiện cận ước lượng. Suy ra gì về xấp xỉ và excess tổng?" ),B("Complexity controls only estimation.","Complexity chỉ kiểm soát ước lượng."),B("Best approximation in a nested richer class cannot worsen, but fitted variance may increase. Lower total excess requires both terms; no profit claim follows.","Xấp xỉ tốt nhất trong lớp lồng không xấu hơn nhưng variance fit có thể tăng. Excess tổng thấp hơn cần cả hai hạng; không suy lợi nhuận."),B("Identifies controlled term.","Xác định hạng được kiểm soát."),B("Uses nesting.","Dùng tính lồng."),B("Limits conclusion.","Giới hạn kết luận."),B("Equates estimation with total risk.","Đồng nhất ước lượng với risk tổng.")),
      Q(B("Counterexample: one large feature","Phản ví dụ: feature rất lớn"),["counterexample","transfer"],B("Why does BR/√n fail if one ||x_i||=n? Offer a valid repair.","Vì sao BR/√n sai nếu một ||x_i||=n? Đưa cách sửa."),B("Inspect the feature-norm assumption.","Xem giả thiết chuẩn feature."),B("Bound is actually B√Σ||x_i||²/n, and one norm n contributes order B. Assume uniform R, clip with target qualification, or keep the sample-dependent bound.","Cận thật là B√Σ||x_i||²/n; một chuẩn n đóng góp cỡ B. Giả sử R đồng đều, clip và nêu target, hoặc giữ cận phụ thuộc mẫu."),B("Finds missing assumption.","Tìm giả thiết thiếu."),B("Evaluates contribution.","Tính đóng góp."),B("Provides repair.","Đưa cách sửa."),B("Invokes theorem without bounded features.","Dùng định lý khi feature không chặn.")),
    ],
  },
  {
    week: 88, title: B("Regularization and error budgets","Regularization và ngân sách sai số"), level: "graduate core", prerequisites: [66,67,85,87],
    outcomes: [B("Connect convex penalties and constraints through KKT.","Nối penalty và ràng buộc qua KKT."),B("Separate selection, approximation, estimation and optimization errors.","Tách lỗi chọn lựa, xấp xỉ, ước lượng, tối ưu.")],
    definitions: B("Regularized ERM minimizes L_n(w)+λΩ(w). A penalty controls capacity but changes the target. A constraint Ω(w)≤r corresponds to a multiplier only with suitable convexity, Slater and KKT; optimization convergence is separate.","Regularized ERM tối thiểu L_n(w)+λΩ(w). Penalty kiểm soát capacity nhưng đổi target. Ràng buộc Ω(w)≤r tương ứng multiplier chỉ khi có lồi, Slater, KKT phù hợp; hội tụ tối ưu là riêng."),
    theoremTitle: B("KKT stationarity implies penalized optimality","KKT dừng suy ra tối ưu bài toán phạt"),
    statement: B("For convex L,Ω and λ≥0, if 0∈∂L(w*)+λ∂Ω(w*), then w* globally minimizes L+λΩ. Slater supplies KKT necessity for the constrained problem; arbitrary λ need not match a chosen radius.","Với L,Ω lồi, λ≥0, nếu 0∈∂L(w*)+λ∂Ω(w*) thì w* tối thiểu toàn cục L+λΩ. Slater cho KKT cần của bài toán ràng buộc; λ tùy ý không nhất thiết khớp radius chọn."),
    proof: B("Choose g∈∂L(w*),h∈∂Ω(w*) with g+λh=0. Add the two convex support inequalities, multiplying the Ω inequality by λ≥0; the linear terms cancel, proving L(w)+λΩ(w)≥L(w*)+λΩ(w*).","Chọn g∈∂L(w*),h∈∂Ω(w*) sao cho g+λh=0. Cộng hai bất đẳng thức support lồi, nhân bất đẳng thức Ω với λ≥0; hạng tuyến tính triệt tiêu, được L(w)+λΩ(w)≥L(w*)+λΩ(w*)."),
    sourceId: "o-boyd", section: "Ch. 5.5–5.6 (KKT and sensitivity); subgradient result proved here.",
    workedExample: B("Minimize (w−3)² with |w|≤1: w*=1, λ=4 by stationarity, and (w−3)²+4|w| is minimized at 1.","Tối thiểu (w−3)² với |w|≤1: w*=1, λ=4 theo điều kiện dừng; (w−3)²+4|w| đạt min tại 1."),
    failureCase: B("Repeated test-set tuning invalidates final evaluation. Stronger regularization can worsen bias; KKT does not prove stochastic optimizer convergence.","Tune test lặp làm mất hiệu lực đánh giá. Regularization mạnh có thể tăng bias; KKT không chứng minh hội tụ optimizer ngẫu nhiên."),
    topic: "penalized ERM; KKT; error decomposition; selection", readingSection: "Boyd Ch. 5.5–5.6; CMU 36-705 Lectures 30–32",
    exercises: [
      Q(B("Find matching multiplier","Tìm multiplier"),["computation"],B("Minimize (w−4)² subject to w≤2. Find the KKT multiplier λ and explicitly minimize the Lagrangian-penalized function L_λ(w)=(w−4)²+λ(w−2). Verify the minimizer when λ=4.","Tối thiểu (w−4)² với w≤2. Tìm multiplier KKT λ và tối thiểu hóa tường minh hàm Lagrange có phạt L_λ(w)=(w−4)²+λ(w−2). Kiểm tra nghiệm khi λ=4."),B("Use g(w)=w−2≤0, complementary slackness, then differentiate L_λ.","Dùng g(w)=w−2≤0, điều kiện bù rồi lấy đạo hàm L_λ."),B("The constrained minimizer is w*=2. KKT stationarity is 2(w*−4)+λ=0, hence λ=4; λ≥0 and λ(w*−2)=0. For the stated Lagrangian, L′₄(w)=2(w−4)+4=2w−4, so its unique unconstrained minimizer is w=2 (strict convexity follows from L″₄=2). The Lagrangian value there is 4.","Nghiệm ràng buộc là w*=2. Điều kiện dừng KKT 2(w*−4)+λ=0 nên λ=4; λ≥0 và λ(w*−2)=0. Với Lagrange đã nêu, L′₄(w)=2(w−4)+4=2w−4 nên nghiệm tối thiểu không ràng buộc duy nhất là w=2 (lồi nghiêm vì L″₄=2). Giá trị Lagrange tại đó là 4."),B("Finds constrained optimum.","Tìm nghiệm ràng buộc."),B("Solves λ.","Giải λ."),B("Verifies the explicit Lagrangian minimizer and value.","Kiểm nghiệm tường minh nghiệm tối thiểu Lagrange và giá trị."),B("Uses wrong multiplier sign or omits λ(w−2) from the Lagrangian.","Dùng sai dấu multiplier hoặc bỏ λ(w−2) khỏi Lagrange.")),
      Q(B("Prove KKT-to-penalty implication","Chứng minh KKT suy bài phạt"),["proof"],B("From 0∈∂L+λ∂Ω prove global minimization of L+λΩ.","Từ 0∈∂L+λ∂Ω chứng minh tối thiểu toàn cục L+λΩ."),B("Add subgradient support inequalities.","Cộng bất đẳng thức support dưới gradient."),B("Choose g+λh=0; support inequalities add and linear terms vanish, proving the global objective inequality.","Chọn g+λh=0; cộng support, hạng tuyến tính triệt tiêu, được bất đẳng thức mục tiêu toàn cục."),B("Chooses compatible subgradients.","Chọn dưới gradient tương thích."),B("Uses convex support.","Dùng support lồi."),B("Uses λ≥0 and concludes.","Dùng λ≥0 và kết luận."),B("Multiplies by negative λ.","Nhân với λ âm.")),
      Q(B("Decompose inexact risk","Phân rã risk xấp xỉ"),["derivation"],B("Add/subtract best-in-class f*_F and ERM f̂ to split risk of returned iterate.","Cộng/trừ f*_F và ERM f̂ để tách risk iterate trả về."),B("Insert the two intermediate risks.","Chèn hai risk trung gian."),B("R(w̃)−R*=[R(f*_F)−R*]+[R(f̂)−R(f*_F)]+[R(w̃)−R(f̂)]: approximation, estimation, optimization.","R(w̃)−R*=[R(f*_F)−R*]+[R(f̂)−R(f*_F)]+[R(w̃)−R(f̂)]: xấp xỉ, ước lượng, tối ưu."),B("Adds correct risks.","Cộng risk đúng."),B("Names terms.","Gọi tên hạng."),B("Separates optimization.","Tách tối ưu."),B("Counts validation uncertainty as optimization.","Coi bất định validation là tối ưu.")),
      Q(B("Transfer: protect final test","Chuyển giao: bảo vệ test cuối"),["application","transfer"],B("You try 80 λ values and report best test loss. Redesign evaluation.","Bạn thử 80 λ rồi báo test loss thấp nhất. Thiết kế lại đánh giá."),B("Select using training/validation, test once on untouched future data.","Chọn bằng train/validation, test một lần trên dữ liệu tương lai chưa đụng."),B("Freeze all choices then use untouched time-ordered holdout or nested rolling origin. Repeated selection creates winner's curse; serial dependence affects uncertainty.","Đóng băng lựa chọn rồi dùng holdout theo thời gian chưa đụng hoặc rolling origin lồng. Chọn lặp tạo winner's curse; phụ thuộc chuỗi ảnh hưởng bất định."),B("Moves selection off final test.","Chuyển chọn khỏi test."),B("Respects time and freeze.","Tôn trọng thời gian/đóng băng."),B("Names selection effect.","Nêu hiệu ứng chọn."),B("Shuffles overlapping labels to claim IID test.","Xáo nhãn chồng lấn để gọi test IID.")),
      Q(B("Counterexample: penalty raises target risk","Phản ví dụ: penalty tăng risk target"),["counterexample","transfer"],B("For R(w)=(w−10)² and penalty λw² find w_λ and show target risk rises.","Với R(w)=(w−10)², penalty λw², tìm w_λ và cho thấy risk target tăng."),B("Differentiate penalized objective.","Lấy đạo hàm mục tiêu phạt."),B("w_λ=10/(1+λ); target risk=(10λ/(1+λ))², increasing from zero for λ≥0.","w_λ=10/(1+λ); risk target=(10λ/(1+λ))², tăng từ 0 khi λ≥0."),B("Solves optimizer.","Giải nghiệm."),B("Computes target risk.","Tính risk target."),B("Explains bias tradeoff.","Giải thích đánh đổi bias."),B("Reports penalized objective as target risk.","Báo objective phạt như risk target.")),
    ],
  },
  {
    week: 89, title: B("Online convex optimization and static regret","Tối ưu lồi trực tuyến và regret tĩnh"), level: "graduate core", prerequisites: [61,66,68,85],
    outcomes: [B("Prove projected OGD regret against a fixed comparator.","Chứng minh regret projected OGD so comparator cố định."),B("State bounded-gradient assumptions and interpretation limits.","Nêu giả thiết gradient chặn và giới hạn diễn giải.")],
    definitions: B("At round t choose x_t∈K before seeing convex f_t; observe g_t∈∂f_t(x_t), update x_{t+1}=Π_K(x_t−ηg_t). Static regret compares with one fixed u∈K. Assume closed convex K, diameter D and ||g_t||≤G.","Ở vòng t chọn x_t∈K trước khi thấy f_t lồi; quan sát g_t∈∂f_t(x_t), cập nhật x_{t+1}=Π_K(x_t−ηg_t). Regret tĩnh so với u∈K cố định. Giả sử K đóng lồi, đường kính D, ||g_t||≤G."),
    theoremTitle: B("Projected OGD regret","Regret projected OGD"),
    statement: B("For every fixed u∈K, Reg_T(u)≤D²/(2η)+ηG²T/2; η=D/(G√T) yields DG√T.","Với u∈K cố định, Reg_T(u)≤D²/(2η)+ηG²T/2; η=D/(G√T) cho DG√T."),
    proof: B("Projection gives ||x_{t+1}−u||²≤||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||². Convexity gives f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Rearrange, sum, telescope distances and use D,G.","Phép chiếu cho ||x_{t+1}−u||²≤||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||². Lồi cho f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Biến đổi, cộng, triệt khoảng cách và dùng D,G."),
    sourceId: "o-hazan", section: "Second ed. §3.1 (online gradient descent); full telescoping proof here.",
    workedExample: B("For D=2,G=3,T=100, η=1/15 and each bound term is 30, hence regret≤60.","Với D=2,G=3,T=100, η=1/15, mỗi hạng cận là 30 nên regret≤60."),
    failureCase: B("Static regret is not dynamic tracking; unbounded gradients invalidate the bound. Regret does not imply significance or net profit after costs.","Regret tĩnh không phải tracking động; gradient không chặn làm cận sai. Regret không hàm ý ý nghĩa hay lợi nhuận ròng sau phí."),
    topic: "online protocol; static comparator; projected OGD", readingSection: "Hazan Ch. 1–2",
    exercises: [
      Q(B("Compute OGD certificate","Tính chứng chỉ OGD"),["computation"],B("For D=1,G=2,T=25 find η and regret bound.","Với D=1,G=2,T=25 tìm η và cận regret."),B("Balance the two terms.","Cân bằng hai hạng."),B("η=.1; each term is 5, so bound=10=DG√T.","η=.1; mỗi hạng 5, cận=10=DG√T."),B("Finds η.","Tìm η."),B("Computes both terms.","Tính hai hạng."),B("Checks result.","Kiểm kết quả."),B("Forgets square root of T.","Quên căn T.")),
      Q(B("Prove projection inequality","Chứng minh bất đẳng thức chiếu"),["proof"],B("Derive one-step squared distance bound against u∈K.","Suy cận bình phương khoảng cách một bước so u∈K."),B("Use nonexpansiveness and Π_K(u)=u.","Dùng không giãn và Π_K(u)=u."),B("Set a=x_t−ηg_t,b=u and expand: distance≤old distance−2ηg_tᵀ(x_t−u)+η²||g_t||².","Đặt a=x_t−ηg_t,b=u rồi khai triển: khoảng cách≤khoảng cách cũ−2ηg_tᵀ(x_t−u)+η²||g_t||²."),B("Invokes projection property.","Dùng tính chất chiếu."),B("Sets comparator.","Thế comparator."),B("Expands correctly.","Khai triển đúng."),B("Drops the projection.","Bỏ phép chiếu.")),
      Q(B("Complete telescoping proof","Hoàn tất chứng minh telescoping"),["proof","derivation"],B("Combine convexity with one-step inequality and sum over t.","Kết hợp lồi với bất đẳng thức một bước rồi cộng t."),B("Rearrange for g_tᵀ(x_t−u).","Biến đổi theo g_tᵀ(x_t−u)."),B("Loss gap≤(a_t−a_{t+1})/(2η)+ηG²/2. Sum gives D²/(2η)+ηG²T/2.","Gap loss≤(a_t−a_{t+1})/(2η)+ηG²/2. Cộng cho D²/(2η)+ηG²T/2."),B("Rearranges.","Biến đổi."),B("Uses convexity.","Dùng lồi."),B("Telescopes and bounds.","Triệt tiêu và chặn."),B("Leaves intermediate distances.","Để lại khoảng cách trung gian.")),
      Q(B("Transfer: regret is not profit","Chuyển giao: regret không phải lợi nhuận"),["application","transfer"],B("An algorithm has regret 4 versus best fixed weight but negative net return after fees. State valid and invalid claims.","Thuật toán regret 4 so trọng số cố định tốt nhất nhưng return ròng âm sau phí. Nêu claim đúng và sai."),B("Keep loss and economic targets distinct.","Tách target loss và kinh tế."),B("It was within 4 cumulative specified loss of the fixed benchmark; realized net return is negative. Low regret does not prove profit or significance.","Loss tích lũy cách benchmark cố định không quá 4; return ròng âm. Regret thấp không chứng minh lợi nhuận hoặc ý nghĩa."),B("States comparator.","Nêu comparator."),B("Reports return separately.","Báo return riêng."),B("Rejects overclaim.","Bác claim quá mức."),B("Equates regret to p-value.","Đồng nhất regret với p-value.")),
      Q(B("Counterexample: static versus dynamic comparator","Phản ví dụ: comparator tĩnh và động"),["counterexample","transfer"],B("K={−1,1}; losses alternate their preferred sign for even T. Compare a fixed action with changing oracle.","K={−1,1}; loss đổi dấu ưa thích mỗi vòng, T chẵn. So action cố định với oracle thay đổi."),B("Fixed action matches half the rounds; changing path matches all.","Action cố định khớp nửa vòng; đường đổi khớp hết."),B("Fixed action loses T/2 rounds; changing comparator loses zero. Static regret cannot certify tracking the changing path.","Action cố định thua T/2 vòng; comparator đổi thua 0. Regret tĩnh không chứng nhận tracking đường đổi."),B("Computes fixed loss.","Tính loss cố định."),B("Computes changing loss.","Tính loss thay đổi."),B("Distinguishes comparator.","Phân biệt comparator."),B("Calls dynamic tracking static regret.","Gọi tracking là regret tĩnh.")),
    ],
  },
  {
    week: 90, title: B("Strongly convex online losses","Loss online lồi mạnh"), level: "graduate core", prerequisites: [66,89],
    outcomes: [B("Derive logarithmic regret for decreasing OGD steps.","Suy regret logarithmic cho bước OGD giảm."),B("Check curvature and gradient assumptions.","Kiểm giả thiết curvature và gradient.")],
    definitions: B("μ-strong convexity means f_t(u)≥f_t(x)+g_tᵀ(u−x)+(μ/2)||u−x||². Assume projection, μ>0, diameter D, ||g_t||≤G, η_t=1/(μt).","μ-lồi mạnh nghĩa f_t(u)≥f_t(x)+g_tᵀ(u−x)+(μ/2)||u−x||². Giả sử phép chiếu, μ>0, đường kính D, ||g_t||≤G, η_t=1/(μt)."),
    theoremTitle: B("Logarithmic regret under strong convexity","Regret logarithmic dưới lồi mạnh"),
    statement: B("With the assumptions above, any fixed u satisfies Reg_T(u)≤(G²/(2μ))(1+log T)+μD²/2; startup constants depend on indexing.","Với giả thiết trên, mọi u cố định thỏa Reg_T(u)≤(G²/(2μ))(1+log T)+μD²/2; hằng số đầu phụ thuộc chỉ số."),
    proof: B("Strong convexity gives gap≤g_tᵀ(x_t−u)−μa_t/2. Projection gives g_tᵀ(x_t−u)≤μt(a_t−a_{t+1})/2+G²/(2μt), where a_t=||x_t−u||². Summing distance terms leaves a nonpositive endpoint under this indexing; Σ1/t≤1+log T.","Lồi mạnh cho gap≤g_tᵀ(x_t−u)−μa_t/2. Phép chiếu cho g_tᵀ(x_t−u)≤μt(a_t−a_{t+1})/2+G²/(2μt), a_t=||x_t−u||². Cộng hạng khoảng cách còn endpoint không dương theo chỉ số này; Σ1/t≤1+log T."),
    sourceId: "o-hazan", section: "Second ed. §3.3.1 (OGD for strongly convex losses); schedule-specific proof here.",
    workedExample: B("For μ=1,G=2,D=1,T=100 the bound is ≈11.71, while generic DG√T=10 is smaller at this horizon; logarithmic order wins asymptotically.","Với μ=1,G=2,D=1,T=100 cận ≈11.71, cận tổng quát DG√T=10 nhỏ hơn tại horizon này; bậc log thắng tiệm cận."),
    failureCase: B("Without strong convexity the negative distance term vanishes. Unbounded gradients require controlling ΣG_t²/t. Regret is not a test of calibration.","Thiếu lồi mạnh thì mất hạng khoảng cách âm. Gradient không chặn cần kiểm soát ΣG_t²/t. Regret không kiểm định hiệu chỉnh."),
    topic: "strong convexity; decreasing steps; logarithmic regret", readingSection: "Hazan Ch. 2–3",
    exercises: [
      Q(B("Evaluate logarithmic bound","Tính cận logarithmic"),["computation"],B("For μ=2,G=3,D=.5,T=10 compute log bound and DG√T.","Với μ=2,G=3,D=.5,T=10 tính cận log và DG√T."),B("Substitute both formulas.","Thế hai công thức."),B("Log bound≈7.68; generic bound≈4.74, tighter for this finite horizon. Rates compare asymptotically.","Cận log≈7.68; cận tổng quát≈4.74, chặt hơn ở horizon hữu hạn. Rate so tiệm cận."),B("Computes harmonic term.","Tính hạng điều hòa."),B("Includes diameter term.","Gồm hạng đường kính."),B("Interprets horizon.","Diễn giải horizon."),B("Claims log bound is always smaller.","Cho cận log luôn nhỏ hơn.")),
      Q(B("Derive one-step strong bound","Suy cận mạnh một bước"),["proof"],B("Combine strong convexity and projected OGD inequality.","Kết hợp lồi mạnh và bất đẳng thức OGD chiếu."),B("Start from the strong first-order inequality.","Bắt đầu từ bất đẳng thức bậc nhất mạnh."),B("Gap≤g_tᵀ(x_t−u)−μ||x_t−u||²/2; projection bounds inner product by Δ_t/(2η_t)+η_tG²/2.","Gap≤g_tᵀ(x_t−u)−μ||x_t−u||²/2; phép chiếu chặn tích vô hướng bằng Δ_t/(2η_t)+η_tG²/2."),B("Uses correct orientation.","Dùng đúng chiều."),B("Applies projection bound.","Áp cận phép chiếu."),B("Keeps curvature term.","Giữ hạng curvature."),B("Drops negative curvature.","Bỏ curvature âm.")),
      Q(B("Verify common curvature","Kiểm curvature chung"),["derivation","transfer"],B("For f_t(x)=a_tx²/2+b_tx on [−1,1], a_t∈[.5,2], find μ and G if |b_t|≤B.","Với f_t(x)=a_tx²/2+b_tx trên [−1,1], a_t∈[.5,2], tìm μ,G nếu |b_t|≤B."),B("Use second derivative and bound the gradient on K.","Dùng đạo hàm hai và chặn gradient trên K."),B("μ=.5 and |f′|=|a_tx+b_t|≤2+B, so G=2+B.","μ=.5, |f′|=|a_tx+b_t|≤2+B nên G=2+B."),B("Finds minimum curvature.","Tìm curvature nhỏ nhất."),B("Bounds gradient.","Chặn gradient."),B("Makes bounds uniform.","Làm cận đồng đều."),B("Uses maximum curvature as μ.","Dùng curvature lớn nhất làm μ.")),
      Q(B("Transfer: linear losses","Chuyển giao: loss tuyến tính"),["application","transfer"],B("Bounded linear adversarial losses on [−1,1]: can you claim logarithmic strongly-convex regret? Give valid rate.","Loss tuyến tính đối kháng bị chặn trên [−1,1]: claim regret log lồi mạnh được không? Nêu rate hợp lệ."),B("Linear loss has zero curvature.","Loss tuyến tính có curvature 0."),B("No. Bounded domain is not strong convexity. Use W89 with D=2 and bounded G for O(√T) static regret.","Không. Miền bị chặn không phải lồi mạnh. Dùng W89 với D=2, G chặn để có regret tĩnh O(√T)."),B("Finds missing curvature.","Tìm curvature thiếu."),B("Rejects invalid rate.","Bác rate sai."),B("Applies valid theorem.","Áp định lý đúng."),B("Confuses bounded domain and strong convexity.","Nhầm miền bị chặn với lồi mạnh.")),
      Q(B("Counterexample: convex not strongly convex","Phản ví dụ: lồi không mạnh"),["counterexample","proof"],B("Prove f(x)=gx on a nontrivial interval cannot be μ-strongly convex for μ>0.","Chứng minh f(x)=gx trên đoạn không suy biến không μ-lồi mạnh với μ>0."),B("Apply strong convexity to both point orders.","Áp lồi mạnh theo cả hai thứ tự điểm."),B("Adding inequalities for x,u and u,x implies 0≥μ|u−x|², contradiction for x≠u.","Cộng bất đẳng thức cho x,u và u,x suy 0≥μ|u−x|², mâu thuẫn khi x≠u."),B("Writes both inequalities.","Viết hai bất đẳng thức."),B("Adds and cancels linear terms.","Cộng và triệt hạng tuyến tính."),B("States contradiction.","Nêu mâu thuẫn."),B("Uses interval boundedness as curvature.","Dùng tính bị chặn của đoạn làm curvature.")),
    ],
  },
  {
    week: 91, title: B("Dynamic regret and variation budget — elective depth","Dynamic regret và ngân sách biến thiên — chiều sâu tự chọn"), level: "specialization", prerequisites: [89,90],
    outcomes: [B("Derive comparator-path regret with explicit variation.","Suy regret theo đường comparator với variation rõ."),B("Keep static OGD core; mark dynamic regret elective.","Giữ OGD tĩnh lõi; đánh dấu dynamic regret tự chọn.")],
    definitions: B("Dynamic regret compares Σf_t(x_t) to Σf_t(u_t). Path length P_T=Σ_{t≥2}||u_t−u_{t−1}||. This is selected depth/elective replacement, not an added sixth session; core proof remains W89.","Dynamic regret so Σf_t(x_t) với Σf_t(u_t). Path length P_T=Σ_{t≥2}||u_t−u_{t−1}||. Đây là chiều sâu/elective thay thế, không thêm buổi sáu; chứng minh lõi là W89."),
    theoremTitle: B("OGD dynamic regret by path length","Dynamic regret OGD theo path length"),
    statement: B("For comparator path u_1:T⊂K, projected OGD with η, diameter D and ||g_t||≤G satisfies Reg_T≤D²/(2η)+ηG²T/2+DP_T/η.","Với đường comparator u_1:T⊂K, OGD chiếu bước η, đường kính D, ||g_t||≤G thỏa Reg_T≤D²/(2η)+ηG²T/2+DP_T/η."),
    proof: B("Apply the W89 one-step bound against u_t. Distance terms fail to telescope; the mismatch is ||x−u_t||²−||x−u_{t+1}||²=(u_{t+1}−u_t)ᵀ(2x−u_t−u_{t+1}), bounded by 2D||u_{t+1}−u_t||. Divide by 2η and sum to get DP_T/η.","Áp cận W89 so với u_t. Khoảng cách không telescoping; mismatch là ||x−u_t||²−||x−u_{t+1}||²=(u_{t+1}−u_t)ᵀ(2x−u_t−u_{t+1}), bị chặn bởi 2D||u_{t+1}−u_t||. Chia 2η rồi cộng được DP_T/η."),
    sourceId: "o-hazan", section: "Second ed. §10.1 (dynamic regret); the comparator path-length OGD derivation is elective extension proved here.",
    workedExample: B("With D=G=1,T=100,P_T=2,η=.1, static terms total 10 and path term 20, so bound=30.","Với D=G=1,T=100,P_T=2,η=.1, hạng tĩnh tổng 10, hạng path 20, cận=30."),
    failureCase: B("An oracle path may use future regime knowledge. Dynamic regret is not causal performance, significance, calibration or profit; abrupt change raises P_T.","Đường oracle có thể dùng chế độ tương lai. Dynamic regret không phải hiệu năng nhân quả, ý nghĩa, hiệu chỉnh hay lợi nhuận; đổi đột ngột tăng P_T."),
    topic: "elective dynamic comparator; path length; variation budget", readingSection: "Hazan (2023 second ed.) §10.1; selected path-length proof is derived here",
    exercises: [
      Q(B("Compute path variation","Tính variation đường"),["computation"],B("For u=(0,0,1,1,0) in [0,1], find P_T and DP_T/η for D=1,η=.2.","Với u=(0,0,1,1,0) trong [0,1], tìm P_T và DP_T/η khi D=1,η=.2."),B("Count adjacent changes.","Đếm thay đổi kề."),B("Two unit changes give P_T=2 and path penalty=10.","Hai lần đổi đơn vị cho P_T=2, phạt path=10."),B("Counts changes.","Đếm thay đổi."),B("Sums variation.","Cộng variation."),B("Computes penalty.","Tính phạt."),B("Counts rounds rather than changes.","Đếm vòng thay số lần đổi.")),
      Q(B("Derive comparator mismatch","Suy mismatch comparator"),["proof"],B("Factor the mismatch of squared distances when comparator changes.","Phân tích mismatch bình phương khoảng cách khi comparator đổi."),B("Add and subtract u_{t+1}.","Cộng trừ u_{t+1}."),B("Difference factors into (u_{t+1}−u_t)ᵀ(2x−u_t−u_{t+1}), bounded by 2D times movement; summing after division by 2η gives DP_T/η.","Hiệu phân tích thành (u_{t+1}−u_t)ᵀ(2x−u_t−u_{t+1}), chặn bởi 2D nhân chuyển động; cộng sau chia 2η cho DP_T/η."),B("Finds noncancelling term.","Tìm hạng không triệt."),B("Factors difference.","Phân tích hiệu."),B("Bounds and sums.","Chặn và cộng."),B("Claims exact telescoping.","Cho telescoping chính xác.")),
      Q(B("Optimize η with known P","Tối ưu η khi biết P"),["derivation"],B("Minimize D²/(2η)+ηG²T/2+DP/η over η>0.","Tối thiểu D²/(2η)+ηG²T/2+DP/η theo η>0."),B("Combine inverse-η terms then balance.","Gộp hạng nghịch đảo η rồi cân bằng."),B("η*=√(D²+2DP)/(G√T); minimum=G√T√(D²+2DP). This uses known P.","η*=√(D²+2DP)/(G√T); min=G√T√(D²+2DP). Cần biết P."),B("Combines inverse terms.","Gộp hạng nghịch đảo."),B("Balances terms.","Cân bằng."),B("Notes known budget.","Nêu ngân sách đã biết."),B("Uses future P without qualification.","Dùng P tương lai không giới hạn.")),
      Q(B("Transfer: preserve five-session core","Chuyển giao: giữ lõi năm buổi"),["application","transfer"],B("A five-session core already requires static regret. How schedule dynamic regret?","Lõi năm buổi đã cần regret tĩnh. Xếp dynamic regret thế nào?"),B("Keep W89 required; W91 replaces elective depth.","Giữ W89 bắt buộc; W91 thay chiều sâu tự chọn."),B("Mark dynamic regret as selected/elective replacement for regime tracking, never as a sixth session or universal core proof.","Đánh dấu dynamic regret là chiều sâu/elective thay thế cho tracking chế độ, không thêm buổi sáu hay chứng minh lõi phổ quát."),B("Preserves static core.","Giữ lõi tĩnh."),B("Labels elective status.","Đánh dấu tự chọn."),B("Keeps time budget.","Giữ thời lượng."),B("Adds unbudgeted session.","Thêm buổi ngoài lịch.")),
      Q(B("Counterexample: oracle hindsight","Phản ví dụ: hindsight oracle"),["counterexample","transfer"],B("Regime identities are revealed later. Why is a best-future-regime path not a real-time guarantee?","Danh tính chế độ chỉ lộ sau. Vì sao đường chế độ tương lai tốt nhất không bảo đảm thời gian thực?"),B("It uses future losses and break locations.","Nó dùng loss và vị trí break tương lai."),B("A causal decision cannot condition on unseen regimes. A deployable claim needs online change-detection assumptions; comparison regret alone is not performance evidence.","Quyết định nhân quả không thể điều kiện theo chế độ chưa thấy. Claim triển khai cần giả thiết phát hiện đổi online; regret so sánh tự nó không phải bằng chứng hiệu năng."),B("Identifies hindsight.","Nhận diện hindsight."),B("Explains information mismatch.","Giải thích lệch thông tin."),B("Names missing model.","Nêu mô hình thiếu."),B("Calls oracle regret out-of-sample guarantee.","Gọi regret oracle là bảo đảm ngoài mẫu.")),
    ],
  },
  {
    week: 92, title: B("Stochastic bandits and partial feedback","Bandit ngẫu nhiên và phản hồi một phần"), level: "graduate core", prerequisites: [85,89],
    outcomes: [B("Derive pseudo-regret and unbiased importance weighting.","Suy pseudo-regret và importance weighting không chệch."),B("Distinguish expected regret from realized economic return.","Phân biệt regret kỳ vọng với return kinh tế thực.")],
    definitions: B("Arm i yields IID rewards in [0,1] with mean μ_i; choose A_t and observe only its reward. Pseudo-regret is Σ_i(μ*−μ_i)E N_i(T); realized regret is random and compares reward paths.","Arm i cho reward IID trong [0,1], mean μ_i; chọn A_t và chỉ thấy reward được chọn. Pseudo-regret Σ_i(μ*−μ_i)E N_i(T); realized regret ngẫu nhiên và so đường reward."),
    theoremTitle: B("Importance-weighted reward is unbiased","Reward importance-weighted không chệch"),
    statement: B("If arm i is chosen with probability p_i>0, r̂_i=1{A=i}Y_i/p_i has conditional expectation μ_i.","Nếu chọn arm i xác suất p_i>0, r̂_i=1{A=i}Y_i/p_i có kỳ vọng điều kiện μ_i."),
    proof: B("Given history, selection indicator has mean p_i and selected reward mean μ_i, so E[1{A=i}Y_i/p_i]=p_iμ_i/p_i=μ_i. Small p_i can still cause high variance.","Cho lịch sử, indicator có mean p_i, reward chọn có mean μ_i, nên E[1{A=i}Y_i/p_i]=p_iμ_i/p_i=μ_i. p_i nhỏ vẫn gây phương sai cao."),
    sourceId: "o-bandit", section: "Ch. 1.1 (protocol), §§4.1–4.5 (model/regret), §11.2 (importance-weighted estimators); the identity is derived here.",
    workedExample: B("For μ_2=.5 and p_2=.2, estimate is 5Y_2 when selected, zero otherwise; expectation remains .5.","Với μ_2=.5,p_2=.2, estimate là 5Y_2 khi chọn, nếu không bằng 0; kỳ vọng vẫn .5."),
    failureCase: B("Unbiasedness does not imply low variance. Pseudo-regret is not realized profit; drift and delayed feedback violate the stationary protocol.","Không chệch không có nghĩa phương sai thấp. Pseudo-regret không phải lợi nhuận thực; drift và feedback trễ vi phạm protocol dừng."),
    topic: "stochastic bandit; partial feedback; pseudo-regret", readingSection: "Lattimore–Szepesvári Ch. 1–2",
    exercises: [
      Q(B("Compute pseudo-regret","Tính pseudo-regret"),["computation"],B("Means (.8,.6,.3), pulls (10,20,5). Compute regret.","Mean (.8,.6,.3), lượt (10,20,5). Tính regret."),B("Weight each suboptimal pull by its gap.","Nhân lượt arm kém với gap."),B("20(.2)+5(.5)=6.5.","20(.2)+5(.5)=6.5."),B("Finds best mean.","Tìm mean tốt nhất."),B("Computes gaps.","Tính gap."),B("Sums weighted pulls.","Cộng lượt có trọng số."),B("Counts all pulls as regret.","Tính mọi lượt là regret.")),
      Q(B("Prove unbiased estimate","Chứng minh ước lượng không chệch"),["proof"],B("Condition on history and prove E[1{A=i}Y_i/p_i]=μ_i.","Điều kiện theo lịch sử, chứng minh E[1{A=i}Y_i/p_i]=μ_i."),B("Separate choice probability and reward mean.","Tách xác suất chọn và mean reward."),B("The numerator has expectation p_iμ_i; divide by p_i>0 to obtain μ_i.","Tử có kỳ vọng p_iμ_i; chia p_i>0 được μ_i."),B("Conditions correctly.","Điều kiện đúng."),B("Uses selection propensity.","Dùng propensity."),B("Divides correctly.","Chia đúng."),B("Omits inverse propensity.","Bỏ inverse propensity.")),
      Q(B("Derive pseudo-regret identity","Suy đồng nhất thức pseudo-regret"),["derivation"],B("Show Tμ*−EΣμ_{A_t}=Σ_iΔ_iE N_i(T).","Chứng minh Tμ*−EΣμ_{A_t}=Σ_iΔ_iE N_i(T)."),B("Group rounds by arm.","Gom vòng theo arm."),B("Rewrite each round as μ*−μ_{A_t}; grouping gives Σ_i(μ*−μ_i)E N_i.","Viết mỗi vòng μ*−μ_{A_t}; gom được Σ_i(μ*−μ_i)E N_i."),B("Rewrites total.","Viết lại tổng."),B("Groups by arm.","Gom arm."),B("Defines gaps.","Định nghĩa gap."),B("Uses realized reward in mean identity.","Dùng reward thực trong đồng nhất thức mean.")),
      Q(B("Transfer: regret versus profit","Chuyển giao: regret và lợi nhuận"),["application","transfer"],B("Low pseudo-regret under stationary expected returns, but net loss after fees. State conclusion and missing model.","Pseudo-regret thấp theo return kỳ vọng dừng nhưng lỗ ròng sau phí. Nêu kết luận và mô hình thiếu."),B("Regret omits costs and realized uncertainty.","Regret bỏ phí và bất định thực."),B("The policy nears best fixed arm under the mean model; profitability needs timing, costs, constraints, risk and return uncertainty.","Policy gần arm cố định tốt nhất theo mean model; lợi nhuận cần thời điểm, phí, ràng buộc, rủi ro, bất định return."),B("States benchmark.","Nêu benchmark."),B("Separates economic costs.","Tách chi phí."),B("Limits conclusion.","Giới hạn kết luận."),B("Calls pseudo-regret net profit.","Gọi pseudo-regret là profit ròng.")),
      Q(B("Counterexample: selected rewards are not pooled IID","Phản ví dụ: reward chọn không phải mẫu IID gộp"),["counterexample","transfer"],B("Why can pooling observed rewards across adaptively selected arms bias arm comparisons?","Vì sao gộp reward quan sát qua arm chọn thích nghi gây chệch so sánh?" ),B("Selection depends on history and arm counts differ.","Lựa chọn phụ thuộc lịch sử, số lượt arm khác nhau."),B("Observed arm/context mixture is policy-selected, not a common IID sample. Use arm-specific conditional estimates or propensity correction with positivity.","Hỗn hợp arm/context quan sát do policy chọn, không phải mẫu IID chung. Dùng estimate điều kiện theo arm hoặc hiệu chỉnh propensity có positivity."),B("Identifies adaptive selection.","Nhận diện chọn thích nghi."),B("Explains mixture bias.","Giải thích chệch hỗn hợp."),B("Gives valid correction.","Đưa sửa hợp lệ."),B("Treats observed data as IID across arms.","Coi dữ liệu quan sát IID qua arm.")),
    ],
  },
  {
    week: 93, title: B("UCB and concentration-based exploration","UCB và khám phá dựa trên nồng độ"), level: "graduate core", prerequisites: [44,92],
    outcomes: [B("Derive Hoeffding confidence radii and UCB pull logic.","Suy bán kính Hoeffding và logic lượt UCB."),B("State simultaneous-coverage and stationarity assumptions.","Nêu coverage đồng thời và giả thiết dừng.")],
    definitions: B("UCB_i=μ̂_i+√(2log t/N_i). Hoeffding gives fixed-n confidence; adaptive use over arm-time pairs needs a union bound or time-uniform theorem.","UCB_i=μ̂_i+√(2log t/N_i). Hoeffding cho confidence n cố định; dùng thích nghi qua arm-time cần union bound hoặc định lý time-uniform."),
    theoremTitle: B("Two-sided Hoeffding confidence","Confidence Hoeffding hai phía"),
    statement: B("For IID X_j∈[0,1] with mean μ, P(|X̄_n−μ|≥r)≤2exp(−2nr²); r=√(log(2/δ)/(2n)) gives fixed-n coverage 1−δ.","Với X_j∈[0,1] IID mean μ, P(|X̄_n−μ|≥r)≤2exp(−2nr²); r=√(log(2/δ)/(2n)) cho coverage 1−δ tại n cố định."),
    proof: B("Hoeffding bounds each tail by exp(−2nr²); union of upper and lower tails yields the factor 2. Adaptive arm/time use needs simultaneous control beyond this pointwise statement.","Hoeffding chặn mỗi đuôi bằng exp(−2nr²); union hai đuôi cho hệ số 2. Dùng arm/time thích nghi cần kiểm soát đồng thời thêm."),
    sourceId: "o-bandit", section: "§5.3 (subgaussian concentration), §7.1 (UCB optimism), §4.4 (regret); fixed-time proof here.",
    workedExample: B("At n=50,δ=.05, radius √(log40/100)≈.192; repeated looks need multiplicity adjustment.","Với n=50,δ=.05, bán kính √(log40/100)≈.192; xem lặp cần điều chỉnh bội số."),
    failureCase: B("Repeatedly checking a fixed-n interval does not preserve coverage. Stationary UCB also fails under arbitrary drift or delay without a new model.","Xem lặp khoảng fixed-n không giữ coverage. UCB dừng cũng sai với drift/trễ tùy ý nếu không có mô hình mới."),
    topic: "Hoeffding; UCB; adaptive confidence; stochastic regret", readingSection: "Lattimore–Szepesvári Ch. 2, 6–7",
    exercises: [
      Q(B("Compute UCB indices","Tính chỉ số UCB"),["computation"],B("At t=100: arm A mean .55,n=25; B mean .50,n=4. Compute indices μ̂+√(2log(t)/n).","Ở t=100: A mean .55,n=25; B mean .50,n=4. Tính chỉ số μ̂+√(2log(t)/n)."),B("Small n gives a larger bonus.","n nhỏ cho bonus lớn."),B("A bonus≈.607, index≈1.157; B bonus≈1.517,index≈2.017, so B is selected despite lower empirical mean.","A bonus≈.607,index≈1.157; B bonus≈1.517,index≈2.017 nên chọn B dù mean thấp."),B("Computes A bonus.","Tính bonus A."),B("Computes B bonus.","Tính bonus B."),B("Compares indices.","So chỉ số."),B("Uses wrong logarithm base.","Dùng sai cơ số log.")),
      Q(B("Prove two-sided radius","Chứng minh bán kính hai phía"),["proof"],B("Derive Hoeffding's two-sided bound and solve for δ.","Suy bound Hoeffding hai phía và giải theo δ."),B("Bound tails separately.","Chặn riêng hai đuôi."),B("Each tail≤e^(−2nr²), so total≤2e^(−2nr²); solve to get r=√(log(2/δ)/(2n)).","Mỗi đuôi≤e^(−2nr²), tổng≤2e^(−2nr²); giải ra r=√(log(2/δ)/(2n))."),B("Upper tail.","Đuôi trên."),B("Lower tail and union.","Đuôi dưới và union."),B("Solves radius.","Giải bán kính."),B("Omits factor two.","Bỏ hệ số hai.")),
      Q(B("Derive UCB gap implication","Suy hệ quả gap UCB"),["proof","derivation"],B("If UCB selects i over best j on simultaneous coverage, show Δ_i≤2r_i.","Nếu UCB chọn i thay j tốt nhất trên coverage đồng thời, chứng minh Δ_i≤2r_i."),B("Use μ_j≤LCB_j≤UCB_i≤μ_i+2r_i.","Dùng μ_j≤LCB_j≤UCB_i≤μ_i+2r_i."),B("Index ordering gives UCB_i≥LCB_j; valid intervals imply μ_j≤LCB_j and UCB_i≤μ_i+2r_i. Rearrange.","Thứ tự index cho UCB_i≥LCB_j; khoảng hợp lệ cho μ_j≤LCB_j và UCB_i≤μ_i+2r_i. Biến đổi."),B("Uses choice ordering.","Dùng thứ tự chọn."),B("Uses confidence bounds.","Dùng bound confidence."),B("Rearranges gap.","Biến đổi gap."),B("Uses upper bound for best arm.","Dùng cận trên arm tốt nhất.")),
      Q(B("Transfer: simultaneous looks","Chuyển giao: xem đồng thời"),["application","transfer"],B("You inspect 10 arms over 100 rounds and report the smallest fixed-time p-value. What problem and remedy?","Bạn xem 10 arm qua 100 vòng rồi báo p-value fixed-time nhỏ nhất. Vấn đề và cách sửa?" ),B("There are many arm-time looks.","Có nhiều lần xem arm-time."),B("Selection inflates false positives. Use simultaneous confidence/union adjustment, alpha spending, or a time-uniform method with assumptions.","Chọn làm tăng false positive. Dùng confidence đồng thời/union, alpha spending hoặc phương pháp time-uniform có giả thiết."),B("Counts looks.","Đếm lượt xem."),B("Identifies multiplicity.","Nhận diện bội số."),B("Gives valid remedy.","Đưa sửa hợp lệ."),B("Calls nominal 5% familywise 5%.","Coi 5% danh nghĩa là familywise 5%.") ),
      Q(B("Counterexample: drift breaks cumulative UCB","Phản ví dụ: drift làm hỏng UCB tích lũy"),["counterexample","transfer"],B("An arm becomes inferior after a regime switch. Why can ordinary UCB stay overconfident?","Arm thành kém sau đổi chế độ. Vì sao UCB thường quá tự tin?" ),B("Old rewards dominate cumulative mean; count grows and bonus shrinks.","Reward cũ lấn mean; count tăng làm bonus giảm."),B("Stationarity fails: estimate is stale and its confidence radius shrinks around the wrong fixed-mean target. Use a nonstationary method with explicit change/variation assumptions.","Dừng thất bại: estimate cũ và radius co quanh target mean cố định sai. Dùng phương pháp không dừng với giả thiết change/variation rõ."),B("Names stationarity failure.","Nêu dừng sai."),B("Explains stale mean and shrinking bonus.","Giải thích mean cũ và bonus giảm."),B("States assumption-aware alternative.","Nêu phương án có giả thiết."),B("Claims Hoeffding handles arbitrary drift.","Cho Hoeffding xử lý drift.") ),
    ],
  },
  {
    week: 94, title: B("Beta–Bernoulli posterior and Thompson sampling","Hậu nghiệm Beta–Bernoulli và Thompson sampling"), level: "graduate core", prerequisites: [92,93],
    outcomes: [B("Derive conjugate posterior and predictive mean.","Suy posterior liên hợp và mean dự báo."),B("Describe TS and label its regret theorem as assumed.","Mô tả TS và đánh dấu theorem regret là giả định.")],
    definitions: B("With Bernoulli mean θ and Beta(α,β) prior, s successes and f failures update the posterior. Thompson sampling draws θ̃_i from each arm posterior and chooses the maximum; only chosen-arm feedback updates. This protocol is not a regret proof.","Với mean Bernoulli θ và prior Beta(α,β), s thắng, f thua cập nhật posterior. Thompson sampling lấy θ̃_i từ posterior mỗi arm rồi chọn lớn nhất; chỉ feedback arm chọn cập nhật. Protocol không phải chứng minh regret."),
    theoremTitle: B("Beta–Bernoulli conjugacy","Liên hợp Beta–Bernoulli"),
    statement: B("After s successes and f failures, Beta(α,β) prior becomes Beta(α+s,β+f), predictive mean (α+s)/(α+β+s+f).","Sau s thắng, f thua, prior Beta(α,β) thành Beta(α+s,β+f), mean dự báo (α+s)/(α+β+s+f)."),
    proof: B("Bernoulli likelihood θ^s(1−θ)^f times prior kernel θ^(α−1)(1−θ)^(β−1) gives the Beta(α+s,β+f) kernel. Its mean is first shape over total shape.","Likelihood θ^s(1−θ)^f nhân kernel prior θ^(α−1)(1−θ)^(β−1) cho kernel Beta(α+s,β+f). Mean là shape đầu trên tổng shape."),
    sourceId: "o-bandit", section: "§34.3 (conjugate priors), §§34.4–34.6 (Bayesian bandit/regret), §36.1 (finite-armed Thompson); TS regret cited as black box.",
    workedExample: B("Beta(1,1) after seven successes and three failures becomes Beta(8,4), predictive mean 2/3.","Beta(1,1) sau bảy thắng, ba thua thành Beta(8,4), mean dự báo 2/3."),
    failureCase: B("Stationarity and correct reveal timing are required; delayed or shifted outcomes need new likelihood handling. TS regret is not proved here.","Cần dừng và đúng thời điểm lộ; outcome trễ/đổi chế độ cần likelihood mới. Regret TS không được chứng minh ở đây."),
    topic: "Beta-Bernoulli; Thompson sampling; partial feedback", readingSection: "Lattimore–Szepesvári Ch. 34, 36",
    exercises: [
      Q(B("Update posterior","Cập nhật posterior"),["computation"],B("Prior Beta(2,3), six successes, four failures. Find posterior and mean.","Prior Beta(2,3), sáu thắng, bốn thua. Tìm posterior và mean."),B("Add successes to α, failures to β.","Cộng thắng vào α, thua vào β."),B("Posterior Beta(8,7), mean 8/15.","Posterior Beta(8,7), mean 8/15."),B("Updates α.","Cập nhật α."),B("Updates β.","Cập nhật β."),B("Computes mean.","Tính mean."),B("Swaps success and failure counts.","Đổi số thắng và thua.") ),
      Q(B("Prove conjugacy","Chứng minh liên hợp"),["proof"],B("Multiply prior and likelihood to identify posterior.","Nhân prior và likelihood nhận diện posterior."),B("Collect powers of θ and 1−θ.","Gom lũy thừa θ và 1−θ."),B("Kernel is θ^(α+s−1)(1−θ)^(β+f−1), hence Beta(α+s,β+f).","Kernel θ^(α+s−1)(1−θ)^(β+f−1), suy Beta(α+s,β+f)."),B("Writes likelihood.","Viết likelihood."),B("Adds exponents.","Cộng số mũ."),B("Identifies posterior.","Nhận diện posterior."),B("Adds failures to α.","Cộng thua vào α.") ),
      Q(B("Derive TS action probability","Suy xác suất action TS"),["derivation"],B("For independent draws θ̃_1,θ̃_2 express P(arm 1 chosen).","Với draw θ̃_1,θ̃_2 độc lập viết P(chọn arm 1)."),B("Condition on θ̃_1.","Điều kiện theo θ̃_1."),B("P(A=1)=P(θ̃_1≥θ̃_2)=∫F_2(x)dF_1(x), with a tie convention.","P(A=1)=P(θ̃_1≥θ̃_2)=∫F_2(x)dF_1(x), có quy ước hòa."),B("Defines comparison.","Định nghĩa so sánh."),B("Uses independence.","Dùng độc lập."),B("States tie handling.","Nêu xử lý hòa."),B("Chooses largest posterior mean instead of posterior draw.","Chọn mean posterior lớn thay vì draw.") ),
      Q(B("Transfer: delayed reward","Chuyển giao: reward trễ"),["application","transfer"],B("A chosen reward arrives three rounds later. How update and what assumption changed?","Reward chọn về sau ba vòng. Cập nhật thế nào, giả thiết nào đổi?" ),B("Track pending assignment; update only when revealed.","Theo dõi arm pending; chỉ cập nhật khi lộ."),B("Apply one Bernoulli likelihood update on reveal; decisions before then use revealed-data posterior only. Immediate-feedback regret theorem no longer directly applies.","Khi lộ áp một likelihood Bernoulli; trước đó quyết định chỉ dùng posterior dữ liệu đã lộ. Định lý feedback tức thời không còn áp trực tiếp."),B("Tracks chosen arm.","Theo dõi arm."),B("Updates at reveal.","Cập nhật khi lộ."),B("Identifies changed protocol.","Nêu protocol đổi."),B("Updates before observing reward.","Cập nhật trước khi thấy reward.") ),
      Q(B("Counterexample: concentrated prior sensitivity","Phản ví dụ: prior tập trung nhạy"),["counterexample","transfer"],B("Arms have Beta(100,1) and Beta(1,100) priors and one observation each. Explain early TS allocations.","Arm có prior Beta(100,1), Beta(1,100), mỗi arm một quan sát. Giải thích phân bổ TS ban đầu."),B("One count is small relative to prior concentration.","Một count nhỏ so với prior tập trung."),B("Posterior draws remain separated; early allocation is prior-dominated. Justify priors and run sensitivity analysis before interpreting behavior.","Posterior draw vẫn cách xa; phân bổ đầu bị prior chi phối. Biện minh prior và phân tích độ nhạy trước khi diễn giải."),B("Compares data count to prior strength.","So số đếm với prior."),B("Explains posterior persistence.","Giải thích posterior còn bền."),B("Names sensitivity analysis.","Nêu phân tích độ nhạy."),B("Claims one observation dominates concentrated prior.","Cho một quan sát lấn prior.") ),
    ],
  },
  {
    week: 95, title: B("Bandit delay and changing means","Bandit trễ và mean thay đổi"), level: "graduate core", prerequisites: [92,93,94],
    outcomes: [B("Bound pending feedback and state limits of that count.","Chặn feedback pending và nêu giới hạn."),B("Define a variation target for changing means.","Định nghĩa target variation cho mean đổi.")],
    definitions: B("Maximum feedback delay d means at most d chosen rewards await observation at a time. Nonstationary arms have μ_{i,t}; variation V_T=Σ_{t<T}max_i|μ_{i,t+1}−μ_{i,t}|. A confidence interval for one fixed μ_i does not cover arbitrary drift.","Delay tối đa d nghĩa tối đa d reward đã chọn đang chờ quan sát. Arm phi dừng có μ_{i,t}; variation V_T=Σ_{t<T}max_i|μ_{i,t+1}−μ_{i,t}|. Khoảng quanh μ_i cố định không bao drift tùy ý."),
    theoremTitle: B("At most d outcomes are pending","Tối đa d outcome đang pending"),
    statement: B("With deterministic feedback delay at most d≥1, one action per round, and losses in [0,1], at any decision cutoff no more than d chosen outcomes are pending. Replacing their unrevealed loss entries by any provisional values in [0,1] changes the cumulative loss ledger by at most d in absolute value. This bookkeeping bound is not a regret guarantee.","Với độ trễ feedback xác định tối đa d≥1, một hành động mỗi vòng, loss thuộc [0,1], tại mọi mốc quyết định có tối đa d outcome đã chọn nhưng chưa lộ. Thay loss chưa lộ bằng giá trị tạm bất kỳ trong [0,1] làm sổ loss tích lũy đổi không quá d theo trị tuyệt đối. Cận hạch toán này không phải bảo đảm regret."),
    proof: B("At cutoff t, an action chosen at round s≤t−d has a reveal time no later than s+d≤t, so any still-pending action must have origin among the latest d rounds; there is at most one action per such round, giving count≤d. If provisional loss a_s and eventual loss ℓ_s both lie in [0,1], then |a_s−ℓ_s|≤1 for every pending s. Summing over at most d pending indices gives absolute ledger error≤d. Neither counting argument constrains how poor the learner's chosen arms are, so it proves no regret rate.","Tại mốc t, hành động ở vòng s≤t−d được lộ không muộn hơn s+d≤t; do đó hành động còn pending chỉ có thể phát sinh trong d vòng gần nhất. Mỗi vòng tối đa một hành động nên số lượng≤d. Nếu loss tạm a_s và loss thật ℓ_s đều thuộc [0,1], thì |a_s−ℓ_s|≤1 với mỗi s pending. Cộng tối đa d chỉ số cho sai số sổ tuyệt đối≤d. Phép đếm không giới hạn arm learner đã chọn tệ đến đâu, nên không chứng minh rate regret."),
    sourceId: "o-bandit", section: "§31.2 (stochastic non-stationary bandits) for setting context; bounded-delay counting argument derived here.",
    workedExample: B("At cutoff t=10 with d=3, actions from rounds 8, 9, 10 may still be pending, while action 7 must have arrived by t=10. Three provisional losses each differ from their eventual [0,1] values by at most one, so the current ledger error is at most 3; no arm-regret claim follows.","Tại mốc t=10 với d=3, hành động vòng 8,9,10 có thể còn pending, còn hành động vòng 7 phải được lộ trước hoặc tại 10. Ba loss tạm mỗi cái lệch loss thật [0,1] tối đa một, nên sai số sổ hiện tại tối đa 3; không suy ra regret arm."),
    failureCase: B("A pending-count bound does not make stale actions harmless. Arbitrary drift invalidates stationary UCB; any window/change method needs explicit variation or switching assumptions and a separate regret proof.","Cận số pending không khiến hành động dùng thông tin cũ trở nên vô hại. Drift tùy ý làm sai UCB dừng; mọi phương pháp cửa sổ/phát hiện đổi cần giả thiết variation/switching rõ và chứng minh regret riêng."),
    topic: "delayed feedback; nonstationarity; variation budget", readingSection: "Lattimore–Szepesvári §31.2; bounded-delay counting argument derived here",
    exercises: [
      Q(B("Count pending outcomes","Đếm outcome pending"),["computation"],B("For d=4, one action per round, find maximum pending outcomes and direct discrepancy for unit-range losses.","Với d=4, mỗi vòng một action, tìm số pending tối đa và sai khác trực tiếp với loss range 1."),B("Count recent four rounds.","Đếm bốn vòng gần."),B("At most four outcomes and discrepancy at most four per batch.","Tối đa bốn outcome, sai khác tối đa bốn mỗi batch."),B("Counts rounds.","Đếm vòng."),B("Applies delay.","Áp delay."),B("Uses loss range.","Dùng range loss."),B("Calls this a regret theorem.","Gọi đây là định lý regret.") ),
      Q(B("Compute mean variation","Tính variation mean"),["computation","derivation"],B("At one switch each arm mean changes by .4. Find V_T using maximum coordinate change.","Tại một switch mỗi mean đổi .4. Tính V_T theo thay đổi tọa độ lớn nhất."),B("Only one time increment is nonzero.","Chỉ một increment thời gian khác 0."),B("max_i|Δμ_i|=.4 at the switch, so V_T=.4.","max_i|Δμ_i|=.4 tại switch nên V_T=.4."),B("Finds switch.","Tìm switch."),B("Uses maximum over arms.","Dùng max arm."),B("Sums time increments.","Cộng increment.") ,B("Adds both arms when definition uses max.","Cộng hai arm khi định nghĩa lấy max.") ),
      Q(B("Prove pending-count bound","Chứng minh bound pending"),["proof"],B("Prove pending outcomes≤d and the unit-range discrepancy.","Chứng minh outcome pending≤d và sai khác loss range 1."),B("Older actions would already be revealed.","Action cũ đã lộ."),B("Pending actions lie in last d rounds; one per round gives≤d. Each loss difference≤1, so total≤d.","Action pending nằm d vòng cuối; mỗi vòng một action nên≤d. Mỗi chênh loss≤1 nên tổng≤d."),B("Uses delay condition.","Dùng điều kiện delay."),B("Counts one action per round.","Đếm action mỗi vòng."),B("Applies range.","Áp range."),B("Counts delayed events rather than pending actions.","Đếm event thay action pending.") ),
      Q(B("Transfer: choose comparator","Chuyển giao: chọn comparator"),["application","transfer"],B("After a permanent mean switch compare with best fixed arm or per-round oracle? Explain assumptions.","Sau mean switch vĩnh viễn so arm cố định tốt nhất hay oracle từng vòng? Nêu giả thiết."),B("Comparator defines the estimand; per-round oracle uses hindsight.","Comparator định estimand; oracle từng vòng dùng hindsight."),B("Best fixed arm is long-run stationary benchmark; per-round oracle asks tracking. A practical target states variation/change, causal information and switching costs.","Arm cố định là benchmark dừng dài hạn; oracle từng vòng hỏi tracking. Target thực tế nêu variation/change, thông tin nhân quả và switching costs."),B("Distinguishes targets.","Phân biệt target."),B("Explains hindsight.","Giải thích hindsight."),B("Names causal assumptions.","Nêu giả thiết nhân quả."),B("Treats oracle as available online.","Coi oracle có sẵn online.") ),
      Q(B("Counterexample: late regime switch","Phản ví dụ: switch chế độ muộn"),["counterexample","transfer"],B("Arm 1 mean .9 for 900 rounds then .1; arm 2 mean .5 always. Explain stale UCB after t=910.","Arm 1 mean .9 trong 900 vòng rồi .1; arm 2 luôn .5. Giải thích UCB cũ ở t=910."),B("Cumulative estimate is dominated by early rewards.","Estimate tích lũy bị reward đầu chi phối."),B("Stationarity is false; arm 1 empirical mean can remain above .5 while current mean is .1, and its growing count shrinks the nominal bonus.","Dừng sai; empirical mean arm 1 còn trên .5 dù mean hiện .1, count lớn làm bonus danh nghĩa nhỏ."),B("Specifies switch.","Nêu switch."),B("Explains stale estimate.","Giải thích estimate cũ."),B("Names model failure.","Nêu sai mô hình."),B("Claims fixed-mean Hoeffding covers drift.","Cho Hoeffding mean cố định bao drift.") ),
    ],
  },
  {
    week: 96, title: B("UCB synthesis and selected bandit depth","Tổng hợp UCB và chiều sâu bandit chọn lọc"), level: "specialization", prerequisites: [92,93,94,95],
    outcomes: [B("Derive a gap-dependent UCB pull threshold on simultaneous coverage.","Suy ngưỡng lượt UCB theo gap trên coverage đồng thời."),B("Keep Thompson regret, statistical significance and economic value claims within their evidence.","Giới hạn claim regret Thompson, ý nghĩa thống kê và giá trị kinh tế theo bằng chứng.")],
    definitions: B("For stationary arms with unique best mean μ*, gaps Δ_i=μ*−μ_i and pseudo-regret Σ_iΔ_iEN_i(T). UCB regret combines a simultaneous good event with a bound on pulls after inferior indices fall below the best arm.","Với arm dừng, mean tốt nhất duy nhất μ*, gap Δ_i=μ*−μ_i và pseudo-regret Σ_iΔ_iEN_i(T). Regret UCB ghép biến cố tốt đồng thời với bound lượt sau khi index arm kém thấp hơn arm tốt."),
    theoremTitle: B("Confidence coverage bounds suboptimal pulls","Coverage confidence chặn lượt arm kém"),
    statement: B("If simultaneously |μ̂_i−μ_i|≤r_i(N_i), r_i(n)=√(c logT/n), then when UCB selects suboptimal i over best j, Δ_i≤2r_i and N_i≤4c logT/Δ_i², up to forced initial pulls. Expected regret also needs failure-event control.","Nếu đồng thời |μ̂_i−μ_i|≤r_i(N_i), r_i(n)=√(c logT/n), khi UCB chọn i kém thay j tốt nhất thì Δ_i≤2r_i và N_i≤4c logT/Δ_i² ngoài lượt ép. Regret kỳ vọng cần kiểm soát biến cố lỗi."),
    proof: B("On simultaneous coverage, the optimal mean satisfies μ*=μ_j≤UCB_j. Since i maximizes UCB, UCB_j≤UCB_i. Coverage also gives UCB_i=μ̂_i+r_i≤μ_i+2r_i. Therefore Δ_i=μ*−μ_i≤2r_i, and squaring positive sides yields N_i≤4c logT/Δ_i² before initialization/crossing corrections. This is a good-event statement only; an expected-regret result additionally needs a simultaneous failure-probability bound.","Trên coverage đồng thời, mean tối ưu thỏa μ*=μ_j≤UCB_j. Vì i cực đại UCB nên UCB_j≤UCB_i. Coverage cũng cho UCB_i=μ̂_i+r_i≤μ_i+2r_i. Do đó Δ_i=μ*−μ_i≤2r_i; bình phương hai vế dương suy N_i≤4c logT/Δ_i² trước hiệu chỉnh lượt khởi tạo/vượt ngưỡng. Đây chỉ là kết quả trên biến cố tốt; regret kỳ vọng cần thêm cận xác suất lỗi đồng thời."),
    sourceId: "o-bandit", section: "§5.3 (concentration), §7.1 (UCB optimism), §4.4 (pseudo-regret), §36.1 (Thompson model); selected theorem proof is derived here.",
    workedExample: B("For Δ=.25,c=1,T=1000, threshold≈4log(1000)/.0625≈442 pulls on the good event, before forced pulls and failure correction; constants can make it vacuous.","Với Δ=.25,c=1,T=1000, ngưỡng≈4log(1000)/.0625≈442 lượt trên biến cố tốt, chưa gồm lượt ép và hiệu chỉnh lỗi; hằng số có thể làm cận lỏng."),
    failureCase: B("Stationarity and simultaneous confidence are assumptions. Thompson regret is cited, not proved. Bandit regret is neither a p-value nor net trading return.","Dừng và confidence đồng thời là giả thiết. Regret Thompson được dẫn, không chứng minh. Regret bandit không phải p-value hay return ròng."),
    topic: "selected bandit depth; gap-dependent UCB; Thompson theorem boundary", readingSection: "Lattimore–Szepesvári Ch. 6–7, 36–37",
    exercises: [
      Q(B("Compute gap threshold","Tính ngưỡng gap"),["computation"],B("For Δ=.25,c=1,T=1000 compute 4c logT/Δ².","Với Δ=.25,c=1,T=1000 tính 4c logT/Δ²."),B("Square Δ in denominator.","Bình phương Δ ở mẫu."),B("4log(1000)/.0625≈442.1, a good-event upper threshold, not an exact expected count.","4log(1000)/.0625≈442.1, là ngưỡng upper trên biến cố tốt, không phải kỳ vọng chính xác."),B("Squares gap.","Bình phương gap."),B("Computes log.","Tính log."),B("Qualifies bound.","Giới hạn cận."),B("Treats upper bound as exact count.","Coi cận trên là số chính xác.") ),
      Q(B("Prove the gap implication","Chứng minh hệ quả gap"),["proof"],B("Under simultaneous coverage and selection of i over best j prove Δ_i≤2r_i.","Dưới coverage đồng thời, chọn i thay j tốt, chứng minh Δ_i≤2r_i."),B("Use the upper endpoint for the optimal arm, then the selected-index ordering.","Dùng cận trên cho arm tối ưu, rồi thứ tự chỉ số được chọn."),B("Let μ*=μ_j. Simultaneous coverage gives μ*≤μ̂_j+r_j=UCB_j. Since i maximizes UCB, UCB_j≤UCB_i. Coverage for i gives UCB_i=μ̂_i+r_i≤μ_i+2r_i. Therefore Δ_i=μ*−μ_i≤2r_i. The lower endpoint satisfies LCB_j≤μ_j and cannot upper-bound μ*.","Đặt μ*=μ_j. Coverage đồng thời cho μ*≤μ̂_j+r_j=UCB_j. Vì i cực đại UCB, UCB_j≤UCB_i. Coverage của i cho UCB_i=μ̂_i+r_i≤μ_i+2r_i. Vậy Δ_i=μ*−μ_i≤2r_i. Cận dưới thỏa LCB_j≤μ_j nên không thể chặn trên μ*.") ,B("Uses μ*≤UCB_j by coverage.","Dùng μ*≤UCB_j từ coverage."),B("Uses UCB_j≤UCB_i by selected-index maximality.","Dùng UCB_j≤UCB_i do tính cực đại của chỉ số được chọn."),B("Bounds UCB_i≤μ_i+2r_i by coverage.","Chặn UCB_i≤μ_i+2r_i theo coverage."),B("Uses the lower endpoint as an upper bound.","Dùng cận dưới làm cận trên.")),
      Q(B("Derive pull threshold","Suy ngưỡng lượt"),["proof","derivation"],B("From Δ_i≤2√(c logT/N_i) isolate N_i.","Từ Δ_i≤2√(c logT/N_i) cô lập N_i."),B("Square nonnegative sides.","Bình phương hai vế không âm."),B("Δ_i²≤4c logT/N_i implies N_i≤4c logT/Δ_i².","Δ_i²≤4c logT/N_i suy N_i≤4c logT/Δ_i²."),B("Squares correctly.","Bình phương đúng."),B("Uses positive gap.","Dùng gap dương."),B("Isolates N_i.","Cô lập N_i."),B("Reverses inequality incorrectly.","Đảo bất đẳng thức sai.") ),
      Q(B("Transfer: audit a TS theorem claim","Chuyển giao: audit claim định lý TS"),["application","transfer"],B("A report says TS regret is proved but only cites a book and omits theorem assumptions. What must it add?","Báo cáo nói đã chứng minh regret TS nhưng chỉ dẫn sách, bỏ giả thiết. Cần thêm gì?" ),B("State exact model, comparator, horizon and theorem status.","Nêu mô hình, comparator, horizon, trạng thái định lý."),B("Give exact hypotheses and applicability; if not reproduced, mark theorem assumed/sourced. A citation is not a proof; distinguish pseudo-regret and realized reward.","Nêu giả thiết và áp dụng; nếu không tự chứng minh thì đánh dấu giả định/dẫn nguồn. Trích dẫn không phải proof; phân biệt pseudo-regret và reward thực."),B("Lists assumptions.","Liệt kê giả thiết."),B("Explains applicability.","Giải thích áp dụng."),B("Labels proof status honestly.","Đánh dấu trung thực.") ,B("Calls a citation a derivation.","Gọi trích dẫn là suy diễn.") ),
      Q(B("Counterexample: regret is not significance","Phản ví dụ: regret không phải ý nghĩa"),["counterexample","transfer"],B("A policy has lower empirical loss over 30 overlapping dates. Why is improvement not established statistically?","Policy loss empirical thấp hơn trong 30 ngày chồng lấn. Vì sao chưa chứng minh cải thiện thống kê?" ),B("Paired loss differences are dependent.","Chênh loss paired phụ thuộc."),B("Need an estimand, dependence-aware uncertainty, selection/multiplicity control, and valid information timing. The sample difference is descriptive only.","Cần estimand, bất định có xét phụ thuộc, kiểm soát chọn/bội số, thời điểm thông tin hợp lệ. Chênh mẫu chỉ mô tả."),B("Names descriptive target.","Nêu target mô tả."),B("Names dependence-aware inference.","Nêu suy luận phụ thuộc."),B("Adds selection and timing.","Thêm chọn và thời điểm."),B("Treats 30 overlaps as IID.","Coi 30 overlap IID.") )
    ],
  },
];


const assessments: MathAssessment[] = [
  { id: "m2-gate-72", week: 72, title: B("Optimization gate: primal-dual, convergence, and numerical reasoning","Cổng tối ưu: primal-dual, hội tụ và số học"), forms: [{ name: "A", exerciseIds: [eid(72,2), eid(72,3), eid(72,4)] }, { name: "B", exerciseIds: [eid(72,1), eid(72,5)] }], blueprint: B("Form A is the ridge equality/KKT and gradient-descent argument, an ill-conditioned least-squares transfer, and a Fenchel-LASSO certificate. Form B is a box-constrained SPD quadratic primal-dual certificate with an ill-scaled SPD residual/sensitivity transfer, plus projected-gradient convergence. The forms use disjoint exercises and each assesses primal-dual reasoning, convergence and numerical failure.","Đề A gồm KKT/đối ngẫu ridge có ràng buộc đẳng thức và lập luận gradient descent, bài chuyển giao bình phương tối thiểu kém điều kiện, cùng chứng chỉ Fenchel-LASSO. Đề B gồm chứng chỉ primal-dual cho quadratic SPD ràng buộc hộp kèm chuyển giao residual/độ nhạy SPD sai thang, và hội tụ projected-gradient. Hai đề dùng bài tập rời nhau; mỗi đề đánh giá đối ngẫu, hội tụ và thất bại số."), passRule: B("At least 70%, with critical credit required separately for feasible primal-dual reasoning, a justified convergence argument and numerical failure analysis.","Ít nhất 70%, phải đạt riêng điểm critical cho lập luận primal-dual khả thi, chứng minh hội tụ có giả thiết và phân tích thất bại số."), remediation: B("Redo the missed domain with a new dual certificate, a new convergence derivation, or a new perturbed ill-conditioned system before retest.","Làm lại miền còn thiếu bằng chứng chỉ dual mới, suy dẫn hội tụ mới hoặc hệ kém điều kiện bị nhiễu mới trước khi thi lại.") },
  { id: "m2-gate-84", week: 84, title: B("Dependence gate: HAC and non-IID reasoning","Cổng phụ thuộc: HAC và lập luận không IID"), forms: [{ name: "A", exerciseIds: [eid(84,2)] }, { name: "B", exerciseIds: [eid(84,5)] }], blueprint: B("A proves finite-sample Bartlett PSD with moving-window sums of squares. B derives unit-root nonstationarity from covariance and selects differenced inference. Different arguments, not numeric variants.","A chứng minh PSD Bartlett mẫu hữu hạn bằng tổng bình phương cửa sổ. B suy phi dừng unit-root từ covariance và chọn suy luận sai phân. Lập luận khác nhau, không đổi số."), passRule: B("At least 70%; must distinguish PSD from consistency and stationary from unit-root asymptotics.","Ít nhất 70%; phải phân biệt PSD với nhất quán và tiệm cận dừng với unit-root."), remediation: B("Re-derive the chosen argument and solve a new dependence-aware inference problem before retest.","Suy lại lập luận đã chọn và giải bài suy luận phụ thuộc mới trước thi lại.") }
];

const earlyWeeks: RawWeek[] = [
  {
    week: 61, title: B('Convex sets, functions, and existence', 'Tập lồi, hàm lồi và sự tồn tại nghiệm'), level: 'graduate bridge', prerequisites: [60],
    outcomes: [B('Prove a set convex by arbitrary convex combinations and distinguish local from global minima.', 'Chứng minh tập lồi bằng tổ hợp lồi tùy ý và phân biệt cực tiểu địa phương với toàn cục.'), B('Use compactness and continuity to justify attainment rather than assume an optimizer exists.', 'Dùng tính compact và liên tục để biện minh nghiệm đạt được thay vì giả định nghiệm tối ưu tồn tại.')],
    definitions: B(String.raw`A set C⊆R^d is convex when (1−t)x+ty∈C for x,y∈C and t∈[0,1]. A function f:C→R is convex when f((1−t)x+ty)≤(1−t)f(x)+tf(y). A strict inequality for x≠y and 0<t<1 defines strict convexity. A differentiable f on an open convex domain is convex iff f(y)≥f(x)+∇f(x)^T(y−x) for every x,y; twice differentiably, ∇²f(x)⪰0 is sufficient (and necessary on a convex open domain).`, String.raw`Tập C⊆R^d lồi nếu (1−t)x+ty∈C với x,y∈C và t∈[0,1]. Hàm f:C→R lồi nếu f((1−t)x+ty)≤(1−t)f(x)+tf(y). Bất đẳng thức nghiêm khi x≠y, 0<t<1 xác định lồi nghiêm. Với f khả vi trên miền lồi mở, f lồi khi và chỉ khi f(y)≥f(x)+∇f(x)^T(y−x) với mọi x,y; nếu khả vi hai lần thì ∇²f(x)⪰0 là đủ (và cần trên miền lồi mở).`),
    theoremTitle: B('A stationary point of a differentiable convex function is globally optimal', 'Điểm dừng của hàm lồi khả vi là nghiệm tối ưu toàn cục'),
    statement: B(String.raw`Let C⊆R^d be convex, f:C→R convex and differentiable on a neighborhood of x*∈C. If ∇f(x*)=0, then f(x*)≤f(y) for every y∈C. No strict convexity is needed; uniqueness is not implied.`, String.raw`Cho C⊆R^d lồi, f:C→R lồi và khả vi trong lân cận của x*∈C. Nếu ∇f(x*)=0 thì f(x*)≤f(y) với mọi y∈C. Không cần lồi nghiêm; kết luận không hàm ý nghiệm duy nhất.`),
    proof: B(String.raw`For arbitrary y∈C, convexity of the one-dimensional restriction g(t)=f(x*+t(y−x*)) on [0,1] gives g(1)≥g(0)+g′(0). By the chain rule g′(0)=∇f(x*)^T(y−x*)=0. Hence f(y)=g(1)≥g(0)=f(x*). Since y was arbitrary, x* is global minimizer. If f is constant on a segment, there can be multiple minimizers.`, String.raw`Với y∈C tùy ý, tính lồi của hàm một biến g(t)=f(x*+t(y−x*)) trên [0,1] cho g(1)≥g(0)+g′(0). Quy tắc dây chuyền cho g′(0)=∇f(x*)^T(y−x*)=0. Do đó f(y)=g(1)≥g(0)=f(x*). Vì y tùy ý nên x* là cực tiểu toàn cục. Nếu f hằng trên một đoạn thì nghiệm có thể không duy nhất.`), sourceId: 'o-boyd', section: '§3.1 and §4.1; the first-order inequality is derived here.',
    workedExample: B(String.raw`For f(x)=½xᵀQx+bᵀx+c with Q=Qᵀ⪰0, ∇f=Qx+b. If Q is invertible, x*=−Q⁻¹b has zero gradient and is a global minimizer. If Q is singular, a solution exists only when b∈range(Q); then the minimizer set is x*+null(Q). For Q=diag(2,0), b=(−2,0), every (1,s) minimizes.`, String.raw`Với f(x)=½xᵀQx+bᵀx+c, Q=Qᵀ⪰0, ta có ∇f=Qx+b. Nếu Q khả nghịch, x*=−Q⁻¹b có gradient bằng không nên là nghiệm toàn cục. Nếu Q suy biến, chỉ có nghiệm khi b∈range(Q); khi đó tập nghiệm là x*+null(Q). Với Q=diag(2,0), b=(−2,0), mọi (1,s) đều tối ưu.`),
    failureCase: B(String.raw`Convexity cannot be dropped: f(x)=−x² is differentiable and ∇f(0)=0, yet 0 is a strict maximum. Conversely, convexity gives global optimality but not uniqueness, as the flat direction above shows.`, String.raw`Không thể bỏ tính lồi: f(x)=−x² khả vi và ∇f(0)=0 nhưng 0 là cực đại nghiêm. Ngược lại, tính lồi cho tối ưu toàn cục nhưng không cho duy nhất, như phương phẳng ở ví dụ trên.`),
    topic: 'convex sets/functions; first-order optimality; existence and nonuniqueness', readingSection: 'Ch. 2.1–2.3, 3.1–3.4, 4.1–4.2',
    exercises: [
      E(B('Convexity by a segment test', 'Kiểm tra lồi bằng đoạn thẳng'), ['proof'], B(String.raw`Prove that C={x∈R²:x₁≥0, x₂≥0, x₁+x₂≤1} is convex by checking an arbitrary convex combination, and identify its extreme points.`, String.raw`Chứng minh C={x∈R²:x₁≥0, x₂≥0, x₁+x₂≤1} lồi bằng cách xét tổ hợp lồi tùy ý, rồi xác định các điểm cực biên.`), [B('Take x,y∈C and write each of the three affine inequalities for (1−t)x+ty.', 'Lấy x,y∈C và viết ba bất đẳng thức affine cho (1−t)x+ty.')], [B(String.raw`For z=(1−t)x+ty, z_i=(1−t)x_i+ty_i≥0; also z₁+z₂=(1−t)(x₁+x₂)+t(y₁+y₂)≤(1−t)+t=1. Thus z∈C. The vertices are (0,0),(1,0),(0,1): each is an intersection of two active boundary constraints, and every point of C is their convex combination (1−x₁−x₂)(0,0)+x₁(1,0)+x₂(0,1).`, String.raw`Đặt z=(1−t)x+ty. Khi đó z_i=(1−t)x_i+ty_i≥0; đồng thời z₁+z₂=(1−t)(x₁+x₂)+t(y₁+y₂)≤(1−t)+t=1. Vậy z∈C. Các đỉnh là (0,0),(1,0),(0,1): mỗi đỉnh là giao của hai biên đang hoạt động và mọi điểm trong C là tổ hợp lồi (1−x₁−x₂)(0,0)+x₁(1,0)+x₂(0,1).`)], [R(1,'Names arbitrary x,y,t∈[0,1].','Nêu x,y,t∈[0,1] tùy ý.'),R(2,'Checks all three inequalities after mixing.','Kiểm tra đủ ba bất đẳng thức sau khi trộn.'),R(1,'Proves membership and identifies vertices.','Kết luận thuộc tập và xác định đỉnh.')], [B('Checks only the vertices and assumes the whole triangle follows.', 'Chỉ kiểm tra các đỉnh rồi mặc định cả tam giác lồi.')]),
      E(B('First-order certificate', 'Chứng chỉ bậc nhất'), ['derivation','proof'], B(String.raw`For f(x,y)=x²+2y²−2x+4y on R², find its minimizer using a first-order certificate and prove uniqueness.`, String.raw`Với f(x,y)=x²+2y²−2x+4y trên R², tìm nghiệm tối ưu bằng chứng chỉ bậc nhất và chứng minh tính duy nhất.`), [B('Compute the gradient and Hessian; test positive definiteness.', 'Tính gradient, Hessian rồi kiểm tra xác định dương.')], [B(String.raw`∇f=(2x−2,4y+4), so ∇f=0 gives (1,−1). The Hessian diag(2,4) is positive definite, so f is strictly convex. The first-order theorem gives global minimality; strict convexity gives uniqueness. f(1,−1)=−3.`, String.raw`∇f=(2x−2,4y+4), nên ∇f=0 cho (1,−1). Hessian diag(2,4) xác định dương nên f lồi nghiêm. Định lý bậc nhất cho cực tiểu toàn cục; lồi nghiêm cho duy nhất. f(1,−1)=−3.`)], [R(1,'Correct gradient and stationary point.','Gradient và điểm dừng đúng.'),R(2,'Uses PSD Hessian to prove strict convexity.','Dùng Hessian PSD để chứng minh lồi nghiêm.'),R(1,'Separates global optimality from uniqueness.','Tách tối ưu toàn cục khỏi tính duy nhất.')], [B('A zero gradient alone is claimed to prove optimality for any differentiable function.', 'Chỉ dùng gradient bằng không để kết luận tối ưu cho mọi hàm khả vi.')]),
      E(B('A flat minimizer set', 'Tập nghiệm cực tiểu phẳng'), ['computation','application'], B(String.raw`Minimize f(u,v)=(u−2)² over R². Give the full minimizer set, its Hessian eigenvalues, and explain the role of the null direction.`, String.raw`Tối thiểu hóa f(u,v)=(u−2)² trên R². Cho toàn bộ tập nghiệm, trị riêng Hessian và giải thích vai trò phương null.`), [B('Differentiate in both coordinates; the objective does not depend on v.', 'Lấy đạo hàm theo hai tọa độ; hàm mục tiêu không phụ thuộc v.')], [B(String.raw`∇f=(2(u−2),0), hence the stationary points are exactly {(2,v):v∈R}; every one has value 0. The Hessian is diag(2,0), with eigenvalues 2 and 0. The null direction (0,1) is flat, causing nonuniqueness, not instability of the objective value.`, String.raw`∇f=(2(u−2),0), nên điểm dừng chính là {(2,v):v∈R}; mọi điểm có giá trị 0. Hessian diag(2,0) có trị riêng 2 và 0. Phương null (0,1) phẳng, gây không duy nhất chứ không làm giá trị mục tiêu bất ổn.`)], [R(1,'Finds the complete set, not one point.','Tìm đầy đủ tập nghiệm, không chỉ một điểm.'),R(1,'Computes eigenvalues correctly.','Tính đúng trị riêng.'),R(2,'Connects zero curvature to nonuniqueness.','Liên hệ độ cong bằng không với không duy nhất.')], [B('Reports (2,0) as the unique minimizer.', 'Báo (2,0) là nghiệm duy nhất.')]),
      E(B('Transfer: a convex function on a convex domain', 'Chuyển giao: hàm lồi trên miền lồi'), ['proof','transfer'], B(String.raw`Let f be convex differentiable on an open convex set C and x*∈C with ∇f(x*)=0. Prove the global-minimum claim without assuming twice differentiability; state why the argument fails if C is nonconvex.`, String.raw`Cho f lồi khả vi trên tập mở lồi C và x*∈C có ∇f(x*)=0. Chứng minh cực tiểu toàn cục mà không giả sử khả vi hai lần; nêu vì sao lập luận hỏng nếu C không lồi.`), [B('Restrict f to the segment from x* to an arbitrary y∈C.', 'Hạn chế f lên đoạn nối x* với y∈C tùy ý.')], [B(String.raw`For each y∈C, convexity of C puts x*+t(y−x*) in C. The one-dimensional convexity inequality gives f(y)≥f(x*)+∇f(x*)ᵀ(y−x*)=f(x*). If C is nonconvex, the segment may leave the domain, so this univariate restriction is not defined throughout [0,1] and the proof has no path to compare f(y) with f(x*).`, String.raw`Với mỗi y∈C, tính lồi của C bảo đảm x*+t(y−x*)∈C. Bất đẳng thức lồi một biến cho f(y)≥f(x*)+∇f(x*)ᵀ(y−x*)=f(x*). Nếu C không lồi, đoạn có thể ra khỏi miền; phép hạn chế hàm không xác định trên toàn [0,1] và chứng minh không còn đường so sánh f(y) với f(x*).`)], [R(1,'Uses only convexity and differentiability.','Chỉ dùng lồi và khả vi.'),R(2,'Applies the segment inequality correctly.','Áp dụng đúng bất đẳng thức trên đoạn.'),R(1,'Identifies the domain failure under nonconvexity.','Chỉ ra lỗi miền khi không lồi.')], [B('Invokes a Hessian although only one derivative is assumed.', 'Viện dẫn Hessian dù chỉ giả sử khả vi bậc nhất.')]),
      E(B('Counterexample: stationary is not enough', 'Phản ví dụ: điểm dừng chưa đủ'), ['counterexample','transfer'], B(String.raw`Construct a differentiable nonconvex function with a stationary point that is not a global minimum; then give a different example with multiple global minima despite convexity.`, String.raw`Dựng hàm khả vi không lồi có điểm dừng không phải cực tiểu toàn cục; sau đó cho ví dụ khác có nhiều cực tiểu toàn cục dù hàm lồi.`), [B('Use a concave quadratic for the first and a constant/flat convex function for the second.', 'Dùng parabol lõm cho ví dụ đầu và hàm hằng/đoạn phẳng lồi cho ví dụ sau.')], [B(String.raw`For f(x)=−x², f′(0)=0 while f(1)=−1<f(0)=0, so 0 is not a minimum. For g(x)=0 on [0,1], every point is a global minimizer. The examples separate the hypotheses needed for globality from those needed for uniqueness.`, String.raw`Với f(x)=−x², f′(0)=0 nhưng f(1)=−1<f(0)=0 nên 0 không là cực tiểu. Với g(x)=0 trên [0,1], mọi điểm đều là cực tiểu toàn cục. Hai ví dụ tách điều kiện cần cho tối ưu toàn cục khỏi điều kiện cho nghiệm duy nhất.`)], [R(1,'First example is differentiable and nonconvex.','Ví dụ đầu khả vi và không lồi.'),R(1,'Shows stationary point fails globally.','Chỉ ra điểm dừng không tối ưu toàn cục.'),R(2,'Second example proves nonuniqueness under convexity.','Ví dụ sau chứng minh không duy nhất dù lồi.')], [B('Uses a convex quadratic with an incorrect gradient.', 'Dùng quadratic lồi với gradient tính sai.')]),
    ],
  },
  {
    week: 62, title: B('Supporting hyperplanes and subgradients', 'Siêu phẳng tựa và dưới gradient'), level: 'graduate core', prerequisites: [61],
    outcomes: [B('Compute subdifferentials of absolute value, norms and maxima.', 'Tính dưới vi phân của trị tuyệt đối, chuẩn và hàm cực đại.'), B('Use a supporting-hyperplane certificate for a nonsmooth optimum.', 'Dùng chứng chỉ siêu phẳng tựa cho nghiệm tối ưu không trơn.')],
    definitions: B(String.raw`For a convex f:R^d→(−∞,∞], g∈∂f(x) iff f(y)≥f(x)+gᵀ(y−x) for all y. Thus ∂f(x) is the set of slopes of global affine lower supports. For |x|, ∂f(0)=[−1,1] and ∂f(x)={sign x} for x≠0. A support at a kink is a set, not a single derivative.`, String.raw`Với f:R^d→(−∞,∞] lồi, g∈∂f(x) khi và chỉ khi f(y)≥f(x)+gᵀ(y−x) với mọi y. Vì vậy ∂f(x) là tập hệ số góc của các hàm affine đỡ toàn cục. Với |x|, ∂f(0)=[−1,1] và ∂f(x)={sign x} khi x≠0. Ở điểm gấp, support là một tập chứ không phải một đạo hàm.`),
    theoremTitle: B('The convex Fermat rule', 'Quy tắc Fermat cho hàm lồi'),
    statement: B(String.raw`If f is proper convex and x∈dom f, then x globally minimizes f over R^d iff 0∈∂f(x).`, String.raw`Nếu f lồi proper và x∈dom f thì x tối thiểu hóa toàn cục f trên R^d khi và chỉ khi 0∈∂f(x).`),
    proof: B(String.raw`By definition, 0∈∂f(x) means f(y)≥f(x)+0ᵀ(y−x)=f(x) for every y, which is exactly global minimality. Conversely, if x globally minimizes f, then f(y)≥f(x) for every y, so the subgradient inequality holds with g=0. Properness rules out the identically +∞ case; no differentiability is assumed.`, String.raw`Theo định nghĩa, 0∈∂f(x) nghĩa là f(y)≥f(x)+0ᵀ(y−x)=f(x) với mọi y, đúng bằng tối thiểu toàn cục. Ngược lại, nếu x tối thiểu toàn cục thì f(y)≥f(x) với mọi y nên bất đẳng thức dưới gradient đúng với g=0. Tính proper loại trừ hàm đồng nhất +∞; không cần khả vi.`), sourceId: 'o-boyd', section: '§3.1–3.2 (supporting hyperplanes and subgradients); Fermat equivalence proved from definition.',
    workedExample: B(String.raw`Minimize |x|+½(x−2)². At x=1, ∂|x|={1}, so 0∈1+(1−2)=0; the Fermat rule certifies x=1. The quadratic term makes the sum strictly convex, hence this minimizer is unique.`, String.raw`Tối thiểu hóa |x|+½(x−2)². Tại x=1, ∂|x|={1}, nên 0∈1+(1−2)=0; quy tắc Fermat chứng nhận x=1. Hạng quadratic làm tổng lồi nghiêm nên nghiệm duy nhất.`),
    failureCase: B(String.raw`A directional derivative need not be a gradient: |x| has no derivative at 0, but ∂|0|=[−1,1]. Replacing the subdifferential by the single number 0 without checking its set-valued definition can invalidate a stationarity argument.`, String.raw`Đạo hàm theo hướng không nhất thiết là gradient: |x| không khả vi tại 0 nhưng ∂|0|=[−1,1]. Thay dưới vi phân bằng một số 0 mà không kiểm tra định nghĩa tập có thể làm sai lập luận dừng.`),
    topic: 'subgradients; supporting hyperplanes; nonsmooth optimality', readingSection: '§3.1–3.2',
    exercises: [
      E(B('Subdifferential at a kink', 'Dưới vi phân tại điểm gấp'), ['derivation'], B(String.raw`Derive ∂|x|(0) directly from its defining inequality; show why no slope outside [−1,1] works.`, String.raw`Suy ra ∂|x|(0) trực tiếp từ bất đẳng thức định nghĩa; chỉ ra vì sao mọi hệ số ngoài [−1,1] đều không hợp lệ.`), [B('Write |y|≥g y separately for y>0 and y<0.', 'Viết |y|≥gy riêng cho y>0 và y<0.')], [B(String.raw`For y>0, gy≤y implies g≤1; for y<0, −y≥gy implies g≥−1. Every g∈[−1,1] satisfies both inequalities, so ∂|·|(0)=[−1,1].`, String.raw`Với y>0, gy≤y cho g≤1; với y<0, −y≥gy cho g≥−1. Mọi g∈[−1,1] thỏa cả hai bất đẳng thức nên ∂|·|(0)=[−1,1].`)], [R(1,'Derives the positive-side bound.','Suy ra cận từ phía dương.'),R(1,'Derives the negative-side bound.','Suy ra cận từ phía âm.'),R(2,'Checks sufficiency for all y.','Kiểm tra tính đủ với mọi y.')], [B('Uses only y=1 and misses the lower bound.', 'Chỉ dùng y=1 và bỏ sót cận dưới.')]),
      E(B('Solve an ℓ1-penalized scalar problem', 'Giải bài toán vô hướng có phạt ℓ1'), ['computation','derivation'], B(String.raw`Find all minimizers of f(x)=3|x|+½(x−1)². Give the subgradient inclusion at the answer and verify it.`, String.raw`Tìm mọi nghiệm của f(x)=3|x|+½(x−1)². Viết bao hàm dưới gradient tại nghiệm và kiểm tra.`), [B('Consider x>0, x<0, and x=0 separately.', 'Xét riêng x>0, x<0 và x=0.')], [B(String.raw`For x>0, derivative 3+x−1=x+2>0; for x<0, derivative −3+x−1=x−4<0. The function decreases toward zero from the left and increases to the right. At zero, ∂f(0)=3[−1,1]+(−1)=[−4,2], containing 0. Thus x=0 is the unique minimizer (strict convexity comes from the quadratic).`, String.raw`Với x>0, đạo hàm là 3+x−1=x+2>0; với x<0 là −3+x−1=x−4<0. Hàm giảm về 0 từ trái và tăng từ phải. Tại 0, ∂f(0)=3[−1,1]+(−1)=[−4,2] chứa 0. Vậy x=0 là nghiệm duy nhất (tính duy nhất do quadratic lồi nghiêm).`)], [R(1,'Checks both smooth regions.','Kiểm tra hai miền trơn.'),R(2,'Computes the subdifferential at zero.','Tính dưới vi phân tại 0.'),R(1,'Uses convex Fermat and uniqueness correctly.','Dùng Fermat lồi và tính duy nhất đúng.')], [B('Differentiates |x| at x=0.', 'Lấy đạo hàm |x| tại x=0.')]),
      E(B('Maximum of affine functions', 'Cực đại các hàm affine'), ['proof','derivation'], B(String.raw`For f(x)=max{2x+1,−x+4}, find the kink and derive its subdifferential there as the convex hull of the active slopes.`, String.raw`Với f(x)=max{2x+1,−x+4}, tìm điểm gấp và suy ra dưới vi phân là bao lồi của các độ dốc đang hoạt động.`), [B('Solve equality of the two affine pieces, then use supporting slopes.', 'Giải giao điểm hai nhánh affine rồi dùng các độ dốc đỡ.')], [B(String.raw`The pieces meet at 2x+1=−x+4, so x=1 and f(1)=3. For x<1 the active slope is −1; for x>1 it is 2. At x=1, any convex combination g=λ(−1)+(1−λ)2, 0≤λ≤1, is a support; hence ∂f(1)=[−1,2].`, String.raw`Hai nhánh gặp nhau tại 2x+1=−x+4 nên x=1, f(1)=3. Khi x<1 độ dốc hoạt động là −1; khi x>1 là 2. Tại x=1, mọi tổ hợp lồi g=λ(−1)+(1−λ)2, 0≤λ≤1, đều là support; do đó ∂f(1)=[−1,2].`)], [R(1,'Finds the intersection.','Tìm đúng giao điểm.'),R(2,'Identifies active slopes on either side.','Xác định độ dốc hoạt động hai phía.'),R(1,'Forms their convex hull.','Lập bao lồi các độ dốc.')], [B('Averages slopes with weights outside [0,1].', 'Lấy trung bình độ dốc với trọng số ngoài [0,1].')]),
      E(B('Transfer: constrained nonsmooth optimum', 'Chuyển giao: tối ưu không trơn có ràng buộc'), ['proof','transfer'], B(String.raw`Minimize |x| over the interval [2,5]. Show that 0∈∂|x| is not the correct constrained stationarity test at the minimizer, and produce a normal-cone certificate.`, String.raw`Tối thiểu hóa |x| trên đoạn [2,5]. Chỉ ra 0∈∂|x| không phải kiểm tra dừng ràng buộc đúng tại nghiệm và lập chứng chỉ nón pháp tuyến.`), [B('At x=2 the function is smooth; the boundary contributes a normal cone.', 'Tại x=2 hàm trơn; biên đóng góp nón pháp tuyến.')], [B(String.raw`The minimizer is x*=2. Its function subgradient is {1}, so 0∉∂f(2). For C=[2,5], define N_C(2)={v:v(y−2)≤0 for all y∈C}=(-∞,0]. The constrained condition 0∈∂f(2)+N_C(2) holds because 1+(−1)=0. This is the normal-cone form of the variational inequality.`, String.raw`Nghiệm là x*=2. Dưới vi phân hàm là {1} nên 0∉∂f(2). Với C=[2,5], đặt N_C(2)={v:v(y−2)≤0 với mọi y∈C}=(-∞,0]. Điều kiện ràng buộc 0∈∂f(2)+N_C(2) đúng vì 1+(−1)=0. Đây là dạng nón pháp tuyến của bất đẳng thức biến phân.`)], [R(1,'Finds the boundary minimizer.','Tìm nghiệm ở biên.'),R(2,'Computes the normal cone with correct sign.','Tính nón pháp tuyến đúng dấu.'),R(1,'Checks the sum inclusion.','Kiểm tra bao hàm tổng.')], [B('Uses an interior unconstrained condition at the boundary.', 'Dùng điều kiện không ràng buộc ở trong miền tại biên.')]),
      E(B('Counterexample: a false smooth derivative rule', 'Phản ví dụ: quy tắc đạo hàm trơn sai'), ['counterexample','transfer'], B(String.raw`Give a convex nonsmooth function whose minimum cannot be found by solving ∇f=0 because the gradient does not exist there. Contrast with a point away from the kink.`, String.raw`Cho hàm lồi không trơn có cực tiểu không thể tìm bằng ∇f=0 vì gradient không tồn tại tại đó; đối chiếu với điểm ngoài chỗ gấp.`), [B('Use |x|; compare its derivative for x≠0 to its subdifferential at zero.', 'Dùng |x|; so sánh đạo hàm ngoài 0 với dưới vi phân tại 0.')], [B(String.raw`For f(x)=|x|, the unique minimum is x=0, where f′(0) does not exist. For x>0, ∂f(x)={1}; for x<0, ∂f(x)={−1}. The correct certificate is 0∈∂f(0)=[−1,1], not the undefined equation f′(0)=0.`, String.raw`Với f(x)=|x|, cực tiểu duy nhất là x=0, nơi f′(0) không tồn tại. Khi x>0, ∂f(x)={1}; khi x<0, ∂f(x)={−1}. Chứng chỉ đúng là 0∈∂f(0)=[−1,1], không phải phương trình không xác định f′(0)=0.`)], [R(1,'Identifies the nondifferentiable minimizer.','Xác định nghiệm không khả vi.'),R(2,'Computes subgradients away and at the kink.','Tính dưới gradient ngoài và tại điểm gấp.'),R(1,'States the valid optimality certificate.','Nêu chứng chỉ tối ưu hợp lệ.')], [B('Calls zero a derivative value rather than a set of slopes.', 'Gọi 0 là giá trị đạo hàm thay vì một tập độ dốc.')]),
    ],
  },
  {
    week: 63, title: B('Fenchel conjugates and dual coordinates', 'Liên hợp Fenchel và tọa độ đối ngẫu'), level: 'graduate core', prerequisites: [62],
    outcomes: [B('Compute conjugates from their supremum definition and state effective domains.', 'Tính liên hợp từ định nghĩa supremum và nêu miền hiệu dụng.'), B('Use Fenchel–Young to create primal lower bounds and equality certificates.', 'Dùng Fenchel–Young tạo cận dưới primal và chứng chỉ dấu bằng.')],
    definitions: B(String.raw`For proper f:R^d→(−∞,∞], its Fenchel conjugate is f*(y)=sup_x{yᵀx−f(x)}. The effective domain is the set of y where this supremum is finite. A conjugate changes coordinates: y is a slope supporting f. The biconjugate equals f for proper closed convex f; that theorem is assumed here (Boyd §3.3), while the inequality below is proved.`, String.raw`Với f:R^d→(−∞,∞] proper, liên hợp Fenchel là f*(y)=sup_x{yᵀx−f(x)}. Miền hiệu dụng gồm các y làm supremum hữu hạn. Liên hợp đổi tọa độ: y là độ dốc đỡ f. Định lý liên hợp kép f**=f đúng với f lồi đóng proper được dùng như định lý giả thiết (Boyd §3.3); bất đẳng thức sau được chứng minh.`),
    theoremTitle: B('Fenchel–Young inequality and equality condition', 'Bất đẳng thức Fenchel–Young và điều kiện dấu bằng'),
    statement: B(String.raw`For every proper f and every x,y, f(x)+f*(y)≥yᵀx. If f is closed convex, equality holds iff y∈∂f(x) (equivalently x∈∂f*(y)).`, String.raw`Với f proper và mọi x,y, f(x)+f*(y)≥yᵀx. Nếu f lồi đóng thì dấu bằng xảy ra khi và chỉ khi y∈∂f(x) (tương đương x∈∂f*(y)).`),
    proof: B(String.raw`By definition, f*(y)=sup_z(yᵀz−f(z))≥yᵀx−f(x), giving the inequality. Equality means the supremum is attained at x, i.e. yᵀz−f(z)≤yᵀx−f(x) for every z. Rearranging gives f(z)≥f(x)+yᵀ(z−x), precisely y∈∂f(x). Closed convexity supplies the usual conjugate/subgradient symmetry for the equivalent condition.`, String.raw`Theo định nghĩa, f*(y)=sup_z(yᵀz−f(z))≥yᵀx−f(x), cho bất đẳng thức. Dấu bằng nghĩa là supremum đạt tại x, tức yᵀz−f(z)≤yᵀx−f(x) với mọi z. Chuyển vế được f(z)≥f(x)+yᵀ(z−x), chính là y∈∂f(x). Tính lồi đóng cho quan hệ đối xứng tương đương giữa liên hợp và dưới vi phân.`), sourceId: 'o-boyd', section: '§3.3 (conjugate functions); equality condition follows from the subgradient definition.',
    workedExample: B(String.raw`For f(x)=½x², maximize yx−½x² over x: derivative y−x=0 gives f*(y)=½y². Fenchel–Young is ½x²+½y²≥xy, equivalent to (x−y)²≥0, with equality iff x=y=∂f(x).`, String.raw`Với f(x)=½x², cực đại yx−½x² theo x cho y−x=0, nên f*(y)=½y². Fenchel–Young là ½x²+½y²≥xy, tương đương (x−y)²≥0; dấu bằng khi x=y=∂f(x).`),
    failureCase: B(String.raw`For f=indicator_C, f*(y)=sup_{x∈C}yᵀx may be +∞ for unbounded C. A formula derived as if every conjugate were finite loses its domain and can state false dual feasibility.`, String.raw`Với f là hàm chỉ thị của C, f*(y)=sup_{x∈C}yᵀx có thể bằng +∞ nếu C không bị chặn. Công thức giả sử mọi liên hợp hữu hạn sẽ làm mất miền và có thể nêu sai tính khả thi đối ngẫu.`),
    topic: 'Fenchel conjugacy; Fenchel–Young; support functions and domains', readingSection: '§3.3',
    exercises: [
      E(B('Conjugate of a quadratic', 'Liên hợp của quadratic'), ['derivation'], B(String.raw`For f(x)=½a x² with a>0, compute f*(y) from the supremum and verify the equality condition.`, String.raw`Với f(x)=½a x², a>0, tính f*(y) từ supremum và kiểm tra điều kiện dấu bằng.`), [B('Complete the square in yx−a x²/2.', 'Hoàn thành bình phương trong yx−a x²/2.')], [B(String.raw`The maximizer solves y−ax=0, x=y/a. Substitution gives f*(y)=y²/(2a). Equality in FY is attained exactly when y=ax, equivalently y∈∂f(x)={ax}.`, String.raw`Điểm cực đại giải y−ax=0 nên x=y/a. Thay vào được f*(y)=y²/(2a). Dấu bằng FY đạt đúng khi y=ax, tương đương y∈∂f(x)={ax}.`)], [R(1,'Finds the unique maximizer.','Tìm điểm cực đại duy nhất.'),R(2,'Computes the conjugate with correct scale.','Tính liên hợp đúng hệ số.'),R(1,'States equality condition.','Nêu điều kiện dấu bằng.')], [B('Drops the factor a in the denominator.', 'Bỏ hệ số a ở mẫu.')]),
      E(B('Conjugate of an indicator', 'Liên hợp hàm chỉ thị'), ['computation','derivation'], B(String.raw`Let C=[−1,2] and δ_C(x)=0 on C, +∞ otherwise. Find δ_C*(y) for y<0, y=0, y>0.`, String.raw`Cho C=[−1,2], δ_C(x)=0 trên C và +∞ ngoài C. Tính δ_C*(y) với y<0, y=0, y>0.`), [B('The supremum reduces to max of yx over the interval.', 'Supremum rút về max của yx trên đoạn.')], [B(String.raw`δ_C*(y)=sup_{x∈[−1,2]}yx. If y<0 the maximum is at x=−1 and equals −y; if y=0 it is 0; if y>0 it is 2y. This is the support function σ_C(y)=max{−y,2y}.`, String.raw`δ_C*(y)=sup_{x∈[−1,2]}yx. Nếu y<0, max ở x=−1 và bằng −y; nếu y=0 thì bằng 0; nếu y>0, bằng 2y. Đây là hàm support σ_C(y)=max{−y,2y}.`)], [R(1,'Restricts supremum to C.','Giới hạn supremum trên C.'),R(2,'Handles both signs at correct endpoints.','Xử lý hai dấu tại đúng đầu mút.'),R(1,'Names the support function.','Gọi đúng hàm support.')], [B('Chooses the right endpoint even when y is negative.', 'Chọn đầu mút phải dù y âm.')]),
      E(B('Conjugate of absolute value', 'Liên hợp trị tuyệt đối'), ['proof','derivation'], B(String.raw`Compute f*(y) for f(x)=|x| and prove why it is infinite outside the dual unit interval.`, String.raw`Tính f*(y) với f(x)=|x| và chứng minh vì sao liên hợp vô hạn ngoài đoạn đơn vị đối ngẫu.`), [B('Consider x→+∞ and x→−∞ separately.', 'Xét riêng x→+∞ và x→−∞.')], [B(String.raw`f*(y)=sup_x(yx−|x|). For x≥0 this is (y−1)x; for x≤0 it is (y+1)x. The supremum is 0 at x=0 when both slopes point downward, exactly −1≤y≤1. If y>1 the first term diverges as x→∞; if y<−1 the second diverges as x→−∞. Thus f*=δ_[−1,1].`, String.raw`f*(y)=sup_x(yx−|x|). Với x≥0 biểu thức là (y−1)x; với x≤0 là (y+1)x. Supremum bằng 0 tại x=0 khi hai hệ số hướng xuống, tức −1≤y≤1. Nếu y>1, hạng đầu tiến vô hạn khi x→∞; nếu y<−1, hạng sau tiến vô hạn khi x→−∞. Vậy f*=δ_[−1,1].`)], [R(1,'Splits positive and negative half-lines.','Tách nửa trục dương và âm.'),R(2,'Proves divergence outside the interval.','Chứng minh phân kỳ ngoài đoạn.'),R(1,'Gives the effective domain.','Nêu miền hiệu dụng.')], [B('Checks only a finite x-grid and misses an infinite supremum.', 'Chỉ kiểm tra lưới x hữu hạn và bỏ sót supremum vô hạn.')]),
      E(B('Transfer: Fenchel dual lower bound', 'Chuyển giao: cận dưới đối ngẫu Fenchel'), ['proof','transfer'], B('For arbitrary q derive f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q), showing both Fenchel–Young inequalities and cancellation.', 'Với q tùy ý suy f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q), nêu hai bất đẳng thức Fenchel–Young và phép triệt tiêu.'), [B('Apply Fenchel–Young to f at −Aᵀq and g at q.', 'Áp dụng Fenchel–Young cho f tại −Aᵀq và g tại q.')], [B('FY gives f(x)+f*(−Aᵀq)≥−qᵀAx, and g(Ax)+g*(q)≥qᵀAx. Add; the inner products cancel, yielding f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q). Infimum over x then supremum over q gives a weak-duality lower bound; equality requires additional attainment/qualification.', 'FY cho f(x)+f*(−Aᵀq)≥−qᵀAx, còn g(Ax)+g*(q)≥qᵀAx. Cộng lại, tích vô hướng triệt tiêu, được f(x)+g(Ax)≥−f*(−Aᵀq)−g*(q). Lấy inf theo x rồi sup theo q cho cận đối ngẫu yếu; dấu bằng cần điều kiện đạt/qualification thêm.')], [R(1,'Uses the correct adjoint argument.','Dùng đúng đối số toán tử liên hợp.'),R(2,'Writes both inequalities with correct signs.','Viết đúng dấu hai bất đẳng thức.'),R(1,'Cancels terms and states weak-duality scope.','Triệt hạng và nêu phạm vi đối ngẫu yếu.')], [B('Uses A instead of Aᵀ or loses the minus sign.','Dùng A thay Aᵀ hoặc mất dấu trừ.')]),
      E(B('Counterexample: conjugate domain matters', 'Phản ví dụ: miền liên hợp rất quan trọng'), ['counterexample','transfer'], B(String.raw`Take f=δ_[0,∞). Compute f*(y) and explain why replacing it by a finite quadratic penalty would change the dual feasible set.`, String.raw`Lấy f=δ_[0,∞). Tính f*(y) và giải thích vì sao thay bằng penalty quadratic hữu hạn sẽ đổi miền khả thi đối ngẫu.`), [B('The conjugate is the supremum of yx for x≥0.', 'Liên hợp là supremum yx trên x≥0.')], [B(String.raw`For y≤0, sup_{x≥0}yx=0; for y>0 it is +∞. Thus f*=δ_(−∞,0]. A finite quadratic conjugate penalty admits y>0 at finite cost, whereas the indicator forbids those dual values entirely; the two models are not equivalent.`, String.raw`Nếu y≤0 thì sup_{x≥0}yx=0; nếu y>0 thì bằng +∞. Vậy f*=δ_(−∞,0]. Một penalty quadratic hữu hạn cho phép y>0 với chi phí hữu hạn, còn indicator loại bỏ hẳn các giá trị đối ngẫu đó; hai mô hình không tương đương.`)], [R(1,'Gets the half-line domain.','Tìm đúng miền nửa trục.'),R(2,'Explains unboundedness for y>0.','Giải thích không bị chặn khi y>0.'),R(1,'Contrasts domains, not just formulas.','So sánh miền chứ không chỉ công thức.')], [B('Treats +∞ outside the primal set as zero.', 'Coi +∞ ngoài tập primal là 0.')]),
    ],
  },
  {
    week: 64, title: B('Constrained convex optimization and KKT', 'Tối ưu lồi có ràng buộc và KKT'), level: 'graduate core', prerequisites: [62, 63],
    outcomes: [B('Derive KKT stationarity, primal feasibility, dual feasibility and complementary slackness.', 'Suy ra dừng KKT, khả thi primal, khả thi đối ngẫu và bổ sung chặt.'), B('Prove KKT sufficiency and diagnose when constraint qualifications fail.', 'Chứng minh tính đủ của KKT và chẩn đoán khi điều kiện chuẩn thất bại.')],
    definitions: B(String.raw`Consider minimize f(x) subject to differentiable convex g_i(x)≤0 and affine Ax=b, with convex f,g_i. A KKT tuple (x*,λ*,ν*) has primal feasibility, λ*≥0, stationarity ∇f(x*)+Σλ_i*∇g_i(x*)+Aᵀν*=0, and λ_i*g_i(x*)=0. Slater means some point satisfies all inequalities strictly and Ax=b.`, String.raw`Xét min f(x) với g_i(x)≤0 khả vi lồi và Ax=b affine, f,g_i lồi. Bộ KKT (x*,λ*,ν*) thỏa khả thi primal, λ*≥0, dừng ∇f(x*)+Σλ_i*∇g_i(x*)+Aᵀν*=0, và λ_i*g_i(x*)=0. Slater nghĩa là tồn tại điểm thỏa nghiêm mọi bất đẳng thức và Ax=b.`),
    theoremTitle: B('KKT conditions are sufficient for global optimality', 'Điều kiện KKT đủ cho tối ưu toàn cục'),
    statement: B(String.raw`For the convex problem above, if a feasible x* and multipliers λ*≥0,ν* satisfy stationarity and complementary slackness, then x* is a global minimizer. Strict convexity of f makes it unique. Slater plus differentiability guarantees KKT multipliers at an optimum; this necessity direction is the separating-hyperplane theorem of Boyd §5.5 and is marked assumed.`, String.raw`Với bài toán lồi trên, nếu x* khả thi và các nhân tử λ*≥0,ν* thỏa dừng và bổ sung chặt thì x* là cực tiểu toàn cục. f lồi nghiêm cho nghiệm duy nhất. Slater cộng khả vi bảo đảm có nhân tử KKT tại nghiệm; chiều cần này dùng định lý siêu phẳng phân cách ở Boyd §5.5 và được ghi rõ là giả thiết.`),
    proof: B(String.raw`For any feasible y, convexity gives f(y)≥f(x*)+∇f(x*)ᵀ(y−x*). Substitute stationarity. The affine term ν*ᵀA(y−x*) vanishes because Ay=Ax*=b. For each i, −λ_i*∇g_i(x*)ᵀ(y−x*) is a lower bound contribution; convexity gives ∇g_i(x*)ᵀ(y−x*)≤g_i(y)−g_i(x*)≤−g_i(x*) since g_i(y)≤0. Hence −λ_i*∇g_iᵀ(y−x*)≥λ_i*g_i(x*)=0 by complementary slackness. Thus f(y)≥f(x*).`, String.raw`Với y khả thi bất kỳ, tính lồi cho f(y)≥f(x*)+∇f(x*)ᵀ(y−x*). Thay điều kiện dừng. Hạng affine ν*ᵀA(y−x*) bằng 0 vì Ay=Ax*=b. Với mỗi i, −λ_i*∇g_i(x*)ᵀ(y−x*) là phần cận dưới; tính lồi cho ∇g_i(x*)ᵀ(y−x*)≤g_i(y)−g_i(x*)≤−g_i(x*) vì g_i(y)≤0. Do đó −λ_i*∇g_iᵀ(y−x*)≥λ_i*g_i(x*)=0 theo bổ sung chặt. Suy ra f(y)≥f(x*).`), sourceId: 'o-boyd', section: '§5.5 (optimality conditions), §5.3 (Slater condition and strong duality).',
    workedExample: B(String.raw`Minimize ½(x−3)² subject to x≤1. Stationarity x−3+λ=0 and complementary slackness λ(x−1)=0. The solution is x*=1, λ*=2; feasibility and λ≥0 hold, so KKT certifies the optimum.`, String.raw`Tối thiểu hóa ½(x−3)² với x≤1. Dừng là x−3+λ=0, bổ sung chặt λ(x−1)=0. Nghiệm x*=1, λ*=2; khả thi và λ≥0 nên KKT chứng nhận tối ưu.`),
    failureCase: B(String.raw`Necessity can fail without a constraint qualification. Minimize f(x)=x subject to g(x)=x²≤0. The only feasible point x=0 is optimal, but ∇f(0)=1 and ∇g(0)=0, so no λ≥0 solves 1+λ·0=0. Strict Slater also fails.`, String.raw`Tính cần có thể thất bại nếu thiếu điều kiện chuẩn. Tối thiểu hóa f(x)=x với g(x)=x²≤0. Điểm khả thi duy nhất x=0 là tối ưu, nhưng ∇f(0)=1, ∇g(0)=0 nên không có λ≥0 thỏa 1+λ·0=0. Slater nghiêm cũng thất bại.`),
    topic: 'KKT; Slater; constraint qualification; complementary slackness', readingSection: '§5.3–5.5',
    exercises: [
      E(B('KKT for a one-sided quadratic', 'KKT cho quadratic một phía'), ['computation','application'], B(String.raw`Solve min ½(x+1)² subject to x≥0. Write all KKT conditions and verify the multiplier.`, String.raw`Giải min ½(x+1)² với x≥0. Viết đủ điều kiện KKT và kiểm tra nhân tử.`), [B('Write g(x)=−x≤0.', 'Viết g(x)=−x≤0.')], [B(String.raw`The unconstrained minimizer −1 is infeasible. At x*=0, g=0. Stationarity x+1−λ=0 gives λ=1≥0; complementary slackness holds. Convex KKT sufficiency proves x*=0 globally optimal.`, String.raw`Nghiệm không ràng buộc −1 không khả thi. Tại x*=0, g=0. Dừng x+1−λ=0 cho λ=1≥0; bổ sung chặt đúng. Tính đủ KKT lồi chứng minh x*=0 tối ưu toàn cục.`)], [R(1,'Uses correct inequality sign.','Dùng đúng dấu bất đẳng thức.'),R(2,'Solves stationarity and slackness.','Giải dừng và bổ sung chặt.'),R(1,'States sufficiency.','Nêu tính đủ.')], [B('Uses +λ for constraint −x≤0.', 'Dùng +λ cho ràng buộc −x≤0.')]),
      E(B('Prove the sufficiency argument', 'Chứng minh lập luận tính đủ'), ['proof'], B(String.raw`Fill in the KKT sufficiency proof for one inequality g(x)≤0 and equality Ax=b; identify precisely where convexity and λ≥0 enter.`, String.raw`Hoàn thiện chứng minh tính đủ KKT cho một bất đẳng thức g(x)≤0 và đẳng thức Ax=b; chỉ rõ nơi dùng tính lồi và λ≥0.`), [B('Use first-order convex lower bounds for f and g.', 'Dùng cận dưới bậc nhất lồi cho f và g.')], [B(String.raw`For feasible y, f(y)≥f(x*)+∇f(x*)ᵀ(y−x*). Substitute ∇f=−λ∇g−Aᵀν. The equality contribution vanishes. Convexity of g gives ∇g(x*)ᵀ(y−x*)≤g(y)−g(x*)≤−g(x*); multiplying by −λ with λ≥0 reverses the inequality to yield −λ∇gᵀ(y−x*)≥λg(x*)=0. Therefore f(y)≥f(x*).`, String.raw`Với y khả thi, f(y)≥f(x*)+∇f(x*)ᵀ(y−x*). Thay ∇f=−λ∇g−Aᵀν. Hạng đẳng thức triệt tiêu. Tính lồi của g cho ∇g(x*)ᵀ(y−x*)≤g(y)−g(x*)≤−g(x*); nhân với −λ, λ≥0, đảo chiều bất đẳng thức để có −λ∇gᵀ(y−x*)≥λg(x*)=0. Vì vậy f(y)≥f(x*).`)], [R(1,'Uses convex lower bound for objective.','Dùng cận dưới lồi cho mục tiêu.'),R(2,'Uses inequality direction and λ sign correctly.','Dùng đúng chiều bất đẳng thức và dấu λ.'),R(1,'Uses feasibility and slackness to finish.','Dùng khả thi và bổ sung chặt để kết luận.')], [B('Multiplying by a negative multiplier without reversing the inequality.', 'Nhân với hệ số âm nhưng không đảo chiều.')]),
      E(B('Active-set geometry', 'Hình học tập hoạt động'), ['derivation','application'], B(String.raw`Minimize ½||x−c||² with c=(2,−1) and constraints x₁≤1, x₂≥0. Identify the projection and KKT multipliers.`, String.raw`Tối thiểu hóa ½||x−c||² với c=(2,−1), ràng buộc x₁≤1, x₂≥0. Tìm phép chiếu và nhân tử KKT.`), [B('Project each coordinate onto its feasible half-line.', 'Chiếu từng tọa độ lên nửa trục khả thi.')], [B(String.raw`The feasible set is [−∞,1]×[0,∞), so projection is x*=(1,0). Write g₁=x₁−1, g₂=−x₂. Stationarity x*−c+λ₁(1,0)+λ₂(0,−1)=0 gives λ₁=1, λ₂=1; both constraints are active, multipliers nonnegative, and complementary slackness holds.`, String.raw`Tập khả thi là (−∞,1]×[0,∞), nên phép chiếu là x*=(1,0). Đặt g₁=x₁−1, g₂=−x₂. Dừng x*−c+λ₁(1,0)+λ₂(0,−1)=0 cho λ₁=1, λ₂=1; cả hai ràng buộc hoạt động, nhân tử không âm và bổ sung chặt đúng.`)], [R(1,'Finds coordinatewise projection.','Tìm phép chiếu từng tọa độ.'),R(2,'Computes both multipliers with signs.','Tính hai nhân tử đúng dấu.'),R(1,'Checks feasibility and slackness.','Kiểm tra khả thi và bổ sung chặt.')], [B('Treats x₂≥0 as x₂≤0.', 'Đổi x₂≥0 thành x₂≤0.')]),
      E(B('Transfer: constraint qualification failure', 'Chuyển giao: thất bại điều kiện chuẩn'), ['proof','counterexample','transfer'], B(String.raw`For min x subject to x²≤0, prove optimality directly, then show no KKT multiplier exists. Name the failed qualification and explain why KKT sufficiency is not contradicted.`, String.raw`Với min x sao cho x²≤0, chứng minh trực tiếp tối ưu rồi chỉ ra không có nhân tử KKT. Nêu điều kiện chuẩn thất bại và vì sao điều này không mâu thuẫn tính đủ KKT.`), [B('The feasible set collapses to {0}; evaluate the gradient of the constraint there.', 'Tập khả thi co về {0}; tính gradient ràng buộc tại đó.')], [B(String.raw`x²≤0 implies x=0, hence the only feasible point and minimizer is 0. KKT stationarity would require 1+λ(2x)=0 at 0, i.e. 1=0, impossible. Slater fails because x²<0 has no solution. KKT sufficiency says any KKT point is optimal; it does not promise that an optimum has multipliers without a qualification.`, String.raw`x²≤0 kéo theo x=0, nên 0 là điểm khả thi duy nhất và là nghiệm. Dừng KKT cần 1+λ(2x)=0 tại 0, tức 1=0, bất khả. Slater thất bại vì x²<0 vô nghiệm. KKT đủ khẳng định mọi điểm KKT đều tối ưu; định lý không hứa mọi nghiệm có nhân tử khi thiếu điều kiện chuẩn.`)], [R(1,'Proves feasible-set collapse and optimum.','Chứng minh tập khả thi co lại và nghiệm.'),R(2,'Shows multiplier equation impossible.','Chỉ ra phương trình nhân tử vô nghiệm.'),R(1,'Distinguishes sufficiency from necessity.','Phân biệt tính đủ với tính cần.')], [B('Claims the KKT sufficiency theorem requires Slater.', 'Cho rằng định lý tính đủ KKT cần Slater.')]),
      E(B('Counterexample: complementary slackness is not enough', 'Phản ví dụ: bổ sung chặt chưa đủ'), ['counterexample','transfer'], B(String.raw`Give a feasible point and nonnegative multiplier satisfying complementary slackness but not stationarity for a convex problem, and show that it is not optimal.`, String.raw`Cho điểm khả thi và nhân tử không âm thỏa bổ sung chặt nhưng không thỏa dừng trong bài toán lồi; chứng minh điểm đó không tối ưu.`), [B('Take unconstrained f(x)=(x−2)² and set λ=0; feasibility is vacuous.', 'Lấy f(x)=(x−2)² không ràng buộc và λ=0; khả thi là hiển nhiên.')], [B(String.raw`Write the redundant constraint g(x)=−1≤0 and choose x=0, λ=0. Feasibility and λg(x)=0 hold, but stationarity f′(0)=−4≠0. The objective at x=0 is 4 while at x=2 it is 0, so x=0 is not optimal. All KKT components, not only slackness, matter.`, String.raw`Viết ràng buộc thừa g(x)=−1≤0 và chọn x=0, λ=0. Khả thi và λg(x)=0 đúng nhưng dừng f′(0)=−4≠0. Mục tiêu tại x=0 bằng 4, còn tại x=2 bằng 0 nên x=0 không tối ưu. Cần đủ mọi thành phần KKT, không chỉ bổ sung chặt.`)], [R(1,'Constructs a convex feasible problem.','Dựng bài toán khả thi lồi.'),R(2,'Verifies slackness while violating stationarity.','Kiểm tra bổ sung chặt đúng nhưng dừng sai.'),R(1,'Exhibits strict objective improvement.','Đưa ra điểm có mục tiêu tốt hơn.')], [B('Forgets that a redundant inequality still has g≤0.', 'Quên rằng bất đẳng thức thừa vẫn phải thỏa g≤0.')]),
    ],
  },
  {
    week: 65, title: B('Lagrange duality and sensitivity', 'Đối ngẫu Lagrange và độ nhạy'), level: 'graduate core', prerequisites: [64],
    outcomes: [B('Construct the Lagrangian dual and prove weak duality with signs explicit.', 'Lập đối ngẫu Lagrange và chứng minh đối ngẫu yếu với dấu minh bạch.'), B('Apply Slater strong duality only under its convexity, feasibility and finiteness hypotheses.', 'Chỉ áp dụng đối ngẫu mạnh Slater khi đủ giả thiết lồi, khả thi và hữu hạn.')],
    definitions: B(String.raw`For min f₀(x) subject to f_i(x)≤0 and Ax=b, define L(x,λ,ν)=f₀(x)+Σλ_i f_i(x)+νᵀ(Ax−b), λ≥0. The dual function q(λ,ν)=inf_x L(x,λ,ν) is concave even if the primal is not. The dual maximizes q over λ≥0. A dual value is a lower bound on every feasible primal objective.`, String.raw`Với min f₀(x), f_i(x)≤0 và Ax=b, đặt L(x,λ,ν)=f₀(x)+Σλ_i f_i(x)+νᵀ(Ax−b), λ≥0. Hàm đối ngẫu q(λ,ν)=inf_x L(x,λ,ν) là hàm lõm kể cả khi primal không lồi. Dual cực đại hóa q với λ≥0. Giá trị dual là cận dưới của mọi giá trị mục tiêu primal khả thi.`),
    theoremTitle: B('Weak duality; Slater strong duality as a stated theorem', 'Đối ngẫu yếu; đối ngẫu mạnh Slater được phát biểu'),
    statement: B(String.raw`For any feasible primal x and any dual-feasible λ≥0, q(λ,ν)≤f₀(x), hence d*≤p*. If f₀,…,f_m are convex, equalities are affine, a strict Slater point exists, and the primal optimum is finite, then p*=d* and a dual optimum is attained. The second assertion is used as a sourced separation theorem, not reproved here.`, String.raw`Với x primal khả thi và λ≥0 khả thi dual bất kỳ, q(λ,ν)≤f₀(x), do đó d*≤p*. Nếu f₀,…,f_m lồi, ràng buộc đẳng thức affine, có điểm Slater nghiêm và tối ưu primal hữu hạn, thì p*=d* và nghiệm tối ưu dual đạt được. Mệnh đề thứ hai dùng định lý phân cách có nguồn, không chứng minh lại ở đây.`),
    proofStatus: 'assumed', proof: B(String.raw`For feasible x, each λ_i f_i(x)≤0 and νᵀ(Ax−b)=0, so L(x,λ,ν)≤f₀(x). Since q(λ,ν)=inf_z L(z,λ,ν)≤L(x,λ,ν), we get q≤f₀(x); infimizing over feasible x and maximizing over dual variables gives d*≤p*. The zero-gap/attainment statement is Slater's theorem (Boyd §5.3–5.5); its separation argument is outside this lesson's proof budget.`, String.raw`Với x khả thi, mỗi λ_i f_i(x)≤0 và νᵀ(Ax−b)=0 nên L(x,λ,ν)≤f₀(x). Vì q(λ,ν)=inf_z L(z,λ,ν)≤L(x,λ,ν), suy ra q≤f₀(x); lấy inf trên primal khả thi và sup trên biến dual được d*≤p*. Mệnh đề không có khoảng cách và đạt nghiệm là định lý Slater (Boyd §5.3–5.5); chứng minh phân cách vượt ngân sách tuần này.`), sourceId: 'o-boyd', section: '§5.1–5.6; weak duality proved; Slater theorem cited as assumed.',
    workedExample: B(String.raw`For min x² subject to x≥1, write g(x)=1−x≤0. L=x²+λ(1−x), and q(λ)=inf_x[x²−λx+λ]=λ−λ²/4, λ≥0. Its maximum occurs at λ=2 with value 1; primal x=1 has value 1, so the gap is zero and complementary slackness holds.`, String.raw`Với min x², x≥1, đặt g(x)=1−x≤0. L=x²+λ(1−x), q(λ)=inf_x[x²−λx+λ]=λ−λ²/4, λ≥0. Cực đại tại λ=2, giá trị 1; primal x=1 có giá trị 1 nên khoảng cách bằng 0 và bổ sung chặt đúng.`),
    failureCase: B(String.raw`Without convexity or a constraint qualification, the primal-dual gap can be positive. Weak duality never fails, but equality is not automatic; never infer strong duality merely because a numerical solver's values look close.`, String.raw`Không lồi hoặc thiếu điều kiện chuẩn có thể tạo khoảng cách primal-dual dương. Đối ngẫu yếu luôn đúng nhưng dấu bằng không tự động có; không suy ra đối ngẫu mạnh chỉ vì nghiệm số gần nhau.`),
    topic: 'Lagrangian dual; weak/strong duality; Slater; sensitivity interpretation', readingSection: '§5.1–5.6',
    exercises: [
      E(B('Dual of a constrained quadratic', 'Đối ngẫu quadratic có ràng buộc'), ['derivation','computation'], B(String.raw`For min ½x² subject to x≥2, derive q(λ), maximize it over λ≥0, and compare primal and dual values.`, String.raw`Với min ½x², x≥2, suy ra q(λ), cực đại trên λ≥0 rồi so sánh giá trị primal và dual.`), [B('Use g(x)=2−x and minimize the Lagrangian over x.', 'Dùng g(x)=2−x rồi tối thiểu hóa Lagrangian theo x.')], [B(String.raw`L=½x²+λ(2−x). Its minimizer is x=λ, so q(λ)=2λ−½λ² for λ≥0. q′=2−λ gives λ*=2 and q*=2. The primal minimizer is x=2 with p*=2; the gap is zero.`, String.raw`L=½x²+λ(2−x). Điểm cực tiểu theo x là x=λ, nên q(λ)=2λ−½λ² với λ≥0. q′=2−λ cho λ*=2, q*=2. Primal tối thiểu tại x=2, p*=2; khoảng cách bằng 0.`)], [R(1,'Forms L with correct sign.','Lập L đúng dấu.'),R(2,'Minimizes in x and optimizes λ.','Tối thiểu theo x rồi tối ưu λ.'),R(1,'Checks primal-dual equality.','Kiểm tra primal bằng dual.')], [B('Uses λ≤0 for an inequality written g≤0.', 'Dùng λ≤0 cho bất đẳng thức dạng g≤0.')]),
      E(B('Prove weak duality for equality constraints', 'Chứng minh đối ngẫu yếu với đẳng thức'), ['proof'], B(String.raw`Prove q(λ,ν)≤p* for λ≥0 for the problem with g_i(x)≤0 and Ax=b; explain why ν has no sign restriction.`, String.raw`Chứng minh q(λ,ν)≤p* với λ≥0 cho bài toán có g_i(x)≤0 và Ax=b; giải thích vì sao ν không bị ràng buộc dấu.`), [B('Evaluate L at an arbitrary primal-feasible x before taking the infimum.', 'Tính L tại x khả thi primal tùy ý trước khi lấy infimum.')], [B(String.raw`At feasible x, g_i(x)≤0 implies λ_i g_i(x)≤0, and Ax−b=0 removes the ν term for any real ν. Thus L(x,λ,ν)≤f₀(x). Since q is the infimum of L over all arguments, q≤L≤f₀(x). Infimizing f₀ over feasible x yields q≤p*. ν is unrestricted because equality makes its product exactly zero; its sign is not needed.`, String.raw`Tại x khả thi, g_i(x)≤0 suy ra λ_i g_i(x)≤0; Ax−b=0 triệt hạng ν với mọi ν thực. Vì vậy L(x,λ,ν)≤f₀(x). q là infimum của L nên q≤L≤f₀(x). Lấy inf f₀ trên tập khả thi cho q≤p*. ν tự do dấu vì hạng của nó bằng 0 tại điểm thỏa đẳng thức.`)], [R(1,'Uses λ≥0 with g_i≤0.','Dùng λ≥0 cùng g_i≤0.'),R(2,'Handles equality multiplier without a sign constraint.','Xử lý nhân tử đẳng thức không cần dấu.'),R(1,'Takes the correct infimum.','Lấy infimum đúng.')], [B('Claims the ν term is nonpositive for all ν.', 'Cho rằng hạng ν không dương với mọi ν.')]),
      E(B('Sensitivity from a value function', 'Độ nhạy từ hàm giá trị'), ['derivation','application'], B(String.raw`For p*(u)=min ½x² subject to x≥u with u>0, compute p*(u) and compare its derivative with the optimal multiplier.`, String.raw`Với p*(u)=min ½x², x≥u, u>0, tính p*(u) và so sánh đạo hàm với nhân tử tối ưu.`), [B('The constraint is active at x=u; differentiate the resulting value.', 'Ràng buộc hoạt động tại x=u; lấy đạo hàm hàm giá trị.')], [B(String.raw`The feasible minimizer is x*=u, so p*(u)=u²/2 and dp*/du=u. With g(x,u)=u−x≤0, stationarity x−λ=0 gives λ*=u. The marginal cost of tightening the lower bound equals the multiplier under this smooth active regime.`, String.raw`Nghiệm khả thi là x*=u nên p*(u)=u²/2 và dp*/du=u. Với g(x,u)=u−x≤0, điều kiện dừng x−λ=0 cho λ*=u. Chi phí biên khi siết cận dưới bằng nhân tử trong chế độ hoạt động trơn này.`)], [R(1,'Finds primal optimizer.','Tìm nghiệm primal.'),R(2,'Computes value and derivative.','Tính hàm giá trị và đạo hàm.'),R(1,'Matches multiplier with stated convention.','Khớp nhân tử theo quy ước đã nêu.')], [B('Gets the sign wrong because perturbation convention is unstated.', 'Sai dấu do không nêu quy ước nhiễu tham số.')]),
      E(B('Transfer: certify a lower bound without solving primal', 'Chuyển giao: chứng nhận cận dưới không giải primal'), ['proof','transfer'], B(String.raw`For any dual-feasible (λ,ν), prove that q(λ,ν) is a valid lower bound even if the primal optimizer is unknown. Then state what an equal feasible primal value certifies.`, String.raw`Với (λ,ν) khả thi dual bất kỳ, chứng minh q(λ,ν) là cận dưới hợp lệ dù chưa biết nghiệm primal; nêu ý nghĩa nếu có giá trị primal khả thi bằng nó.`), [B('Apply weak duality; equality brackets the optimum from both sides.', 'Áp dụng đối ngẫu yếu; dấu bằng kẹp tối ưu từ hai phía.')], [B(String.raw`Weak duality gives q(λ,ν)≤p*≤f₀(x) for every feasible x. If a feasible x has f₀(x)=q(λ,ν), then both inequalities are equalities, so x is primal optimal, (λ,ν) dual optimal, and the duality gap is zero. This certificate needs feasibility, not knowledge of how either candidate was found.`, String.raw`Đối ngẫu yếu cho q(λ,ν)≤p*≤f₀(x) với mọi x khả thi. Nếu có x khả thi với f₀(x)=q(λ,ν), cả hai bất đẳng thức thành đẳng thức; x tối ưu primal, (λ,ν) tối ưu dual và khoảng cách bằng 0. Chứng chỉ cần tính khả thi, không cần biết cách tìm ứng viên.`)], [R(1,'States the weak-duality sandwich.','Nêu chuỗi cận đối ngẫu yếu.'),R(2,'Uses feasibility of both candidates.','Dùng khả thi của hai ứng viên.'),R(1,'Concludes zero gap and optimality.','Kết luận khoảng cách 0 và tối ưu.')], [B('Treats an infeasible primal point as an upper certificate.', 'Coi điểm primal không khả thi là cận trên chứng nhận.')]),
      E(B('Counterexample: Slater can fail to deliver dual attainment', 'Phản ví dụ: thiếu Slater có thể làm nghiệm dual không đạt'), ['counterexample','transfer'], B(String.raw`For min −x subject to x²≤0, calculate the primal value and dual function. Show that p*=d* although no finite dual multiplier attains d*, and identify why this is not a positive-gap example.`, String.raw`Với min −x sao cho x²≤0, tính giá trị primal và hàm dual. Chỉ ra p*=d* dù không có nhân tử dual hữu hạn đạt d*, đồng thời giải thích đây không phải ví dụ khoảng cách dương.`), [B('The feasible set is a singleton; minimize −x+λx² over all real x.', 'Tập khả thi chỉ có một điểm; tối thiểu hóa −x+λx² trên R.')], [B(String.raw`Primal feasibility forces x=0, so p*=0. L=−x+λx². For λ>0, its infimum is −1/(4λ); for λ=0 it is −∞. Thus q(λ)=−1/(4λ) for λ>0 and q(0)=−∞. The dual supremum is 0 as λ→∞, so d*=0=p*, but no finite λ attains it. There is no value gap; the failed Slater condition illustrates loss of dual attainment, not failure of equality.`, String.raw`Khả thi primal buộc x=0 nên p*=0. L=−x+λx². Với λ>0, infimum là −1/(4λ); với λ=0 là −∞. Vậy q(λ)=−1/(4λ) khi λ>0 và q(0)=−∞. Supremum dual là 0 khi λ→∞, nên d*=0=p*, nhưng không nhân tử hữu hạn nào đạt được. Không có khoảng cách giá trị; Slater thất bại minh họa mất tính đạt nghiệm dual chứ không phải mất đẳng thức giá trị.`)], [R(1,'Finds primal value.','Tìm giá trị primal.'),R(2,'Computes q on λ≥0.','Tính q trên λ≥0.'),R(1,'Distinguishes zero gap from nonattainment.','Phân biệt khoảng cách 0 với không đạt nghiệm.')], [B('Calls a supremum that is not attained a positive gap.', 'Gọi supremum không đạt là khoảng cách dương.')]),
    ],
  },
  {
    week: 66, title: B('Smoothness, strong convexity, and gradient descent', 'Độ trơn, lồi mạnh và gradient descent'), level: 'graduate core', prerequisites: [61, 64],
    outcomes: [B('Derive the descent lemma from Lipschitz continuity of the gradient.', 'Suy ra bổ đề giảm từ tính Lipschitz của gradient.'), B('State step-size and smoothness assumptions before claiming monotone descent.', 'Nêu giả thiết bước học và độ trơn trước khi khẳng định giảm đơn điệu.')],
    definitions: B(String.raw`A differentiable f is L-smooth when ||∇f(x)−∇f(y)||≤L||x−y||. It is μ-strongly convex if f(y)≥f(x)+∇f(x)ᵀ(y−x)+(μ/2)||y−x||² for all x,y; this implies a unique minimizer when one exists. The descent lemma is a quadratic upper model, not a convexity assertion.`, String.raw`Hàm khả vi f là L-trơn nếu ||∇f(x)−∇f(y)||≤L||x−y||. Hàm μ-lồi mạnh nếu f(y)≥f(x)+∇f(x)ᵀ(y−x)+(μ/2)||y−x||² với mọi x,y; tính này kéo theo nghiệm duy nhất nếu nghiệm tồn tại. Bổ đề giảm là mô hình chặn trên quadratic, không phải khẳng định lồi.`),
    theoremTitle: B('Descent lemma and a safe gradient step', 'Bổ đề giảm và bước gradient an toàn'),
    statement: B(String.raw`If f has L-Lipschitz gradient on R^d, then f(y)≤f(x)+∇f(x)ᵀ(y−x)+(L/2)||y−x||². Consequently for x⁺=x−(1/L)∇f(x), f(x⁺)≤f(x)−(1/(2L))||∇f(x)||².`, String.raw`Nếu gradient của f Lipschitz hằng L trên R^d thì f(y)≤f(x)+∇f(x)ᵀ(y−x)+(L/2)||y−x||². Vì thế với x⁺=x−(1/L)∇f(x), f(x⁺)≤f(x)−(1/(2L))||∇f(x)||².`),
    proof: B(String.raw`Let d=y−x and φ(t)=f(x+td). The fundamental theorem of calculus gives f(y)−f(x)−∇f(x)ᵀd=∫₀¹[∇f(x+td)−∇f(x)]ᵀd dt. By Cauchy–Schwarz and L-smoothness, the integrand is at most Lt||d||²; integration gives (L/2)||d||². Substitute d=−∇f(x)/L: the linear term is −||∇f||²/L and the quadratic term is ||∇f||²/(2L), yielding the claim.`, String.raw`Đặt d=y−x, φ(t)=f(x+td). Định lý cơ bản của giải tích cho f(y)−f(x)−∇f(x)ᵀd=∫₀¹[∇f(x+td)−∇f(x)]ᵀd dt. Cauchy–Schwarz và L-trơn chặn tích phân bởi ∫₀¹Lt||d||²dt=(L/2)||d||². Thay d=−∇f(x)/L: hạng tuyến tính là −||∇f||²/L, hạng quadratic là ||∇f||²/(2L), suy ra kết luận.`), sourceId: 'o-boyd', section: '§9.1–9.2 (gradient descent, smoothness and convergence).',
    workedExample: B(String.raw`For f(x)=½ax², a>0, L=a. The step x⁺=x−f′(x)/a=0 reaches the minimizer in one update; the certified decrease is f(x)−f(x⁺)=½ax²=|f′(x)|²/(2a), equality in the descent lemma.`, String.raw`Với f(x)=½ax², a>0, L=a. Bước x⁺=x−f′(x)/a=0 đến nghiệm chỉ sau một lần; mức giảm được chứng nhận là f(x)−f(x⁺)=½ax²=|f′(x)|²/(2a), đạt dấu bằng bổ đề giảm.`),
    failureCase: B(String.raw`If η>2/L, even the scalar quadratic f(x)=Lx²/2 can increase: x⁺=(1−ηL)x and f(x⁺)>f(x) whenever |1−ηL|>1. Smoothness is not a license for arbitrary step size.`, String.raw`Nếu η>2/L, ngay quadratic f(x)=Lx²/2 có thể tăng: x⁺=(1−ηL)x và f(x⁺)>f(x) khi |1−ηL|>1. Độ trơn không cho phép tùy ý chọn bước học.`),
    topic: 'L-smoothness; descent lemma; gradient steps; strong convexity', readingSection: '§9.1–9.2, §9.6',
    exercises: [
      E(B('Compute the descent certificate', 'Tính chứng chỉ giảm'), ['computation'], B(String.raw`For f(x)=3x²−6x, use L=6 and the 1/L step from x₀=0. Compute x₁, f(x₀), f(x₁), and the theorem's guaranteed decrease.`, String.raw`Với f(x)=3x²−6x, dùng L=6 và bước 1/L tại x₀=0. Tính x₁, f(x₀), f(x₁) và mức giảm bảo đảm.`), [B('The derivative is 6x−6.', 'Đạo hàm là 6x−6.')], [B(String.raw`∇f(0)=−6, so x₁=0−(1/6)(−6)=1. f(0)=0 and f(1)=−3, actual decrease 3. The certificate gives |∇f(0)|²/(2L)=36/12=3, tight here.`, String.raw`∇f(0)=−6 nên x₁=0−(1/6)(−6)=1. f(0)=0, f(1)=−3, mức giảm thực 3. Chứng chỉ cho |∇f(0)|²/(2L)=36/12=3, đạt dấu bằng.`)], [R(1,'Computes gradient and update.','Tính gradient và bước cập nhật.'),R(2,'Evaluates both objective values.','Tính hai giá trị mục tiêu.'),R(1,'Computes guaranteed decrease.','Tính đúng mức giảm bảo đảm.')], [B('Confuses gradient norm with its square.', 'Nhầm chuẩn gradient với bình phương chuẩn.')]),
      E(B('Derive the descent lemma', 'Suy ra bổ đề giảm'), ['proof'], B(String.raw`Starting from the path φ(t)=f(x+t(y−x)), derive the smoothness upper bound and name the inequality that controls the integral.`, String.raw`Từ đường φ(t)=f(x+t(y−x)), suy ra cận trên độ trơn và nêu bất đẳng thức chặn tích phân.`), [B('Integrate the derivative and use Cauchy–Schwarz.', 'Tích phân đạo hàm và dùng Cauchy–Schwarz.')], [B(String.raw`With d=y−x, FTC gives the remainder ∫₀¹(∇f(x+td)−∇f(x))ᵀd dt. Cauchy–Schwarz bounds the integrand by ||∇f(x+td)−∇f(x)||||d||≤Lt||d||². Integrating t from 0 to 1 yields (L/2)||d||², proving the stated bound.`, String.raw`Với d=y−x, FTC cho phần dư ∫₀¹(∇f(x+td)−∇f(x))ᵀd dt. Cauchy–Schwarz chặn tích phân bởi ||∇f(x+td)−∇f(x)||||d||≤Lt||d||². Tích phân t từ 0 đến 1 được (L/2)||d||², chứng minh cận đã nêu.`)], [R(1,'Applies the chain rule along the segment.','Áp dụng quy tắc dây chuyền trên đoạn.'),R(2,'Uses Lipschitz and Cauchy–Schwarz with correct t.','Dùng Lipschitz và Cauchy–Schwarz đúng hệ số t.'),R(1,'Integrates to L/2.','Tích phân ra L/2.')], [B('Integrates the constant L||d||² and gets L instead of L/2.', 'Tích phân hằng L||d||² và nhận L thay vì L/2.')]),
      E(B('Strong convexity condition number', 'Số điều kiện dưới lồi mạnh'), ['derivation','application'], B(String.raw`For f(x)=½xᵀQx with Q=diag(1,9), find μ,L and κ=L/μ. What geometric consequence does κ=9 have for gradient progress?`, String.raw`Với f(x)=½xᵀQx, Q=diag(1,9), tìm μ,L, κ=L/μ. κ=9 hàm ý hình học gì đối với tiến triển gradient?`), [B('For a quadratic, the Hessian eigenvalue extremes determine μ and L.', 'Với quadratic, trị riêng cực trị Hessian quyết định μ và L.')], [B(String.raw`The Hessian is Q, so μ=λ_min=1 and L=λ_max=9; κ=9. The level sets are ellipses stretched by a factor √9=3 across principal axes. A scalar step must accommodate the steep direction while the shallow direction advances more slowly; conditioning controls the linear-rate factor, not just arithmetic scale.`, String.raw`Hessian là Q nên μ=λ_min=1, L=λ_max=9; κ=9. Đường mức là ellipse kéo dài theo các trục chính với tỷ lệ √9=3. Bước vô hướng phải phù hợp hướng dốc, khiến hướng nông tiến chậm hơn; điều kiện hóa điều khiển hệ số hội tụ tuyến tính, không chỉ thang số học.`)], [R(1,'Finds eigenvalue extremes.','Tìm trị riêng cực trị.'),R(1,'Computes κ.','Tính κ.'),R(2,'Interprets anisotropic progress.','Diễn giải tiến triển dị hướng.')], [B('Uses the average eigenvalue as the condition number.', 'Dùng trị riêng trung bình làm số điều kiện.')]),
      E(B('Transfer: prove a linear contraction', 'Chuyển giao: chứng minh co tuyến tính'), ['proof','transfer'], B(String.raw`Let f be μ-strongly convex and L-smooth with minimizer x*. For exact gradient descent step η=1/L, prove ||x₁−x*||≤(1−μ/L)||x₀−x*|| using the Hessian argument for a twice-differentiable quadratic; state the extra restriction needed for the factor to be nonnegative.`, String.raw`Cho f μ-lồi mạnh, L-trơn, có nghiệm x*. Với bước gradient chính xác η=1/L, chứng minh ||x₁−x*||≤(1−μ/L)||x₀−x*|| bằng lập luận Hessian cho quadratic khả vi hai lần; nêu điều kiện thêm để hệ số không âm.`), [B('For quadratic Q, the update matrix is I−Q/L.', 'Với quadratic Q, ma trận cập nhật là I−Q/L.')], [B(String.raw`For f(x)=½(x−x*)ᵀQ(x−x*) with μI⪯Q⪯LI, x₁−x*=(I−Q/L)(x₀−x*). The eigenvalues of I−Q/L lie in [0,1−μ/L], so its operator norm is at most 1−μ/L and the bound follows. The interval is nonnegative because μ≤L. For a general smooth strongly convex function, the same contraction requires a separate Hessian/integral argument and appropriate differentiability; this exercise proves the quadratic case only.`, String.raw`Với f(x)=½(x−x*)ᵀQ(x−x*), μI⪯Q⪯LI, ta có x₁−x*=(I−Q/L)(x₀−x*). Trị riêng I−Q/L thuộc [0,1−μ/L], nên chuẩn toán tử không quá 1−μ/L và suy ra cận. Khoảng này không âm vì μ≤L. Với hàm tổng quát, cần lập luận Hessian/tích phân riêng và khả vi phù hợp; bài này chỉ chứng minh trường hợp quadratic.`)], [R(1,'Writes the update error exactly.','Viết chính xác sai số sau cập nhật.'),R(2,'Bounds eigenvalues and operator norm.','Chặn trị riêng và chuẩn toán tử.'),R(1,'Limits conclusion to proved scope.','Giới hạn kết luận đúng phạm vi đã chứng minh.')], [B('Claims the quadratic proof covers all nonsmooth functions.', 'Cho rằng chứng minh quadratic áp dụng mọi hàm không trơn.')]),
      E(B('Counterexample: oversized steps oscillate and grow', 'Phản ví dụ: bước quá lớn gây dao động và tăng'), ['counterexample','numerical analysis'], B(String.raw`For f(x)=½x², analyze gradient descent with η=2.2 from x₀=1. Compute x₁,x₂ and show objective growth.`, String.raw`Với f(x)=½x², phân tích gradient descent η=2.2 từ x₀=1. Tính x₁,x₂ và chứng minh mục tiêu tăng.`), [B('The scalar recurrence is xₙ₊₁=(1−η)xₙ.', 'Truy hồi vô hướng là xₙ₊₁=(1−η)xₙ.')], [B(String.raw`Here xₙ₊₁=−1.2xₙ, so x₁=−1.2 and x₂=1.44. f(x₁)=.72>.5=f(x₀), and f(x₂)=1.0368>.72. The sign alternates while magnitude grows because |1−η|=1.2>1; smoothness alone does not ensure descent.`, String.raw`Ở đây xₙ₊₁=−1.2xₙ nên x₁=−1.2, x₂=1.44. f(x₁)=.72>.5=f(x₀), f(x₂)=1.0368>.72. Dấu luân phiên trong khi biên độ tăng vì |1−η|=1.2>1; độ trơn không tự bảo đảm giảm.`)], [R(1,'Computes recurrence.','Tính truy hồi.'),R(2,'Computes two iterates and losses.','Tính hai lần lặp và loss.'),R(1,'Explains stability threshold.','Giải thích ngưỡng ổn định.')], [B('Uses x⁺=(1−ηL/2)x.', 'Dùng công thức cập nhật sai x⁺=(1−ηL/2)x.')]),
    ],
  },
  {
    week: 67, title: B('Proximal maps and proximal gradient', 'Ánh xạ proximal và proximal gradient'), level: 'graduate core', prerequisites: [62, 63, 66],
    outcomes: [B('Derive the proximal optimality condition from a strongly convex subproblem.', 'Suy ra điều kiện tối ưu proximal từ bài toán con lồi mạnh.'), B('Prove firm nonexpansiveness and derive soft thresholding.', 'Chứng minh không giãn vững và suy ra ngưỡng mềm.')],
    definitions: B(String.raw`For proper lower-semicontinuous convex h and γ>0, prox_{γh}(v)=argmin_x {h(x)+(1/(2γ))||x−v||²}. The quadratic makes the objective strongly convex; its minimizer is unique. The optimality condition is (v−x)/γ∈∂h(x).`, String.raw`Với h lồi proper nửa liên tục dưới và γ>0, prox_{γh}(v)=argmin_x {h(x)+(1/(2γ))||x−v||²}. Hạng quadratic làm mục tiêu lồi mạnh nên nghiệm duy nhất. Điều kiện tối ưu là (v−x)/γ∈∂h(x).`),
    theoremTitle: B('Proximal maps are firmly nonexpansive', 'Ánh xạ proximal không giãn vững'),
    statement: B(String.raw`For x=prox_{γh}(u), y=prox_{γh}(v), one has ||x−y||²≤(x−y)ᵀ(u−v); hence ||prox(u)−prox(v)||≤||u−v||.`, String.raw`Với x=prox_{γh}(u), y=prox_{γh}(v), ta có ||x−y||²≤(x−y)ᵀ(u−v); do đó ||prox(u)−prox(v)||≤||u−v||.`),
    proof: B(String.raw`Optimality gives (u−x)/γ∈∂h(x) and (v−y)/γ∈∂h(y). The subdifferential of a convex function is monotone: for a∈∂h(x), b∈∂h(y), the two support inequalities add to (a−b)ᵀ(x−y)≥0. Substitute a,b: (u−v−x+y)ᵀ(x−y)≥0, so ||x−y||²≤(x−y)ᵀ(u−v). Cauchy–Schwarz yields nonexpansiveness (including x=y).`, String.raw`Điều kiện tối ưu cho (u−x)/γ∈∂h(x), (v−y)/γ∈∂h(y). Dưới vi phân của hàm lồi đơn điệu: với a∈∂h(x), b∈∂h(y), cộng hai bất đẳng thức support được (a−b)ᵀ(x−y)≥0. Thay a,b: (u−v−x+y)ᵀ(x−y)≥0, tức ||x−y||²≤(x−y)ᵀ(u−v). Cauchy–Schwarz cho không giãn (kể cả x=y).`), sourceId: 'o-prox', section: '§2.1–2.3 (definition, optimality and firm nonexpansiveness).',
    workedExample: B(String.raw`For h(x)=λ|x|, minimize λ|x|+(x−v)²/(2γ). If v>γλ, the positive-region derivative gives x=v−γλ; if v<−γλ, x=v+γλ; otherwise x=0. Thus prox is soft-threshold S_{γλ}(v)=sign(v)(|v|−γλ)_+.`, String.raw`Với h(x)=λ|x|, tối thiểu hóa λ|x|+(x−v)²/(2γ). Nếu v>γλ, đạo hàm miền dương cho x=v−γλ; nếu v<−γλ, x=v+γλ; còn lại x=0. Do đó prox là ngưỡng mềm S_{γλ}(v)=sign(v)(|v|−γλ)_+.`),
    failureCase: B(String.raw`If h is nonconvex, the subdifferential need not be monotone and the proximal subproblem may have multiple minimizers; the nonexpansive proof no longer follows. For ℓ1 regularization the threshold is γλ, not λ unless γ=1.`, String.raw`Nếu h không lồi, dưới vi phân không nhất thiết đơn điệu và bài toán proximal có thể có nhiều nghiệm; chứng minh không giãn không còn áp dụng. Với phạt ℓ1, ngưỡng là γλ, không phải λ trừ khi γ=1.`),
    topic: 'proximal map; firm nonexpansiveness; soft threshold; proximal gradient', readingSection: 'Parikh & Boyd §§2–4',
    exercises: [
      E(B('Soft-threshold coordinates', 'Ngưỡng mềm theo tọa độ'), ['computation'], B(String.raw`Compute prox_{γλ||·||₁}(v) for v=(3,−0.5,−4), γ=.5, λ=2.`, String.raw`Tính prox_{γλ||·||₁}(v) với v=(3,−0.5,−4), γ=.5, λ=2.`), [B('The threshold equals γλ=1.', 'Ngưỡng bằng γλ=1.')], [B(String.raw`Apply sign(v_j)(|v_j|−1)_+ coordinatewise: (2,0,−3). The middle coordinate is thresholded to zero because |−.5|≤1.`, String.raw`Áp dụng sign(v_j)(|v_j|−1)_+ theo từng tọa độ: (2,0,−3). Tọa độ giữa thành 0 vì |−.5|≤1.`)], [R(1,'Computes threshold.','Tính ngưỡng.'),R(2,'Applies all three coordinates.','Áp dụng đủ ba tọa độ.'),R(1,'Identifies zeroing condition.','Nêu điều kiện bị triệt tiêu.')], [B('Forgets to multiply λ by γ.', 'Quên nhân λ với γ.')]),
      E(B('Derive the proximal optimality condition', 'Suy ra điều kiện tối ưu proximal'), ['proof','derivation'], B(String.raw`For differentiable convex h, derive x=prox_{γh}(v) iff v−x=γ∇h(x); then rewrite the statement for nonsmooth h using ∂h.`, String.raw`Với h lồi khả vi, suy ra x=prox_{γh}(v) khi và chỉ khi v−x=γ∇h(x); rồi viết lại cho h không trơn bằng ∂h.`), [B('Set the derivative of the proximal objective to zero.', 'Cho đạo hàm mục tiêu proximal bằng không.')], [B(String.raw`The objective is h(x)+||x−v||²/(2γ), whose gradient is ∇h(x)+(x−v)/γ. Setting it to zero gives v−x=γ∇h(x). For proper closed convex nonsmooth h, the exact convex optimality condition replaces ∇h(x) with a subgradient: (v−x)/γ∈∂h(x).`, String.raw`Mục tiêu h(x)+||x−v||²/(2γ) có gradient ∇h(x)+(x−v)/γ. Cho bằng 0 được v−x=γ∇h(x). Với h lồi đóng proper không trơn, điều kiện tối ưu lồi thay ∇h(x) bằng dưới gradient: (v−x)/γ∈∂h(x).`)], [R(1,'Differentiates the quadratic term correctly.','Lấy đạo hàm hạng quadratic đúng.'),R(2,'Rearranges with correct γ scaling.','Biến đổi đúng hệ số γ.'),R(1,'States nonsmooth inclusion.','Nêu bao hàm không trơn.')], [B('Uses γ∇h=(x−v) with the wrong sign.', 'Dùng sai dấu γ∇h=(x−v).')]),
      E(B('Prove firm nonexpansiveness', 'Chứng minh không giãn vững'), ['proof'], B(String.raw`Starting only from the two proximal optimality inclusions and the subgradient inequality, prove ||prox(u)−prox(v)||²≤(prox(u)−prox(v))ᵀ(u−v).`, String.raw`Chỉ dùng hai bao hàm tối ưu proximal và bất đẳng thức dưới gradient, chứng minh ||prox(u)−prox(v)||²≤(prox(u)−prox(v))ᵀ(u−v).`), [B('Add the supporting inequalities for the two subgradients.', 'Cộng hai bất đẳng thức support của hai dưới gradient.')], [B(String.raw`Let x=prox(u), y=prox(v); a=(u−x)/γ∈∂h(x), b=(v−y)/γ∈∂h(y). Add h(y)≥h(x)+aᵀ(y−x) and h(x)≥h(y)+bᵀ(x−y): (a−b)ᵀ(x−y)≥0. Substitute and multiply by γ>0 to obtain (u−v−x+y)ᵀ(x−y)≥0, which rearranges to the target inequality.`, String.raw`Đặt x=prox(u), y=prox(v); a=(u−x)/γ∈∂h(x), b=(v−y)/γ∈∂h(y). Cộng h(y)≥h(x)+aᵀ(y−x) và h(x)≥h(y)+bᵀ(x−y) được (a−b)ᵀ(x−y)≥0. Thay vào và nhân γ>0 được (u−v−x+y)ᵀ(x−y)≥0, biến đổi thành bất đẳng thức cần chứng minh.`)], [R(1,'Writes optimality inclusions.','Viết đúng bao hàm tối ưu.'),R(2,'Derives monotonicity by adding supports.','Suy ra đơn điệu bằng cách cộng support.'),R(1,'Rearranges to firm inequality.','Biến đổi ra bất đẳng thức không giãn vững.')], [B('Subtracts the two support inequalities in the same direction.', 'Trừ hai support cùng chiều thay vì cộng triệt tiêu.')]),
      E(B('Transfer: prox for a half-line indicator', 'Chuyển giao: prox của hàm chỉ thị nửa trục'), ['derivation','transfer'], B(String.raw`For h=δ_[0,∞), find prox_{γh}(v) and verify the subgradient inclusion both when v≥0 and v<0.`, String.raw`Với h=δ_[0,∞), tìm prox_{γh}(v) và kiểm tra bao hàm dưới gradient khi v≥0 và v<0.`), [B('The proximal map is Euclidean projection; inspect the normal cone at zero.', 'Prox là phép chiếu Euclid; xét nón pháp tuyến tại 0.')], [B(String.raw`The minimization is projection of v onto [0,∞), so prox(v)=max(v,0). If v≥0, x=v and (v−x)/γ=0∈∂δ_C(x). If v<0, x=0 and v/γ<0; the subdifferential of the indicator at 0 is the normal cone (−∞,0], so the inclusion holds.`, String.raw`Bài toán là chiếu v lên [0,∞), nên prox(v)=max(v,0). Nếu v≥0, x=v và (v−x)/γ=0∈∂δ_C(x). Nếu v<0, x=0 và v/γ<0; dưới vi phân của indicator tại 0 là nón pháp tuyến (−∞,0], nên bao hàm đúng.`)], [R(1,'Recognizes projection.','Nhận ra phép chiếu.'),R(2,'Checks interior case.','Kiểm tra trường hợp trong.'),R(1,'Checks boundary normal cone.','Kiểm tra nón pháp tuyến ở biên.')], [B('Says the indicator subgradient at the boundary is {0}.', 'Cho rằng dưới vi phân indicator ở biên chỉ là {0}.')]),
      E(B('Counterexample: a nonconvex prox can be set-valued', 'Phản ví dụ: proximal không lồi có thể đa trị'), ['counterexample','transfer'], B(String.raw`Let h(x)=−|x| and γ=1. For v=0, minimize h(x)+x²/2. Find all minimizers and explain which convex proof step fails.`, String.raw`Cho h(x)=−|x|, γ=1. Với v=0, tối thiểu hóa h(x)+x²/2. Tìm mọi nghiệm và giải thích bước nào trong chứng minh lồi thất bại.`), [B('Complete the square separately for x≥0 and x≤0.', 'Hoàn thành bình phương riêng cho x≥0 và x≤0.')], [B(String.raw`For x≥0, objective −x+x²/2=(x−1)²/2−1/2, minimized at x=1. For x≤0, it is x+x²/2=(x+1)²/2−1/2, minimized at x=−1. The proximal set is {−1,1}, so the map is not single-valued. h is nonconvex; monotonicity of ∂h, the key firm-nonexpansiveness step, fails.`, String.raw`Với x≥0, mục tiêu −x+x²/2=(x−1)²/2−1/2 đạt min tại x=1. Với x≤0, mục tiêu x+x²/2=(x+1)²/2−1/2 đạt min tại x=−1. Tập proximal là {−1,1}, nên ánh xạ không đơn trị. h không lồi; tính đơn điệu của ∂h, bước then chốt cho không giãn vững, thất bại.`)], [R(1,'Optimizes each half-line.','Tối ưu trên từng nửa trục.'),R(2,'Finds both minimizers.','Tìm cả hai nghiệm.'),R(1,'Names monotonicity failure.','Nêu thất bại tính đơn điệu.')], [B('Chooses one minimizer and ignores the other.', 'Chọn một nghiệm rồi bỏ qua nghiệm còn lại.')]),
    ],
  },
  {
    week: 68, title: B('Projected stochastic gradients and noise', 'Gradient ngẫu nhiên có chiếu và nhiễu'), level: 'graduate core', prerequisites: [66, 67, 60],
    outcomes: [B('Prove the finite-horizon expected regret bound for projected SGD.', 'Chứng minh cận regret kỳ vọng hữu hạn cho SGD có chiếu.'), B('Separate conditional unbiasedness, bounded variance and bounded domain.', 'Phân biệt không chệch có điều kiện, phương sai bị chặn và miền bị chặn.')],
    definitions: B(String.raw`Let C be closed convex with diameter D, and let f be convex and differentiable on an open convex neighborhood of C. At x_t observe g_t with E[g_t|F_t]=∇f(x_t) and E[||g_t||²|F_t]≤G². Projected SGD is x_{t+1}=Π_C(x_t−ηg_t). Projection is nonexpansive and x*∈C.`, String.raw`Cho C đóng lồi có đường kính D, f lồi và khả vi trên một lân cận mở lồi của C. Tại x_t quan sát g_t với E[g_t|F_t]=∇f(x_t), E[||g_t||²|F_t]≤G². SGD có chiếu là x_{t+1}=Π_C(x_t−ηg_t). Phép chiếu không giãn và x*∈C.`),
    theoremTitle: B('Expected regret bound for projected SGD', 'Cận regret kỳ vọng của SGD có chiếu'),
    statement: B(String.raw`Assume C is closed convex with diameter D and f is convex and differentiable on an open convex neighborhood of C. For any x*∈C, T updates and η>0, if E[g_t|F_t]=∇f(x_t) and E[||g_t||²|F_t]≤G², then E[Σ_{t=1}^T(f(x_t)−f(x*))]≤D²/(2η)+ηG²T/2. Thus the average iterate has expected excess at most D²/(2ηT)+ηG²/2.`, String.raw`Giả sử C đóng lồi có đường kính D và f lồi, khả vi trên một lân cận mở lồi của C. Với x*∈C, T bước và η>0, nếu E[g_t|F_t]=∇f(x_t), E[||g_t||²|F_t]≤G² thì E[Σ_{t=1}^T(f(x_t)−f(x*))]≤D²/(2η)+ηG²T/2. Vì vậy iterate trung bình có excess kỳ vọng không quá D²/(2ηT)+ηG²/2.`),
    proof: B(String.raw`Projection and x*∈C give ||x_{t+1}−x*||²≤||x_t−ηg_t−x*||²=||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||². Rearrange and sum: Σg_tᵀ(x_t−x*)≤D²/(2η)+ηΣ||g_t||²/2. Convexity gives f(x_t)−f(x*)≤∇f(x_t)ᵀ(x_t−x*). Conditional expectation replaces g_t by ∇f(x_t); use the conditional second-moment bound and take expectation. Divide by T; convexity also bounds f of the averaged iterate by the average risks.`, String.raw`Tính không giãn của phép chiếu và x*∈C cho ||x_{t+1}−x*||²≤||x_t−ηg_t−x*||²=||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||². Chuyển vế rồi cộng theo t: Σg_tᵀ(x_t−x*)≤D²/(2η)+ηΣ||g_t||²/2. Tính lồi cho f(x_t)−f(x*)≤∇f(x_t)ᵀ(x_t−x*). Lấy kỳ vọng có điều kiện thay g_t bằng ∇f(x_t), dùng cận moment rồi lấy kỳ vọng. Chia T; tính lồi còn chặn rủi ro tại iterate trung bình bởi trung bình rủi ro.`), sourceId: 'o-hazan', section: 'Ch. 2–4 (online gradient descent); the projected stochastic version is proved here.',
    workedExample: B(String.raw`On C=[0,1], let f(x)=x and x*=0, deterministic g=1, x₁=1, η=.25, T=4. Iterates are 1,.75,.5,.25 and regret sum 2.5. With D=1,G=1, the bound is 1/(.5)+.25·4/2=2.5, tight for this horizon.`, String.raw`Trên C=[0,1], f(x)=x, x*=0, g=1 xác định, x₁=1, η=.25, T=4. Các iterate là 1,.75,.5,.25 và tổng regret 2.5. Với D=1,G=1, cận là 1/.5+.25·4/2=2.5, đạt dấu bằng ở chân trời này.`),
    failureCase: B(String.raw`If gradients have no finite second moment or the domain is unbounded, the displayed finite bound may be infinite. If g_t is biased conditional on F_t, the cross term no longer equals the population gradient pairing; an unreported bias term must be controlled.`, String.raw`Nếu gradient không có moment bậc hai hữu hạn hoặc miền không bị chặn, cận hữu hạn trên có thể thành vô hạn. Nếu g_t chệch theo F_t, hạng chéo không còn bằng tích gradient population; phải kiểm soát hạng bias chưa được ghi.`),
    topic: 'projected SGD; stochastic oracle assumptions; expected regret', readingSection: 'Hazan Ch. 2–4; Boyd §9.3 for stochastic gradient context',
    exercises: [
      E(B('Choose the regret-optimal constant step', 'Chọn bước hằng tối ưu regret'), ['computation','derivation'], B(String.raw`Given D=3, G=2, T=100, minimize the stated bound over η>0 and compute the resulting average excess bound.`, String.raw`Cho D=3, G=2, T=100, tối thiểu hóa cận trên theo η>0 rồi tính cận excess trung bình.`), [B('Balance D²/(2η) and ηG²T/2.', 'Cân bằng D²/(2η) và ηG²T/2.')], [B(String.raw`Differentiate −D²/(2η²)+G²T/2=0, giving η*=D/(G√T)=3/20=.15. The total bound is DG√T=60; divided by T gives .6.`, String.raw`Lấy đạo hàm −D²/(2η²)+G²T/2=0 được η*=D/(G√T)=3/20=.15. Cận tổng là DG√T=60; chia T được .6.`)], [R(1,'Finds positive optimizer η*.','Tìm η* dương.'),R(2,'Evaluates total bound.','Tính cận tổng.'),R(1,'Divides by T for average.','Chia T ra cận trung bình.')], [B('Uses D/(GT) instead of D/(G√T).', 'Dùng D/(GT) thay cho D/(G√T).')]),
      E(B('Derive the one-step potential inequality', 'Suy ra bất đẳng thức thế một bước'), ['proof'], B(String.raw`Prove ||Π_C(z)−x*||≤||z−x*|| for x*∈C from the projection variational inequality, then expand the squared distance for z=x_t−ηg_t.`, String.raw`Từ bất đẳng thức biến phân của phép chiếu, chứng minh ||Π_C(z)−x*||≤||z−x*|| với x*∈C, rồi khai triển khoảng cách bình phương cho z=x_t−ηg_t.`), [B('Use ⟨z−Π_C(z), x*−Π_C(z)⟩≤0.', 'Dùng ⟨z−Π_C(z), x*−Π_C(z)⟩≤0.')], [B(String.raw`Let p=Π_C(z). Projection optimality gives (z−p)ᵀ(x*−p)≤0. Expanding ||z−x*||²=||z−p||²+||p−x*||²+2(z−p)ᵀ(p−x*) and noting the cross term is nonnegative yields ||p−x*||²≤||z−x*||². With z=x_t−ηg_t, expansion gives ||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||².`, String.raw`Đặt p=Π_C(z). Tối ưu chiếu cho (z−p)ᵀ(x*−p)≤0. Khai triển ||z−x*||²=||z−p||²+||p−x*||²+2(z−p)ᵀ(p−x*); tích chéo không âm nên ||p−x*||²≤||z−x*||². Với z=x_t−ηg_t, khai triển được ||x_t−x*||²−2ηg_tᵀ(x_t−x*)+η²||g_t||².`)], [R(1,'States projection inequality with correct sign.','Nêu bất đẳng thức chiếu đúng dấu.'),R(2,'Derives nonexpansive distance bound.','Suy ra cận khoảng cách không giãn.'),R(1,'Expands update norm correctly.','Khai triển chuẩn cập nhật đúng.')], [B('Reverses the projection variational inequality.', 'Đảo chiều bất đẳng thức biến phân chiếu.')]),
      E(B('Compute a projected stochastic step', 'Tính một bước ngẫu nhiên có chiếu'), ['computation','application'], B(String.raw`On C=[0,2], x₁=1.8, η=.4 and sampled gradient g₁=3, compute x₂ and the squared-distance potential to comparator x*=0.5.`, String.raw`Trên C=[0,2], x₁=1.8, η=.4, gradient mẫu g₁=3, tính x₂ và thế khoảng cách bình phương tới comparator x*=0.5.`), [B('Take the gradient step first, then project.', 'Thực hiện bước gradient trước rồi mới chiếu.')], [B(String.raw`The tentative point is 1.8−.4(3)=.6, already in C, so x₂=.6. The potential changes from (1.8−.5)²=1.69 to (.6−.5)²=.01, a decrease of 1.68. The unprojected identity predicts 1.69−2(.4)(3)(1.3)+(.4)²9=.01.`, String.raw`Điểm tạm là 1.8−.4(3)=.6, đã thuộc C nên x₂=.6. Thế giảm từ (1.8−.5)²=1.69 xuống (.6−.5)²=.01, tức giảm 1.68. Đẳng thức chưa chiếu cho 1.69−2(.4)(3)(1.3)+(.4)²9=.01.`)], [R(1,'Updates before projecting.','Cập nhật trước khi chiếu.'),R(2,'Finds x₂ in the feasible set.','Tìm x₂ khả thi.'),R(1,'Computes both potentials.','Tính hai thế.')], [B('Projects the gradient rather than the iterate.', 'Chiếu gradient thay vì iterate.')]),
      E(B('Transfer: identify the bias term', 'Chuyển giao: nhận diện hạng chệch'), ['proof','transfer'], B(String.raw`Suppose E[g_t|F_t]=∇f(x_t)+b_t with ||b_t||≤β. Modify the one-step regret argument and state the extra cumulative term under ||x_t−x*||≤D.`, String.raw`Giả sử E[g_t|F_t]=∇f(x_t)+b_t, ||b_t||≤β. Điều chỉnh lập luận regret một bước và nêu hạng cộng dồn thêm khi ||x_t−x*||≤D.`), [B('Write the expected gradient pairing as ∇fᵀd+bᵀd.', 'Viết tích gradient kỳ vọng thành ∇fᵀd+bᵀd.')], [B(String.raw`Let d_t=x_t−x*. Convexity's first-order inequality, with base x_t and endpoint x*, is f(x_t)−f(x*)≤∇f(x_t)ᵀd_t. Since E[g_t|F_t]=∇f(x_t)+b_t, we have ∇f(x_t)ᵀd_t=E[g_tᵀd_t|F_t]−b_tᵀd_t≤E[g_tᵀd_t|F_t]+βD. The projection potential proof bounds the sum of E[g_tᵀd_t] by D²/(2η)+ηG²T/2. Therefore expected cumulative excess is at most D²/(2η)+ηG²T/2+βDT, and average excess adds βD.`, String.raw`Đặt d_t=x_t−x*. Bất đẳng thức bậc nhất của tính lồi, với gốc x_t và đầu cuối x*, là f(x_t)−f(x*)≤∇f(x_t)ᵀd_t. Vì E[g_t|F_t]=∇f(x_t)+b_t nên ∇f(x_t)ᵀd_t=E[g_tᵀd_t|F_t]−b_tᵀd_t≤E[g_tᵀd_t|F_t]+βD. Chứng minh thế từ phép chiếu chặn tổng E[g_tᵀd_t] bởi D²/(2η)+ηG²T/2. Do đó excess tích lũy kỳ vọng không quá D²/(2η)+ηG²T/2+βDT; excess trung bình tăng βD.`)], [R(1,'Uses the correct convex first-order orientation.','Dùng đúng chiều bất đẳng thức bậc nhất lồi.'),R(2,'Separates the true gradient from oracle bias and bounds βD.','Tách gradient thật khỏi bias oracle và chặn βD.'),R(1,'Adds the bias once per round and averages correctly.','Cộng bias mỗi vòng và lấy trung bình đúng.')], [B('Writes ∇fᵀd≤f(x_t)−f(x*) or adds β only once.', 'Viết ∇fᵀd≤f(x_t)−f(x*) hoặc chỉ cộng β một lần.')]),
      E(B('Counterexample: unbounded gradients destroy the stated bound', 'Phản ví dụ: gradient không bị chặn phá cận đã nêu'), ['counterexample','transfer'], B(String.raw`Take C=[0,1], f(x)=x, x₁=1, and let the gradient oracle return g₁=M with probability 1/M and 0 otherwise, for M>1. Check unbiasedness and second moment; explain which assumption fails as M grows.`, String.raw`Cho C=[0,1], f(x)=x, x₁=1; oracle trả g₁=M xác suất 1/M, và 0 xác suất còn lại, M>1. Kiểm tra không chệch, moment bậc hai; giải thích giả thiết nào hỏng khi M tăng.`), [B('The mean is 1 but the second moment equals M.', 'Kỳ vọng bằng 1 nhưng moment bậc hai bằng M.')], [B(String.raw`E[g₁]=M(1/M)=1=f′(x₁), so the oracle is unbiased. E[g₁²]=M²/M=M, which has no uniform finite bound as M→∞. Thus the theorem's G² must grow with M and the advertised regret bound is not uniform; unbiasedness alone is insufficient.`, String.raw`E[g₁]=M(1/M)=1=f′(x₁), nên oracle không chệch. E[g₁²]=M²/M=M, không có cận hữu hạn đồng đều khi M→∞. Do đó G² trong định lý tăng theo M và cận regret không đồng đều; chỉ không chệch là chưa đủ.`)], [R(1,'Verifies conditional mean.','Kiểm tra kỳ vọng có điều kiện.'),R(2,'Computes second moment.','Tính moment bậc hai.'),R(1,'Names bounded-second-moment failure.','Nêu đúng thất bại cận moment bậc hai.')], [B('Confuses E[g²] with (E[g])².', 'Nhầm E[g²] với (E[g])².')]),
    ],
  },
  {
    week: 69, title: B('Conditioning, QR/SVD, and stable least squares', 'Điều kiện hóa, QR/SVD và bình phương tối thiểu ổn định'), level: 'graduate core', prerequisites: [12, 61, 66],
    outcomes: [B('Relate singular values to sensitivity of least-squares solutions.', 'Liên hệ trị suy biến với độ nhạy của nghiệm bình phương tối thiểu.'), B('Explain why normal equations square the condition number and prefer QR/SVD solves.', 'Giải thích vì sao phương trình chuẩn bình phương số điều kiện và ưu tiên giải QR/SVD.')],
    definitions: B(String.raw`For full-column-rank A∈R^{m×n}, κ₂(A)=σ_max(A)/σ_min(A). The least-squares solution minimizes ||Ax−b||₂; reduced QR A=QR with QᵀQ=I gives Rx=Qᵀb. In floating point, backward error asks whether the computed answer exactly solves a nearby input problem; forward error measures distance to the exact answer.`, String.raw`Với A∈R^{m×n} hạng cột đầy đủ, κ₂(A)=σ_max(A)/σ_min(A). Nghiệm bình phương tối thiểu tối thiểu hóa ||Ax−b||₂; QR rút gọn A=QR, QᵀQ=I, cho Rx=Qᵀb. Trong số học dấu phẩy động, sai số ngược hỏi nghiệm máy giải chính xác bài toán dữ liệu gần kề; sai số xuôi đo khoảng cách tới nghiệm chính xác.`),
    theoremTitle: B('Normal equations square the 2-norm condition number', 'Phương trình chuẩn bình phương số điều kiện chuẩn 2'),
    statement: B(String.raw`If A has full column rank, κ₂(AᵀA)=κ₂(A)². Thus a relative perturbation at the normal-equation matrix can be amplified at scale κ(A)², while QR works with A and has scale κ(A).`, String.raw`Nếu A có hạng cột đầy đủ thì κ₂(AᵀA)=κ₂(A)². Vì vậy nhiễu tương đối ở ma trận phương trình chuẩn có thể được khuếch đại theo κ(A)², còn QR làm việc trực tiếp với A, có thang κ(A).`),
    proof: B(String.raw`Let σ₁≥…≥σ_n>0 be singular values of A. The eigenvalues of AᵀA are σ_i² because A=UΣVᵀ implies AᵀA=VΣ²Vᵀ. For a positive-definite symmetric matrix, κ₂ equals largest eigenvalue divided by smallest. Hence κ₂(AᵀA)=σ₁²/σ_n²=(σ₁/σ_n)²=κ₂(A)². Full column rank is essential so σ_n>0.`, String.raw`Gọi σ₁≥…≥σ_n>0 là trị suy biến của A. Trị riêng AᵀA là σ_i² vì A=UΣVᵀ suy ra AᵀA=VΣ²Vᵀ. Với ma trận đối xứng xác định dương, κ₂ bằng trị riêng lớn nhất chia nhỏ nhất. Vậy κ₂(AᵀA)=σ₁²/σ_n²=(σ₁/σ_n)²=κ₂(A)². Hạng cột đầy đủ là thiết yếu để σ_n>0.`), sourceId: 'o-boyd', section: '§A.5 (conditioning); §10.3 (least squares implementation); statement proved by SVD.',
    workedExample: B(String.raw`For A=diag(1,10⁻⁴), κ₂(A)=10⁴, while AᵀA=diag(1,10⁻⁸) has κ₂=10⁸. The direction of the small singular value controls sensitivity; forming AᵀA has already magnified the scale disparity before a solver acts.`, String.raw`Với A=diag(1,10⁻⁴), κ₂(A)=10⁴, còn AᵀA=diag(1,10⁻⁸) có κ₂=10⁸. Hướng trị suy biến nhỏ điều khiển độ nhạy; lập AᵀA đã khuếch đại chênh lệch thang trước khi bộ giải hoạt động.`),
    failureCase: B(String.raw`A small residual ||A x̂−b|| does not guarantee small parameter error when A is ill-conditioned: perturbations in b along the left singular vector for σ_min create solution error proportional to 1/σ_min. A numerically tiny residual can coexist with a poor x̂.`, String.raw`Residual ||A x̂−b|| nhỏ không bảo đảm sai số tham số nhỏ khi A kém điều kiện: nhiễu b theo vector suy biến trái ứng với σ_min tạo sai số nghiệm tỷ lệ 1/σ_min. Residual rất nhỏ vẫn có thể đi cùng x̂ kém.`),
    topic: 'conditioning; backward/forward error; QR/SVD least squares; normal equations', readingSection: '§A.5, §10.3',
    exercises: [
      E(B('Condition number from singular values', 'Số điều kiện từ trị suy biến'), ['computation'], B(String.raw`A has singular values 5, 1, .01. Compute κ₂(A), κ₂(AᵀA), and the amplification ratio between them.`, String.raw`A có các trị suy biến 5, 1, .01. Tính κ₂(A), κ₂(AᵀA) và tỷ số khuếch đại.`), [B('Use largest divided by smallest, then square.', 'Lấy trị lớn nhất chia nhỏ nhất rồi bình phương.')], [B(String.raw`κ₂(A)=5/.01=500. κ₂(AᵀA)=500²=250,000. The normal-equation condition number is 500 times larger than κ(A), illustrating squared sensitivity scale.`, String.raw`κ₂(A)=5/.01=500. κ₂(AᵀA)=500²=250,000. Số điều kiện phương trình chuẩn lớn hơn κ(A) 500 lần, thể hiện thang nhạy bị bình phương.`)], [R(1,'Computes κ(A).','Tính κ(A).'),R(2,'Squares the ratio.','Bình phương tỷ số.'),R(1,'Computes comparison factor.','Tính hệ số so sánh.')], [B('Squares singular values before taking their ratio twice.', 'Bình phương trị suy biến rồi lại chia sai lần nữa.')]),
      E(B('Prove the singular-value identity', 'Chứng minh đồng nhất thức trị suy biến'), ['proof'], B(String.raw`Using an SVD of full-column-rank A, prove κ₂(AᵀA)=κ₂(A)² and explain which rank assumption is needed.`, String.raw`Dùng SVD của A hạng cột đầy đủ để chứng minh κ₂(AᵀA)=κ₂(A)² và giải thích giả thiết hạng cần thiết.`), [B('Write A=UΣVᵀ and diagonalize AᵀA.', 'Viết A=UΣVᵀ rồi chéo hóa AᵀA.')], [B(String.raw`AᵀA=VΣᵀUᵀUΣVᵀ=VΣ²Vᵀ. Its eigenvalues are σ_i², so κ₂(AᵀA)=σ_max²/σ_min²=κ₂(A)². Full column rank ensures σ_min>0; otherwise AᵀA is singular and κ₂ is infinite.`, String.raw`AᵀA=VΣᵀUᵀUΣVᵀ=VΣ²Vᵀ. Trị riêng là σ_i² nên κ₂(AᵀA)=σ_max²/σ_min²=κ₂(A)². Hạng cột đầy đủ bảo đảm σ_min>0; nếu không, AᵀA suy biến và κ₂ vô hạn.`)], [R(1,'Uses orthogonality UᵀU=I.','Dùng tính trực giao UᵀU=I.'),R(2,'Identifies squared eigenvalues.','Nhận diện trị riêng bình phương.'),R(1,'States rank consequence.','Nêu hệ quả hạng.')], [B('Assumes A is square though the result allows rectangular full rank.', 'Giả sử A vuông dù kết quả cho phép A chữ nhật hạng cột đầy đủ.')]),
      E(B('Backward versus forward error', 'Sai số ngược và sai số xuôi'), ['numerical analysis','application'], B(String.raw`A solver returns x̂ with ||A x̂−b||₂=10⁻⁸, but κ₂(A)=10¹⁰. What can you conclude about residual and solution accuracy? Give the standard qualitative forward-error scaling.`, String.raw`Bộ giải trả x̂ với ||A x̂−b||₂=10⁻⁸ nhưng κ₂(A)=10¹⁰. Có thể kết luận gì về residual và độ chính xác nghiệm? Nêu thang sai số xuôi định tính.`), [B('Residual is a backward diagnostic; conditioning multiplies relative input error.', 'Residual là chẩn đoán ngược; điều kiện hóa nhân sai số dữ liệu tương đối.')], [B(String.raw`The computed residual is small in absolute norm, but without scales for ||A||,||x̂||,||b|| it is not even a relative backward-error statement. For a backward-stable solver, relative forward error is typically bounded on the order of κ(A) times relative backward error when κ(A)u is not large. Here κ=10¹⁰ can amplify tiny perturbations; no guarantee of accurate parameters follows from the residual alone.`, String.raw`Residual tuyệt đối nhỏ, nhưng thiếu thang ||A||,||x̂||,||b|| thì chưa thể gọi là sai số ngược tương đối nhỏ. Với bộ giải ổn định ngược, sai số xuôi tương đối thường cỡ κ(A) nhân sai số ngược tương đối khi κ(A)u chưa lớn. Ở đây κ=10¹⁰ có thể khuếch đại nhiễu nhỏ; residual riêng lẻ không bảo đảm tham số chính xác.`)], [R(1,'Separates residual from relative backward error.','Tách residual khỏi sai số ngược tương đối.'),R(2,'States κ amplification with condition.','Nêu khuếch đại κ cùng điều kiện.'),R(1,'Avoids an unsupported accuracy claim.','Tránh khẳng định chính xác không có căn cứ.')], [B('Claims every small residual implies small parameter error.', 'Khẳng định residual nhỏ luôn cho sai số tham số nhỏ.')]),
      E(B('Transfer: QR least squares', 'Chuyển giao: bình phương tối thiểu QR'), ['derivation','transfer'], B(String.raw`Suppose A=QR with QᵀQ=I and R nonsingular. Derive the least-squares solution from ||Ax−b||² and explain why one solves triangular R rather than forming AᵀA.`, String.raw`Giả sử A=QR, QᵀQ=I và R khả nghịch. Suy ra nghiệm bình phương tối thiểu từ ||Ax−b||² và giải thích vì sao giải R tam giác thay vì lập AᵀA.`), [B('Decompose b into its projection onto col(Q) and orthogonal residual.', 'Phân rã b thành hình chiếu lên col(Q) và residual trực giao.')], [B(String.raw`||QRx−b||²=||Qᵀ(QRx−b)||²+||(I−QQᵀ)b||²=||Rx−Qᵀb||²+constant. The first term is minimized to zero by Rx=Qᵀb, so x=R⁻¹Qᵀb via a triangular solve. This avoids explicitly squaring the singular spectrum as AᵀA does.`, String.raw`||QRx−b||²=||Qᵀ(QRx−b)||²+||(I−QQᵀ)b||²=||Rx−Qᵀb||²+hằng số. Hạng đầu đạt 0 khi Rx=Qᵀb nên x=R⁻¹Qᵀb bằng phép giải tam giác. Cách này tránh bình phương phổ suy biến như AᵀA.`)], [R(1,'Uses orthogonal decomposition.','Dùng phân rã trực giao.'),R(2,'Derives triangular solve.','Suy ra phép giải tam giác.'),R(1,'Connects QR to conditioning.','Liên hệ QR với điều kiện hóa.')], [B('Uses Q⁻¹ although Q may be rectangular.', 'Dùng Q⁻¹ dù Q có thể chữ nhật.')]),
      E(B('Counterexample: residual hides an ill-conditioned direction', 'Phản ví dụ: residual che hướng kém điều kiện'), ['counterexample','numerical analysis'], B(String.raw`For A=diag(1,ε), b=(1,ε), compare the exact solution with x̃=(1,0). Compute residual and parameter error as ε→0.`, String.raw`Với A=diag(1,ε), b=(1,ε), so sánh nghiệm chính xác với x̃=(1,0). Tính residual và sai số tham số khi ε→0.`), [B('Solve coordinatewise; the second coordinate is amplified by 1/ε.', 'Giải theo tọa độ; tọa độ thứ hai được khuếch đại bởi 1/ε.')], [B(String.raw`The exact solution is x=(1,1); x̃=(1,0) has parameter error ||x̃−x||=1. Its residual is Ax̃−b=(0,−ε), norm ε→0. Thus residual tends to zero while solution error remains one because κ(A)=1/ε.`, String.raw`Nghiệm chính xác x=(1,1); x̃=(1,0) có sai số tham số ||x̃−x||=1. Residual Ax̃−b=(0,−ε), chuẩn ε→0. Vậy residual tiến về 0 trong khi sai số nghiệm giữ bằng 1 do κ(A)=1/ε.`)], [R(1,'Computes exact solution.','Tính nghiệm chính xác.'),R(2,'Computes residual and error.','Tính residual và sai số.'),R(1,'Explains conditioning link.','Giải thích liên hệ điều kiện hóa.')], [B('Reports relative error without noticing changing scales.', 'Báo sai số tương đối mà không xét thang thay đổi.')]),
    ],
  },
  {
    week: 70, title: B('Stopping certificates, scaling, and KKT residuals', 'Chứng chỉ dừng, co giãn và residual KKT'), level: 'graduate core', prerequisites: [64, 66, 69],
    outcomes: [B('Convert gradient norm into an objective-gap bound under strong convexity.', 'Chuyển chuẩn gradient thành cận gap mục tiêu dưới lồi mạnh.'), B('Design stopping rules that combine primal feasibility, dual feasibility and complementarity.', 'Thiết kế quy tắc dừng kết hợp khả thi primal/dual và bổ sung chặt.')],
    definitions: B(String.raw`A stopping certificate is a computable upper bound on distance to optimality, conditional on stated assumptions. For differentiable μ-strongly convex f, the gradient norm controls suboptimality. In a constrained problem track primal residual ||Ax−b||, inequality violation max_i[g_i(x)]_+, dual violation ||[−λ]_+||, stationarity residual and complementarity |λ_i g_i(x)|. Rescale variables and constraints so tolerances have interpretable units.`, String.raw`Chứng chỉ dừng là cận trên tính được cho khoảng cách tới tối ưu, dựa trên giả thiết đã nêu. Với f khả vi μ-lồi mạnh, chuẩn gradient kiểm soát độ không tối ưu. Trong bài toán ràng buộc, theo dõi residual primal ||Ax−b||, vi phạm bất đẳng thức max_i[g_i(x)]_+, vi phạm dual ||[−λ]_+||, residual dừng và bổ sung chặt |λ_i g_i(x)|. Co giãn biến và ràng buộc để dung sai có đơn vị diễn giải được.`),
    theoremTitle: B('Strong convexity gives a gradient-gap certificate', 'Lồi mạnh cho chứng chỉ gap từ gradient'),
    statement: B(String.raw`If f is differentiable μ-strongly convex on R^d and has minimizer x*, then 0≤f(x)−f(x*)≤||∇f(x)||²/(2μ) for every x.`, String.raw`Nếu f khả vi μ-lồi mạnh trên R^d và có nghiệm x*, thì 0≤f(x)−f(x*)≤||∇f(x)||²/(2μ) với mọi x.`),
    proof: B(String.raw`Strong convexity applied with base x and endpoint y gives f(y)≥f(x)+∇f(x)ᵀ(y−x)+(μ/2)||y−x||². Set y=x* and rearrange: f(x)−f(x*)≤∇f(x)ᵀ(x−x*)−(μ/2)||x−x*||². For any vector d, aᵀd−(μ/2)||d||²≤||a||²/(2μ), by completing the square. Set a=∇f(x), d=x−x*. Nonnegativity follows from optimality of x*.`, String.raw`Áp dụng lồi mạnh với điểm gốc x và đầu cuối y: f(y)≥f(x)+∇f(x)ᵀ(y−x)+(μ/2)||y−x||². Chọn y=x* rồi chuyển vế: f(x)−f(x*)≤∇f(x)ᵀ(x−x*)−(μ/2)||x−x*||². Với mọi d, aᵀd−(μ/2)||d||²≤||a||²/(2μ) do hoàn thành bình phương. Đặt a=∇f(x), d=x−x*. Vế trái không âm do x* tối ưu.`), sourceId: 'o-boyd', section: '§9.1–9.3; strong convexity and gradient optimality bounds.',
    workedExample: B(String.raw`For f(x)=½xᵀQx with Q⪰2I, μ=2. At x=(1,−1), gradient norm²=||Qx||². If Q=2I, the certified gap is ||2x||²/4=2, equal to f(x)−f(0)=2.`, String.raw`Với f(x)=½xᵀQx, Q⪰2I, μ=2. Tại x=(1,−1), bình phương chuẩn gradient là ||Qx||². Nếu Q=2I thì gap chứng nhận là ||2x||²/4=2, đúng bằng f(x)−f(0)=2.`),
    failureCase: B(String.raw`A small gradient alone gives no global gap bound without curvature or another error-bound condition: f(x)=x⁴ has derivative 4x³ near zero, while its curvature degenerates at the minimizer; a fixed μ>0 strong-convexity certificate is unavailable. In constrained problems a small objective change also says nothing about infeasibility.`, String.raw`Gradient nhỏ không tự cho cận gap toàn cục nếu thiếu độ cong hoặc điều kiện sai số khác: f(x)=x⁴ có đạo hàm 4x³ gần 0 nhưng độ cong suy biến tại nghiệm; không có chứng chỉ lồi mạnh với μ>0 cố định. Trong bài toán ràng buộc, objective ít đổi cũng không cho biết còn vi phạm khả thi.`),
    topic: 'optimality gap; stopping certificates; KKT residuals; scaling', readingSection: '§5.5, §9.1–9.3, §10.3–10.4',
    exercises: [
      E(B('Gradient certificate calculation', 'Tính chứng chỉ gradient'), ['computation'], B(String.raw`A differentiable objective is μ=0.5 strongly convex and an iterate has ||∇f(x)||=.04. Bound its suboptimality.`, String.raw`Mục tiêu khả vi lồi mạnh μ=0.5, iterate có ||∇f(x)||=.04. Chặn độ không tối ưu.`), [B('Square the norm and divide by 2μ.', 'Bình phương chuẩn rồi chia 2μ.')], [B(String.raw`The gap is at most .04²/(2·.5)=.0016. This is a valid objective-gap certificate only because the global μ-strong-convexity hypothesis holds.`, String.raw`Gap không quá .04²/(2·.5)=.0016. Đây là chứng chỉ gap hợp lệ chỉ vì giả thiết lồi mạnh toàn cục μ đúng.`)], [R(1,'Uses squared gradient norm.','Dùng bình phương chuẩn gradient.'),R(2,'Computes denominator 2μ.','Tính mẫu 2μ.'),R(1,'States dependency on strong convexity.','Nêu phụ thuộc vào lồi mạnh.')], [B('Divides by μ rather than 2μ.', 'Chia cho μ thay vì 2μ.')]),
      E(B('Prove the gap bound by completing a square', 'Chứng minh cận gap bằng hoàn thành bình phương'), ['proof'], B(String.raw`Starting from μ-strong convexity with endpoint x*, derive f(x)−f(x*)≤||∇f(x)||²/(2μ), making the square completion explicit.`, String.raw`Từ lồi mạnh μ với đầu cuối x*, suy ra f(x)−f(x*)≤||∇f(x)||²/(2μ), viết rõ bước hoàn thành bình phương.`), [B('Use aᵀd−μ||d||²/2 = ||a||²/(2μ)−(μ/2)||d−a/μ||².', 'Dùng aᵀd−μ||d||²/2 = ||a||²/(2μ)−(μ/2)||d−a/μ||².')], [B(String.raw`Strong convexity at x toward x* yields gap≤aᵀd−(μ/2)||d||² with a=∇f(x), d=x−x*. Complete the square: aᵀd−(μ/2)||d||²=||a||²/(2μ)−(μ/2)||d−a/μ||²≤||a||²/(2μ). Optimality gives gap≥0.`, String.raw`Lồi mạnh tại x hướng tới x* cho gap≤aᵀd−(μ/2)||d||² với a=∇f(x), d=x−x*. Hoàn thành bình phương: aᵀd−(μ/2)||d||²=||a||²/(2μ)−(μ/2)||d−a/μ||²≤||a||²/(2μ). Tính tối ưu cho gap≥0.`)], [R(1,'Substitutes strong convexity correctly.','Thay lồi mạnh đúng.'),R(2,'Completes square with correct μ scale.','Hoàn thành bình phương đúng hệ số μ.'),R(1,'Includes lower bound from optimality.','Nêu cận dưới từ tối ưu.')], [B('Drops the negative square and reverses the remaining inequality.', 'Bỏ hạng bình phương âm rồi đảo chiều bất đẳng thức.')]),
      E(B('Build a scaled KKT residual report', 'Lập báo cáo residual KKT đã co giãn'), ['application','numerical analysis'], B(String.raw`For g₁(x)=x₁−1≤0, g₂(x)=−x₂≤0, equality x₁+x₂=1, report separate feasibility, dual, stationarity and complementarity residuals at x=(1.02,−.01), λ=(.4,−.02), ν=.3 for f=½||x−(2,1)||².`, String.raw`Với g₁=x₁−1≤0, g₂=−x₂≤0, đẳng thức x₁+x₂=1, báo riêng residual khả thi, dual, dừng và bổ sung chặt tại x=(1.02,−.01), λ=(.4,−.02), ν=.3 cho f=½||x−(2,1)||².`), [B('Compute each residual separately; do not combine units prematurely.', 'Tính từng residual riêng, chưa gộp đơn vị vội.')], [B(String.raw`Inequality violation is max{.02,.01}=.02; equality residual is |1.01−1|=.01. Dual violation is max{0,−λ₂}=.02. ∇f=x−(2,1)=(-.98,-1.01); ∇g₁=(1,0), ∇g₂=(0,−1), equality gradient=(1,1). Stationarity residual is ||(-.98,-1.01)+(.4,.02)+(.3,.3)||₂=||(-.28,-.69)||₂≈.7446. Complementarity magnitudes are |.4(.02)|=.008 and |(−.02)(.01)|=.0002.`, String.raw`Vi phạm bất đẳng thức max{.02,.01}=.02; residual đẳng thức |1.01−1|=.01. Vi phạm dual max{0,−λ₂}=.02. ∇f=x−(2,1)=(-.98,-1.01); ∇g₁=(1,0), ∇g₂=(0,−1), gradient đẳng thức=(1,1). Residual dừng là ||(-.98,-1.01)+(.4,.02)+(.3,.3)||₂=||(-.28,-.69)||₂≈.7446. Độ lớn bổ sung chặt là |.4(.02)|=.008 và |(−.02)(.01)|=.0002.`)], [R(1,'Computes primal violations.','Tính vi phạm primal.'),R(1,'Computes dual violation.','Tính vi phạm dual.'),R(2,'Forms stationarity vector and norm.','Lập vector dừng và chuẩn.'),R(1,'Reports both complementarity products.','Báo cả hai tích bổ sung chặt.')], [B('Treats negative λ₂ as feasible because its magnitude is small.', 'Coi λ₂ âm là khả thi vì độ lớn nhỏ.')]),
      E(B('Transfer: a noisy gradient certificate', 'Chuyển giao: chứng chỉ gradient nhiễu'), ['derivation','transfer'], B(String.raw`Suppose ||∇f(x)−ĝ||≤ε and f is μ-strongly convex. Derive a gap upper bound in terms of ||ĝ|| and ε using the triangle inequality.`, String.raw`Giả sử ||∇f(x)−ĝ||≤ε và f μ-lồi mạnh. Dùng bất đẳng thức tam giác suy ra cận gap theo ||ĝ|| và ε.`), [B('First bound the true gradient norm.', 'Trước tiên chặn chuẩn gradient thật.')], [B(String.raw`||∇f(x)||≤||ĝ||+ε. Apply the gap theorem: f(x)−f*≤(||ĝ||+ε)²/(2μ). This is conservative but valid; treating ||ĝ|| itself as the true gradient would omit the oracle error.`, String.raw`||∇f(x)||≤||ĝ||+ε. Áp dụng định lý gap: f(x)−f*≤(||ĝ||+ε)²/(2μ). Cận này bảo thủ nhưng hợp lệ; dùng trực tiếp ||ĝ|| như gradient thật sẽ bỏ qua sai số oracle.`)], [R(1,'Uses triangle inequality.','Dùng bất đẳng thức tam giác.'),R(2,'Substitutes into strong-convexity gap.','Thay vào cận gap lồi mạnh.'),R(1,'Interprets conservatism.','Diễn giải tính bảo thủ.')], [B('Adds ε after squaring the estimated norm.', 'Cộng ε sau khi bình phương chuẩn ước lượng.')]),
      E(B('Counterexample: a small gradient in a flat region', 'Phản ví dụ: gradient nhỏ trong vùng phẳng'), ['counterexample','transfer'], B(String.raw`For f(x)=x⁴, evaluate |f′(x)| and f(x) at x=.01 and x=1. Explain why no fixed μ>0 strong-convexity certificate can be used near zero.`, String.raw`Với f(x)=x⁴, tính |f′(x)| và f(x) tại x=.01 và x=1. Giải thích vì sao không dùng được chứng chỉ lồi mạnh μ>0 cố định gần 0.`), [B('The second derivative is 12x² and tends to zero.', 'Đạo hàm bậc hai là 12x² và tiến về 0.')], [B(String.raw`At x=.01, f=.00000001 and |f′|=.000004; at x=1, f=1 and |f′|=4. The Hessian f″=12x² has infimum 0, so f is not μ-strongly convex for any fixed μ>0 on R. A small gradient near zero coincides with a small gap here, but this does not justify the quadratic certificate; the uniform curvature premise is absent.`, String.raw`Tại x=.01, f=.00000001 và |f′|=.000004; tại x=1, f=1 và |f′|=4. Hessian f″=12x² có infimum 0 nên f không μ-lồi mạnh với μ>0 cố định trên R. Gradient nhỏ gần 0 đi cùng gap nhỏ trong ví dụ này nhưng không biện minh chứng chỉ quadratic; thiếu giả thiết độ cong đồng đều.`)], [R(1,'Computes values at both points.','Tính giá trị ở cả hai điểm.'),R(1,'Finds curvature infimum.','Tìm infimum độ cong.'),R(2,'Separates observed behavior from theorem premise.','Tách hành vi quan sát khỏi giả thiết định lý.')], [B('Infers strong convexity from one local positive second derivative.', 'Suy ra lồi mạnh từ một đạo hàm bậc hai dương cục bộ.')]),
    ],
  },
  {
    week: 71, title: B('Composite optimization and proximal-gradient synthesis', 'Tổng hợp tối ưu hợp thành và proximal-gradient'), level: 'graduate core', prerequisites: [63, 66, 67, 70],
    outcomes: [B('Derive the proximal-gradient update for a smooth-plus-nonsmooth objective.', 'Suy ra cập nhật proximal-gradient cho mục tiêu trơn cộng không trơn.'), B('Prove an O(1/T) objective bound for averaged iterates under a safe step.', 'Chứng minh cận mục tiêu O(1/T) cho iterate trung bình dưới bước an toàn.')],
    definitions: B(String.raw`Consider F(x)=f(x)+h(x), with convex differentiable L-smooth f and proper closed convex h. A proximal-gradient step is x⁺=prox_{ηh}(x−η∇f(x)); it performs a gradient model of f followed by exact minimization of that model plus h. For η≤1/L the quadratic model majorizes f.`, String.raw`Xét F(x)=f(x)+h(x), trong đó f lồi khả vi L-trơn, h lồi đóng proper. Bước proximal-gradient là x⁺=prox_{ηh}(x−η∇f(x)); nó tạo mô hình gradient cho f rồi tối thiểu hóa chính xác mô hình cộng h. Với η≤1/L, mô hình quadratic chặn trên f.`),
    theoremTitle: B('Proximal-gradient one-step inequality and sublinear rate', 'Bất đẳng thức một bước và tốc độ dưới tuyến tính proximal-gradient'),
    statement: B(String.raw`Assume F=f+h has a minimizer x*, f is convex differentiable with L-Lipschitz gradient, h is proper closed convex, and 0<η≤1/L. If x⁺=prox_{ηh}(x−η∇f(x)), then for every z, F(x⁺)−F(z)≤(||x−z||²−||x⁺−z||²)/(2η). Hence for z=x* and x̄_T=T⁻¹Σ_{t=1}^T x_{t+1}, F(x̄_T)−F(x*)≤||x₁−x*||²/(2ηT).`, String.raw`Giả sử F=f+h có nghiệm tối ưu x*, f lồi khả vi với gradient L-Lipschitz, h lồi đóng proper, và 0<η≤1/L. Nếu x⁺=prox_{ηh}(x−η∇f(x)), thì với mọi z, F(x⁺)−F(z)≤(||x−z||²−||x⁺−z||²)/(2η). Do đó với z=x* và x̄_T=T⁻¹Σ_{t=1}^T x_{t+1}, F(x̄_T)−F(x*)≤||x₁−x*||²/(2ηT).`),
    proof: B(String.raw`Smoothness gives f(x⁺)≤f(x)+∇f(x)ᵀ(x⁺−x)+(L/2)||x⁺−x||². Since η≤1/L, this is at most f(x)+∇f(x)ᵀd+||d||²/(2η), d=x⁺−x. Proximal optimality says −∇f(x)−d/η∈∂h(x⁺); its support inequality gives h(z)≥h(x⁺)+(−∇f(x)−d/η)ᵀ(z−x⁺). Convexity also gives the necessary lower bound f(z)≥f(x)+∇f(x)ᵀ(z−x); subtract this from the smooth upper bound and add the h support inequality to obtain F(x⁺)−F(z)≤[||x−z||²−||x⁺−z||²−(1−ηL)||d||²]/(2η), so dropping the final nonpositive term proves the one-step inequality. Set z=x*, sum over t; squared distances telescope. Convexity gives F(x̄_T)≤T⁻¹Σ_{t=1}^T F(x_{t+1}); summing the one-step inequalities gives the exact displayed rate from x₁.`, String.raw`Độ trơn cho f(x⁺)≤f(x)+∇f(x)ᵀ(x⁺−x)+(L/2)||x⁺−x||². Vì η≤1/L, vế này không quá f(x)+∇f(x)ᵀd+||d||²/(2η), d=x⁺−x. Tối ưu proximal cho −∇f(x)−d/η∈∂h(x⁺); bất đẳng thức đỡ là h(z)≥h(x⁺)+(−∇f(x)−d/η)ᵀ(z−x⁺). Tính lồi còn cho cận dưới cần thiết f(z)≥f(x)+∇f(x)ᵀ(z−x); lấy hiệu với cận trên trơn rồi cộng bất đẳng thức đỡ h để được F(x⁺)−F(z)≤[||x−z||²−||x⁺−z||²−(1−ηL)||d||²]/(2η), nên bỏ hạng cuối không dương cho bất đẳng thức một bước. Chọn z=x*, cộng theo t thì bình phương khoảng cách triệt tiêu dạng telescoping. Tính lồi cho F(x̄_T)≤T⁻¹Σ_{t=1}^T F(x_{t+1}); cộng bất đẳng thức một bước cho đúng cận đã nêu tính từ x₁.`), sourceId: 'o-prox', section: '§4 (proximal-gradient method and convergence).',
    workedExample: B(String.raw`For F(x)=½(x−3)²+2|x|, L=1, η=1, start x=0. The gradient of f is −3, so the proximal argument is 3 and soft threshold at 2 gives x⁺=1. The nonsmooth penalty changes the update from the plain gradient point 3 to 1.`, String.raw`Với F(x)=½(x−3)²+2|x|, L=1, η=1, bắt đầu x=0. Gradient f là −3 nên đối số prox bằng 3; ngưỡng mềm 2 cho x⁺=1. Penalty không trơn đổi điểm gradient thuần 3 thành 1.`),
    failureCase: B(String.raw`If η>1/L, the quadratic model may understate f and the one-step proof loses its majorization step. If h is omitted, the method is ordinary gradient descent; if h is nonconvex, the global convex bound does not follow from this proof.`, String.raw`Nếu η>1/L, mô hình quadratic có thể chặn thiếu f và chứng minh một bước mất bước majorization. Bỏ h thì thành gradient descent thường; nếu h không lồi, cận toàn cục lồi không theo từ chứng minh này.`),
    topic: 'composite objectives; proximal gradient; descent certificates; telescoping rate', readingSection: 'Parikh & Boyd §4; Boyd §9.1',
    exercises: [
      E(B('One proximal-gradient iterate', 'Một iterate proximal-gradient'), ['computation'], B(String.raw`For F(x)=½(x−4)²+|x|, L=1, η=1, x₀=0, compute x₁ and F(x₀),F(x₁).`, String.raw`Với F(x)=½(x−4)²+|x|, L=1, η=1, x₀=0, tính x₁ và F(x₀),F(x₁).`), [B('Take a gradient step on the quadratic, then soft-threshold by one.', 'Lấy bước gradient trên quadratic rồi ngưỡng mềm mức một.')], [B(String.raw`∇f(0)=−4, so v=4. prox_{|·|}(4)=3, hence x₁=3. F(0)=8; F(3)=½+3=3.5.`, String.raw`∇f(0)=−4 nên v=4. prox_{|·|}(4)=3, do đó x₁=3. F(0)=8; F(3)=½+3=3.5.`)], [R(1,'Computes smooth gradient step.','Tính bước gradient trơn.'),R(2,'Applies threshold.','Áp dụng ngưỡng.'),R(1,'Evaluates both composite objectives.','Tính cả hai mục tiêu hợp thành.')], [B('Applies the proximal map to the gradient instead of the iterate argument.', 'Áp dụng prox lên gradient thay vì đối số iterate.')]),
      E(B('Derive proximal-gradient optimality', 'Suy ra điều kiện tối ưu proximal-gradient'), ['derivation','proof'], B(String.raw`Show that x⁺ minimizes h(u)+∇f(x)ᵀ(u−x)+(1/(2η))||u−x||², and derive its subgradient inclusion.`, String.raw`Chứng minh x⁺ tối thiểu hóa h(u)+∇f(x)ᵀ(u−x)+(1/(2η))||u−x||² rồi suy ra bao hàm dưới gradient.`), [B('Complete the square to match prox_{ηh}.', 'Hoàn thành bình phương để khớp prox_{ηh}.')], [B(String.raw`The u-dependent terms equal h(u)+(1/(2η))||u−(x−η∇f(x))||² up to a constant independent of u. Thus x⁺=prox_{ηh}(x−η∇f(x)). Optimality gives 0∈∂h(x⁺)+∇f(x)+(x⁺−x)/η, equivalently −∇f(x)−(x⁺−x)/η∈∂h(x⁺).`, String.raw`Các hạng phụ thuộc u bằng h(u)+(1/(2η))||u−(x−η∇f(x))||² cộng hằng số không phụ thuộc u. Do đó x⁺=prox_{ηh}(x−η∇f(x)). Tối ưu cho 0∈∂h(x⁺)+∇f(x)+(x⁺−x)/η, tương đương −∇f(x)−(x⁺−x)/η∈∂h(x⁺).`)], [R(1,'Completes the square correctly.','Hoàn thành bình phương đúng.'),R(2,'Identifies exact proximal center.','Nhận diện đúng tâm proximal.'),R(1,'Writes inclusion with correct sign.','Viết bao hàm đúng dấu.')], [B('Drops η from the proximal center.', 'Bỏ η khỏi tâm proximal.')]),
      E(B('Prove the telescoping objective bound', 'Chứng minh cận mục tiêu telescoping'), ['proof'], B(String.raw`From the stated one-step inequality, sum t=1,…,T with z=x* and derive a bound for the average of F(x_{t+1})−F(x*).`, String.raw`Từ bất đẳng thức một bước, cộng t=1,…,T với z=x* và suy ra cận trung bình F(x_{t+1})−F(x*).`), [B('Write the first and last squared distances after cancellation.', 'Viết bình phương khoảng cách đầu và cuối sau khi triệt tiêu.')], [B(String.raw`Summing gives Σ[F(x_{t+1})−F(x*)]≤(||x₁−x*||²−||x_{T+1}−x*||²)/(2η)≤||x₁−x*||²/(2η). Divide by T. By convexity, F(T⁻¹Σx_{t+1})≤T⁻¹ΣF(x_{t+1}), so the averaged iterate obeys the same upper bound.`, String.raw`Cộng lại được Σ[F(x_{t+1})−F(x*)]≤(||x₁−x*||²−||x_{T+1}−x*||²)/(2η)≤||x₁−x*||²/(2η). Chia T. Tính lồi cho F(T⁻¹Σx_{t+1})≤T⁻¹ΣF(x_{t+1}), nên iterate trung bình thỏa cùng cận.`)], [R(1,'Telescopes squared distances.','Triệt tiêu bình phương khoảng cách.'),R(2,'Uses nonnegative terminal distance.','Dùng khoảng cách cuối không âm.'),R(1,'Applies Jensen/convexity to average.','Dùng Jensen/tính lồi cho trung bình.')], [B('Leaves a T factor in the averaged bound.', 'Để sót hệ số T trong cận trung bình.')]),
      E(B('Transfer: choose the split that makes prox cheap', 'Chuyển giao: chọn phân tách để prox tính rẻ'), ['application','transfer'], B(String.raw`For least squares with lasso, F(x)=½||Ax−b||²+λ||x||₁, identify f,h, compute ∇f and write one proximal-gradient step without expanding an inverse.`, String.raw`Với least squares lasso F(x)=½||Ax−b||²+λ||x||₁, xác định f,h, tính ∇f và viết một bước proximal-gradient không khai triển nghịch đảo.`), [B('The smooth gradient is Aᵀ(Ax−b); h is λ||x||₁.', 'Gradient trơn là Aᵀ(Ax−b); h là λ||x||₁.')], [B(String.raw`Take f(x)=½||Ax−b||² and h(x)=λ||x||₁. Then ∇f(x)=Aᵀ(Ax−b), with L=||A||₂². A safe step η≤1/||A||₂² gives x⁺=S_{ηλ}(x−ηAᵀ(Ax−b)) coordinatewise. The only linear-algebra operation is a matrix-vector multiply; no inverse is formed.`, String.raw`Chọn f(x)=½||Ax−b||², h(x)=λ||x||₁. Khi đó ∇f(x)=Aᵀ(Ax−b), L=||A||₂². Bước an toàn η≤1/||A||₂² cho x⁺=S_{ηλ}(x−ηAᵀ(Ax−b)) theo từng tọa độ. Chỉ cần nhân ma trận-vector, không lập nghịch đảo.`)], [R(1,'Separates smooth and nonsmooth terms.','Tách hạng trơn/không trơn.'),R(2,'Computes gradient and Lipschitz constant.','Tính gradient và hằng số Lipschitz.'),R(1,'Writes correct thresholded update.','Viết cập nhật ngưỡng đúng.')], [B('Uses ||AᵀA|| without linking it to ||A||².', 'Dùng ||AᵀA|| mà không liên hệ với ||A||².')]),
      E(B('Counterexample: unsafe proximal step', 'Phản ví dụ: bước proximal không an toàn'), ['counterexample','transfer'], B(String.raw`Let f(x)=½x², h=0, L=1 and η=3. Compute the update and compare F(x⁺) with F(x) for x=1; identify the failed hypothesis.`, String.raw`Cho f(x)=½x², h=0, L=1, η=3. Tính cập nhật và so sánh F(x⁺) với F(x) khi x=1; nêu giả thiết thất bại.`), [B('prox of the zero function is the identity.', 'prox của hàm 0 là đồng nhất.')], [B(String.raw`x⁺=x−3x=−2. F(1)=.5 while F(−2)=2, so the objective increases fourfold. The theorem requires η≤1/L=1; smoothness and convexity alone do not justify this step.`, String.raw`x⁺=x−3x=−2. F(1)=.5 còn F(−2)=2, nên mục tiêu tăng gấp bốn. Định lý cần η≤1/L=1; chỉ lồi và trơn không biện minh bước này.`)], [R(1,'Computes update.','Tính cập nhật.'),R(2,'Compares objectives.','So sánh mục tiêu.'),R(1,'Names violated step restriction.','Nêu hạn chế bước bị vi phạm.')], [B('Treats h=0 as a projection onto zero.', 'Coi h=0 là phép chiếu về 0.')]),
    ],
  },
  {
    week: 72, title: B('Optimization graduate gate: primal, dual, and numerical evidence', 'Cổng tối ưu graduate: primal, dual và bằng chứng số'), level: 'graduate core', prerequisites: [61, 62, 63, 64, 65, 66, 67, 68, 69, 70, 71],
    outcomes: [B('Prove and apply a primal-dual optimality certificate.', 'Chứng minh và áp dụng chứng chỉ tối ưu primal-dual.'), B('Choose a numerically stable method and diagnose a failed assumption.', 'Chọn phương pháp ổn định số và chẩn đoán giả thiết thất bại.')],
    definitions: B(String.raw`For a feasible primal point x and a feasible dual point (λ,ν), weak duality brackets p*: q(λ,ν)≤p*≤f₀(x). The gap f₀(x)−q(λ,ν) is a computable certificate when both feasibility residuals are controlled. The gate has two alternate forms: A proves a Fenchel certificate for a regularized estimator; B proves a projected-method bound and analyzes a failure. Choose one form only; time remains 240 minutes.`, String.raw`Với điểm primal x khả thi và dual (λ,ν) khả thi, đối ngẫu yếu kẹp p*: q(λ,ν)≤p*≤f₀(x). Gap f₀(x)−q(λ,ν) là chứng chỉ tính được khi residual khả thi cả hai phía được kiểm soát. Cổng có hai đề thay thế: A chứng minh chứng chỉ Fenchel cho ước lượng có regularization; B chứng minh cận phương pháp chiếu và phân tích thất bại. Chỉ làm một đề; thời lượng vẫn 240 phút.`),
    theoremTitle: B('Zero primal-dual gap certifies global optimality', 'Khoảng cách primal-dual bằng không chứng nhận tối ưu toàn cục'),
    statement: B(String.raw`If x is primal feasible and (λ,ν) dual feasible with f₀(x)=q(λ,ν), then x is primal optimal, (λ,ν) is dual optimal and p*=d*. More generally, 0≤f₀(x)−p*≤f₀(x)−q(λ,ν).`, String.raw`Nếu x khả thi primal và (λ,ν) khả thi dual với f₀(x)=q(λ,ν), thì x tối ưu primal, (λ,ν) tối ưu dual, p*=d*. Tổng quát hơn, 0≤f₀(x)−p*≤f₀(x)−q(λ,ν).`),
    proof: B(String.raw`Weak duality gives q(λ,ν)≤p*≤f₀(x). If the outer values coincide, the sandwich forces p*=d*=f₀(x), proving both optimalities. Subtracting p* from the inequalities gives the nonnegative upper bound on primal suboptimality. No algorithmic convergence claim is needed: this is a certificate checked at the candidate points.`, String.raw`Đối ngẫu yếu cho q(λ,ν)≤p*≤f₀(x). Nếu hai đầu ngoài bằng nhau thì nguyên lý kẹp buộc p*=d*=f₀(x), chứng minh cả hai tối ưu. Trừ p* khỏi bất đẳng thức cho cận trên không âm của độ không tối ưu primal. Không cần khẳng định hội tụ thuật toán: đây là chứng chỉ kiểm tra tại các điểm ứng viên.`), sourceId: 'o-boyd', section: '§5.2–5.5; weak-duality sandwich restated as a certificate.',
    workedExample: B(String.raw`For min ½x² subject to x≥2, x=2 is feasible with value 2; λ=2 is dual feasible and q(2)=2. Equal feasible values certify exact optimality. If numerical rounding yields q=1.999 and primal 2.001, the gap .002 bounds the objective error only if feasibility is also verified.`, String.raw`Với min ½x², x≥2, x=2 khả thi giá trị 2; λ=2 khả thi dual và q(2)=2. Hai giá trị khả thi bằng nhau chứng nhận tối ưu chính xác. Nếu làm tròn cho q=1.999 và primal 2.001 thì gap .002 chặn sai số mục tiêu chỉ khi khả thi cũng được xác minh.`),
    failureCase: B(String.raw`A small duality gap computed at infeasible candidates is not a certificate. Likewise, form A's LASSO derivation and form B's projection proof are different assessed arguments; replacing constants within one proof does not create an alternate form.`, String.raw`Gap nhỏ tính tại ứng viên không khả thi không phải chứng chỉ. Tương tự, suy dẫn LASSO của đề A và chứng minh phép chiếu của đề B là hai lập luận được đánh giá khác nhau; thay hằng số trong một chứng minh không tạo đề thay thế.`),
    topic: 'optimization cumulative gate; primal-dual certificate; numerical and proof reasoning', readingSection: 'Boyd §§5.1–5.6, 9.1–10.4; Parikh & Boyd §4',
    exercises: [
      E(B('Read a primal-dual bracket', 'Đọc cận primal-dual'), ['computation','application'], B(String.raw`A feasible primal point has value 12.4 and a feasible dual point value 11.9. Bound the unknown optimum and the candidate's suboptimality.`, String.raw`Một điểm primal khả thi có giá trị 12.4, điểm dual khả thi có giá trị 11.9. Chặn tối ưu chưa biết và độ không tối ưu của ứng viên.`), [B('Place p* between dual lower and primal upper values.', 'Đặt p* giữa cận dưới dual và cận trên primal.')], [B(String.raw`Weak duality gives 11.9≤p*≤12.4. Hence candidate suboptimality 12.4−p* lies in [0,.5], so .5 is a certified upper bound.`, String.raw`Đối ngẫu yếu cho 11.9≤p*≤12.4. Vì thế độ không tối ưu 12.4−p* thuộc [0,.5], nên .5 là cận trên chứng nhận.`)], [R(1,'Orders the two feasible values.','Sắp đúng thứ tự hai giá trị khả thi.'),R(2,'Bounds p*.','Chặn p*.'),R(1,'Computes candidate error bound.','Tính cận sai số ứng viên.')], [B('Calls the primal candidate a lower bound for minimization.', 'Gọi ứng viên primal là cận dưới trong bài toán min.')]),
      E(B('Primal-dual certificate and one-step convergence', 'Chứng chỉ primal-dual và hội tụ một bước'), ['proof','derivation'], B(String.raw`(i) Derive q(λ,ν)≤p*≤f₀(x) and the zero-gap certificate for feasible points. (ii) For differentiable convex L-smooth f on R^d with minimizer x*, derive f(x−∇f(x)/L)−f(x*)≤(L/2)(||x−x*||²−||x−∇f(x)/L−x*||²), and state why the exact gradient-descent iterates converge in objective when summed.`, String.raw`(i) Suy ra q(λ,ν)≤p*≤f₀(x) và chứng chỉ gap 0 cho điểm khả thi. (ii) Với f khả vi lồi L-trơn trên R^d có nghiệm x*, suy f(x−∇f(x)/L)−f(x*)≤(L/2)(||x−x*||²−||x−∇f(x)/L−x*||²), rồi nêu vì sao cộng lại cho hội tụ mục tiêu của iterate gradient descent chính xác.`), [B('For (i), use weak duality. For (ii), combine the descent lemma and convex first-order inequality, then expand the squared distance.', 'Với (i), dùng đối ngẫu yếu. Với (ii), kết hợp bổ đề giảm và bất đẳng thức bậc nhất lồi, rồi khai triển khoảng cách bình phương.')], [B(String.raw`(i) For primal-feasible x and dual-feasible (λ,ν), weak duality gives q≤p*≤f₀(x); equality of the outside endpoints forces p*=q=f₀(x), so both points optimize. (ii) Write g=∇f(x), x⁺=x−g/L. L-smoothness gives f(x⁺)≤f(x)−||g||²/(2L). Convexity gives f(x)−f(x*)≤gᵀ(x−x*). Also ||x⁺−x*||²=||x−x*||²−(2/L)gᵀ(x−x*)+||g||²/L². Combining these inequalities yields f(x⁺)−f(x*)≤(L/2)(||x−x*||²−||x⁺−x*||²). Sum over k: Σ_{k=0}^{N−1}[f(x_{k+1})−f*]≤(L/2)||x₀−x*||². Since gaps are nonnegative, they tend to zero; monotonic descent follows from the descent lemma. This proves objective convergence (not a linear rate without strong convexity).`, String.raw`(i) Với x primal khả thi và (λ,ν) dual khả thi, đối ngẫu yếu cho q≤p*≤f₀(x); hai đầu bằng nhau buộc p*=q=f₀(x), nên cả hai điểm tối ưu. (ii) Đặt g=∇f(x), x⁺=x−g/L. L-trơn cho f(x⁺)≤f(x)−||g||²/(2L). Tính lồi cho f(x)−f(x*)≤gᵀ(x−x*). Đồng thời ||x⁺−x*||²=||x−x*||²−(2/L)gᵀ(x−x*)+||g||²/L². Kết hợp được f(x⁺)−f(x*)≤(L/2)(||x−x*||²−||x⁺−x*||²). Cộng k=0,…,N−1: Σ[f(x_{k+1})−f*]≤(L/2)||x₀−x*||². Gap không âm nên tiến về 0; bổ đề giảm cho mục tiêu giảm đơn điệu. Đây là hội tụ mục tiêu, chưa có tốc độ tuyến tính nếu thiếu lồi mạnh.`)], [R(1,'Uses feasibility-dependent weak-duality sandwich.','Dùng chuỗi đối ngẫu yếu phụ thuộc khả thi.'),R(1,'Applies descent lemma with η=1/L.','Áp bổ đề giảm với η=1/L.'),R(2,'Combines convexity and distance expansion to obtain the potential inequality.','Kết hợp tính lồi và khai triển khoảng cách ra bất đẳng thức thế.'),R(1,'Telescopes and states only the proved convergence rate.','Cộng triệt tiêu và nêu đúng rate đã chứng minh.')], [B('Uses only equal reported numbers or claims linear convergence without strong convexity.', 'Chỉ dùng hai số báo cáo bằng nhau hoặc khẳng định hội tụ tuyến tính khi thiếu lồi mạnh.')]),
      E(B('Numerical choice under ill-conditioning', 'Chọn phương pháp số khi kém điều kiện'), ['numerical analysis','application'], B(String.raw`A least-squares design matrix has κ₂(A)=10⁵. Compare κ₂(AᵀA) and give a stable solver choice plus one verification quantity.`, String.raw`Ma trận thiết kế bình phương tối thiểu có κ₂(A)=10⁵. So sánh κ₂(AᵀA), chọn bộ giải ổn định và nêu một đại lượng cần xác minh.`), [B('The normal equations produce condition number 10¹⁰.', 'Phương trình chuẩn tạo số điều kiện 10¹⁰.')], [B(String.raw`κ₂(AᵀA)=10¹⁰. Prefer QR or SVD applied directly to A, not an explicit inverse or normal equations. Verify a scaled residual/backward error and inspect singular values/rank; a small raw residual alone cannot certify parameter accuracy at this conditioning.`, String.raw`κ₂(AᵀA)=10¹⁰. Ưu tiên QR hoặc SVD trực tiếp trên A, không dùng nghịch đảo tường minh hay phương trình chuẩn. Kiểm tra residual/sai số ngược đã co giãn và xem trị suy biến/hạng; residual tuyệt đối nhỏ không tự chứng nhận tham số chính xác với mức điều kiện này.`)], [R(1,'Squares κ.','Bình phương κ.'),R(2,'Chooses QR/SVD for the stated reason.','Chọn QR/SVD đúng lý do.'),R(1,'Names a scaled verification.','Nêu phép kiểm tra có co giãn.')], [B('Recommends explicitly inverting AᵀA.', 'Khuyến nghị nghịch đảo tường minh AᵀA.')]),
      E(B('Form A — prove a Fenchel certificate for LASSO', 'Đề A — chứng minh chứng chỉ Fenchel cho LASSO'), ['proof','derivation'], B(String.raw`For P(x)=½||Ax−b||²+λ||x||₁, derive the dual D(u)=−½||u||²−bᵀu subject to ||Aᵀu||∞≤λ, using conjugates. Then show that any x,u satisfying primal feasibility, dual feasibility, u=Ax−b and −Aᵀu∈λ∂||x||₁ attain equal values.`, String.raw`Với P(x)=½||Ax−b||²+λ||x||₁, suy ra dual D(u)=−½||u||²−bᵀu với ||Aᵀu||∞≤λ bằng liên hợp. Sau đó chứng minh x,u thỏa primal khả thi, dual khả thi, u=Ax−b và −Aᵀu∈λ∂||x||₁ thì đạt hai giá trị bằng nhau.`), [B('Use conjugate of ½||·||² and conjugate of λ||·||₁; set u=Ax−b.', 'Dùng liên hợp của ½||·||² và λ||·||₁; đặt u=Ax−b.')], [B(String.raw`Write P(x)=g(Ax−b)+h(x), g(r)=½||r||², h(x)=λ||x||₁. The dual is sup_u{−g*(u)−bᵀu−h*(−Aᵀu)}. Since g*(u)=½||u||² and h*(v)=0 when ||v||∞≤λ (∞ otherwise), D is the stated constrained maximization. For the proposed pair, u=Ax−b gives the quadratic Fenchel equality; −Aᵀu∈∂h(x) gives the h equality. Adding the two equalities yields P(x)=D(u), so weak duality certifies optimality.`, String.raw`Viết P(x)=g(Ax−b)+h(x), g(r)=½||r||², h(x)=λ||x||₁. Dual là sup_u{−g*(u)−bᵀu−h*(−Aᵀu)}. Vì g*(u)=½||u||² và h*(v)=0 khi ||v||∞≤λ (vô hạn nếu không), ta được dual đã nêu. Với cặp đề bài, u=Ax−b cho dấu bằng Fenchel quadratic; −Aᵀu∈∂h(x) cho dấu bằng của h. Cộng hai đẳng thức được P(x)=D(u), nên đối ngẫu yếu chứng nhận tối ưu.`)], [R(2,'Computes both conjugates and the dual domain.','Tính hai liên hợp và miền dual.'),R(2,'Derives stationarity/subgradient equality.','Suy ra đẳng thức dừng/dưới gradient.'),R(1,'Uses zero gap to certify optimality.','Dùng gap 0 để chứng nhận tối ưu.')], [B('Uses ||Aᵀu||₂≤λ instead of the infinity norm.', 'Dùng chuẩn 2 thay chuẩn vô cùng.')]),
      E(B('Form B — prove a projected-gradient regret bound', 'Đề B — chứng minh cận regret projected-gradient'), ['proof','transfer'], B(String.raw`Let C be compact convex of diameter D, and let f₁,…,f_T be convex with ||∇f_t(x)||≤G on C. For x_{t+1}=Π_C(x_t−η∇f_t(x_t)), prove Σ[f_t(x_t)−f_t(u)]≤D²/(2η)+ηG²T/2 for every fixed u∈C. Then show why this is not a statistical-significance or profitability claim.`, String.raw`Cho C compact lồi đường kính D, f₁,…,f_T lồi và ||∇f_t(x)||≤G trên C. Với x_{t+1}=Π_C(x_t−η∇f_t(x_t)), chứng minh Σ[f_t(x_t)−f_t(u)]≤D²/(2η)+ηG²T/2 với mọi u∈C cố định. Sau đó giải thích vì sao đây không phải khẳng định ý nghĩa thống kê hay lợi nhuận.`), [B('Use projection nonexpansiveness, expand distance, sum and invoke convexity.', 'Dùng không giãn phép chiếu, khai triển khoảng cách, cộng rồi dùng tính lồi.')], [B(String.raw`Projection gives ||x_{t+1}−u||²≤||x_t−ηg_t−u||². Rearrange to g_tᵀ(x_t−u)≤[||x_t−u||²−||x_{t+1}−u||²]/(2η)+η||g_t||²/2. Convexity yields f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Sum: potentials telescope to at most D²/(2η), while the gradient terms contribute ηG²T/2. The result compares cumulative losses with a fixed feasible comparator in the specified sequence; it contains no sampling uncertainty model, transaction costs or return conversion, so it proves neither statistical significance nor profit.`, String.raw`Phép chiếu cho ||x_{t+1}−u||²≤||x_t−ηg_t−u||². Chuyển vế được g_tᵀ(x_t−u)≤[||x_t−u||²−||x_{t+1}−u||²]/(2η)+η||g_t||²/2. Tính lồi cho f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Cộng lại: thế triệt tiêu còn tối đa D²/(2η), hạng gradient góp ηG²T/2. Kết quả so sánh loss tích lũy với comparator cố định trong chuỗi cho trước; không có mô hình bất định lấy mẫu, chi phí giao dịch hay chuyển đổi thành return, nên không chứng minh ý nghĩa thống kê hoặc lợi nhuận.`)], [R(1,'Uses projection inequality.','Dùng bất đẳng thức chiếu.'),R(2,'Derives one-step potential and telescopes.','Suy ra thế một bước và cộng triệt tiêu.'),R(1,'Applies convexity and gradient bound.','Dùng tính lồi và cận gradient.'),R(1,'Separates regret from inference/economics.','Tách regret khỏi suy luận/kinh tế.')], [B('Compares against a changing comparator without a variation term.', 'So sánh với comparator thay đổi mà không có hạng biến thiên.')]),
    ],
  },
  {
    week: 73, title: B('Stationarity, autocovariance, and long-run variance', 'Tính dừng, tự hiệp phương sai và phương sai dài hạn'), level: 'graduate core', prerequisites: [44, 58, 60, 72],
    outcomes: [B('Distinguish strict and weak stationarity and construct a counterexample to the converse.', 'Phân biệt tính dừng nghiêm ngặt/yếu và dựng phản ví dụ cho chiều ngược.'), B('Derive sample-mean variance under dependence and state when the long-run variance exists.', 'Suy ra phương sai trung bình mẫu dưới phụ thuộc và nêu điều kiện tồn tại phương sai dài hạn.')],
    definitions: B(String.raw`Strict stationarity means every finite-dimensional distribution is invariant under time shifts. Weak stationarity requires finite second moments, constant mean μ, and Cov(X_t,X_{t+h})=γ(h), independent of t. Then γ(−h)=γ(h). The long-run variance is Ω=Σ_{h∈Z}γ(h) when the series converges absolutely. Strict plus finite second moment implies weak stationarity; the converse need not hold.`, String.raw`Dừng nghiêm ngặt nghĩa là mọi phân phối hữu hạn chiều bất biến theo dịch thời gian. Dừng yếu cần moment bậc hai hữu hạn, kỳ vọng μ không đổi và Cov(X_t,X_{t+h})=γ(h), không phụ thuộc t. Khi đó γ(−h)=γ(h). Phương sai dài hạn Ω=Σ_{h∈Z}γ(h) nếu chuỗi hội tụ tuyệt đối. Dừng nghiêm ngặt cùng moment bậc hai hữu hạn kéo theo dừng yếu; chiều ngược không nhất thiết đúng.`),
    theoremTitle: B('Finite-sample variance identity and long-run variance limit', 'Đẳng thức phương sai hữu hạn mẫu và giới hạn phương sai dài hạn'),
    statement: B(String.raw`For weakly stationary X_t with absolutely summable autocovariances, Var(√n( X̄_n−μ))=Σ_{|h|<n}(1−|h|/n)γ(h)→Ω=Σ_{h∈Z}γ(h). The Toeplitz covariance matrix Γ_n=[γ(i−j)] is positive semidefinite.`, String.raw`Với X_t dừng yếu có tự hiệp phương sai tuyệt đối khả tổng, Var(√n( X̄_n−μ))=Σ_{|h|<n}(1−|h|/n)γ(h)→Ω=Σ_{h∈Z}γ(h). Ma trận Toeplitz hiệp phương sai Γ_n=[γ(i−j)] nửa xác định dương.`),
    proof: B(String.raw`Expand Var(n⁻¹Σ_t X_t)=n⁻²Σ_{s,t}γ(s−t). For each lag h with |h|<n there are n−|h| pairs (s,t), so multiplying by n yields the displayed finite sum. Absolute summability and |1−|h|/n|≤1 allow dominated convergence over h, giving Ω. For any a∈R^n, aᵀΓ_na=Var(Σ_i a_i(X_i−μ))≥0, proving positive semidefiniteness.`, String.raw`Khai triển Var(n⁻¹Σ_t X_t)=n⁻²Σ_{s,t}γ(s−t). Với mỗi độ trễ |h|<n có n−|h| cặp (s,t), nhân n được tổng hữu hạn đã nêu. Hội tụ tuyệt đối và |1−|h|/n|≤1 cho phép hội tụ bị chặn theo h, thu được Ω. Với a∈R^n, aᵀΓ_na=Var(Σ_i a_i(X_i−μ))≥0, chứng minh nửa xác định dương.`), sourceId: 'o-mit-ts', section: 'Lecture Notes 1 (stationarity and covariance structure); Lecture Notes 2 (limit theorems).',
    workedExample: B(String.raw`For a centered weakly stationary AR(1) with γ(h)=σ_X²ρ^{|h|}, |ρ|<1, Ω=σ_X²(1+2Σ_{h≥1}ρ^h)=σ_X²(1+ρ)/(1−ρ). At ρ=.5 the sample-mean variance asymptotically triples the IID variance σ_X²/n.`, String.raw`Với AR(1) dừng yếu trung tâm có γ(h)=σ_X²ρ^{|h|}, |ρ|<1, Ω=σ_X²(1+2Σ_{h≥1}ρ^h)=σ_X²(1+ρ)/(1−ρ). Khi ρ=.5, phương sai trung bình mẫu tiệm cận gấp ba phương sai IID σ_X²/n.`),
    failureCase: B(String.raw`A random walk X_t=X_{t−1}+ε_t with nonzero innovation variance has Var(X_t)=Var(X_0)+tσ², so it is not weakly stationary and has no lag-only autocovariance. Applying Ω/n standard errors to levels is invalid.`, String.raw`Random walk X_t=X_{t−1}+ε_t với phương sai nhiễu khác 0 có Var(X_t)=Var(X_0)+tσ², nên không dừng yếu và không có tự hiệp phương sai chỉ phụ thuộc độ trễ. Dùng sai số chuẩn Ω/n cho mức là không hợp lệ.`),
    topic: 'strict/weak stationarity; autocovariance; covariance PSD; long-run variance', readingSection: 'Lecture Notes 1–2',
    exercises: [
      E(B('Autocovariance and PSD check', 'Kiểm tra tự hiệp phương sai và PSD'), ['computation'], B(String.raw`For γ(h)=.25(.6)^{|h|}, compute γ(0), γ(1), γ(−1), and Ω. State why Ω is positive.`, String.raw`Với γ(h)=.25(.6)^{|h|}, tính γ(0), γ(1), γ(−1), Ω và nêu vì sao Ω dương.`), [B('Use symmetry and sum the geometric tail.', 'Dùng tính đối xứng rồi cộng cấp số nhân.')], [B(String.raw`γ(0)=.25; γ(1)=γ(−1)=.15. Ω=.25[1+2(.6)/(1−.6)]=.25(4)=1. The AR(1)-form covariance has positive long-run variance; algebra confirms positivity.`, String.raw`γ(0)=.25; γ(1)=γ(−1)=.15. Ω=.25[1+2(.6)/(1−.6)]=.25(4)=1. Dạng hiệp phương sai AR(1) cho phương sai dài hạn dương; phép tính xác nhận.`)], [R(1,'Uses evenness of γ.','Dùng tính chẵn của γ.'),R(2,'Sums both tails.','Cộng cả hai đuôi.'),R(1,'States interpretation.','Nêu diễn giải.')], [B('Counts lag zero twice.', 'Đếm độ trễ 0 hai lần.')]),
      E(B('Prove the sample-mean variance formula', 'Chứng minh công thức phương sai trung bình mẫu'), ['proof'], B(String.raw`From Var(ΣX_t)=Σ_{s,t}γ(s−t), count pairs at each lag and derive the finite-n Bartlett weights.`, String.raw`Từ Var(ΣX_t)=Σ_{s,t}γ(s−t), đếm số cặp ở mỗi độ trễ và suy ra trọng số Bartlett hữu hạn n.`), [B('For lag h, count allowable starting indices.', 'Với độ trễ h, đếm các chỉ số bắt đầu khả dĩ.')], [B(String.raw`There are n−|h| pairs with s−t=h when |h|<n and none otherwise. Thus Var(X̄_n)=n⁻²Σ_{|h|<n}(n−|h|)γ(h); multiplying by n yields Σ(1−|h|/n)γ(h).`, String.raw`Có n−|h| cặp với s−t=h khi |h|<n, ngoài ra không có. Do đó Var(X̄_n)=n⁻²Σ_{|h|<n}(n−|h|)γ(h); nhân n được Σ(1−|h|/n)γ(h).`)], [R(1,'Writes covariance double sum.','Viết tổng kép hiệp phương sai.'),R(2,'Counts n−|h| pairs.','Đếm n−|h| cặp.'),R(1,'Gets normalization right.','Chuẩn hóa đúng.')], [B('Uses n−h for negative lags without absolute value.', 'Dùng n−h cho độ trễ âm mà thiếu trị tuyệt đối.')]),
      E(B('Weak but not strict stationarity', 'Dừng yếu nhưng không dừng nghiêm ngặt'), ['counterexample','proof'], B('Let U_k,V_k be independent Rademacher variables across k∈Z and set (X_{3k},X_{3k+1},X_{3k+2})=(U_k,V_k,(-1)^k U_kV_k). Prove weak stationarity and show strict stationarity fails.', 'Cho U_k,V_k là biến Rademacher độc lập qua k∈Z, đặt (X_{3k},X_{3k+1},X_{3k+2})=(U_k,V_k,(-1)^kU_kV_k). Chứng minh dừng yếu và chỉ ra dừng nghiêm ngặt thất bại.'), [B('Check marginals and pairs; then inspect the triple product across blocks.', 'Kiểm tra biên và cặp; sau đó xét tích bộ ba qua block.')], [B('Each X_t is Rademacher. Within a block, every distinct pair among U,V,UV is independent; different blocks are independent. Thus mean 0, variance 1 and every nonzero-lag covariance 0, independent of t: weak stationarity. But X_{3k}X_{3k+1}X_{3k+2}=(-1)^k deterministically, so the law of consecutive triples changes with k; strict stationarity fails.', 'Mỗi X_t là Rademacher. Trong block, mọi cặp khác nhau trong U,V,UV độc lập; block khác độc lập. Vậy mean 0, variance 1, covariance lag khác 0 bằng 0, không phụ thuộc t: dừng yếu. Nhưng X_{3k}X_{3k+1}X_{3k+2}=(-1)^k xác định, nên luật bộ ba liên tiếp đổi theo k; dừng nghiêm ngặt thất bại.')], [R(1,'Verifies marginals and pair independence.','Kiểm tra biên và độc lập từng cặp.'),R(2,'Computes constant mean and covariance.','Tính mean và covariance không đổi.'),R(1,'Uses the triple law to refute strict stationarity.','Dùng luật bộ ba bác dừng nghiêm ngặt.')], [B('Checks only covariances and concludes strict stationarity.','Chỉ kiểm covariance rồi kết luận dừng nghiêm ngặt.')]),
      E(B('Prove covariance matrices are PSD', 'Chứng minh ma trận hiệp phương sai PSD'), ['proof','derivation'], B(String.raw`For any finite vector (X₁,…,X_n) with finite second moments, prove its covariance matrix Γ is PSD and explain why negative estimated eigenvalues can arise numerically.`, String.raw`Với vector hữu hạn (X₁,…,X_n) có moment bậc hai hữu hạn, chứng minh ma trận hiệp phương sai Γ PSD và giải thích vì sao trị riêng ước lượng âm có thể xuất hiện số học.`), [B('Write aᵀΓa as a variance.', 'Viết aᵀΓa thành phương sai.')], [B(String.raw`For any a, aᵀΓa=Var(aᵀX)≥0, hence Γ⪰0. A sample covariance computed by exact centered outer products is PSD in exact arithmetic; rounding, asymmetric lag truncation or independent entry estimates can introduce small negative eigenvalues. Large negative eigenvalues signal a construction/conditioning issue, not valid covariance geometry.`, String.raw`Với mọi a, aᵀΓa=Var(aᵀX)≥0 nên Γ⪰0. Hiệp phương sai mẫu từ tích ngoài đã trừ trung bình là PSD trong số học chính xác; làm tròn, cắt độ trễ không đối xứng hoặc ước lượng từng phần tử độc lập có thể tạo trị riêng âm nhỏ. Trị âm lớn báo vấn đề dựng ma trận/điều kiện hóa, không phải hình học covariance hợp lệ.`)], [R(1,'Expands variance.','Khai triển phương sai.'),R(2,'Uses nonnegativity for every vector.','Dùng không âm với mọi vector.'),R(1,'Distinguishes rounding from structure.','Phân biệt làm tròn với cấu trúc.')], [B('Checks diagonal entries only.', 'Chỉ kiểm tra các phần tử đường chéo.')]),
      E(B('Transfer: long-run variance under absolute summability', 'Chuyển giao: phương sai dài hạn khi khả tổng tuyệt đối'), ['proof','transfer'], B(String.raw`Use the finite-n identity and dominated convergence to justify Ω as the limit of n Var(X̄_n); state exactly what summability assumption is used.`, String.raw`Dùng đẳng thức hữu hạn n và hội tụ bị chặn để biện minh Ω là giới hạn n Var(X̄_n); nêu chính xác giả thiết khả tổng.`), [B('Extend the finite sum by zeros and dominate each lag term by |γ(h)|.', 'Kéo tổng hữu hạn thành tổng vô hạn bằng số 0 và chặn mỗi hạng bởi |γ(h)|.')], [B(String.raw`Set a_{n,h}=1_{|h|<n}(1−|h|/n)γ(h). For each fixed h, a_{n,h}→γ(h); |a_{n,h}|≤|γ(h)|. If Σ_{h∈Z}|γ(h)|<∞, dominated convergence for series yields Σ_h a_{n,h}→Σ_hγ(h)=Ω. This proves the variance limit, not a CLT; a distributional limit needs additional dependence assumptions.`, String.raw`Đặt a_{n,h}=1_{|h|<n}(1−|h|/n)γ(h). Với h cố định, a_{n,h}→γ(h); |a_{n,h}|≤|γ(h)|. Nếu Σ_{h∈Z}|γ(h)|<∞, hội tụ bị chặn cho chuỗi cho Σ_h a_{n,h}→Σ_hγ(h)=Ω. Điều này chứng minh giới hạn phương sai, chưa phải CLT; giới hạn phân phối cần giả thiết phụ thuộc bổ sung.`)], [R(1,'Defines lag-indexed terms.','Định nghĩa hạng theo độ trễ.'),R(2,'States pointwise convergence and domination.','Nêu hội tụ từng điểm và chặn.'),R(1,'Separates variance limit from CLT.','Tách giới hạn phương sai khỏi CLT.')], [B('Claims dominated convergence proves a Gaussian limit.', 'Cho rằng hội tụ bị chặn chứng minh giới hạn Gaussian.')]),
    ],
  },
  {
    week: 74, title: B('ARMA causality, invertibility, and unit roots', 'ARMA nhân quả, khả nghịch và nghiệm đơn vị'), level: 'graduate core', prerequisites: [73],
    outcomes: [B('Derive the stationary AR(1) solution and Yule–Walker equation.', 'Suy ra nghiệm AR(1) dừng và phương trình Yule–Walker.'), B('Diagnose unit-root and root-location failures instead of assuming differencing repairs every series.', 'Chẩn đoán nghiệm đơn vị và thất bại định vị nghiệm thay vì mặc định sai phân chữa mọi chuỗi.')],
    definitions: B(String.raw`For AR(p), φ(B)X_t=ε_t with lag operator BX_t=X_{t−1}. A causal linear solution exists when φ(z)≠0 for |z|≤1; it is a convergent filter of present/past innovations. For MA(q), invertibility means θ(z)≠0 for |z|≤1, allowing innovations to be recovered from present/past observations. AR(1) X_t=φX_{t−1}+ε_t is covariance-stationary for |φ|<1 when ε is white noise with finite variance.`, String.raw`Với AR(p), φ(B)X_t=ε_t, toán tử trễ BX_t=X_{t−1}. Nghiệm nhân quả tuyến tính tồn tại khi φ(z)≠0 với |z|≤1; đây là bộ lọc hội tụ của nhiễu hiện tại/quá khứ. Với MA(q), khả nghịch nghĩa θ(z)≠0 với |z|≤1, cho phép khôi phục innovation từ quan sát hiện tại/quá khứ. AR(1) X_t=φX_{t−1}+ε_t dừng hiệp phương sai khi |φ|<1, ε là nhiễu trắng có phương sai hữu hạn.`),
    theoremTitle: B('Stationary AR(1) autocovariance and Yule–Walker', 'Tự hiệp phương sai AR(1) dừng và Yule–Walker'),
    statement: B(String.raw`If |φ|<1 and ε_t is zero-mean white noise with variance σ², the unique causal finite-variance solution is X_t=Σ_{j=0}∞φ^jε_{t−j}. It has γ(0)=σ²/(1−φ²) and γ(h)=φ^{|h|}γ(0).`, String.raw`Nếu |φ|<1 và ε_t là nhiễu trắng kỳ vọng 0, phương sai σ², nghiệm nhân quả hữu hạn phương sai duy nhất là X_t=Σ_{j=0}∞φ^jε_{t−j}. Khi đó γ(0)=σ²/(1−φ²), γ(h)=φ^{|h|}γ(0).`),
    proof: B(String.raw`The geometric coefficients are square-summable, so the series converges in L². Its mean is zero; shifting indices shows it satisfies X_t=φX_{t−1}+ε_t. Multiply the equation by X_{t−1} and take expectations: γ(1)=φγ(0), since ε_t is orthogonal to the past. For h≥1, multiplying by X_{t−h} gives γ(h)=φγ(h−1). At lag zero, Var(X_t)=φ²Var(X_{t−1})+σ² because the innovation is orthogonal to the past, yielding γ(0)=σ²/(1−φ²). Symmetry gives negative lags. For uniqueness among stationary finite-variance causal solutions driven by the same innovations, their difference D_t satisfies D_t=φD_{t−1}; stationarity implies Var(D_t)=Var(D_{t−1}), while the recursion gives Var(D_t)=φ²Var(D_{t−1}). Since |φ|<1, Var(D_t)=0, and the zero-mean difference is zero almost surely.`, String.raw`Hệ số hình học bình phương khả tổng nên chuỗi hội tụ trong L². Kỳ vọng bằng 0; dịch chỉ số cho thấy X_t=φX_{t−1}+ε_t. Nhân phương trình với X_{t−1}, lấy kỳ vọng: γ(1)=φγ(0), vì ε_t trực giao với quá khứ. Với h≥1, nhân X_{t−h} được γ(h)=φγ(h−1). Ở độ trễ 0, Var(X_t)=φ²Var(X_{t−1})+σ² do innovation trực giao quá khứ, suy ra γ(0)=σ²/(1−φ²). Độ trễ âm theo tính đối xứng. Để chứng minh duy nhất trong lớp nghiệm nhân quả dừng moment hai hữu hạn cùng innovation, hiệu D_t thỏa D_t=φD_{t−1}; tính dừng cho Var(D_t)=Var(D_{t−1}), còn truy hồi cho Var(D_t)=φ²Var(D_{t−1}). Vì |φ|<1 nên Var(D_t)=0, và hiệu kỳ vọng không bằng không với xác suất một.`), sourceId: 'o-mit-ts', section: 'Lecture Notes 1 (ARMA and covariance structure); Lecture Notes 17 (unit roots).',
    workedExample: B(String.raw`For φ=−.5, σ²=3, γ(0)=3/(1−.25)=4 and γ(1)=−2; correlation alternates signs and decays geometrically. The negative lag-one correlation does not violate stationarity.`, String.raw`Với φ=−.5, σ²=3, γ(0)=3/(1−.25)=4 và γ(1)=−2; tương quan đổi dấu rồi giảm hình học. Tự tương quan âm ở độ trễ một không vi phạm tính dừng.`),
    failureCase: B(String.raw`At φ=1, X_t=X_{t−1}+ε_t is a unit-root random walk; variance grows with t and no stationary infinite-past geometric sum exists. A structural break in mean can also mimic a unit root, so unit-root tests require a specified deterministic component and have nonstandard null distributions.`, String.raw`Tại φ=1, X_t=X_{t−1}+ε_t là random walk nghiệm đơn vị; phương sai tăng theo t và không tồn tại tổng hình học quá khứ dừng. Gãy cấu trúc ở kỳ vọng cũng có thể giống nghiệm đơn vị, nên kiểm định cần xác định thành phần xác định và có phân phối không chuẩn dưới giả thuyết không.`),
    topic: 'ARMA causality/invertibility; Yule–Walker; unit roots and breaks', readingSection: 'Lecture Notes 1, 17–19',
    exercises: [
      E(B('Yule–Walker values', 'Giá trị Yule–Walker'), ['computation'], B(String.raw`For an AR(1) with φ=.8 and σ²=1.44, compute γ(0), γ(1), and γ(3).`, String.raw`Với AR(1) φ=.8, σ²=1.44, tính γ(0), γ(1), γ(3).`), [B('Use γ(h)=φ^hγ(0) for h≥0.', 'Dùng γ(h)=φ^hγ(0) với h≥0.')], [B(String.raw`γ(0)=1.44/(1−.64)=4; γ(1)=3.2; γ(3)=.8³·4=2.048.`, String.raw`γ(0)=1.44/(1−.64)=4; γ(1)=3.2; γ(3)=.8³·4=2.048.`)], [R(1,'Computes denominator.','Tính mẫu số.'),R(2,'Finds variance and lag one.','Tìm phương sai và lag một.'),R(1,'Uses lag-three power.','Dùng lũy thừa lag ba.')], [B('Uses σ²/(1−φ) instead of 1−φ².', 'Dùng σ²/(1−φ) thay 1−φ².')]),
      E(B('Derive Yule–Walker for AR(1)', 'Suy ra Yule–Walker cho AR(1)'), ['proof'], B(String.raw`Multiply X_t=φX_{t−1}+ε_t by X_{t−h}, take expectations for h≥1, and derive γ(h)=φγ(h−1); explain the orthogonality used.`, String.raw`Nhân X_t=φX_{t−1}+ε_t với X_{t−h}, lấy kỳ vọng với h≥1, suy ra γ(h)=φγ(h−1); giải thích tính trực giao được dùng.`), [B('ε_t is orthogonal to variables measurable from innovations through t−1.', 'ε_t trực giao với biến đo được từ các innovation đến t−1.')], [B(String.raw`E[X_tX_{t−h}]=φE[X_{t−1}X_{t−h}]+E[ε_tX_{t−h}]. For h≥1, X_{t−h} is past-measurable and the last expectation is zero; the first is φγ(h−1). At h=0, the product E[ε_tX_t]=σ², yielding γ(0)=φγ(1)+σ².`, String.raw`E[X_tX_{t−h}]=φE[X_{t−1}X_{t−h}]+E[ε_tX_{t−h}]. Với h≥1, X_{t−h} đo được từ quá khứ nên hạng cuối bằng 0; hạng đầu là φγ(h−1). Với h=0, E[ε_tX_t]=σ², suy ra γ(0)=φγ(1)+σ².`)], [R(1,'Expands covariance equation.','Khai triển phương trình covariance.'),R(2,'Justifies zero cross term.','Biện minh hạng chéo bằng 0.'),R(1,'Handles lag zero separately.','Xử lý lag 0 riêng.')], [B('Assumes ε_t is independent of all future X values.', 'Giả sử ε_t độc lập với mọi X tương lai.')]),
      E(B('Causality and invertibility roots', 'Nghiệm nhân quả và khả nghịch'), ['application','computation'], B(String.raw`Classify AR(1) φ=.7 for causality/stationarity and MA(1) X_t=ε_t+.8ε_{t−1} for invertibility using polynomial roots.`, String.raw`Phân loại AR(1) φ=.7 về nhân quả/dừng và MA(1) X_t=ε_t+.8ε_{t−1} về khả nghịch bằng nghiệm đa thức.`), [B('AR polynomial is 1−φz; MA polynomial is 1+.8z.', 'Đa thức AR là 1−φz; MA là 1+.8z.')], [B(String.raw`AR root solves 1−.7z=0, z≈1.429 outside the unit circle, so the causal stationary solution exists. MA root solves 1+.8z=0, z=−1.25 outside the unit circle, so the MA is invertible under the stated convention.`, String.raw`Nghiệm AR giải 1−.7z=0, z≈1.429 ngoài đường tròn đơn vị nên có nghiệm nhân quả dừng. Nghiệm MA giải 1+.8z=0, z=−1.25 ngoài đường tròn đơn vị nên MA khả nghịch theo quy ước đã nêu.`)], [R(1,'Writes correct polynomials.','Viết đúng đa thức.'),R(2,'Computes roots.','Tính nghiệm.'),R(1,'Applies root-location rule.','Áp dụng quy tắc vị trí nghiệm.')], [B('Uses the AR root φ instead of 1/φ.', 'Dùng φ làm nghiệm AR thay vì 1/φ.')]),
      E(B('Transfer: nonstationary differenced series', 'Chuyển giao: chuỗi sai phân không dừng'), ['proof','transfer'], B(String.raw`Let X_t=X_{t−1}+ε_t and ΔX_t=ε_t. Show ΔX_t is weakly stationary white noise but X_t is not; state why a stationary ARMA limit theorem on levels is unavailable.`, String.raw`Cho X_t=X_{t−1}+ε_t, ΔX_t=ε_t. Chứng minh ΔX_t là nhiễu trắng dừng yếu còn X_t không dừng; nêu vì sao không áp dụng định lý giới hạn ARMA dừng trên mức.`), [B('Compute Var(X_t) and Cov(ε_t,ε_s).', 'Tính Var(X_t) và Cov(ε_t,ε_s).')], [B(String.raw`For iid zero-mean innovations of variance σ², ΔX_t=ε_t has constant mean, variance σ² and zero nonzero-lag covariance, so it is weakly stationary. If X₀ is fixed, Var(X_t)=tσ², which changes with t; X is not weakly stationary. A limit theorem requiring covariance stationarity or summable fixed-lag covariances for levels cannot be applied to X_t.`, String.raw`Với innovation iid kỳ vọng 0, phương sai σ², ΔX_t=ε_t có kỳ vọng/phương sai cố định và covariance ngoài lag 0 bằng 0 nên dừng yếu. Nếu X₀ cố định thì Var(X_t)=tσ² thay đổi theo t; X không dừng yếu. Không áp dụng được định lý giới hạn cần dừng covariance hoặc tự hiệp phương sai cố định khả tổng cho mức X_t.`)], [R(1,'Establishes stationarity of differences.','Chứng minh sai phân dừng.'),R(2,'Shows level variance grows.','Chỉ ra phương sai mức tăng.'),R(1,'Matches theorem assumptions to levels.','Đối chiếu giả thiết định lý với mức.')], [B('Claims differencing makes the original level stationary.', 'Khẳng định sai phân khiến chính mức ban đầu dừng.')]),
      E(B('Counterexample: structural break versus unit root', 'Phản ví dụ: gãy cấu trúc so với nghiệm đơn vị'), ['counterexample','transfer'], B(String.raw`Compare X_t=μ_t+ε_t with μ_t=0 for t≤0 and μ_t=5 for t>0 against a random walk. Which has growing variance? Why can a mean break distort a unit-root diagnosis?`, String.raw`So sánh X_t=μ_t+ε_t với μ_t=0 khi t≤0, μ_t=5 khi t>0 với random walk. Chuỗi nào có phương sai tăng? Vì sao gãy kỳ vọng làm lệch chẩn đoán nghiệm đơn vị?`), [B('The break shifts the mean but not the innovation variance at each fixed t.', 'Gãy dịch kỳ vọng nhưng không làm phương sai innovation tại từng t tăng.')], [B(String.raw`The one-time mean break has Var(X_t)=Var(ε_t)=σ² on both regimes (away from uncertainty over the break date), whereas a random walk variance grows linearly in t. The level shift causes persistent apparent deviations and changes sample autocorrelations, so a unit-root test with an omitted break can confuse deterministic nonstationarity with stochastic persistence. Model the break or report this ambiguity.`, String.raw`Gãy kỳ vọng một lần có Var(X_t)=Var(ε_t)=σ² ở cả hai chế độ (khi thời điểm gãy đã biết), còn phương sai random walk tăng tuyến tính theo t. Dịch mức tạo lệch dai dẳng và đổi tự tương quan mẫu; kiểm định nghiệm đơn vị bỏ qua gãy có thể nhầm không dừng tất định với bền vững ngẫu nhiên. Cần mô hình hóa gãy hoặc báo sự mơ hồ.`)], [R(1,'Distinguishes variance behavior.','Phân biệt hành vi phương sai.'),R(2,'Explains test misspecification.','Giải thích sai đặc tả kiểm định.'),R(1,'States a responsible conclusion.','Nêu kết luận thận trọng.')], [B('Says every persistent series has a unit root.', 'Nói mọi chuỗi bền vững đều có nghiệm đơn vị.')]),
    ],
  },
  {
    week: 75, title: B('Linear filters, spectral density, and covariance geometry', 'Bộ lọc tuyến tính, mật độ phổ và hình học covariance'), level: 'graduate core', prerequisites: [73, 74],
    outcomes: [B('Compute the transfer function and spectral density of a stable linear filter.', 'Tính hàm truyền và mật độ phổ của bộ lọc tuyến tính ổn định.'), B('Connect zero-frequency spectral power to long-run variance.', 'Liên hệ công suất phổ tần số 0 với phương sai dài hạn.')],
    definitions: B(String.raw`For a zero-mean weakly stationary process with absolutely summable γ(h), define f(ω)=(1/(2π))Σ_{h∈Z}γ(h)e^{−ihω}, −π≤ω≤π. Then γ(h)=∫_{−π}^{π}e^{ihω}f(ω)dω. For X_t=Σ_j ψ_j ε_{t−j} with Σ|ψ_j|<∞ and white noise variance σ², transfer Ψ(e^{−iω})=Σψ_j e^{−ijω} and f_X(ω)=σ²|Ψ(e^{−iω})|²/(2π).`, String.raw`Với quá trình dừng yếu kỳ vọng 0, Σ|γ(h)|<∞, đặt f(ω)=(1/(2π))Σ_{h∈Z}γ(h)e^{−ihω}, −π≤ω≤π. Khi đó γ(h)=∫_{−π}^{π}e^{ihω}f(ω)dω. Với X_t=Σ_j ψ_j ε_{t−j}, Σ|ψ_j|<∞, nhiễu trắng phương sai σ², hàm truyền Ψ(e^{−iω})=Σψ_j e^{−ijω} và f_X(ω)=σ²|Ψ(e^{−iω})|²/(2π).`),
    theoremTitle: B('Linear filtering multiplies the input spectrum by squared gain', 'Bộ lọc tuyến tính nhân phổ đầu vào với bình phương độ lợi'),
    statement: B(String.raw`Under the stated absolutely summable filter and white-noise assumptions, f_X(ω)=σ²|Ψ(e^{−iω})|²/(2π) is nonnegative and integrates to Var(X_t).`, String.raw`Dưới giả thiết bộ lọc khả tổng tuyệt đối và nhiễu trắng đã nêu, f_X(ω)=σ²|Ψ(e^{−iω})|²/(2π) không âm và tích phân bằng Var(X_t).`),
    proof: B(String.raw`Expand γ_X(h)=E[Σ_jψ_jε_{t−j} Σ_kψ_kε_{t−h−k}]=σ²Σ_jψ_jψ_{j−h}, using orthogonality of distinct innovations; absolute summability justifies rearrangement. Its Fourier series is σ²/(2π)(Σ_jψ_j e^{−ijω})(Σ_kψ_k e^{ikω})=σ²|Ψ(e^{−iω})|²/(2π), nonnegative. Integrating over [−π,π] keeps only the zero Fourier coefficient and gives γ_X(0)=Var(X_t).`, String.raw`Khai triển γ_X(h)=E[Σ_jψ_jε_{t−j} Σ_kψ_kε_{t−h−k}]=σ²Σ_jψ_jψ_{j−h}, dùng tính trực giao của innovation khác thời điểm; khả tổng tuyệt đối cho phép đổi thứ tự. Chuỗi Fourier bằng σ²/(2π)(Σ_jψ_j e^{−ijω})(Σ_kψ_k e^{ikω})=σ²|Ψ(e^{−iω})|²/(2π), không âm. Tích phân trên [−π,π] chỉ giữ hệ số Fourier lag 0 và bằng γ_X(0)=Var(X_t).`), sourceId: 'o-mit-ts', section: 'Lecture Notes 4 (spectrum); Notes 5 (spectrum estimation).',
    workedExample: B(String.raw`For AR(1), ψ_j=φ^j for j≥0 and Ψ(e^{−iω})=1/(1−φe^{−iω}); therefore f(ω)=σ²/[2π(1+φ²−2φ cosω)]. At ω=0 it is largest for φ>0, matching Ω=2πf(0)=σ²/(1−φ)².`, String.raw`Với AR(1), ψ_j=φ^j, j≥0, Ψ(e^{−iω})=1/(1−φe^{−iω}); vậy f(ω)=σ²/[2π(1+φ²−2φ cosω)]. Khi ω=0, phổ lớn nhất nếu φ>0, phù hợp Ω=2πf(0)=σ²/(1−φ)².`),
    failureCase: B(String.raw`A periodogram ordinate is a noisy estimate of spectral power and does not by itself prove periodic structure. If the covariance sequence is not summable or the process has a unit root, the ordinary stationary spectral-density formula may not define an integrable density; spectral mass can be singular or the process nonstationary.`, String.raw`Giá trị periodogram là ước lượng phổ nhiễu, tự nó không chứng minh chu kỳ. Nếu covariance không khả tổng hoặc chuỗi có nghiệm đơn vị, công thức mật độ phổ dừng thông thường có thể không tạo mật độ khả tích; phổ có thể suy biến hoặc quá trình không dừng.`),
    topic: 'spectral density; linear filters; transfer functions; zero-frequency/LRV', readingSection: 'Lecture Notes 4–5',
    exercises: [
      E(B('Spectrum of a two-tap filter', 'Phổ của bộ lọc hai nhánh'), ['derivation','computation'], B(String.raw`For X_t=ε_t+0.5ε_{t−1}, ε white noise variance 4, derive f_X(ω) and evaluate it at 0 and π.`, String.raw`Với X_t=ε_t+0.5ε_{t−1}, ε nhiễu trắng phương sai 4, suy ra f_X(ω) và tính tại 0, π.`), [B('Compute |1+0.5e^(−iω)|².', 'Tính |1+0.5e^(−iω)|².')], [B(String.raw`Ψ=1+.5e^(−iω), so |Ψ|²=1.25+cosω. f=4(1.25+cosω)/(2π). Thus f(0)=4(2.25)/(2π)=4.5/π and f(π)=4(.25)/(2π)=.5/π.`, String.raw`Ψ=1+.5e^(−iω), nên |Ψ|²=1.25+cosω. f=4(1.25+cosω)/(2π). Do đó f(0)=4(2.25)/(2π)=4.5/π và f(π)=4(.25)/(2π)=.5/π.`)], [R(1,'Finds transfer function.','Tìm hàm truyền.'),R(2,'Expands squared modulus.','Khai triển bình phương môđun.'),R(1,'Evaluates both frequencies.','Tính cả hai tần số.')], [B('Drops the factor 1/(2π).', 'Bỏ hệ số 1/(2π).')]),
      E(B('Derive filter covariance and spectrum', 'Suy ra covariance và phổ bộ lọc'), ['proof'], B(String.raw`Starting from X_t=Σψ_jε_{t−j}, derive γ_X(h) and factor its Fourier series into |Ψ|²; state why rearranging sums is valid.`, String.raw`Từ X_t=Σψ_jε_{t−j}, suy ra γ_X(h) và phân tích chuỗi Fourier thành |Ψ|²; nêu vì sao được đổi thứ tự tổng.`), [B('Only equal innovation time indices survive expectation.', 'Chỉ các chỉ số thời gian innovation trùng nhau còn lại trong kỳ vọng.')], [B(String.raw`Expand the product and use E[ε_aε_b]=σ²1_{a=b}; this gives γ_X(h)=σ²Σ_jψ_jψ_{j−h}. Absolute summability of ψ makes the double Fourier product absolutely convergent, so Fubini/reindexing is justified. Multiplying Ψ by its complex conjugate yields the claimed squared gain and nonnegative density.`, String.raw`Khai triển tích và dùng E[ε_aε_b]=σ²1_{a=b}; được γ_X(h)=σ²Σ_jψ_jψ_{j−h}. Khả tổng tuyệt đối của ψ làm tích Fourier kép hội tụ tuyệt đối nên được dùng Fubini/đổi chỉ số. Nhân Ψ với liên hợp phức cho bình phương độ lợi và mật độ không âm.`)], [R(1,'Expands the innovation product.','Khai triển tích innovation.'),R(2,'Derives lag covariance.','Suy ra covariance theo lag.'),R(1,'Justifies interchange.','Biện minh đổi tổng.')], [B('Treats correlated lagged copies of white noise as independent at the same index.', 'Coi các bản trễ cùng chỉ số white noise là độc lập.')]),
      E(B('Recover variance by integrating spectrum', 'Khôi phục phương sai bằng tích phân phổ'), ['proof','derivation'], B(String.raw`Using Fourier orthogonality, show ∫_{−π}^{π}f_X(ω)dω=γ_X(0) for the absolutely summable covariance case.`, String.raw`Dùng tính trực giao Fourier, chứng minh ∫_{−π}^{π}f_X(ω)dω=γ_X(0) khi covariance khả tổng tuyệt đối.`), [B('Integrate each exponential term; only h=0 survives.', 'Tích phân từng hàm mũ; chỉ h=0 còn lại.')], [B(String.raw`Insert f=(1/(2π))Σ_hγ(h)e^(−ihω). Absolute summability permits termwise integration. ∫e^(−ihω)dω is 2π if h=0 and 0 otherwise. The integral therefore equals γ(0)=Var(X_t).`, String.raw`Thay f=(1/(2π))Σ_hγ(h)e^(−ihω). Khả tổng tuyệt đối cho phép tích phân từng hạng. ∫e^(−ihω)dω bằng 2π khi h=0, bằng 0 nếu khác. Tích phân bằng γ(0)=Var(X_t).`)], [R(1,'Substitutes the definition.','Thay định nghĩa.'),R(2,'Uses justified termwise integration.','Dùng tích phân từng hạng có biện minh.'),R(1,'Identifies variance.','Nhận diện phương sai.')], [B('Integrates over [0,π] without changing normalization.', 'Tích phân trên [0,π] nhưng giữ nguyên chuẩn hóa.')]),
      E(B('Transfer: long-run variance is zero-frequency power', 'Chuyển giao: phương sai dài hạn là phổ tại tần số 0'), ['derivation','transfer'], B(String.raw`For an absolutely summable covariance sequence, prove Ω=2πf(0), then compute Ω for AR(1) and compare with its geometric covariance sum.`, String.raw`Với chuỗi covariance khả tổng tuyệt đối, chứng minh Ω=2πf(0), rồi tính Ω AR(1) và đối chiếu tổng covariance hình học.`), [B('At ω=0 all Fourier phases equal one.', 'Tại ω=0 mọi pha Fourier bằng một.')], [B(String.raw`By definition, 2πf(0)=Σ_hγ(h)=Ω. For AR(1), f(0)=σ²/[2π(1−φ)²], so Ω=σ²/(1−φ)². Also γ(0)[1+2Σ_{h≥1}φ^h]=σ²/(1−φ²)·(1+φ)/(1−φ)=σ²/(1−φ)², matching.`, String.raw`Theo định nghĩa, 2πf(0)=Σ_hγ(h)=Ω. Với AR(1), f(0)=σ²/[2π(1−φ)²], nên Ω=σ²/(1−φ)². Mặt khác γ(0)[1+2Σ_{h≥1}φ^h]=σ²/(1−φ²)·(1+φ)/(1−φ)=σ²/(1−φ)², khớp.`)], [R(1,'Evaluates Fourier series at zero.','Tính chuỗi Fourier tại 0.'),R(2,'Derives AR(1) frequency-zero value.','Suy ra phổ AR(1) tại 0.'),R(1,'Verifies against covariance sum.','Kiểm tra với tổng covariance.')], [B('Uses f(0)=Ω instead of Ω/(2π).', 'Dùng f(0)=Ω thay vì Ω/(2π).')]),
      E(B('Counterexample: a unit root has no ordinary stationary density', 'Phản ví dụ: nghiệm đơn vị không có mật độ dừng thông thường'), ['counterexample','transfer'], B(String.raw`For a random walk with nonzero innovation variance, explain why the stationary covariance Fourier series cannot be applied to levels; contrast with the differenced innovations.`, String.raw`Với random walk có phương sai innovation khác 0, giải thích vì sao không áp dụng chuỗi Fourier covariance dừng cho mức; đối chiếu sai phân.`), [B('The level variance grows and covariance depends on calendar time.', 'Phương sai mức tăng và covariance phụ thuộc thời gian lịch.')], [B(String.raw`For X_t=X_{t−1}+ε_t, Var(X_t)=Var(X₀)+tσ² and Cov(X_t,X_s) depends on min(t,s), not only lag. The weak-stationary covariance sequence γ(h) is therefore undefined for levels. ΔX_t=ε_t is white noise with f_Δ(ω)=σ²/(2π), but that spectrum describes increments, not the random-walk level.`, String.raw`Với X_t=X_{t−1}+ε_t, Var(X_t)=Var(X₀)+tσ² và Cov(X_t,X_s) phụ thuộc min(t,s), không chỉ lag. Vì vậy mức không có chuỗi γ(h) dừng yếu. ΔX_t=ε_t là nhiễu trắng có f_Δ(ω)=σ²/(2π), nhưng phổ này mô tả sai phân chứ không phải mức random walk.`)], [R(1,'Shows time-varying variance.','Chỉ ra phương sai thay đổi theo thời gian.'),R(2,'Identifies covariance dependence on calendar time.','Nhận diện covariance phụ thuộc thời gian lịch.'),R(1,'Distinguishes level and increments.','Phân biệt mức và sai phân.')], [B('Assigns white-noise spectrum to the random-walk level.', 'Gán phổ nhiễu trắng cho mức random walk.')]),
    ],
  },
  {
    week: 76, title: B('Mixing, ergodic averages, and dependent CLT', 'Tính trộn, trung bình ergodic và CLT phụ thuộc'), level: 'graduate core', prerequisites: [73, 74, 75],
    outcomes: [B('State an α-mixing CLT with moment and summability conditions.', 'Phát biểu CLT α-mixing cùng điều kiện moment và khả tổng.'), B('Derive a law of large numbers from variance decay and distinguish it from a CLT.', 'Suy ra luật số lớn từ phương sai suy giảm và phân biệt với CLT.')],
    definitions: B(String.raw`For a strictly stationary sequence, α(k)=sup{|P(A∩B)−P(A)P(B)|:A∈σ(X_s:s≤0),B∈σ(X_s:s≥k)}. α(k)→0 means remote past and future events become asymptotically independent. Ergodicity concerns time averages of integrable functions; mixing is a quantitative sufficient route to ergodicity under usual conditions, not its definition.`, String.raw`Với chuỗi dừng nghiêm ngặt, α(k)=sup{|P(A∩B)−P(A)P(B)|:A∈σ(X_s:s≤0),B∈σ(X_s:s≥k)}. α(k)→0 nghĩa là biến cố quá khứ/tương lai xa dần độc lập tiệm cận. Ergodicity nói về trung bình thời gian của hàm khả tích; mixing là con đường đủ định lượng để có ergodicity trong điều kiện thường dùng, không phải định nghĩa.`),
    theoremTitle: B('Selected α-mixing CLT', 'CLT α-mixing được chọn'),
    statement: B(String.raw`Let (X_t) be strictly stationary, centered, α-mixing, E|X_0|^{2+δ}<∞ for some δ>0, and Σ_{k≥1}α(k)^{δ/(2+δ)}<∞. Then Ω=γ(0)+2Σ_{k≥1}γ(k) exists and n^{-1/2}Σ_{t=1}^nX_t⇒N(0,Ω); if Ω>0 the limit is nondegenerate. This theorem is assumed; its blocking/martingale proof is beyond the week.`, String.raw`Cho (X_t) dừng nghiêm ngặt, trung tâm, α-mixing, E|X_0|^{2+δ}<∞ với δ>0 và Σ_{k≥1}α(k)^{δ/(2+δ)}<∞. Khi đó Ω=γ(0)+2Σ_{k≥1}γ(k) tồn tại và n^{-1/2}Σ_{t=1}^nX_t⇒N(0,Ω); nếu Ω>0 thì giới hạn không suy biến. Định lý được giả thiết; chứng minh chia khối/đổi martingale vượt thời lượng tuần.`),
    proofStatus: 'assumed', proof: B(String.raw`The exact cited theorem is CMU 36-754, Chapter 27, Theorem 396. It explicitly identifies the limiting variance as the long-run covariance and marks the proof as technical, referring readers to Doukhan or Durrett. We do not claim to prove the dependent CLT here. We do prove the finite-variance LLN implication used below: if n Var(X̄_n)→0, Chebyshev gives X̄_n→μ in probability; the CLT's summability conditions instead produce a nonzero √n-scale limit and are stronger.` , String.raw`Định lý được dẫn chính xác ở CMU 36-754, Chương 27, Định lý 396. Nguồn nêu phương sai giới hạn là covariance dài hạn và ghi chứng minh phức tạp, dẫn tới Doukhan hoặc Durrett. Tuần này không tuyên bố chứng minh CLT phụ thuộc. Ta chứng minh hệ quả LLN dùng ở dưới: nếu n Var(X̄_n)→0 thì Chebyshev cho X̄_n→μ theo xác suất; điều kiện tổng của CLT tạo giới hạn √n không triệt tiêu và mạnh hơn.`), sourceId: 'o-cmu-mixing', section: 'Chapter 27, Theorem 396; proof is explicitly omitted in source.',
    workedExample: B(String.raw`Take the stationary Gaussian MA(1) X_t=ε_t+θ ε_{t−1}, with IID ε_t~N(0,σ²), θ≠−1. X_t uses only innovations at t and t−1, so σ(X_s:s≤0) and σ(X_s:s≥2) are generated by disjoint independent innovations; hence α(k)=0 for every k≥2. All moments are finite, and Ω=γ(0)+2γ(1)=σ²(1+θ²)+2θσ²=σ²(1+θ)²>0. The selected CLT applies without inferring mixing from covariance decay alone.`, String.raw`Xét MA(1) Gaussian dừng X_t=ε_t+θ ε_{t−1}, với ε_t~N(0,σ²) IID, θ≠−1. X_t chỉ dùng innovation thời điểm t và t−1, nên σ(X_s:s≤0) và σ(X_s:s≥2) sinh bởi các innovation độc lập rời nhau; do đó α(k)=0 với mọi k≥2. Mọi moment hữu hạn và Ω=γ(0)+2γ(1)=σ²(1+θ²)+2θσ²=σ²(1+θ)²>0. CLT được chọn áp dụng mà không suy mixing chỉ từ covariance giảm.`),
    failureCase: B(String.raw`Pairwise uncorrelatedness alone does not imply a CLT: variables can have zero pairwise covariance but shared higher-order dependence. Also Ω=0 gives a degenerate limit under the theorem, not a usable nonzero standard error; the sample sum may telescope, as X_t=Y_t−Y_{t−1}.`, String.raw`Không tương quan từng cặp không tự kéo theo CLT: biến có thể covariance bằng 0 từng cặp nhưng phụ thuộc bậc cao chung. Ngoài ra Ω=0 cho giới hạn suy biến theo định lý, không cho sai số chuẩn khác 0; tổng mẫu có thể telescoping, như X_t=Y_t−Y_{t−1}.`),
    topic: 'mixing coefficients; ergodicity; dependent LLN/CLT and long-run variance', readingSection: 'CMU Ch. 27, Theorem 396; MIT Notes 2',
    exercises: [
      E(B('Mixing and moment check', 'Kiểm tra mixing và moment'), ['application'], B(String.raw`A process has α(k)=.2^k and E|X₀|³<∞. For δ=1, evaluate whether Σα(k)^{δ/(2+δ)} converges, and state the CLT conclusion if the process is stationary, centered and Ω>0.`, String.raw`Quá trình có α(k)=.2^k và E|X₀|³<∞. Với δ=1, xét Σα(k)^{δ/(2+δ)} có hội tụ không và nêu kết luận CLT nếu quá trình dừng, trung tâm, Ω>0.`), [B('The exponent is 1/3, leaving a geometric series.', 'Số mũ là 1/3 nên còn chuỗi hình học.')], [B(String.raw`The series is Σ(.2^k)^{1/3}=Σ(.2^{1/3})^k, geometric with ratio below one, hence finite. All selected hypotheses hold, so n^{-1/2}ΣX_t⇒N(0,Ω).`, String.raw`Chuỗi là Σ(.2^k)^{1/3}=Σ(.2^{1/3})^k, cấp số nhân công bội nhỏ hơn 1 nên hội tụ. Các giả thiết được chọn đều đúng, suy ra n^{-1/2}ΣX_t⇒N(0,Ω).`)], [R(1,'Computes δ/(2+δ).','Tính δ/(2+δ).'),R(2,'Recognizes geometric convergence.','Nhận ra hội tụ hình học.'),R(1,'States normalized limit.','Nêu giới hạn chuẩn hóa.')], [B('Uses exponent δ rather than δ/(2+δ).', 'Dùng số mũ δ thay vì δ/(2+δ).')]),
      E(B('Prove LLN from a variance rate', 'Chứng minh LLN từ tốc độ phương sai'), ['proof'], B(String.raw`If n Var(X̄_n)→0 and E[X̄_n]=μ, prove X̄_n→μ in probability; explain why a variance limit Ω>0 instead suggests a √n CLT scale.`, String.raw`Nếu n Var(X̄_n)→0 và E[X̄_n]=μ, chứng minh X̄_n→μ theo xác suất; giải thích vì sao giới hạn phương sai Ω>0 gợi ý thang CLT √n.`), [B('Apply Chebyshev to nε² in the denominator.', 'Áp dụng Chebyshev với mẫu nε².')], [B(String.raw`For ε>0, P(|X̄_n−μ|>ε)≤Var(X̄_n)/ε²=[nVar(X̄_n)]/(nε²)→0. Hence convergence in probability. If nVar(X̄_n)→Ω>0, the mean fluctuates at order n^{-1/2}; this variance scale is compatible with, but does not itself prove, a √n CLT.`, String.raw`Với ε>0, P(|X̄_n−μ|>ε)≤Var(X̄_n)/ε²=[nVar(X̄_n)]/(nε²)→0. Suy ra hội tụ theo xác suất. Nếu nVar(X̄_n)→Ω>0 thì trung bình dao động cỡ n^{-1/2}; thang phương sai này phù hợp với CLT √n nhưng tự nó chưa chứng minh CLT.`)], [R(1,'Applies Chebyshev.','Áp dụng Chebyshev.'),R(2,'Uses the assumed rate to obtain zero.','Dùng tốc độ giả thiết để về 0.'),R(1,'Separates variance scale from distributional limit.','Tách thang phương sai khỏi giới hạn phân phối.')], [B('Confuses n Var with Var directly.', 'Nhầm n Var với Var trực tiếp.')]),
      E(B('Zero long-run variance through telescoping', 'Phương sai dài hạn bằng không do telescoping'), ['derivation'], B(String.raw`Let Y_t be iid variance τ² and X_t=Y_t−Y_{t−1}. Compute γ(0), γ(1), Ω and explain the degenerate normalized sum.`, String.raw`Cho Y_t iid phương sai τ², X_t=Y_t−Y_{t−1}. Tính γ(0), γ(1), Ω và giải thích tổng chuẩn hóa suy biến.`), [B('Adjacent differences share one innovation with opposite signs.', 'Hai sai phân kề dùng chung một innovation với dấu ngược.')], [B(String.raw`γ(0)=2τ². γ(1)=Cov(Y_t−Y_{t−1},Y_{t+1}−Y_t)=−τ²; other nonzero lags vanish. Thus Ω=2τ²+2(−τ²)=0. The sum telescopes: Σ_{t=1}^nX_t=Y_n−Y_0, whose variance is 2τ², so dividing by √n tends to zero in L², a degenerate limit.`, String.raw`γ(0)=2τ². γ(1)=Cov(Y_t−Y_{t−1},Y_{t+1}−Y_t)=−τ²; các lag xa hơn bằng 0. Vậy Ω=2τ²+2(−τ²)=0. Tổng telescoping: Σ_{t=1}^nX_t=Y_n−Y_0, phương sai 2τ²; chia √n thì về 0 trong L², giới hạn suy biến.`)], [R(1,'Computes lag-zero variance.','Tính phương sai lag 0.'),R(2,'Finds adjacent covariance and Ω.','Tìm covariance kề và Ω.'),R(1,'Uses telescoping for sum scale.','Dùng telescoping cho thang tổng.')], [B('Treats adjacent differences as independent.', 'Coi các sai phân kề độc lập.')]),
      E(B('Transfer: verify hypotheses on a finite-dependent Gaussian model', 'Chuyển giao: kiểm tra giả thiết trên mô hình Gaussian phụ thuộc hữu hạn'), ['proof','transfer'], B(String.raw`For X_t=ε_t+θ ε_{t−1}, ε IID N(0,σ²), θ≠−1, prove α(k)=0 for k≥2, verify all moment/summability conditions and compute Ω>0 before invoking the selected CLT.`, String.raw`Với X_t=ε_t+θ ε_{t−1}, ε IID N(0,σ²), θ≠−1, chứng minh α(k)=0 khi k≥2, kiểm tra moment/khả tổng và tính Ω>0 trước khi dùng CLT được chọn.`), [B('Compare the innovation index sets for the remote past and future.', 'So sánh tập chỉ số innovation của quá khứ và tương lai xa.')], [B(String.raw`The past through time 0 depends only on ε_s with s≤0; the future from time k≥2 depends only on ε_s with s≥k−1≥1. These sigma-fields are independent, so α(k)=0. Gaussianity gives finite E|X_0|^{2+δ} for every δ>0, and the mixing sum has only finitely many nonzero terms. γ(0)=σ²(1+θ²), γ(1)=θσ², higher lags vanish; Ω=σ²(1+θ)²>0 since θ≠−1. Thus every theorem hypothesis is checked.`, String.raw`Quá khứ tới thời điểm 0 chỉ phụ thuộc ε_s với s≤0; tương lai từ k≥2 chỉ phụ thuộc ε_s với s≥k−1≥1. Hai sigma-field độc lập nên α(k)=0. Tính Gaussian cho E|X_0|^{2+δ} hữu hạn với mọi δ>0 và tổng mixing chỉ có hữu hạn hạng khác 0. γ(0)=σ²(1+θ²), γ(1)=θσ², lag cao hơn triệt tiêu; Ω=σ²(1+θ)²>0 vì θ≠−1. Vậy mọi giả thiết định lý đều được kiểm tra.`)], [R(1,'Identifies the disjoint innovation sigma-fields.','Nhận diện hai sigma-field innovation rời nhau.'),R(1,'Derives exact finite-dependence cutoff.','Suy ra chính xác ngưỡng phụ thuộc hữu hạn.'),R(2,'Checks moments, summability and long-run variance.','Kiểm tra moment, khả tổng và phương sai dài hạn.')], [B('Infers mixing solely from geometric covariance decay.', 'Suy mixing chỉ từ covariance giảm hình học.')]),
      E(B('Counterexample: pairwise zero covariance is not independence', 'Phản ví dụ: covariance từng cặp bằng không chưa là độc lập'), ['counterexample','transfer'], B(String.raw`Let U,V be independent Rademacher variables and W=UV. Show all three pairs are uncorrelated but U,V,W are dependent; explain why covariance decay alone may miss higher-order dependence.`, String.raw`Cho U,V độc lập Rademacher, W=UV. Chứng minh cả ba cặp không tương quan nhưng U,V,W phụ thuộc; giải thích vì sao covariance giảm có thể bỏ sót phụ thuộc bậc cao.`), [B('Use symmetry to compute each pair product expectation and the triple product.', 'Dùng đối xứng tính kỳ vọng tích từng cặp và tích ba biến.')], [B(String.raw`E[UV]=E[U]E[V]=0; E[UW]=E[U²V]=E[V]=0; likewise E[VW]=0. But W is determined by U,V and UVW=1 surely, so the triple is dependent. Thus second-order decorrelation need not imply the event mixing assumptions behind a CLT.`, String.raw`E[UV]=E[U]E[V]=0; E[UW]=E[U²V]=E[V]=0; tương tự E[VW]=0. Nhưng W được xác định bởi U,V và UVW=1 chắc chắn nên bộ ba phụ thuộc. Vì vậy mất tương quan bậc hai không kéo theo giả thiết trộn sự kiện cần cho CLT.`)], [R(1,'Computes pair covariances.','Tính covariance từng cặp.'),R(2,'Shows deterministic triple relation.','Chỉ ra quan hệ xác định của bộ ba.'),R(1,'Connects limitation to CLT hypotheses.','Liên hệ hạn chế với giả thiết CLT.')], [B('Treats pairwise independence and mutual independence as equivalent.', 'Coi độc lập từng cặp tương đương độc lập đồng thời.')]),
    ],
  },
  {
    week: 77, title: B('HAC sandwich covariance and Newey–West weights', 'Covariance sandwich HAC và trọng số Newey–West'), level: 'graduate core', prerequisites: [60, 73, 76],
    outcomes: [B('Derive the long-run sandwich covariance from an asymptotic linear representation.', 'Suy ra covariance sandwich dài hạn từ biểu diễn tuyến tính tiệm cận.'), B('Prove positive semidefiniteness of the Bartlett-kernel long-run covariance estimate.', 'Chứng minh nửa xác định dương của ước lượng covariance dài hạn kernel Bartlett.')],
    definitions: B(String.raw`For a stationary score z_t∈R^p with E z_t=0, Ω=Σ_{h∈Z}E[z_tz_{t−h}ᵀ]. If √n(θ̂−θ₀)=A^{-1}n^{-1/2}Σz_t+o_p(1), then asymptotic covariance is A^{-1}ΩA^{-T}. HAC estimates Ω by weighting sample lag covariances with a kernel; Bartlett weights w_h=1−|h|/(b+1) for |h|≤b, zero otherwise.`, String.raw`Với score dừng z_t∈R^p, E z_t=0, Ω=Σ_{h∈Z}E[z_tz_{t−h}ᵀ]. Nếu √n(θ̂−θ₀)=A^{-1}n^{-1/2}Σz_t+o_p(1), covariance tiệm cận là A^{-1}ΩA^{-T}. HAC ước lượng Ω bằng trọng số kernel cho covariance trễ; Bartlett w_h=1−|h|/(b+1) khi |h|≤b, còn lại 0.`),
    theoremTitle: B('Bartlett HAC is positive semidefinite; sandwich limit', 'HAC Bartlett PSD; giới hạn sandwich'),
    statement: B(String.raw`For zero-padded finite data z_1,…,z_n, the scalar Bartlett estimator Ω̂_b=Σ_{|h|≤b}w_h γ̂_h is nonnegative. For a vector score, the same quadratic-form argument makes Ω̂_b⪰0. Under a stationary mixing CLT, nonsingular A, consistent score estimates, b_n→∞ and b_n/n→0 plus moment/mixing conditions controlling truncation, Â^{-1}Ω̂_bÂ^{-T} consistently estimates the sandwich covariance. The consistency assertion is sourced/assumed; positivity is proved.`, String.raw`Với dữ liệu hữu hạn z_1,…,z_n thêm số 0 ngoài mẫu, ước lượng Bartlett vô hướng Ω̂_b=Σ_{|h|≤b}w_hγ̂_h không âm. Với score vector, lập luận dạng quadratic cho Ω̂_b⪰0. Dưới CLT mixing dừng, A khả nghịch, score ước lượng nhất quán, b_n→∞, b_n/n→0 và điều kiện moment/mixing kiểm soát cắt cụt, Â^{-1}Ω̂_bÂ^{-T} ước lượng nhất quán covariance sandwich. Mệnh đề nhất quán được dẫn/giả thiết; tính dương được chứng minh.`),
    proofStatus: 'proof sketch', proof: B(String.raw`For scalar centered u_t with zero padding, expand (1/[n(b+1)])Σ_{s∈Z}(Σ_{j=0}^b u_{s−j})². Each lag h appears exactly b+1−|h| times, so this equals Σ_{|h|≤b}(1−|h|/(b+1))γ̂_h≥0. For vectors, replace squares with outer products and test any vector a: aᵀΩ̂_ba is the same nonnegative scalar expression for u_t=aᵀz_t. The consistency claim requires controlling bias from omitted lags and variance from estimated lags as b grows; see Newey–West Theorem 2 and MIT Notes 2–3.`, String.raw`Với u_t tâm hóa, thêm số 0 ngoài mẫu, khai triển (1/[n(b+1)])Σ_{s∈Z}(Σ_{j=0}^b u_{s−j})². Mỗi lag h xuất hiện đúng b+1−|h| lần nên biểu thức bằng Σ_{|h|≤b}(1−|h|/(b+1))γ̂_h≥0. Với vector, thay bình phương bằng tích ngoài rồi thử vector a: aᵀΩ̂_ba là cùng biểu thức không âm cho u_t=aᵀz_t. Tính nhất quán cần kiểm soát bias do bỏ lag và phương sai do ước lượng lag khi b tăng; xem Newey–West Định lý 2 và MIT Notes 2–3.`), sourceId: 'o-neweywest', section: 'Theorem 1 (positive semidefiniteness) and consistency result; MIT 14.384 Lecture Notes 2–3.',
    workedExample: B(String.raw`For γ̂₀=4, γ̂₁=1, γ̂₂=−.5 and b=2, Ω̂=4+2[(2/3)·1+(1/3)(−.5)]=4+1=5. Bartlett weighting keeps the lag-2 contribution but tapers it; the resulting estimate is nonnegative by the quadratic-form identity.`, String.raw`Với γ̂₀=4, γ̂₁=1, γ̂₂=−.5 và b=2, Ω̂=4+2[(2/3)·1+(1/3)(−.5)]=4+1=5. Trọng số Bartlett giữ lag 2 nhưng giảm trọng số; tính không âm theo đồng nhất thức quadratic.`),
    failureCase: B(String.raw`HAC does not repair a nonstationary score, bad identification, or look-ahead bias. A bandwidth that is fixed as n→∞ generally leaves truncation bias; one that approaches n leaves too few effective lag estimates. Overlapping h-step forecast losses share observations through lag h−1, so an IID standard error is not justified.`, String.raw`HAC không sửa score không dừng, nhận dạng sai hay look-ahead bias. Bandwidth cố định khi n→∞ thường giữ bias cắt cụt; bandwidth gần n để lại quá ít lag hữu hiệu. Loss dự báo h bước chồng lấn chia sẻ quan sát tới lag h−1 nên không được dùng sai số chuẩn IID.`),
    topic: 'HAC/Newey–West; sandwich asymptotics; bandwidth; overlap dependence', readingSection: 'MIT Lecture Notes 2–3; Newey & West Theorems 1–2',
    exercises: [
      E(B('Bartlett HAC arithmetic', 'Tính HAC Bartlett'), ['computation'], B(String.raw`Given γ̂₀=2, γ̂₁=.5, γ̂₂=.25 and b=2, compute Ω̂_b.`, String.raw`Cho γ̂₀=2, γ̂₁=.5, γ̂₂=.25, b=2, tính Ω̂_b.`), [B('Weights are 1, 2/3 and 1/3 for lags 0,1,2.', 'Trọng số là 1, 2/3, 1/3 ở lag 0,1,2.')], [B(String.raw`Ω̂=2+2[(2/3)(.5)+(1/3)(.25)]=2+2(.4167)=2.8333.`, String.raw`Ω̂=2+2[(2/3)(.5)+(1/3)(.25)]=2+2(.4167)=2.8333.`)], [R(1,'Uses correct weights.','Dùng trọng số đúng.'),R(2,'Counts positive and negative lags.','Tính cả lag âm và dương.'),R(1,'Computes total.','Tính tổng.')], [B('Forgets the negative-lag symmetric contribution.', 'Quên phần lag âm đối xứng.')]),
      E(B('Prove Bartlett positive semidefiniteness', 'Chứng minh Bartlett nửa xác định dương'), ['proof'], B(String.raw`For zero-padded u_t, expand the sum of squared moving windows and count the number of times each lag h occurs to recover Bartlett weights.`, String.raw`Với u_t được thêm số 0 ngoài mẫu, khai triển tổng bình phương cửa sổ trượt và đếm số lần mỗi lag h xuất hiện để thu trọng số Bartlett.`), [B('A lag h appears in (b+1−|h|) ordered pairs of window indices.', 'Lag h xuất hiện trong (b+1−|h|) cặp có thứ tự của chỉ số cửa sổ.')], [B(String.raw`In (b+1)^{-1}Σ_s(Σ_{j=0}^b u_{s−j})², the product u_{s−j}u_{s−k} has lag h=j−k. There are b+1−|h| pairs with this lag. Summing over s gives the zero-padded empirical covariance γ̂_h, so the expression equals Σ_h(1−|h|/(b+1))γ̂_h. It is a sum of squares divided by n(b+1), hence nonnegative.`, String.raw`Trong (b+1)^{-1}Σ_s(Σ_{j=0}^b u_{s−j})², tích u_{s−j}u_{s−k} có lag h=j−k. Có b+1−|h| cặp như vậy. Cộng theo s cho covariance mẫu thêm số 0 γ̂_h nên biểu thức bằng Σ_h(1−|h|/(b+1))γ̂_h. Đây là tổng bình phương chia n(b+1), nên không âm.`)], [R(1,'Expands the square.','Khai triển bình phương.'),R(2,'Counts pairs for each lag.','Đếm cặp cho từng lag.'),R(1,'Recognizes a sum of squares.','Nhận ra tổng bình phương.')], [B('Counts unordered pairs and loses a factor of two.', 'Đếm cặp không thứ tự rồi mất hệ số hai.')]),
      E(B('Derive the sandwich from an asymptotic linearization', 'Suy ra sandwich từ tuyến tính hóa tiệm cận'), ['derivation','proof'], B(String.raw`If √n(θ̂−θ₀)=A^{-1}n^{-1/2}Σz_t+o_p(1) and the score sum converges to N(0,Ω), derive the asymptotic covariance of θ̂.`, String.raw`Nếu √n(θ̂−θ₀)=A^{-1}n^{-1/2}Σz_t+o_p(1) và tổng score hội tụ N(0,Ω), suy ra covariance tiệm cận của θ̂.`), [B('Apply the covariance transformation rule.', 'Áp dụng quy tắc biến đổi covariance.')], [B(String.raw`The limiting vector is A^{-1}Z with Cov(Z)=Ω. Therefore Cov(A^{-1}Z)=A^{-1}Ω(A^{-1})ᵀ=A^{-1}ΩA^{-T}. The approximation is justified by Slutsky when Â→A and the remainder is o_p(1); IID information replaces Ω only when cross-time covariances vanish.`, String.raw`Vector giới hạn là A^{-1}Z với Cov(Z)=Ω. Vậy Cov(A^{-1}Z)=A^{-1}Ω(A^{-1})ᵀ=A^{-1}ΩA^{-T}. Slutsky biện minh thay A bằng Â→A khi phần dư o_p(1); information IID chỉ thay được Ω khi covariance giữa thời điểm khác bằng 0.`)], [R(1,'Identifies linear transform.','Nhận diện biến đổi tuyến tính.'),R(2,'Applies sandwich covariance.','Áp dụng covariance sandwich.'),R(1,'States Slutsky/serial-covariance condition.','Nêu điều kiện Slutsky/covariance chuỗi.')], [B('Uses AΩAᵀ although the expansion contains A inverse.', 'Dùng AΩAᵀ dù biểu diễn có A nghịch đảo.')]),
      E(B('Transfer: overlapping forecast losses', 'Chuyển giao: loss dự báo chồng lấn'), ['application','transfer'], B(String.raw`Two methods produce h-step forecasts each date and losses d_t=ℓ_A,t−ℓ_B,t share target returns over h days. Explain why d_t can be serially dependent through at least h−1 lags and outline a valid uncertainty estimator.`, String.raw`Hai phương pháp dự báo h bước mỗi ngày, loss d_t=ℓ_A,t−ℓ_B,t dùng chung return mục tiêu trong h ngày. Giải thích vì sao d_t phụ thuộc chuỗi ít nhất h−1 lag và phác thảo ước lượng bất định hợp lệ.`), [B('Adjacent forecast windows overlap in h−1 outcomes.', 'Cửa sổ mục tiêu kề nhau chồng lấn h−1 outcome.')], [B(String.raw`For t and t+k with 0≤k<h, the target windows share h−k returns, so their losses need not be independent; overlap alone can induce dependence through lag h−1. Compare losses by paired origin, estimate their long-run variance using a HAC estimator with bandwidth at least covering the overlap and a justified increasing-b bandwidth, or use a block method under stationarity. State sampling/weak-dependence assumptions; paired means do not erase temporal dependence.`, String.raw`Với t và t+k, 0≤k<h, cửa sổ mục tiêu chia sẻ h−k return nên loss không nhất thiết độc lập; chỉ riêng chồng lấn đã gây phụ thuộc đến lag h−1. So sánh loss theo cùng origin, ước lượng phương sai dài hạn bằng HAC với bandwidth bao phủ overlap và tăng theo n có biện minh, hoặc dùng block dưới tính dừng. Nêu giả thiết lấy mẫu/phụ thuộc yếu; trung bình paired không xóa phụ thuộc thời gian.`)], [R(1,'Counts overlap horizon.','Đếm chân trời chồng lấn.'),R(2,'Chooses dependence-aware uncertainty.','Chọn bất định có xét phụ thuộc.'),R(1,'States required assumptions.','Nêu giả thiết cần.')], [B('Treats matching forecast origins as independence.', 'Coi ghép cùng origin là độc lập.')]),
      E(B('Counterexample: truncated covariance can be negative', 'Phản ví dụ: cắt covariance có thể âm'), ['counterexample','derivation'], B(String.raw`Let γ̂₀=1, γ̂₁=−.8 and truncate at lag one with unit weights. Compute the raw estimate and Bartlett-b=1 estimate; explain the PSD difference.`, String.raw`Cho γ̂₀=1, γ̂₁=−.8, cắt tại lag một với trọng số đơn vị. Tính ước lượng thô và Bartlett b=1; giải thích khác biệt PSD.`), [B('Raw sum includes both signed lags; Bartlett lag-one weight is 1/2.', 'Tổng thô gồm hai lag có dấu; Bartlett cho trọng số lag 1 là 1/2.')], [B(String.raw`The raw truncation is 1+2(−.8)=−.6, impossible as a variance estimate. Bartlett gives 1+2(.5)(−.8)=.2≥0. The PSD guarantee comes from positive-definite Bartlett weights, not from every arbitrary lag window.`, String.raw`Cắt thô cho 1+2(−.8)=−.6, không thể là ước lượng phương sai. Bartlett cho 1+2(.5)(−.8)=.2≥0. Bảo đảm PSD đến từ trọng số Bartlett xác định dương, không phải mọi cửa sổ lag tùy ý.`)], [R(1,'Computes raw truncation.','Tính cắt thô.'),R(2,'Computes Bartlett estimate.','Tính Bartlett.'),R(1,'Explains positive-definite kernel role.','Giải thích vai trò kernel xác định dương.')], [B('Uses the full weight one at lag one for Bartlett b=1.', 'Dùng trọng số một ở lag một thay vì Bartlett b=1.')]),
    ],
  },
  {
    week: 78, title: B('Block bootstrap, paired prediction tests, and resampling limits', 'Block bootstrap, kiểm định dự báo paired và giới hạn tái lấy mẫu'), level: 'graduate core', prerequisites: [73, 76, 77],
    outcomes: [B('Construct a moving-block bootstrap and derive the conditions b→∞, b/n→0.', 'Lập moving-block bootstrap và suy ra điều kiện b→∞, b/n→0.'), B('Use paired loss differences and explain exchangeability and dependence boundaries.', 'Dùng chênh loss paired và giải thích ranh giới trao đổi được/phụ thuộc.')],
    definitions: B(String.raw`For data X₁,…,X_n, moving-block bootstrap forms overlapping blocks B_i=(X_i,…,X_{i+b−1}) and samples blocks with replacement until n observations are assembled. Resampling preserves within-block order, breaks dependence at joins. For paired forecast comparison, d_t=ℓ_A,t−ℓ_B,t is the target series; negative mean favors A. Permutation/sign-flip tests require exchangeability or symmetry under the null, not merely pairing.`, String.raw`Với dữ liệu X₁,…,X_n, moving-block bootstrap tạo block chồng lấn B_i=(X_i,…,X_{i+b−1}) rồi lấy mẫu block có hoàn lại đến đủ n quan sát. Tái lấy mẫu giữ thứ tự trong block nhưng cắt phụ thuộc tại mối nối. So sánh dự báo paired dùng d_t=ℓ_A,t−ℓ_B,t; trung bình âm ủng hộ A. Kiểm định hoán vị/đổi dấu cần trao đổi được hoặc đối xứng dưới H₀, không chỉ cần ghép cặp.`),
    theoremTitle: B('Moving-block bootstrap consistency for a stationary mean', 'Tính nhất quán block bootstrap cho trung bình dừng'),
    statement: B(String.raw`For a short-memory strictly stationary sequence satisfying Künsch's moment and weak-dependence conditions for the sample-mean bootstrap, if b_n→∞ and b_n/n→0, the centered moving-block-bootstrap distribution of √n(X̄_n*−X̄_n) consistently estimates the sampling limit of √n(X̄_n−μ). This selected theorem is assumed from Künsch (1989); exact conditions are stronger than stationarity alone.`, String.raw`Với chuỗi dừng nghiêm ngặt phụ thuộc ngắn thỏa điều kiện moment và phụ thuộc yếu của Künsch cho bootstrap trung bình mẫu, nếu b_n→∞ và b_n/n→0 thì phân phối moving-block-bootstrap đã tâm hóa của √n(X̄_n*−X̄_n) ước lượng nhất quán giới hạn lấy mẫu của √n(X̄_n−μ). Định lý chọn này được giả thiết theo Künsch (1989); chỉ dừng thôi chưa đủ.`),
    proofStatus: 'assumed', proof: B(String.raw`Künsch (1989), Annals of Statistics 17(3), establishes block-based consistency for general stationary observations under appropriate dependence/moment conditions and growing block length with block/n→0. The mechanism is: b→∞ retains increasingly long local dependence; b/n→0 leaves an increasing number of blocks for empirical resampling. This intuition is not the proof: approximation of the process law and control of block-boundary error require the paper's assumptions. The bootstrap does not restore stationarity after a structural break or unit root.`, String.raw`Künsch (1989), Annals of Statistics 17(3), chứng minh tính nhất quán block dưới điều kiện moment/phụ thuộc thích hợp, block tăng và block/n→0. Cơ chế là: b→∞ giữ phần phụ thuộc cục bộ ngày càng dài; b/n→0 giữ số block tăng để tái lấy mẫu thực nghiệm. Trực giác này không thay chứng minh: xấp xỉ luật quá trình và kiểm soát lỗi biên cần giả thiết bài báo. Bootstrap không khôi phục tính dừng sau gãy cấu trúc hoặc nghiệm đơn vị.`), sourceId: 'o-kunsch', section: 'Main consistency results for stationary block resampling; assumptions stated in original article.',
    workedExample: B(String.raw`Given centered residuals [1,1,−1,−1] and blocks [1,1],[1,−1],[−1,−1], one bootstrap sample choosing the first and third blocks is [1,1,−1,−1], whose mean is 0. Each within-block pair remains consecutive; the original boundary pattern is not preserved at every join.`, String.raw`Với residual đã tâm hóa [1,1,−1,−1] và các block [1,1],[1,−1],[−1,−1], một mẫu bootstrap chọn block đầu và cuối là [1,1,−1,−1], trung bình 0. Mỗi cặp trong block vẫn kề nhau; cấu trúc biên ban đầu không được giữ ở mọi mối nối.`),
    failureCase: B(String.raw`An IID row bootstrap destroys serial clusters; a block bootstrap with b fixed does not capture longer dependence asymptotically; b=n yields one block and no meaningful resampling diversity. Standard stationary block validity also fails for untreated unit-root levels, structural breaks, or post-selection intervals whose same holdout chose the method.`, String.raw`Bootstrap IID theo hàng phá cụm chuỗi; block bootstrap b cố định không giữ phụ thuộc dài hơn khi tiệm cận; b=n chỉ còn một block, không đa dạng tái lấy mẫu. Tính hợp lệ dừng chuẩn cũng thất bại với mức nghiệm đơn vị chưa xử lý, gãy cấu trúc hoặc khoảng sau chọn mô hình bằng chính holdout.`),
    topic: 'moving/block bootstrap; paired loss; permutation exchangeability; break/unit-root limits', readingSection: 'Künsch (1989); MIT Lecture Notes 9; CMU 36-705 Lectures 22, 26–27',
    exercises: [
      E(B('Construct one block resample', 'Lập một mẫu block'), ['computation'], B(String.raw`For x=[2,3,8,9,4,5], b=2, use sampled block starts 2 and 5 (1-indexed). Write the resample and its mean.`, String.raw`Với x=[2,3,8,9,4,5], b=2, chọn block bắt đầu 2 và 5 (đánh số từ 1). Viết mẫu bootstrap và trung bình.`), [B('Blocks are [3,8] and [4,5].', 'Các block là [3,8] và [4,5].')], [B(String.raw`Concatenate to get [3,8,4,5]. Its mean is 20/4=5. Within-block adjacency is preserved; the original adjacency 8→9 and 5→end is not necessarily preserved.`, String.raw`Ghép được [3,8,4,5], trung bình 20/4=5. Tính kề trong block được giữ; kề ban đầu 8→9 và 5→cuối không nhất thiết giữ.`)], [R(1,'Extracts correct blocks.','Lấy block đúng.'),R(2,'Concatenates in sampled order.','Ghép theo thứ tự mẫu.'),R(1,'Computes mean and limitation.','Tính trung bình và hạn chế.')], [B('Uses start indices as block values.', 'Dùng chỉ số đầu block làm giá trị.')]),
      E(B('Explain the two block-length limits', 'Giải thích hai giới hạn độ dài block'), ['derivation'], B(String.raw`Explain mathematically why consistency requires b_n→∞ and b_n/n→0: what dependence is lost if b stays bounded, and what sampling capacity is lost if b/n does not vanish?`, String.raw`Giải thích bằng toán vì sao cần b_n→∞ và b_n/n→0: mất phụ thuộc nào nếu b bị chặn, và mất năng lực lấy mẫu nào nếu b/n không về 0?`), [B('Compare retained run length with number of resampled blocks n/b.', 'So sánh độ dài phụ thuộc giữ được với số block n/b.')], [B(String.raw`If b remains bounded, any dependence beyond that finite span is severed inside every replicate, so covariance contributions at larger lags are omitted. If b/n stays bounded away from zero, the number of sampled blocks is O(1); conditional bootstrap variability cannot average over an increasing collection of local blocks. The two limits respectively preserve local dependence and create enough resampling units; Künsch's theorem adds further moment/mixing conditions.`, String.raw`Nếu b bị chặn, mọi phụ thuộc dài hơn span hữu hạn đó đều bị cắt trong từng replicate, nên covariance lag xa bị bỏ. Nếu b/n không về 0, số block lấy mẫu là O(1); biến thiên bootstrap có điều kiện không thể trung bình hóa trên số lượng block cục bộ tăng. Hai giới hạn lần lượt giữ phụ thuộc cục bộ và tạo đủ đơn vị tái lấy mẫu; định lý Künsch còn cần moment/mixing.`)], [R(1,'Explains bounded-block truncation.','Giải thích cắt cụt khi block bị chặn.'),R(2,'Explains too-few-block failure.','Giải thích thất bại do quá ít block.'),R(1,'Names theorem conditions beyond rates.','Nêu giả thiết khác ngoài tốc độ.')], [B('Claims either rate alone proves validity.', 'Cho rằng chỉ một tốc độ đủ chứng minh hợp lệ.')]),
      E(B('Paired forecast loss and uncertainty', 'Loss dự báo paired và bất định'), ['computation','application'], B(String.raw`At four common origins, losses A=[2,1,4,3], B=[3,1,2,5]. Compute d=A−B, mean d, and explain what a block/HAC interval would target.`, String.raw`Ở bốn origin chung, loss A=[2,1,4,3], B=[3,1,2,5]. Tính d=A−B, trung bình d và giải thích khoảng HAC/block nhắm tới điều gì.`), [B('Subtract at matched origins before averaging.', 'Trừ theo origin ghép trước khi lấy trung bình.')], [B(String.raw`d=[−1,0,2,−2], mean d=−1/4=−.25, favoring A on this sample mean. A dependence-aware interval targets uncertainty in E[d_t] or its stationary-process long-run distribution; it does not transform the four-row sample into independent evidence or prove future profitability.`, String.raw`d=[−1,0,2,−2], trung bình −1/4=−.25, nghiêng về A theo trung bình mẫu. Khoảng có xét phụ thuộc nhắm tới bất định của E[d_t] hoặc phân phối dài hạn của chuỗi dừng; nó không biến bốn dòng thành bằng chứng độc lập hay chứng minh lợi nhuận tương lai.`)], [R(1,'Pairs by origin.','Ghép theo origin.'),R(2,'Computes differences and mean.','Tính chênh lệch và trung bình.'),R(1,'States estimand and limit.','Nêu estimand và giới hạn.')], [B('Computes mean(A)−mean(B) without preserving paired rows.', 'Tính mean(A)−mean(B) nhưng làm mất ghép cặp.')]),
      E(B('Transfer: when sign-flip is exact', 'Chuyển giao: khi nào đổi dấu chính xác'), ['proof','transfer'], B(String.raw`A paired permutation test independently flips signs of d_t. State a condition under which this is exact under H₀, and explain why dependence over time invalidates unrestricted independent sign flips absent additional symmetry.`, String.raw`Kiểm định hoán vị paired độc lập đổi dấu d_t. Nêu điều kiện để chính xác dưới H₀ và giải thích vì sao phụ thuộc thời gian làm đổi dấu độc lập tùy ý không hợp lệ nếu thiếu đối xứng bổ sung.`), [B('Exact randomization requires the joint null law to be invariant under every allowed flip.', 'Tính chính xác cần luật kết hợp dưới H₀ bất biến với mọi phép đổi dấu được phép.')], [B(String.raw`Independent sign flips are exact if, conditional on magnitudes (or pair construction), the joint null distribution is invariant under all 2^n coordinate sign changes; IID symmetric paired differences are one sufficient case. Under serial dependence, the joint sign vector need not be invariant under coordinatewise flips even if each marginal is symmetric, so the reference distribution is wrong. Use a dependence-preserving block method or a justified time-series null.`, String.raw`Đổi dấu độc lập chính xác nếu, có điều kiện theo trị tuyệt đối (hoặc thiết kế cặp), luật kết hợp dưới H₀ bất biến với cả 2^n phép đổi dấu tọa độ; hiệu paired iid đối xứng là một trường hợp đủ. Dưới phụ thuộc chuỗi, vector dấu kết hợp không nhất thiết bất biến với đổi dấu từng tọa độ dù mỗi biên đối xứng, nên phân phối tham chiếu sai. Dùng block giữ phụ thuộc hoặc null chuỗi có biện minh.`)], [R(1,'States joint invariance condition.','Nêu điều kiện bất biến kết hợp.'),R(2,'Separates marginal symmetry from joint invariance.','Tách đối xứng biên khỏi bất biến kết hợp.'),R(1,'Proposes dependence-aware alternative.','Đề xuất phương án xét phụ thuộc.')], [B('Assumes pairwise symmetry implies joint sign-flip invariance.', 'Giả sử đối xứng từng cặp kéo theo bất biến đổi dấu kết hợp.')]),
      E(B('Counterexample: block bootstrap after a break', 'Phản ví dụ: block bootstrap sau gãy'), ['counterexample','transfer'], B(String.raw`Let X_t=ε_t for t≤n/2 and X_t=5+ε_t for t>n/2, iid ε_t with mean zero. Explain why resampled stationary blocks do not estimate one common stationary mean's sampling distribution.`, String.raw`Cho X_t=ε_t khi t≤n/2, X_t=5+ε_t khi t>n/2, ε iid kỳ vọng 0. Giải thích vì sao block dừng tái lấy mẫu không ước lượng phân phối lấy mẫu của một trung bình dừng chung.`), [B('The data-generating mean depends on the calendar regime.', 'Kỳ vọng sinh dữ liệu phụ thuộc chế độ thời gian lịch.')], [B(String.raw`The first half has mean 0 and the second half mean 5; the sequence is not stationary and does not have one time-invariant marginal mean. Resampling blocks pooled from both regimes creates random regime mixtures and treats boundary frequencies as exchangeable, so the usual stationary-block theorem does not apply. Model the break, resample within declared regimes, or define a different estimand.`, String.raw`Nửa đầu có kỳ vọng 0, nửa sau 5; chuỗi không dừng và không có một kỳ vọng biên cố định. Lấy block gộp hai chế độ tạo hỗn hợp chế độ ngẫu nhiên và coi tần suất biên có thể hoán đổi, nên định lý block dừng chuẩn không áp dụng. Mô hình hóa gãy, lấy mẫu trong chế độ đã khai báo hoặc xác định estimand khác.`)], [R(1,'Identifies nonstationary mean.','Nhận diện kỳ vọng không dừng.'),R(2,'Explains pooled-block mismatch.','Giải thích sai lệch block gộp.'),R(1,'Suggests estimand-aware remedy.','Đề xuất sửa phù hợp estimand.')], [B('Uses stationarity theorem based only on within-block order.', 'Dùng định lý dừng chỉ dựa vào thứ tự trong block.')]),
    ],
  },
  {
    week: 79, title: B('Matrix Gaussian state-space model and Kalman filtering', 'Mô hình trạng thái Gaussian ma trận và lọc Kalman'), level: 'graduate core', prerequisites: [12, 60, 73, 76],
    outcomes: [B('Derive matrix Kalman prediction/update through conditional Gaussian projection.', 'Suy ra dự báo/cập nhật Kalman ma trận bằng chiếu Gaussian có điều kiện.'), B('Check dimensions, positive-definite innovation covariance and basic observability.', 'Kiểm tra số chiều, covariance innovation xác định dương và tính quan sát cơ bản.')],
    definitions: B(String.raw`State model: x_t=F_t x_{t−1}+w_t, y_t=H_t x_t+v_t, with x_t∈R^d, y_t∈R^m, w_t~N(0,Q_t), v_t~N(0,R_t), mutually independent across time and from the initial Gaussian state. Given past data, x_t~N(m_t^−,P_t^−). Innovation r_t=y_t−H_tm_t^− has covariance S_t=H_tP_t^−H_tᵀ+R_t. Observability of (F,H) over d steps means O=[Hᵀ,(HF)ᵀ,…,(HF^{d−1})ᵀ]ᵀ has rank d.`, String.raw`Mô hình trạng thái: x_t=F_t x_{t−1}+w_t, y_t=H_t x_t+v_t, x_t∈R^d, y_t∈R^m, w_t~N(0,Q_t), v_t~N(0,R_t), độc lập theo thời gian và với trạng thái Gaussian ban đầu. Có điều kiện theo quá khứ, x_t~N(m_t^−,P_t^−). Innovation r_t=y_t−H_tm_t^− có covariance S_t=H_tP_t^−H_tᵀ+R_t. Tính quan sát của (F,H) trong d bước nghĩa là O=[Hᵀ,(HF)ᵀ,…,(HF^{d−1})ᵀ]ᵀ có hạng d.`),
    theoremTitle: B('Matrix Kalman update is Gaussian conditioning', 'Cập nhật Kalman ma trận là Gaussian conditioning'),
    statement: B(String.raw`If x~N(m,P), y=Hx+v, v~N(0,R) independent, P⪰0 and R≻0, then S=HPHᵀ+R≻0, K=PHᵀS^{-1}, E[x|y]=m+K(y−Hm), and Cov(x|y)=P−PHᵀS^{-1}HP. Prediction through x_t=F_tx_{t−1}+w_t gives m_t^−=F_tm_{t−1}^+, P_t^−=F_tP_{t−1}^+F_tᵀ+Q_t.`, String.raw`Nếu x~N(m,P), y=Hx+v, v~N(0,R) độc lập, P⪰0 và R≻0 thì S=HPHᵀ+R≻0, K=PHᵀS^{-1}, E[x|y]=m+K(y−Hm), Cov(x|y)=P−PHᵀS^{-1}HP. Dự báo qua x_t=F_tx_{t−1}+w_t cho m_t^−=F_tm_{t−1}^+, P_t^−=F_tP_{t−1}^+F_tᵀ+Q_t.`),
    proof: B(String.raw`Let e=x−m and r=y−Hm=He+v. Then Cov(e,r)=PHᵀ and Cov(r)=S. Define e⁺=e−PHᵀS^{-1}r. It is jointly Gaussian with r and Cov(e⁺,r)=PHᵀ−PHᵀS^{-1}S=0, so e⁺ is independent of r. Therefore E[e|r]=PHᵀS^{-1}r and E[x|y]=m+Kr. Cov(e⁺)=P−PHᵀS^{-1}HP, yielding the conditional covariance. Since R≻0, for nonzero a, aᵀSa=(Hᵀa)ᵀP(Hᵀa)+aᵀRa>0, so S is invertible. Prediction mean/covariance follow by linear transformation and independent process noise.`, String.raw`Đặt e=x−m, r=y−Hm=He+v. Khi đó Cov(e,r)=PHᵀ và Cov(r)=S. Định nghĩa e⁺=e−PHᵀS^{-1}r. Nó đồng Gaussian với r và Cov(e⁺,r)=PHᵀ−PHᵀS^{-1}S=0, nên độc lập r. Vậy E[e|r]=PHᵀS^{-1}r và E[x|y]=m+Kr. Cov(e⁺)=P−PHᵀS^{-1}HP là covariance có điều kiện. Vì R≻0, với a khác 0, aᵀSa=(Hᵀa)ᵀP(Hᵀa)+aᵀRa>0 nên S khả nghịch. Mean/covariance dự báo theo biến đổi tuyến tính và nhiễu quá trình độc lập.`), sourceId: 'o-sarkka', section: 'Second ed. §6.3; MIT 14.384 Lecture Notes 21–22.',
    workedExample: B(String.raw`Scalar prior m⁻=0, P⁻=4; H=2, R=1; observe y=3. S=2²·4+1=17, K=4·2/17=8/17. Posterior mean is 24/17≈1.412 and variance 4−(8/17)·2·4=4/17≈0.2353. The observation measures 2x, so treating H as 1 would change both gain and units.`, String.raw`Prior vô hướng m⁻=0, P⁻=4; H=2, R=1; quan sát y=3. S=2²·4+1=17, K=4·2/17=8/17. Mean hậu nghiệm là 24/17≈1.412 và phương sai 4−(8/17)·2·4=4/17≈0.2353. Quan sát đo 2x nên coi H=1 sẽ đổi cả gain lẫn đơn vị.`),
    failureCase: B(String.raw`If the model omits observation noise (R=0) and HPHᵀ is singular, S^{-1} does not exist; use a reduced observation subspace or generalized conditioning, not an unexamined inverse. Gaussianity is what turns zero cross-covariance into conditional independence; for non-Gaussian states the same linear update is only an L² projection, not generally the full conditional mean.`, String.raw`Nếu mô hình bỏ nhiễu quan sát (R=0) và HPHᵀ suy biến thì S^{-1} không tồn tại; dùng không gian quan sát rút gọn hoặc conditioning tổng quát, không nghịch đảo mù. Gaussian biến covariance chéo bằng 0 thành độc lập có điều kiện; với trạng thái không Gaussian, cập nhật tuyến tính chỉ là chiếu L², thường không phải kỳ vọng có điều kiện đầy đủ.`),
    topic: 'matrix Kalman filter; conditional Gaussian projection; observability matrix', readingSection: 'Särkkä & Svensson (2023) Ch. 5 and §6.3; MIT 14.384 Lecture Notes 21',
    exercises: [
      E(B('Dimension audit and update', 'Kiểm tra số chiều và cập nhật'), ['computation'], B(String.raw`State d=2, observation m=1; P⁻=[[2,1],[1,2]], H=[1,1], R=1, m⁻=(0,0), y=2. Compute S, K, m⁺ and P⁺.`, String.raw`Trạng thái d=2, quan sát m=1; P⁻=[[2,1],[1,2]], H=[1,1], R=1, m⁻=(0,0), y=2. Tính S,K,m⁺,P⁺.`), [B('First compute H P Hᵀ, which is scalar.', 'Trước tiên tính HPHᵀ là scalar.')], [B(String.raw`HPHᵀ=6, so S=7. PHᵀ=(3,3)ᵀ, hence K=(3/7,3/7)ᵀ. m⁺=K·2=(6/7,6/7). P⁺=P−(1/7)[[9,9],[9,9]]=[[5/7,−2/7],[−2/7,5/7]]. It is symmetric PSD (eigenvalues 3/7 and 1).`, String.raw`HPHᵀ=6 nên S=7. PHᵀ=(3,3)ᵀ nên K=(3/7,3/7)ᵀ. m⁺=K·2=(6/7,6/7). P⁺=P−(1/7)[[9,9],[9,9]]=[[5/7,−2/7],[-2/7,5/7]]. Ma trận đối xứng PSD (trị riêng 3/7 và 1).`)], [R(1,'Computes scalar S.','Tính S vô hướng.'),R(2,'Computes vector gain and mean.','Tính gain vector và mean.'),R(1,'Computes symmetric covariance.','Tính covariance đối xứng.')], [B('Treats H as a column and gets wrong dimensions.', 'Coi H là cột và sai số chiều.')]),
      E(B('Derive the conditional Gaussian gain', 'Suy ra gain Gaussian có điều kiện'), ['proof'], B(String.raw`Using e=x−m and r=He+v, derive K=PHᵀS^{-1} by requiring the residual e−Kr to be uncorrelated with r; explain why this gives conditional expectation here.`, String.raw`Dùng e=x−m, r=He+v, suy ra K=PHᵀS^{-1} bằng cách yêu cầu residual e−Kr không tương quan với r; giải thích vì sao điều này cho kỳ vọng có điều kiện trong trường hợp này.`), [B('Set Cov(e−Kr,r)=0 and solve for K.', 'Đặt Cov(e−Kr,r)=0 rồi giải K.')], [B(String.raw`Cov(e,r)=PHᵀ and Cov(r,r)=S. Thus Cov(e−Kr,r)=PHᵀ−KS=0 implies K=PHᵀS^{-1}. The residual and r are jointly Gaussian; zero covariance implies independence, so E[e−Kr|r]=0. Therefore E[e|r]=Kr and E[x|y]=m+K(y−Hm).`, String.raw`Cov(e,r)=PHᵀ, Cov(r,r)=S. Vì vậy Cov(e−Kr,r)=PHᵀ−KS=0 suy ra K=PHᵀS^{-1}. Residual và r đồng Gaussian; covariance bằng 0 kéo theo độc lập nên E[e−Kr|r]=0. Do đó E[e|r]=Kr và E[x|y]=m+K(y−Hm).`)], [R(1,'Writes covariance equation.','Viết phương trình covariance.'),R(2,'Solves matrix equation with correct order.','Giải phương trình ma trận đúng thứ tự.'),R(1,'Uses joint Gaussianity for conditioning.','Dùng đồng Gaussian để suy ra điều kiện.')], [B('Reverses S^{-1} and P in the gain.', 'Đảo thứ tự S^{-1} và P trong gain.')]),
      E(B('Prediction covariance and process noise', 'Covariance dự báo và nhiễu quá trình'), ['derivation'], B(String.raw`For x_t=F x_{t−1}+w_t with Cov(x_{t−1}|past)=P and independent w_t~N(0,Q), derive the prediction covariance. Evaluate for F=[[1,1],[0,1]], P=I, Q=diag(.1,.2).`, String.raw`Với x_t=F x_{t−1}+w_t, Cov(x_{t−1}|quá khứ)=P, w_t~N(0,Q) độc lập, suy ra covariance dự báo. Tính khi F=[[1,1],[0,1]], P=I, Q=diag(.1,.2).`), [B('Covariance of a sum of independent terms adds.', 'Covariance tổng biến độc lập cộng lại.')], [B(String.raw`Cov(Fx+w)=F Cov(x)Fᵀ+Q. Here FFᵀ=[[2,1],[1,1]], so P⁻=[[2.1,1],[1,1.2]]. Process noise adds uncertainty; omitting Q understates forecast variance.`, String.raw`Cov(Fx+w)=F Cov(x)Fᵀ+Q. Ở đây FFᵀ=[[2,1],[1,1]], nên P⁻=[[2.1,1],[1,1.2]]. Nhiễu quá trình cộng bất định; bỏ Q sẽ đánh giá thấp phương sai dự báo.`)], [R(1,'Uses independent covariance addition.','Dùng cộng covariance độc lập.'),R(2,'Multiplies FPFᵀ correctly.','Tính FPFᵀ đúng.'),R(1,'Adds Q.','Cộng Q.')], [B('Uses FᵀPF rather than FPFᵀ.', 'Dùng FᵀPF thay FPFᵀ.')]),
      E(B('Transfer: observability and state uniqueness', 'Chuyển giao: tính quan sát và duy nhất trạng thái'), ['proof','transfer'], B(String.raw`For the noiseless deterministic system x_{t+1}=Fx_t, y_t=Hx_t, prove x₀ is uniquely determined by y₀,…,y_{d−1} iff O=[H;HF;…;HF^{d−1}] has full column rank.`, String.raw`Với hệ xác định không nhiễu x_{t+1}=Fx_t, y_t=Hx_t, chứng minh x₀ được xác định duy nhất từ y₀,…,y_{d−1} khi và chỉ khi O=[H;HF;…;HF^{d−1}] đủ hạng cột.`), [B('Two initial states produce identical outputs exactly when their difference lies in ker(O).', 'Hai trạng thái đầu cho cùng quan sát đúng khi hiệu của chúng thuộc ker(O).')], [B(String.raw`Stacked observations equal O x₀. If O has full column rank, Oδ=0 implies δ=0, so no two initial states yield the same data. If rank is deficient, choose nonzero δ∈ker(O); x₀ and x₀+δ produce identical outputs, so uniqueness fails. This is deterministic identifiability; noisy estimation also depends on conditioning and noise covariance.`, String.raw`Chồng các quan sát được O x₀. Nếu O đủ hạng cột, Oδ=0 kéo theo δ=0 nên không có hai trạng thái đầu cùng dữ liệu. Nếu thiếu hạng, chọn δ khác 0 trong ker(O); x₀ và x₀+δ cho quan sát y hệt nên không duy nhất. Đây là nhận dạng xác định; ước lượng nhiễu còn phụ thuộc điều kiện hóa và covariance nhiễu.`)], [R(1,'Writes stacked observation equation.','Viết phương trình quan sát xếp chồng.'),R(2,'Proves full-rank sufficiency and necessity.','Chứng minh đủ và cần của đủ hạng.'),R(1,'Distinguishes identifiability from precision.','Phân biệt nhận dạng với độ chính xác.')], [B('Calls a full row rank condition sufficient regardless of state dimension.', 'Gọi đủ hạng hàng là đủ bất kể số chiều trạng thái.')]),
      E(B('Counterexample: scalar observation cannot identify two static states', 'Phản ví dụ: một quan sát vô hướng không nhận dạng hai trạng thái tĩnh'), ['counterexample'], B(String.raw`Let F=I₂, H=[1,0]. Find O for d=2 and a nonzero state direction invisible to all noiseless observations.`, String.raw`Cho F=I₂, H=[1,0]. Tìm O với d=2 và hướng trạng thái khác 0 không thể thấy qua mọi quan sát không nhiễu.`), [B('HF=H because F is identity.', 'HF=H vì F là ma trận đơn vị.')], [B(String.raw`O=[[1,0],[1,0]] has rank 1<2. Direction δ=(0,1) lies in its null space; changing the second state coordinate leaves every y_t unchanged. The filter may still produce a posterior by relying on its prior, but data alone do not identify that coordinate.`, String.raw`O=[[1,0],[1,0]] có hạng 1<2. Hướng δ=(0,1) thuộc null; đổi tọa độ trạng thái thứ hai không làm y_t đổi. Bộ lọc vẫn có thể cho hậu nghiệm nhờ prior, nhưng dữ liệu riêng không nhận dạng tọa độ đó.`)], [R(1,'Forms observability matrix.','Lập ma trận quan sát.'),R(2,'Finds null direction.','Tìm hướng null.'),R(1,'Distinguishes prior information from observation.','Tách thông tin prior khỏi quan sát.')], [B('Claims filtering requires full observability at every single time.', 'Khẳng định lọc cần quan sát đầy đủ tại từng thời điểm riêng lẻ.')]),
    ],
  },
  {
    week: 80, title: B('Innovation likelihood and Riccati recursion', 'Likelihood innovation và truy hồi Riccati'), level: 'graduate core', prerequisites: [79, 64],
    outcomes: [B('Factor the state-space likelihood into Gaussian innovation terms.', 'Phân tích likelihood state-space thành các hạng innovation Gaussian.'), B('Derive the covariance Riccati recursion and identify covariance parameterization assumptions.', 'Suy ra truy hồi Riccati covariance và nhận diện giả thiết tham số covariance.')],
    definitions: B(String.raw`At each time, the one-step predictive law is y_t|y_{1:t−1}~N(μ_t,S_t), with innovation r_t=y_t−μ_t. By the chain rule, p(y_{1:T}|θ)=∏_t p(y_t|y_{1:t−1},θ). The innovation log likelihood is −½Σ_t[m log(2π)+log|S_t|+r_tᵀS_t^{-1}r_t]. The covariance recursion alternates prediction P⁻=FP^+Fᵀ+Q and update P^+=P⁻−P⁻Hᵀ(HP⁻Hᵀ+R)^{-1}HP⁻.`, String.raw`Mỗi thời điểm có luật dự báo một bước y_t|y_{1:t−1}~N(μ_t,S_t), innovation r_t=y_t−μ_t. Theo quy tắc dây chuyền, p(y_{1:T}|θ)=∏_t p(y_t|y_{1:t−1},θ). Log-likelihood innovation là −½Σ_t[m log(2π)+log|S_t|+r_tᵀS_t^{-1}r_t]. Truy hồi covariance xen kẽ dự báo P⁻=FP^+Fᵀ+Q và cập nhật P^+=P⁻−P⁻Hᵀ(HP⁻Hᵀ+R)^{-1}HP⁻.`),
    theoremTitle: B('Innovation factorization gives the exact Gaussian likelihood', 'Phân tích innovation cho likelihood Gaussian chính xác'),
    statement: B(String.raw`Under the linear Gaussian model with known parameter θ and positive-definite innovation covariances S_t, the joint observation density equals the product of conditional Gaussian densities; hence the displayed innovation log likelihood is exact. Innovations r_t are mutually independent N(0,S_t) under the correctly specified model.`, String.raw`Dưới mô hình Gaussian tuyến tính với θ đã biết và covariance innovation S_t xác định dương, mật độ kết hợp quan sát bằng tích mật độ Gaussian có điều kiện; do đó log-likelihood innovation nêu trên là chính xác. Innovations r_t độc lập lẫn nhau, r_t~N(0,S_t), nếu mô hình được đặc tả đúng.`),
    proof: B(String.raw`The density chain rule gives p(y_{1:T})=p(y₁)∏_{t=2}^T p(y_t|y_{1:t−1}) without any independence assumption. The Kalman recursion supplies each conditional Gaussian mean μ_t and covariance S_t, so taking logarithms of the multivariate normal densities yields the formula. For nonsingular S_t, correct linear-Gaussian filtering gives the full conditional law S_t^{-1/2}r_t | y_{1:t−1} ~ N(0,I), with deterministic covariance I, not merely zero conditional mean. A conditional distribution that is constant in the past implies independence from that past. Equivalently, the stacked observation/innovation vectors are jointly Gaussian and each innovation is orthogonal to earlier observations; joint Gaussianity upgrades orthogonality to independence. Induction then gives mutual independence across time.`, String.raw`Quy tắc mật độ cho p(y_{1:T})=p(y₁)∏_{t=2}^T p(y_t|y_{1:t−1}), không cần giả sử độc lập. Truy hồi Kalman cung cấp mean có điều kiện μ_t và covariance S_t; lấy log mật độ chuẩn đa biến cho công thức. Innovation có điều kiện đã tâm hóa nên độc lập quá khứ do Gaussian; quy nạp, mỗi r_t độc lập với quan sát/innovation trước. Tính Gaussian kết hợp cho độc lập lẫn nhau.`), sourceId: 'o-sarkka', section: 'Second ed. §6.3 (Gaussian innovations/Kalman likelihood); MIT Lecture Notes 21–22.',
    workedExample: B(String.raw`For scalar innovation r=2, S=4, one observation contributes −½[log(2π)+log 4+1] to log likelihood because r²/S=1. A large residual is penalized relative to its predicted variance, not as an unscaled squared error.`, String.raw`Với innovation vô hướng r=2, S=4, một quan sát góp −½[log(2π)+log 4+1] vào log-likelihood vì r²/S=1. Residual lớn bị phạt theo phương sai dự báo, không phải bình phương không co giãn.`),
    failureCase: B(String.raw`If S_t is singular, the ordinary Gaussian density/log determinant is undefined; if model parameters are estimated then innovations are not independent conditional on the fitted parameter in the same unconditional sense. A large innovation can mean a rare draw or model mismatch; likelihood alone does not diagnose which.`, String.raw`Nếu S_t suy biến, mật độ Gaussian/log định thức thông thường không xác định; nếu tham số ước lượng thì innovation không độc lập theo cùng nghĩa vô điều kiện khi đã fit tham số. Innovation lớn có thể là biến cố hiếm hoặc sai mô hình; likelihood riêng không chẩn đoán được nguyên nhân.`),
    topic: 'innovations likelihood; Gaussian chain rule; Riccati covariance; model checking', readingSection: 'Särkkä & Svensson (2023) §6.3; MIT 14.384 Lecture Notes 21–22',
    exercises: [
      E(B('One-step innovation log likelihood', 'Log-likelihood innovation một bước'), ['computation'], B(String.raw`For m=1, r=−1.5 and S=2.25, compute the observation's log-likelihood contribution.`, String.raw`Với m=1, r=−1.5, S=2.25, tính đóng góp log-likelihood của quan sát.`), [B('The quadratic term r²/S equals one.', 'Hạng quadratic r²/S bằng một.')], [B(String.raw`r²/S=2.25/2.25=1. Contribution is −½[log(2π)+log(2.25)+1]≈−1.8244.`, String.raw`r²/S=2.25/2.25=1. Đóng góp là −½[log(2π)+log(2.25)+1]≈−1.8244.`)], [R(1,'Computes standardized quadratic.','Tính hạng quadratic chuẩn hóa.'),R(2,'Includes log determinant and dimension.','Gồm log định thức và số chiều.'),R(1,'Applies negative one-half.','Áp dụng âm một nửa.')], [B('Uses r² alone and omits variance scaling.', 'Dùng r² riêng, bỏ co giãn phương sai.')]),
      E(B('Derive the likelihood factorization', 'Suy ra phân tích likelihood'), ['proof'], B(String.raw`Use the probability chain rule, not an IID assumption, to derive the innovation likelihood product and log expression.`, String.raw`Dùng quy tắc dây chuyền xác suất, không dùng giả thiết IID, để suy ra tích likelihood innovation và công thức log.`), [B('Write p(y₁,…,y_T)=∏p(y_t|y_{1:t−1}).', 'Viết p(y₁,…,y_T)=∏p(y_t|y_{1:t−1}).')], [B(String.raw`Factor the joint density sequentially by the chain rule. Under the model each factor is N(μ_t,S_t), whose log density is −½[m log(2π)+log|S_t|+(y_t−μ_t)ᵀS_t^{-1}(y_t−μ_t)]. Summing over t gives the exact likelihood. Dependence is represented by μ_t,S_t conditioned on history; iid factorization is unnecessary.`, String.raw`Phân tích mật độ kết hợp tuần tự theo chain rule. Mỗi hạng dưới mô hình là N(μ_t,S_t), log mật độ bằng −½[m log(2π)+log|S_t|+(y_t−μ_t)ᵀS_t^{-1}(y_t−μ_t)]. Cộng theo t cho likelihood chính xác. Phụ thuộc được biểu diễn trong μ_t,S_t theo lịch sử; không cần factor IID.`)], [R(1,'Uses chain rule.','Dùng chain rule.'),R(2,'Writes Gaussian density term.','Viết hạng mật độ Gaussian.'),R(1,'Explains dependence representation.','Giải thích biểu diễn phụ thuộc.')], [B('Claims observations are IID because the likelihood factors.', 'Khẳng định quan sát IID vì likelihood phân tích được.')]),
      E(B('Riccati update with scalar data', 'Cập nhật Riccati với dữ liệu vô hướng'), ['computation','derivation'], B(String.raw`For P⁻=3, H=2, R=1, compute S, K and P⁺; verify P⁺≥0.`, String.raw`Với P⁻=3, H=2, R=1, tính S,K,P⁺ và kiểm tra P⁺≥0.`), [B('S=H²P⁻+R.', 'S=H²P⁻+R.')], [B(String.raw`S=4·3+1=13, K=P⁻H/S=6/13. P⁺=P⁻−P⁻H S^{-1}H P⁻=3−36/13=3/13≈.2308≥0.`, String.raw`S=4·3+1=13, K=P⁻H/S=6/13. P⁺=P⁻−P⁻H S^{-1}H P⁻=3−36/13=3/13≈.2308≥0.`)], [R(1,'Computes S.','Tính S.'),R(2,'Computes gain and posterior variance.','Tính gain và phương sai hậu nghiệm.'),R(1,'Checks nonnegativity.','Kiểm tra không âm.')], [B('Uses P⁻−K rather than P⁻−KHP⁻.', 'Dùng P⁻−K thay vì P⁻−KHP⁻.')]),
      E(B('Transfer: innovations as sequential residual diagnostics', 'Chuyển giao: innovation làm chẩn đoán residual tuần tự'), ['application','transfer'], B(String.raw`Under a correctly specified Gaussian model, state what distribution standardized innovations S_t^{-1/2}r_t should have and give two distinct diagnostics for misspecification. Explain why a histogram alone is insufficient.`, String.raw`Dưới mô hình Gaussian đặc tả đúng, nêu phân phối của innovation chuẩn hóa S_t^{-1/2}r_t và hai chẩn đoán sai mô hình khác nhau. Giải thích vì sao histogram riêng chưa đủ.`), [B('Check both marginal calibration and serial dependence.', 'Kiểm tra cả hiệu chỉnh biên và phụ thuộc chuỗi.')], [B(String.raw`Standardized innovations should be N(0,I) and serially independent under the exact model. Check mean/variance and tail/quantile calibration, and separately inspect autocorrelation or a portmanteau statistic. A pooled histogram can look Gaussian while order-dependent correlation remains; it does not test conditional calibration.`, String.raw`Innovation chuẩn hóa phải N(0,I) và độc lập chuỗi dưới mô hình chính xác. Kiểm tra mean/phương sai, đuôi/quantile hiệu chỉnh, đồng thời xem tự tương quan hoặc thống kê portmanteau. Histogram gộp có thể giống Gaussian dù còn tương quan theo thứ tự; nó không kiểm tra hiệu chỉnh có điều kiện.`)], [R(1,'States standardized reference law.','Nêu luật tham chiếu chuẩn hóa.'),R(2,'Names two distinct diagnostics.','Nêu hai chẩn đoán khác nhau.'),R(1,'Explains histogram limitation.','Giải thích hạn chế histogram.')], [B('Treats independent innovations as automatically calibrated after parameter fitting.', 'Coi innovation độc lập là tự động hiệu chỉnh sau fit tham số.')]),
      E(B('Counterexample: a fitted model can hide innovation dependence', 'Phản ví dụ: mô hình đã fit có thể che phụ thuộc innovation'), ['counterexample','transfer'], B(String.raw`Suppose standardized residuals alternate deterministically +1,−1,+1,−1,… but have a symmetric pooled histogram. Which innovation assumptions fail and what statistic detects the issue?`, String.raw`Giả sử residual chuẩn hóa luân phiên xác định +1,−1,+1,−1,… nhưng histogram gộp đối xứng. Giả thiết innovation nào thất bại và thống kê nào phát hiện?`), [B('Lag-one sample autocorrelation is near −1.', 'Tự tương quan mẫu lag một gần −1.')], [B(String.raw`The marginal mean/variance may mimic centered unit variance, but the innovations are not independent over time; lag-one correlation is approximately −1. Inspect the innovation ACF or Ljung–Box-type portmanteau statistic. A histogram ignores temporal ordering and therefore misses this failure.`, String.raw`Kỳ vọng/phương sai biên có thể giống 0 và 1, nhưng innovation không độc lập theo thời gian; tương quan lag một xấp xỉ −1. Xem ACF innovation hoặc thống kê portmanteau dạng Ljung–Box. Histogram bỏ thứ tự thời gian nên không phát hiện lỗi này.`)], [R(1,'Separates marginal shape from independence.','Tách dạng biên khỏi độc lập.'),R(2,'Identifies lag-one signal.','Nhận diện tín hiệu lag một.'),R(1,'Names ordering-aware diagnostic.','Nêu chẩn đoán xét thứ tự.')], [B('Concludes the Gaussian model is correct from symmetry alone.', 'Kết luận mô hình Gaussian đúng chỉ từ tính đối xứng.')]),
    ],
  },
  {
    week: 81, title: B('Filtering versus smoothing, detectability, and mismatch', 'Lọc so với làm trơn, khả phát hiện và sai mô hình'), level: 'graduate core', prerequisites: [79, 80],
    outcomes: [B('Derive the Rauch–Tung–Striebel fixed-interval smoothing recursion.', 'Suy ra truy hồi làm trơn khoảng cố định Rauch–Tung–Striebel.'), B('Distinguish observability, detectability, filtering stability and model mismatch.', 'Phân biệt tính quan sát, khả phát hiện, ổn định lọc và sai mô hình.')],
    definitions: B(String.raw`Filtering estimates x_t|y_{1:t}; smoothing estimates x_t|y_{1:T}, T>t and may use future observations. For linear Gaussian models, P_{t+1|t}=F_{t+1}P_{t|t}F_{t+1}ᵀ+Q_{t+1}. The smoother gain is J_t=P_{t|t}F_{t+1}ᵀP_{t+1|t}^{-1}. A pair (F,H) is detectable if every unobservable eigenmode of F is strictly stable (inside the unit disk); detectability, stabilizability and finite covariance assumptions are standard hypotheses for a bounded steady-state Riccati solution.`, String.raw`Lọc ước lượng x_t|y_{1:t}; làm trơn ước lượng x_t|y_{1:T}, T>t và có thể dùng quan sát tương lai. Với mô hình Gaussian tuyến tính, P_{t+1|t}=F_{t+1}P_{t|t}F_{t+1}ᵀ+Q_{t+1}. Gain smoother J_t=P_{t|t}F_{t+1}ᵀP_{t+1|t}^{-1}. Cặp (F,H) khả phát hiện nếu mọi mode trị riêng không quan sát được của F ổn định nghiêm ngặt (nằm trong đĩa đơn vị); khả phát hiện, khả ổn định hóa và covariance hữu hạn là giả thiết chuẩn để có nghiệm Riccati dừng bị chặn.`),
    theoremTitle: B('RTS fixed-interval smoothing recursion', 'Truy hồi làm trơn khoảng cố định RTS'),
    statement: B(String.raw`If P_{t+1|t} is invertible in a linear Gaussian state-space model, then m_{t|T}=m_{t|t}+J_t(m_{t+1|T}−m_{t+1|t}) and P_{t|T}=P_{t|t}+J_t(P_{t+1|T}−P_{t+1|t})J_tᵀ, where J_t=P_{t|t}F_{t+1}ᵀP_{t+1|t}^{−1}.`, String.raw`Nếu P_{t+1|t} khả nghịch trong mô hình trạng thái Gaussian tuyến tính thì m_{t|T}=m_{t|t}+J_t(m_{t+1|T}−m_{t+1|t}) và P_{t|T}=P_{t|t}+J_t(P_{t+1|T}−P_{t+1|t})J_tᵀ, với J_t=P_{t|t}F_{t+1}ᵀP_{t+1|t}^{−1}.`),
    proof: B(String.raw`Condition on y_{1:t}. The joint vector (x_t,x_{t+1}) is Gaussian with means (m_{t|t},m_{t+1|t}), Cov(x_t)=P_{t|t}, Cov(x_{t+1})=P_{t+1|t}, and cross-covariance P_{t|t}F_{t+1}ᵀ. Gaussian conditioning gives E[x_t|x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}−m_{t+1|t}) and conditional covariance P_{t|t}−J_tP_{t+1|t}J_tᵀ. Now average this conditional mean over x_{t+1}|y_{1:T}; its mean yields the stated m smoother. The law of total covariance adds J_tP_{t+1|T}J_tᵀ to the conditional covariance, giving the stated P smoother after substituting J_tP_{t+1|t}J_tᵀ.`, String.raw`Có điều kiện theo y_{1:t}, vector chung (x_t,x_{t+1}) Gaussian, mean (m_{t|t},m_{t+1|t}), Cov(x_t)=P_{t|t}, Cov(x_{t+1})=P_{t+1|t}, covariance chéo P_{t|t}F_{t+1}ᵀ. Gaussian conditioning cho E[x_t|x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}−m_{t+1|t}) và covariance điều kiện P_{t|t}−J_tP_{t+1|t}J_tᵀ. Lấy trung bình theo x_{t+1}|y_{1:T}; kỳ vọng cho mean smoother. Luật covariance toàn phần cộng J_tP_{t+1|T}J_tᵀ vào covariance điều kiện, được covariance smoother sau khi thay J_tP_{t+1|t}J_tᵀ.`), sourceId: 'o-sarkka', section: 'Second ed. §§12.1–12.3 (Bayesian smoothing equations and affine RTS); Ch. 5 (state-space model).',
    workedExample: B(String.raw`If m_{t|t}=0, m_{t+1|t}=1, smoothed m_{t+1|T}=1.5 and J_t=.4, then m_{t|T}=0+.4(.5)=.2. Future evidence shifts the past estimate by a gain-scaled forecast correction.`, String.raw`Nếu m_{t|t}=0, m_{t+1|t}=1, mean đã làm trơn m_{t+1|T}=1.5, J_t=.4 thì m_{t|T}=0+.4(.5)=.2. Bằng chứng tương lai dịch ước lượng quá khứ theo hiệu chỉnh dự báo nhân gain.`),
    failureCase: B(String.raw`Smoothing is not a real-time forecast: it uses y_{t+1:T}. Scoring a smoothed state against a future target as if it had been available at t leaks information. Under model mismatch, innovations may be biased/autocorrelated and filter covariance can be overconfident; detectability does not protect against a wrong transition or heavy-tailed shocks.`, String.raw`Làm trơn không phải dự báo thời gian thực: nó dùng y_{t+1:T}. Chấm trạng thái đã làm trơn với mục tiêu tương lai như thể có sẵn tại t là rò rỉ thông tin. Sai mô hình có thể làm innovation chệch/tự tương quan và covariance lọc quá tự tin; khả phát hiện không bảo vệ trước chuyển tiếp sai hay shock đuôi dày.`),
    topic: 'RTS smoothing; detectability/stability; model mismatch; information-time boundary', readingSection: 'Särkkä & Svensson (2023) Ch. 5, §§12.1–12.3; MIT 14.384 Lecture Notes 21–22',
    exercises: [
      E(B('One RTS mean/covariance step', 'Một bước mean/covariance RTS'), ['computation'], B(String.raw`Given m_{t|t}=2, m_{t+1|t}=3, m_{t+1|T}=1, J=.25, P_{t|t}=2, P_{t+1|t}=4, P_{t+1|T}=1, compute smoothed mean and variance.`, String.raw`Cho m_{t|t}=2, m_{t+1|t}=3, m_{t+1|T}=1, J=.25, P_{t|t}=2, P_{t+1|t}=4, P_{t+1|T}=1, tính mean và phương sai đã làm trơn.`), [B('Mean correction is J times the next-state forecast error.', 'Hiệu chỉnh mean là J nhân sai số dự báo trạng thái kế tiếp.')], [B(String.raw`m_{t|T}=2+.25(1−3)=1.5. P_{t|T}=2+.25²(1−4)=2−.1875=1.8125. The future observation moves the mean down and reduces uncertainty.`, String.raw`m_{t|T}=2+.25(1−3)=1.5. P_{t|T}=2+.25²(1−4)=2−.1875=1.8125. Quan sát tương lai kéo mean xuống và giảm bất định.`)], [R(1,'Computes correction sign.','Tính đúng dấu hiệu chỉnh.'),R(2,'Computes covariance adjustment.','Tính điều chỉnh covariance.'),R(1,'Interprets direction.','Diễn giải hướng thay đổi.')], [B('Uses m_{t|T}−m_{t|t} in the covariance formula.', 'Dùng m_{t|T}−m_{t|t} trong công thức covariance.')]),
      E(B('Derive the smoother gain by Gaussian conditioning', 'Suy ra gain làm trơn bằng Gaussian conditioning'), ['proof'], B(String.raw`Given cross covariance Cov(x_t,x_{t+1}|y_{1:t})=P_{t|t}Fᵀ, derive J_t and the conditional mean of x_t given x_{t+1} and past data.`, String.raw`Cho covariance chéo Cov(x_t,x_{t+1}|y_{1:t})=P_{t|t}Fᵀ, suy ra J_t và mean có điều kiện của x_t theo x_{t+1} cùng dữ liệu quá khứ.`), [B('Use Cov(first,second) Cov(second)^{-1}.', 'Dùng Cov(thứ nhất,thứ hai) Cov(thứ hai)^{-1}.')], [B(String.raw`The conditional Gaussian coefficient is cross-covariance times inverse second-state covariance: J_t=P_{t|t}FᵀP_{t+1|t}^{−1}. Thus E[x_t|x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}−m_{t+1|t}). The formula requires invertible P_{t+1|t}; singular models need conditioning on its support.`, String.raw`Hệ số Gaussian có điều kiện là covariance chéo nhân nghịch đảo covariance trạng thái thứ hai: J_t=P_{t|t}FᵀP_{t+1|t}^{−1}. Vì vậy E[x_t|x_{t+1},y_{1:t}]=m_{t|t}+J_t(x_{t+1}−m_{t+1|t}). Công thức cần P_{t+1|t} khả nghịch; mô hình suy biến cần điều kiện hóa trên support.`)], [R(1,'Identifies cross covariance orientation.','Nhận diện đúng chiều covariance chéo.'),R(2,'Uses forecast covariance inverse.','Dùng nghịch đảo covariance dự báo.'),R(1,'States invertibility condition.','Nêu điều kiện khả nghịch.')], [B('Uses P_{t+1|t}^{−1}P_{t|t}Fᵀ, with incompatible dimensions.', 'Dùng P_{t+1|t}^{−1}P_{t|t}Fᵀ sai chiều số.')]),
      E(B('Observability versus detectability', 'Tính quan sát so với khả phát hiện'), ['application','derivation'], B(String.raw`Give an example with F=diag(.5,1.2), H=[1,0]. Determine which eigenmode is unobservable and whether the pair is detectable under the stated definition.`, String.raw`Cho F=diag(.5,1.2), H=[1,0]. Xác định mode không quan sát được và cặp có khả phát hiện theo định nghĩa đã nêu không.`), [B('The second coordinate never enters H F^k.', 'Tọa độ thứ hai không bao giờ xuất hiện trong HF^k.')], [B(String.raw`For every k, HF^k=[(.5)^k,0], so the second coordinate is unobservable. Its eigenvalue is 1.2, outside the unit disk, so the pair is not detectable: an unstable unobservable mode cannot be corrected by observations.`, String.raw`Với mọi k, HF^k=[(.5)^k,0], nên tọa độ thứ hai không quan sát được. Trị riêng của nó là 1.2 ngoài đĩa đơn vị, nên cặp không khả phát hiện: mode không quan sát bất ổn không thể được quan sát hiệu chỉnh.`)], [R(1,'Computes row HF^k.','Tính hàng HF^k.'),R(2,'Identifies hidden coordinate.','Xác định tọa độ ẩn.'),R(1,'Applies stability requirement.','Áp dụng yêu cầu ổn định.')], [B('Calls the pair detectable because the first mode is observed.', 'Gọi cặp khả phát hiện vì mode đầu quan sát được.')]),
      E(B('Transfer: identify real-time leakage', 'Chuyển giao: nhận diện rò rỉ thời gian thực'), ['counterexample','transfer'], B(String.raw`A backtest at date t uses x_{t|T} from a fixed-interval smoother with T>t to size a position for return t+1. Explain the leakage and rewrite the valid information set.`, String.raw`Backtest tại ngày t dùng x_{t|T} từ smoother khoảng cố định T>t để chọn vị thế cho return t+1. Giải thích rò rỉ và viết lại tập thông tin hợp lệ.`), [B('The smoother conditions on observations after t.', 'Smoother điều kiện hóa trên quan sát sau t.')], [B(String.raw`x_{t|T}=E[x_t|y_{1:T}] uses y_{t+1:T}, which are unavailable at decision time t; the backtest has look-ahead leakage. A real-time filter uses x_{t|t}=E[x_t|y_{1:t}] and estimates model parameters only from information available by t or a separately frozen training window.`, String.raw`x_{t|T}=E[x_t|y_{1:T}] dùng y_{t+1:T}, chưa có tại thời điểm quyết định t; backtest rò rỉ nhìn trước. Bộ lọc thời gian thực dùng x_{t|t}=E[x_t|y_{1:t}], còn tham số chỉ ước lượng từ dữ liệu có tới t hoặc cửa sổ train đóng băng riêng.`)], [R(1,'Identifies future observations in conditioning set.','Nhận diện quan sát tương lai trong tập điều kiện.'),R(2,'Replaces smoother with filter.','Thay smoother bằng filter.'),R(1,'Handles parameter window honestly.','Xử lý trung thực cửa sổ tham số.')], [B('Claims smoothing is valid because the state timestamp is t.', 'Cho smoothing hợp lệ vì timestamp trạng thái là t.')]),
      E(B('Counterexample: model mismatch creates biased innovations', 'Phản ví dụ: sai mô hình tạo innovation chệch'), ['counterexample','transfer'], B(String.raw`The true observation is y_t=x_t+5+v_t but the fitted filter assumes y_t=x_t+v_t. What is the expected innovation after a settled filter, and which diagnostic should flag the mismatch?`, String.raw`Quan sát thật y_t=x_t+5+v_t nhưng filter fit giả sử y_t=x_t+v_t. Kỳ vọng innovation sau khi filter ổn định là gì, chẩn đoán nào báo sai mô hình?`), [B('The omitted intercept enters the innovation mean.', 'Intercept bị bỏ đi đi vào mean innovation.')], [B(String.raw`The model predicts the observation without the +5 offset, so the innovation has mean near 5 after state transients (exact value depends on filter adaptation). A rolling innovation mean/standardized-residual calibration check should flag it; a covariance-only stability claim does not correct a systematic mean error.`, String.raw`Mô hình dự báo quan sát thiếu offset +5 nên innovation có kỳ vọng gần 5 sau quá độ (giá trị chính xác tùy khả năng thích ứng của filter). Kiểm tra mean innovation cuộn hoặc hiệu chỉnh residual chuẩn hóa sẽ phát hiện; khẳng định ổn định covariance không sửa lỗi mean hệ thống.`)], [R(1,'Identifies omitted offset.','Nhận diện offset bị bỏ.'),R(2,'States innovation mean consequence.','Nêu hệ quả mean innovation.'),R(1,'Chooses mean/calibration diagnostic.','Chọn chẩn đoán mean/hiệu chỉnh.')], [B('Claims a wider R removes all systematic bias.', 'Cho rằng tăng R xóa mọi bias hệ thống.')]),
    ],
  },
  {
    week: 82, title: B('Sequential forecasts, proper scores, and calibration', 'Dự báo tuần tự, score proper và hiệu chỉnh'), level: 'graduate core', prerequisites: [76, 77, 80],
    outcomes: [B('Prove the logarithmic score is strictly proper by a KL-divergence identity.', 'Chứng minh log score strictly proper bằng đồng nhất thức KL.'), B('Use the conditional probability integral transform and preserve the forecast-time information set.', 'Dùng PIT xác suất có điều kiện và giữ đúng tập thông tin khi dự báo.')],
    definitions: B(String.raw`At time t, a prequential forecast F_t must be measurable with respect to information available before Y_t; score S(F_t,Y_t), reveal Y_t, then update. For continuous conditional CDF F_t(y)=P(Y_t≤y|F_{t−1}), the probability integral transform U_t=F_t(Y_t) is conditionally uniform under the true model. Calibration is a repeated-sampling property and sharpness describes concentration; neither alone replaces a proper score.`, String.raw`Tại thời điểm t, dự báo tuần tự F_t phải đo được theo thông tin có trước Y_t; tính S(F_t,Y_t), sau đó lộ Y_t rồi cập nhật. Với CDF có điều kiện liên tục F_t(y)=P(Y_t≤y|F_{t−1}), PIT U_t=F_t(Y_t) đều có điều kiện nếu mô hình đúng. Hiệu chỉnh là tính chất lấy mẫu lặp lại, sharpness nói độ tập trung; không yếu tố nào riêng lẻ thay proper score.`),
    theoremTitle: B('Log score is strictly proper', 'Log score là strictly proper'),
    statement: B(String.raw`Let q and p be densities with q≪p and finite cross-entropy. Under Y~q, E_q[−log p(Y)]−E_q[−log q(Y)]=KL(q||p)≥0, with equality iff p=q q-a.e. Thus the expected negative log score is uniquely minimized by the true predictive density.`, String.raw`Cho q,p là mật độ, q≪p và cross-entropy hữu hạn. Với Y~q, E_q[−log p(Y)]−E_q[−log q(Y)]=KL(q||p)≥0, dấu bằng khi và chỉ khi p=q q-hầu khắp nơi. Vì vậy negative log score kỳ vọng đạt min duy nhất tại mật độ dự báo thật.`),
    proof: B(String.raw`Subtract the expected log losses: ∫q(y)[−log p(y)+log q(y)]dy=∫q(y)log(q(y)/p(y))dy=KL(q||p). Gibbs' inequality follows from −log u≥1−u for u>0: KL=−∫q log(p/q)≥∫q(1−p/q)=1−∫p=0. Equality in −log u≥1−u requires u=1 q-a.e., so p=q q-a.e. Densities with p=0 on a set of positive q-mass have infinite loss and cannot improve the score.`, String.raw`Hiệu hai negative log loss là ∫q(y)[−log p(y)+log q(y)]dy=∫q(y)log(q(y)/p(y))dy=KL(q||p). Bất đẳng thức Gibbs suy từ −log u≥1−u với u>0: KL=−∫q log(p/q)≥∫q(1−p/q)=1−∫p=0. Dấu bằng của −log u≥1−u cần u=1 q-hầu khắp nơi, tức p=q. Mật độ p=0 trên tập có q-mass dương gây loss vô hạn, không thể score tốt hơn.`), sourceId: 'o-scoring', section: '§2 (strict propriety and logarithmic score); conditional PIT derived directly from CDF.',
    workedExample: B(String.raw`For true q=N(0,1) and forecast p=N(0,4), KL(q||p)=½[1/4−1+log 4]≈.3181 nats per observation. The broader forecast has worse expected log score despite covering more values; calibration and sharpness must be considered together.`, String.raw`Với q=N(0,1) thật và dự báo p=N(0,4), KL(q||p)=½[1/4−1+log 4]≈.3181 nat mỗi quan sát. Dự báo rộng hơn có expected log score kém hơn dù bao phủ nhiều giá trị; cần xem hiệu chỉnh và độ sắc cùng nhau.`),
    failureCase: B(String.raw`A histogram of PIT values can look uniform while the sequence U_t is serially dependent or forecasts fail conditionally in a regime. Conversely, a sharp but miscalibrated forecast can score badly. Rolling or regime-conditioned diagnostics must be prespecified; a stationary calibration theorem does not survive arbitrary drift.`, String.raw`Histogram PIT có thể đều trong khi chuỗi U_t phụ thuộc thời gian hoặc dự báo sai có điều kiện theo chế độ. Ngược lại, dự báo sắc nhưng lệch hiệu chỉnh có thể score kém. Chẩn đoán cuộn/theo chế độ cần định trước; định lý hiệu chỉnh dừng không còn đúng dưới drift tùy ý.`),
    topic: 'prequential information order; logarithmic scoring; PIT calibration; regime diagnostics', readingSection: 'Gneiting & Raftery §§2–3; Särkkä & Svensson (2023) §6.3',
    exercises: [
      E(B('Normal log-score divergence', 'Độ lệch log score Gaussian'), ['computation'], B(String.raw`For true q=N(0,1) and forecast p=N(1,1), compute KL(q||p), the excess expected negative log score.`, String.raw`Với q=N(0,1) thật, dự báo p=N(1,1), tính KL(q||p), tức expected negative log score tăng thêm.`), [B('Equal variances reduce KL to half the squared mean difference.', 'Phương sai bằng nhau rút KL còn nửa bình phương chênh mean.')], [B(String.raw`KL(N(0,1)||N(1,1))=½(0−1)²=.5 nats. Therefore the forecast incurs .5 more expected negative log score per observation than the truth.`, String.raw`KL(N(0,1)||N(1,1))=½(0−1)²=.5 nat. Dự báo chịu thêm .5 expected negative log score mỗi quan sát so với phân phối thật.`)], [R(1,'Uses correct direction q||p.','Dùng đúng chiều q||p.'),R(2,'Computes mean-shift term.','Tính hạng dịch mean.'),R(1,'Interprets excess score.','Diễn giải score tăng thêm.')], [B('Reverses KL arguments and gets the same value only by coincidence.', 'Đảo đối số KL và ra cùng giá trị do ngẫu nhiên.')]),
      E(B('Prove strict propriety from Gibbs inequality', 'Chứng minh tính proper nghiêm từ Gibbs'), ['proof'], B(String.raw`Derive nonnegativity of the expected log-score excess using −log u≥1−u, and identify the equality condition.`, String.raw`Suy ra tính không âm của phần log-score tăng thêm bằng −log u≥1−u và xác định điều kiện dấu bằng.`), [B('Set A={q>0}; check whether p vanishes on positive q-mass before integrating.', 'Đặt A={q>0}; kiểm tra p có bằng không trên tập q-mass dương trước khi tích phân.')], [B(String.raw`Let A={y:q(y)>0}. If p=0 on a subset of A with positive q-mass, then KL(q||p)=∞. Otherwise apply −log(p/q)≥1−p/q only on A, giving KL(q||p)≥∫_Aq−∫_Ap=1−∫_Ap≥0. Equality requires p=q q-a.e. on A and ∫_A p=1, so p places no mass outside A and p=q almost everywhere. The restriction to A matters: without q≪p, one cannot replace ∫_A p by the full integral ∫p=1.`, String.raw`Đặt A={y:q(y)>0}. Nếu p=0 trên tập con của A có q-mass dương thì KL(q||p)=∞. Nếu không, chỉ áp dụng −log(p/q)≥1−p/q trên A, suy ra KL(q||p)≥∫_Aq−∫_Ap=1−∫_Ap≥0. Dấu bằng cần p=q q-hầu khắp trên A và ∫_A p=1, nên p không có khối lượng ngoài A và p=q hầu khắp nơi. Giới hạn A quan trọng: nếu chưa có q≪p, không thể thay ∫_A p bằng tích phân đầy đủ ∫p=1.`)], [R(1,'Defines the q-support and checks infinite loss.', 'Xác định support của q và kiểm tra loss vô hạn.'),R(1,'Integrates the inequality only over A and concludes nonnegativity.', 'Chỉ tích phân bất đẳng thức trên A và kết luận không âm.'),R(1,'Gives the equality condition, including no p-mass outside A.', 'Nêu điều kiện dấu bằng, gồm không có p-mass ngoài A.')], [B('Integrates over the full space without a support condition, or omits the equality case.', 'Tích phân trên toàn miền khi thiếu điều kiện support hoặc bỏ trường hợp dấu bằng.')]),
      E(B('Conditional probability integral transform', 'Biến đổi tích phân xác suất có điều kiện'), ['proof','derivation'], B(String.raw`Assume Y_t|F_{t−1} has a continuous CDF F_t. Prove P(F_t(Y_t)≤u|F_{t−1})=u for 0<u<1.`, String.raw`Giả sử Y_t|F_{t−1} có CDF liên tục F_t. Chứng minh P(F_t(Y_t)≤u|F_{t−1})=u với 0<u<1.`), [B('Use a conditional quantile y_u satisfying F_t(y_u)=u.', 'Dùng quantile có điều kiện y_u thỏa F_t(y_u)=u.')], [B(String.raw`Condition on the past, so F_t is fixed. By continuity choose y_u with F_t(y_u)=u. Then {F_t(Y_t)≤u} agrees up to null sets with {Y_t≤y_u}; its conditional probability is F_t(y_u)=u. Thus the conditional PIT is Uniform(0,1).`, String.raw`Điều kiện hóa theo quá khứ để F_t cố định. Do liên tục, chọn y_u với F_t(y_u)=u. Khi đó {F_t(Y_t)≤u} trùng {Y_t≤y_u} sai khác tập không, xác suất có điều kiện là F_t(y_u)=u. Vậy PIT có điều kiện Uniform(0,1).`)], [R(1,'Conditions on past information.','Điều kiện hóa quá khứ.'),R(2,'Uses continuity/quantile.','Dùng liên tục/quantile.'),R(1,'Computes conditional probability.','Tính xác suất có điều kiện.')], [B('Uses an unconditional CDF rather than the forecast CDF.', 'Dùng CDF vô điều kiện thay CDF dự báo.')]),
      E(B('Transfer: audit information time', 'Chuyển giao: kiểm toán thời điểm thông tin'), ['application','transfer'], B(String.raw`A model issues F_t after observing Y_t and evaluates it on that same Y_t. Give the violated measurability condition and a valid one-step protocol.`, String.raw`Mô hình phát F_t sau khi quan sát Y_t rồi đánh giá trên chính Y_t. Nêu điều kiện đo được bị vi phạm và quy trình một bước hợp lệ.`), [B('The forecast must be based on F_{t−1}, not F_t including Y_t.', 'Dự báo phải dựa trên F_{t−1}, không gồm Y_t.')], [B(String.raw`The forecast is not measurable with respect to pre-outcome information F_{t−1}; it can encode the answer and make scores meaningless. Freeze F_t using y_{1:t−1}, record it, reveal y_t and score, then update the model to produce F_{t+1}.`, String.raw`Dự báo không đo được theo thông tin trước outcome F_{t−1}; nó có thể mã hóa đáp án khiến score vô nghĩa. Đóng băng F_t từ y_{1:t−1}, ghi lại, lộ y_t để chấm rồi cập nhật mô hình tạo F_{t+1}.`)], [R(1,'Identifies the filtration breach.','Nhận diện vi phạm filtration.'),R(2,'Orders forecast, outcome and update.','Sắp đúng thứ tự dự báo, outcome, cập nhật.'),R(1,'Explains validity.','Giải thích tính hợp lệ.')], [B('Scores a smoothed forecast as though it were prequential.', 'Chấm dự báo đã làm trơn như thể tuần tự.')]),
      E(B('Counterexample: uniform PIT histogram with serial dependence', 'Phản ví dụ: histogram PIT đều nhưng phụ thuộc chuỗi'), ['counterexample','transfer'], B(String.raw`Let U_t alternate between a draw U and 1−U with U~Uniform(0,1). Each U_t is marginally uniform. Explain why a PIT histogram may pass while independence fails.`, String.raw`Cho U_t luân phiên giữa U và 1−U với U~Uniform(0,1). Mỗi U_t có biên đều. Giải thích vì sao histogram PIT có thể đạt nhưng độc lập thất bại.`), [B('Neighboring values are deterministically linked.', 'Giá trị kề nhau liên hệ xác định.')], [B(String.raw`Both U and 1−U are Uniform(0,1), so pooled PIT values have uniform marginals. But U_{t+1}=1−U_t exactly, giving perfect negative dependence (correlation −1). A histogram tests only the marginal law; inspect serial dependence and condition on regimes as separate diagnostics.`, String.raw`U và 1−U đều Uniform(0,1), nên PIT gộp có biên đều. Nhưng U_{t+1}=1−U_t chính xác, tạo phụ thuộc âm hoàn toàn (tương quan −1). Histogram chỉ kiểm tra luật biên; cần chẩn đoán phụ thuộc chuỗi và chế độ riêng.`)], [R(1,'Checks both marginal distributions.','Kiểm tra hai phân phối biên.'),R(2,'Shows deterministic temporal dependence.','Chỉ ra phụ thuộc thời gian xác định.'),R(1,'Names additional diagnostic.','Nêu chẩn đoán bổ sung.')], [B('Treats marginal uniformity as sequence independence.', 'Coi đều biên là độc lập chuỗi.')]),
    ],
  },
  {
    week: 83, title: B('Paired loss inference, effective information, and overlapping labels', 'Suy luận loss paired, thông tin hiệu dụng và nhãn chồng lấn'), level: 'graduate core', prerequisites: [73, 76, 77, 78, 82],
    outcomes: [B('Derive the variance of a paired stationary loss mean and identify its estimand.', 'Suy ra phương sai trung bình loss paired dừng và xác định estimand.'), B('Calculate overlap-induced covariance and separate forecast improvement from significance or economic value.', 'Tính covariance do chồng lấn và tách cải thiện dự báo khỏi ý nghĩa thống kê/giá trị kinh tế.')],
    definitions: B(String.raw`Let d_t=ℓ_{A,t}−ℓ_{B,t}; Δ=E[d_t] is the average paired loss difference under the target process. For weak stationarity, Var(d̄_n)=n^{-1}Σ_{|h|<n}(1−|h|/n)γ_d(h). If γ_d is absolutely summable, n Var(d̄_n)→Ω_d. Overlapping h-step targets can induce dependence even when one-step innovations are IID. Effective sample size is a model-based variance ratio, not a replacement for the dependence assumptions.`, String.raw`Đặt d_t=ℓ_{A,t}−ℓ_{B,t}; Δ=E[d_t] là chênh lệch loss paired trung bình theo quá trình mục tiêu. Với dừng yếu, Var(d̄_n)=n^{-1}Σ_{|h|<n}(1−|h|/n)γ_d(h). Nếu γ_d khả tổng tuyệt đối thì n Var(d̄_n)→Ω_d. Mục tiêu h bước chồng lấn có thể tạo phụ thuộc ngay cả khi innovation một bước IID. Cỡ mẫu hiệu dụng là tỷ số phương sai dựa trên mô hình, không thay giả thiết phụ thuộc.`),
    theoremTitle: B('Dependence-aware paired-mean limit', 'Giới hạn trung bình paired có xét phụ thuộc'),
    statement: B(String.raw`If d_t is centered strictly stationary α-mixing, E|d_0|^{2+δ}<∞, Σα(k)^{δ/(2+δ)}<∞ and Ω_d>0, then √n(d̄_n−Δ)⇒N(0,Ω_d); a valid standard error estimates Ω_d/n, not Var(d_t)/n unless serial covariances vanish.`, String.raw`Nếu d_t−Δ dừng nghiêm ngặt α-mixing, E|d_0−Δ|^{2+δ}<∞, Σα(k)^{δ/(2+δ)}<∞ và Ω_d>0 thì √n(d̄_n−Δ)⇒N(0,Ω_d); sai số chuẩn hợp lệ ước lượng Ω_d/n, không phải Var(d_t)/n trừ khi covariance chuỗi bằng 0.`),
    proofStatus: 'assumed', proof: B(String.raw`Apply the selected α-mixing CLT from W76 to z_t=d_t−Δ. Its hypotheses are restated, and the long-run variance is Ω_d=γ_d(0)+2Σ_{h≥1}γ_d(h). The finite-sample variance identity is derived in W73; it shows why the IID standard error drops terms. The CLT proof remains the explicitly cited black box rather than being implied by the paired design.`, String.raw`Áp dụng CLT α-mixing được chọn ở W76 cho z_t=d_t−Δ. Giả thiết được nêu lại, phương sai dài hạn Ω_d=γ_d(0)+2Σ_{h≥1}γ_d(h). Đẳng thức phương sai hữu hạn mẫu đã suy ra ở W73 cho thấy sai số chuẩn IID bỏ sót hạng nào. Chứng minh CLT vẫn là black box được dẫn rõ, không phải hệ quả của thiết kế paired.`), sourceId: 'o-cmu-mixing', section: 'Ch. 27, Theorem 396 applied to paired losses; MIT Lecture Notes 2–3 (HAC).',
    workedExample: B(String.raw`For iid zero-mean innovations ε_t with variance σ², define h-step overlapping sums R_t=Σ_{j=1}^h ε_{t+j}. Then Var(R_t)=hσ² and Cov(R_t,R_{t+k})=(h−k)σ² for 0≤k<h, zero for k≥h. The variance inflation for the sample mean is 1+2Σ_{k=1}^{h−1}(h−k)/h=h, so n observations carry about n/h IID-equivalent information for this target.`, String.raw`Với innovation iid ε_t kỳ vọng 0, phương sai σ², đặt tổng h bước chồng lấn R_t=Σ_{j=1}^h ε_{t+j}. Var(R_t)=hσ² và Cov(R_t,R_{t+k})=(h−k)σ² khi 0≤k<h, bằng 0 khi k≥h. Hệ số tăng phương sai trung bình là 1+2Σ_{k=1}^{h−1}(h−k)/h=h, nên n quan sát tương đương khoảng n/h thông tin IID cho mục tiêu này.`),
    failureCase: B(String.raw`A negative sample mean d̄ does not imply a statistically resolved advantage: its dependence-aware interval may include zero. Even a resolved lower forecast loss is not net return; costs, feasible execution timing, and a separate economic estimand are required. Comparing each method against its own unpaired sample discards covariance and can inflate or deflate uncertainty.`, String.raw`Trung bình mẫu d̄ âm không hàm ý lợi thế có ý nghĩa: khoảng phụ thuộc có thể chứa 0. Ngay cả loss dự báo thấp hơn có ý nghĩa cũng không phải return ròng; cần chi phí, thời điểm thực thi khả thi và estimand kinh tế riêng. So từng phương pháp trên mẫu không ghép làm mất covariance và có thể tăng/giảm bất định.`),
    topic: 'paired-loss estimands; long-run covariance; overlapping forecasts/labels; effective sample size', readingSection: 'MIT Lecture Notes 2–3, 9; CMU Ch. 27',
    exercises: [
      E(B('Overlapping h-step covariance', 'Covariance h bước chồng lấn'), ['derivation','computation'], B(String.raw`For R_t=ε_{t+1}+ε_{t+2}+ε_{t+3} with IID variance 2, compute Var(R_t), Cov(R_t,R_{t+1}), Cov(R_t,R_{t+2}), and the long-run variance.`, String.raw`Với R_t=ε_{t+1}+ε_{t+2}+ε_{t+3}, ε IID phương sai 2, tính Var(R_t), Cov(R_t,R_{t+1}), Cov(R_t,R_{t+2}) và phương sai dài hạn.`), [B('Count shared innovations at each offset.', 'Đếm innovation chung ở mỗi độ lệch.')], [B(String.raw`Var=3·2=6. Adjacent windows share two innovations, so γ(1)=4; lag two shares one, γ(2)=2; lag≥3 is zero. Ω=6+2(4+2)=18, an inflation factor 3 over the marginal variance.`, String.raw`Var=3·2=6. Cửa sổ kề chia sẻ hai innovation nên γ(1)=4; lag hai chia sẻ một nên γ(2)=2; lag≥3 bằng 0. Ω=6+2(4+2)=18, hệ số tăng 3 so với phương sai biên.`)], [R(1,'Counts three innovation terms.','Đếm ba hạng innovation.'),R(2,'Counts overlap at both lags.','Đếm chồng lấn hai lag.'),R(1,'Computes Ω and factor.','Tính Ω và hệ số.')], [B('Counts covariance once instead of both lag signs.', 'Chỉ tính covariance một lần thay vì hai dấu lag.')]),
      E(B('Derive the paired mean variance', 'Suy ra phương sai trung bình paired'), ['proof'], B(String.raw`Starting from d̄_n=n^{-1}Σd_t, derive Var(d̄_n)=n^{-1}Σ_{|h|<n}(1−|h|/n)γ_d(h), and identify the IID special case.`, String.raw`Từ d̄_n=n^{-1}Σd_t, suy ra Var(d̄_n)=n^{-1}Σ_{|h|<n}(1−|h|/n)γ_d(h), rồi nêu trường hợp IID.`), [B('Expand the double sum and count n−|h| pairs.', 'Khai triển tổng kép và đếm n−|h| cặp.')], [B(String.raw`Var(d̄_n)=n^{-2}Σ_{s,t}Cov(d_s,d_t)=n^{-2}Σ_{|h|<n}(n−|h|)γ_d(h). Factor n^{-1} to obtain the formula. Under IID, only γ_d(0) remains, giving Var(d_t)/n.`, String.raw`Var(d̄_n)=n^{-2}Σ_{s,t}Cov(d_s,d_t)=n^{-2}Σ_{|h|<n}(n−|h|)γ_d(h). Tách n^{-1} được công thức. Dưới IID, chỉ còn γ_d(0), cho Var(d_t)/n.`)], [R(1,'Expands covariance of sum.','Khai triển covariance tổng.'),R(2,'Counts pairs by lag.','Đếm cặp theo lag.'),R(1,'Identifies IID reduction.','Nhận diện rút gọn IID.')], [B('Assumes pairing cancels all serial covariance.', 'Giả sử ghép cặp xóa mọi covariance chuỗi.')]),
      E(B('Paired contrast with uncertainty target', 'Chênh paired và mục tiêu bất định'), ['computation','application'], B(String.raw`At 5 origins, d=[−2,1,−1,0,−3]. Compute d̄ and state what additional quantity is required for a dependence-aware interval.`, String.raw`Tại 5 origin, d=[−2,1,−1,0,−3]. Tính d̄ và nêu đại lượng cần thêm để lập khoảng có xét phụ thuộc.`), [B('Sum the paired differences, then divide by five.', 'Cộng chênh paired rồi chia năm.')], [B(String.raw`The sum is −5, so d̄=−1. A dependence-aware interval needs an estimate of the long-run variance Ω_d (for example HAC with bandwidth/mixing justification) and an appropriate reference approximation; five points alone do not identify a reliable asymptotic interval.`, String.raw`Tổng bằng −5 nên d̄=−1. Khoảng có xét phụ thuộc cần ước lượng phương sai dài hạn Ω_d (ví dụ HAC với bandwidth/giả thiết mixing có biện minh) và xấp xỉ tham chiếu phù hợp; năm điểm không đủ tự xác định khoảng tiệm cận đáng tin.`)], [R(1,'Computes paired mean.','Tính mean paired.'),R(2,'Names long-run variance estimate.','Nêu ước lượng phương sai dài hạn.'),R(1,'States small-sample limitation.','Nêu hạn chế mẫu nhỏ.')], [B('Reports a p-value without an uncertainty estimator.', 'Báo p-value không có ước lượng bất định.')]),
      E(B('Transfer: separate statistical and economic targets', 'Chuyển giao: tách mục tiêu thống kê và kinh tế'), ['derivation','transfer'], B(String.raw`A model lowers paired mean squared error by .02 with a 95% HAC interval [−.04,.00] for d=loss_new−loss_base. State the statistical conclusion and two missing elements for a trading-profit claim.`, String.raw`Mô hình giảm MSE paired .02 nhưng khoảng HAC 95% cho d=loss_new−loss_base là [−.04,.00]. Nêu kết luận thống kê và hai thành phần còn thiếu cho khẳng định lợi nhuận giao dịch.`), [B('The interval touches zero; keep the claim about forecast loss and its uncertainty.', 'Khoảng chạm 0; chỉ nêu claim loss dự báo cùng bất định.')], [B(String.raw`The estimate favors the new model but the stated interval touches zero, so evidence does not resolve a strictly negative population loss difference at that level. Trading profit additionally requires executable position timing/price and transaction costs (and a return-risk estimand); forecast MSE is not a portfolio payoff.`, String.raw`Ước lượng nghiêng về mô hình mới nhưng khoảng chạm 0 nên bằng chứng chưa xác nhận chênh lệch population âm nghiêm ngặt ở mức đó. Lợi nhuận giao dịch còn cần thời điểm/giá khớp khả thi và chi phí giao dịch (cùng estimand return-risk); MSE dự báo không phải payoff danh mục.`)], [R(1,'Interprets interval endpoint.','Diễn giải đầu mút khoảng.'),R(2,'Separates predictive target from economic target.','Tách mục tiêu dự báo khỏi mục tiêu kinh tế.'),R(1,'Names missing execution/cost assumptions.','Nêu giả thiết khớp lệnh/chi phí thiếu.')], [B('Calls touching zero proof of equality.', 'Coi khoảng chạm 0 là chứng minh bằng nhau.')]),
      E(B('Counterexample: equal forecast signs, different effective information', 'Phản ví dụ: cùng số dự báo nhưng thông tin hiệu dụng khác'), ['counterexample','transfer'], B(String.raw`Compare n=120 IID loss differences with n=120 overlapping 12-step sums of IID innovations. Use the overlap result to compare approximate IID-equivalent sample sizes and explain why both datasets do not supply 120 independent labels.`, String.raw`So sánh n=120 chênh loss IID với n=120 tổng chồng lấn 12 bước của innovation IID. Dùng kết quả overlap so sánh cỡ mẫu IID tương đương và giải thích vì sao hai bộ không cùng có 120 nhãn độc lập.`), [B('For a width-h moving sum, LRV inflation equals h.', 'Với tổng trượt rộng h, hệ số tăng LRV bằng h.')], [B(String.raw`The IID series has n_eff=120 under its stated model. For h=12 overlapping sums, long-run variance is 12 times marginal variance, so n_eff≈n/12=10 for the sample mean. This is an AR/overlap model-based approximation, not a universal count; dependence-aware uncertainty is required.`, String.raw`Chuỗi IID có n_eff=120 theo mô hình nêu. Với tổng chồng lấn h=12, phương sai dài hạn gấp 12 phương sai biên, nên n_eff≈n/12=10 cho trung bình. Đây là xấp xỉ dựa mô hình overlap, không phải số lượng phổ quát; cần bất định có xét phụ thuộc.`)], [R(1,'States IID baseline.','Nêu chuẩn IID.'),R(2,'Computes effective-size ratio.','Tính tỷ lệ cỡ mẫu hiệu dụng.'),R(1,'Limits interpretation.','Giới hạn diễn giải.')], [B('Uses the raw count n as effective n for overlapping targets.', 'Dùng số đếm n làm n hiệu dụng cho mục tiêu chồng lấn.')]),
    ],
  },
];
const weeks: MathWeek[] = [...laterWeeks.map(makeWeek), ...earlyWeeks.map(makeWeek)];
weeks.sort((a, b) => a.week - b.week);
const deepenExercise = (weekNumber: number, exerciseNumber: number, prompt: Bilingual, hint: Bilingual, solution: Bilingual, checks: Bilingual[], commonError: Bilingual) => {
  const week = weeks.find((candidate) => candidate.week === weekNumber)!;
  const item = week.exercises[exerciseNumber - 1];
  item.prompt = prompt;
  item.hints = [hint];
  item.solution = [solution];
  item.rubric = checks.map((criterion, i) => R(1, criterion.en, criterion.vi, i === 0));
  item.commonErrors = [commonError];
};

// W72 default assessment path: make the numerical failure a genuine transfer problem.
deepenExercise(72, 3,
  B(String.raw`Let A=diag(1,10⁻⁵), x*=(1,1), b=Ax*, and b̃=b+(0,10⁻⁸). Derive κ₂(A), κ₂(AᵀA), and the least-squares solution under b̃. Quantify the relative data and solution perturbations, explain why normal equations are risky, and justify a QR/SVD solution plus a scaled residual check.`, String.raw`Cho A=diag(1,10⁻⁵), x*=(1,1), b=Ax*, b̃=b+(0,10⁻⁸). Suy κ₂(A), κ₂(AᵀA) và nghiệm bình phương tối thiểu với b̃. Định lượng nhiễu tương đối của dữ liệu và nghiệm, giải thích rủi ro phương trình chuẩn, rồi biện minh QR/SVD cùng kiểm residual đã co giãn.`),
  B(String.raw`Compute each coordinate of A⁻¹b̃; compare relative perturbations, then recall κ₂(AᵀA)=κ₂(A)².`, String.raw`Tính từng tọa độ A⁻¹b̃; so nhiễu tương đối rồi dùng κ₂(AᵀA)=κ₂(A)².`),
  B(String.raw`The singular values are 1 and 10⁻⁵, so κ₂(A)=10⁵ and κ₂(AᵀA)=10¹⁰. Here b=(1,10⁻⁵), b̃=(1,1.001·10⁻⁵), and x̃=A⁻¹b̃=(1,1.001). Thus ||b̃−b||₂/||b||₂≈10⁻⁸ while ||x̃−x*||₂/||x*||₂≈7.07·10⁻⁴, consistent with amplification on the order of κ(A). Forming AᵀA squares conditioning and can lose small singular directions in finite precision. QR or SVD works on A without explicitly squaring its condition number; report ||A x̃−b̃||₂/(||A||₂||x̃||₂+||b̃||₂) and the singular-value/rank diagnostic. Conditioning explains the real forward sensitivity; a stable algorithm cannot remove it.`, String.raw`Trị kỳ dị là 1 và 10⁻⁵ nên κ₂(A)=10⁵, κ₂(AᵀA)=10¹⁰. Ta có b=(1,10⁻⁵), b̃=(1,1.001·10⁻⁵), x̃=A⁻¹b̃=(1,1.001). Vì vậy ||b̃−b||₂/||b||₂≈10⁻⁸ trong khi ||x̃−x*||₂/||x*||₂≈7.07·10⁻⁴, phù hợp hệ số khuếch đại cỡ κ(A). Lập AᵀA bình phương số điều kiện và có thể làm mất hướng kỳ dị nhỏ ở độ chính xác hữu hạn. QR hoặc SVD làm trực tiếp trên A, không bình phương tường minh số điều kiện; báo ||A x̃−b̃||₂/(||A||₂||x̃||₂+||b̃||₂) và chẩn đoán trị kỳ dị/hạng. Kém điều kiện giải thích độ nhạy tiến thực; thuật toán ổn định không thể xóa nó.`),
  [B('Computes both singular-value condition numbers, including the square.', 'Tính đúng hai số điều kiện từ trị kỳ dị, gồm phép bình phương.'), B('Solves the perturbed system and quantifies both relative perturbations.', 'Giải hệ nhiễu và định lượng cả hai nhiễu tương đối.'), B('Explains normal-equation loss and QR/SVD stability.', 'Giải thích mất ổn định phương trình chuẩn và QR/SVD.'), B('Reports a scaled residual and separates sensitivity from algorithmic instability.', 'Báo residual co giãn và tách độ nhạy khỏi bất ổn thuật toán.')],
  B('Claims QR removes the intrinsic forward sensitivity caused by κ(A).', 'Cho rằng QR loại được độ nhạy tiến vốn có do κ(A).'));

// W85: finite-class bounds and the approximation/estimation/optimization ledger.
deepenExercise(85, 1,
  B(String.raw`Given R*=.10, inf_F R=.16, R(f̂)=.21 and R(f̃)=.24, calculate the approximation, estimation and returned-iterate excess. Then verify their sum equals R(f̃)−R*.`, String.raw`Cho R*=.10, inf_F R=.16, R(f̂)=.21, R(f̃)=.24; tính lỗi xấp xỉ, ước lượng và excess của iterate trả về, rồi kiểm tổng bằng R(f̃)−R*.`),
  B(String.raw`Subtract adjacent risks in the order R*→inf_F R→R(f̂)→R(f̃).`, String.raw`Lấy hiệu hai risk kề nhau theo thứ tự R*→inf_F R→R(f̂)→R(f̃).`),
  B(String.raw`Approximation is .16−.10=.06; estimation is .21−.16=.05; optimization/return is .24−.21=.03. The total is .06+.05+.03=.14=.24−.10. These are distinct definitions: only the last is the excess of the returned point over the empirical ERM here, and a nonexact optimizer should be measured by an explicit objective gap.`, String.raw`Lỗi xấp xỉ là .16−.10=.06; ước lượng là .21−.16=.05; tối ưu/đầu ra là .24−.21=.03. Tổng .06+.05+.03=.14=.24−.10. Đây là ba định nghĩa riêng: chỉ hạng cuối là excess của điểm trả về so với ERM thực nghiệm ở đây; nghiệm không chính xác nên đo bằng gap objective tường minh.`),
  [B('Defines each adjacent risk difference correctly.', 'Định nghĩa đúng từng hiệu risk liền kề.'), B('Computes the approximation gap.', 'Tính đúng gap xấp xỉ.'), B('Computes the estimation and optimization gaps.', 'Tính đúng gap ước lượng và tối ưu.'), B('Checks the telescoping total.', 'Kiểm tra tổng triệt tiêu.')],
  B('Uses best-in-class risk as the population optimum.', 'Coi risk tốt nhất trong lớp là tối ưu tổng thể.'));
deepenExercise(85, 2,
  B(String.raw`Assume |F|=M<∞, Z_i IID and 0≤ℓ≤1. Starting from fixed-f two-sided Hoeffding, derive P(sup_F|R̂−R|>ε) and solve for a radius ε that makes this probability at most δ.`, String.raw`Giả sử |F|=M<∞, Z_i IID, 0≤ℓ≤1. Từ Hoeffding hai phía với f cố định, suy P(sup_F|R̂−R|>ε) rồi giải bán kính ε để xác suất không quá δ.`),
  B(String.raw`Apply the fixed-f inequality first; only then take a union bound over the finite class.`, String.raw`Trước hết dùng bất đẳng thức cho f cố định; sau đó mới lấy union bound trên lớp hữu hạn.`),
  B(String.raw`For each f, Hoeffding gives P(|R̂(f)−R(f)|>ε)≤2e^(−2nε²). A union bound yields P(sup_F|R̂−R|>ε)≤2M e^(−2nε²). Requiring 2M e^(−2nε²)≤δ is equivalent to ε²≥log(2M/δ)/(2n); hence ε=√[log(2M/δ)/(2n)] suffices. This is a uniform high-probability radius, not a pointwise interval selected after seeing the winner.`, String.raw`Với mỗi f, Hoeffding cho P(|R̂(f)−R(f)|>ε)≤2e^(−2nε²). Union bound cho P(sup_F|R̂−R|>ε)≤2M e^(−2nε²). Điều kiện 2M e^(−2nε²)≤δ tương đương ε²≥log(2M/δ)/(2n), nên ε=√[log(2M/δ)/(2n)] là đủ. Đây là bán kính xác suất cao đồng đều, không phải khoảng điểm được chọn sau khi xem mô hình thắng.`),
  [B('States the fixed-f two-sided tail bound.', 'Nêu cận đuôi hai phía với f cố định.'), B('Uses a union bound with M terms.', 'Dùng union bound có M hạng.'), B('Solves the logarithmic inequality for ε.', 'Giải bất đẳng thức log để tìm ε.'), B('States the uniform, high-probability interpretation.', 'Nêu đúng diễn giải đồng đều, xác suất cao.')],
  B('Omits the factor 2 or treats the selected model as fixed.', 'Bỏ hệ số 2 hoặc coi mô hình được chọn là cố định.'));
deepenExercise(85, 3,
  B(String.raw`For finite F, let f̂ minimize R̂ and let f̃ satisfy R̂(f̃)≤min_F R̂+ε_opt. On the event sup_F|R̂−R|≤ε, prove R(f̃)−min_F R≤2ε+ε_opt by inserting empirical risks and labeling the ERM inequality.`, String.raw`Với F hữu hạn, f̂ tối thiểu R̂ và f̃ thỏa R̂(f̃)≤min_F R̂+ε_opt. Trên biến cố sup_F|R̂−R|≤ε, chứng minh R(f̃)−min_F R≤2ε+ε_opt bằng cách chèn risk thực nghiệm và ghi rõ bất đẳng thức ERM.`),
  B(String.raw`Insert R̂(f̃), R̂(f̂) and R̂(f*_F); the approximate optimization gap is the middle empirical difference.`, String.raw`Chèn R̂(f̃), R̂(f̂), R̂(f*_F); gap tối ưu gần đúng là hiệu thực nghiệm ở giữa.`),
  B(String.raw`Choose f*_F∈argmin_F R, which exists because F is finite. Then R(f̃)−R(f*_F)=[R(f̃)−R̂(f̃)]+[R̂(f̃)−R̂(f̂)]+[R̂(f̂)−R̂(f*_F)]+[R̂(f*_F)−R(f*_F)]. The four terms are at most ε, ε_opt, 0 (ERM), and ε, respectively. Thus excess≤2ε+ε_opt. The optimization allowance is empirical; no claim is made that population risk of f̃ exceeds that of f̂.`, String.raw`Chọn f*_F∈argmin_F R, tồn tại vì F hữu hạn. Khi đó R(f̃)−R(f*_F)=[R(f̃)−R̂(f̃)]+[R̂(f̃)−R̂(f̂)]+[R̂(f̂)−R̂(f*_F)]+[R̂(f*_F)−R(f*_F)]. Bốn hạng lần lượt không quá ε, ε_opt, 0 (ERM), ε. Vậy excess≤2ε+ε_opt. Dung sai tối ưu là thực nghiệm; không khẳng định risk tổng thể của f̃ lớn hơn risk của f̂.`),
  [B('Inserts all four empirical/population differences.', 'Chèn đủ bốn hiệu empirical/population.'), B('Uses both uniform-deviation bounds.', 'Dùng cả hai cận lệch đều.'), B('Uses the approximate empirical-optimality condition.', 'Dùng điều kiện tối ưu thực nghiệm gần đúng.'), B('Identifies existence and scope of the minimizer.', 'Nêu sự tồn tại và phạm vi nghiệm tối ưu.')],
  B('Calls R(f̃)−R(f̂) a necessarily nonnegative optimization gap.', 'Gọi R(f̃)−R(f̂) là gap tối ưu luôn không âm.'));
deepenExercise(85, 4,
  B(String.raw`At n=1000 and δ=.05 compare ε(M)=√[log(2M/δ)/(2n)] for M=20 and M=2²⁰. Compute both radii and their ratio; explain why the larger class pays for searching more candidates.`, String.raw`Với n=1000, δ=.05, so ε(M)=√[log(2M/δ)/(2n)] khi M=20 và M=2²⁰. Tính hai bán kính và tỷ số; giải thích vì sao lớp lớn trả giá cho việc tìm nhiều ứng viên.`),
  B(String.raw`Keep δ inside both logarithms; use the same n and δ for both classes.`, String.raw`Giữ δ trong cả hai log; dùng cùng n và δ cho hai lớp.`),
  B(String.raw`ε(20)=√[log(800)/2000]≈.0578. For M=2²⁰, ε≈√[log(41,943,040)/2000]≈.0937. The ratio is √[log(2·2²⁰/.05)/log(2·20/.05)]≈1.62. The uniform bound controls every candidate considered, so an expanded data-dependent search incurs a larger complexity term; it does not say the actual selected model must generalize worse.`, String.raw`ε(20)=√[log(800)/2000]≈.0578. Với M=2²⁰, ε≈√[log(41,943,040)/2000]≈.0937. Tỷ số √[log(2·2²⁰/.05)/log(2·20/.05)]≈1.62. Cận đều khống chế mọi ứng viên được xét nên tìm kiếm phụ thuộc dữ liệu rộng hơn chịu hạng độ phức tạp lớn hơn; điều này không nói mô hình được chọn chắc chắn tổng quát hóa tệ hơn.`),
  [B('Uses the same confidence level in both logarithms.', 'Dùng cùng mức tin cậy trong hai log.'), B('Computes the small-class radius.', 'Tính bán kính lớp nhỏ.'), B('Computes the large-class radius.', 'Tính bán kính lớp lớn.'), B('Interprets multiplicity as a bound cost, not a deterministic outcome.', 'Diễn giải bội số là chi phí cận, không phải kết quả chắc chắn.')],
  B('Drops δ and compares only √log M.', 'Bỏ δ và chỉ so √log M.'));
deepenExercise(85, 5,
  B(String.raw`A 20-day return label is attached to each of 1000 adjacent origins. Identify the exact IID step that fails, explain why replacing n by an informal effective sample size does not restore the theorem, and give two defensible alternatives with their estimands/assumptions.`, String.raw`Nhãn lợi suất 20 ngày gắn với 1000 mốc kề nhau. Chỉ ra chính xác bước IID nào thất bại, giải thích vì sao thay n bằng cỡ mẫu hiệu dụng tùy ý không khôi phục định lý, và nêu hai lựa chọn hợp lệ cùng estimand/giả thiết.`),
  B(String.raw`Adjacent labels share 19 daily returns; locate where factorization or independent Hoeffding summands are used.`, String.raw`Nhãn kề nhau chia sẻ 19 return ngày; tìm chỗ cần phân tích nhân tử hoặc tổng hạng Hoeffding độc lập.`),
  B(String.raw`Adjacent 20-day windows share 19 observations, so the empirical terms are dependent and the product-MGF step behind IID Hoeffding is invalid. A justified non-overlap/gap design can recover independent blocks only if the underlying daily blocks are themselves independent; its estimand is performance on that coarser origin schedule. Alternatively, retain all origins and prove a uniform concentration result for a stated mixing/dependence class with its rate and complexity assumptions. An informal n_eff substitution proves neither tail validity nor a uniform bound over the searched F.`, String.raw`Hai cửa sổ 20 ngày kề nhau chia sẻ 19 quan sát nên các hạng thực nghiệm phụ thuộc, bước tích MGF của Hoeffding IID không hợp lệ. Thiết kế không chồng lấn/có khoảng cách được biện minh có thể khôi phục block độc lập nếu các block ngày nền thực sự độc lập; estimand là hiệu năng trên lịch mốc thưa hơn. Hoặc giữ mọi mốc và chứng minh cận concentration đồng đều cho lớp phụ thuộc/mixing đã nêu cùng tốc độ và giả thiết độ phức tạp. Thay n bằng n_eff tùy tiện không chứng minh cận đuôi hay cận đều trên F đã tìm.`),
  [B('Identifies shared observations and the failed independence step.', 'Nhận diện quan sát chung và bước độc lập thất bại.'), B('Qualifies when gaps yield independent blocks.', 'Nêu điều kiện để khoảng cách cho block độc lập.'), B('States the altered estimand for thinning.', 'Nêu estimand đổi khi lấy mốc thưa.'), B('Specifies dependence assumptions for the alternative.', 'Nêu giả thiết phụ thuộc cho lựa chọn khác.')],
  B('Treats an estimated n_eff as a proof of IID Hoeffding.', 'Coi n_eff ước lượng là chứng minh Hoeffding IID.'));

// W86: show both symmetrization steps and correct the four-sign enumeration.
deepenExercise(86, 1,
  B(String.raw`Let S=(Z₁,…,Zₙ) and S′ be an independent IID ghost sample. For a measurable/separable class F, condition on S and prove E sup_f|P_nf−Pf|≤E sup_f|P_nf−P′_nf|.`, String.raw`Cho S=(Z₁,…,Zₙ), S′ là mẫu phụ IID độc lập. Với lớp F đo được/tách được, điều kiện hóa theo S và chứng minh E sup_f|P_nf−Pf|≤E sup_f|P_nf−P′_nf|.`),
  B(String.raw`Use Pf=E[P′_nf|S], then apply conditional Jensen to absolute value before taking the supremum.`, String.raw`Dùng Pf=E[P′_nf|S], rồi Jensen có điều kiện cho trị tuyệt đối trước khi lấy supremum.`),
  B(String.raw`For each f, P_nf−Pf=E[P_nf−P′_nf|S]. Conditional Jensen gives |P_nf−Pf|≤E[|P_nf−P′_nf||S]. Since the same conditional expectation dominates each f, take sup_f and then expectation to obtain the inequality. The separability/measurability assumption justifies exchanging supremum and expectation; without it, outer expectation or a measurable subclass is needed.`, String.raw`Với mỗi f, P_nf−Pf=E[P_nf−P′_nf|S]. Jensen có điều kiện cho |P_nf−Pf|≤E[|P_nf−P′_nf||S]. Vì cùng một kỳ vọng có điều kiện chặn từng f, lấy sup_f rồi kỳ vọng được bất đẳng thức. Giả thiết tách/đo được biện minh việc đổi supremum và kỳ vọng; nếu thiếu cần outer expectation hoặc lớp con đo được.`),
  [B('Writes the ghost conditional expectation identity.', 'Viết đẳng thức kỳ vọng có điều kiện của mẫu phụ.'), B('Applies conditional Jensen to absolute deviation.', 'Áp Jensen có điều kiện cho độ lệch tuyệt đối.'), B('Takes the supremum under the common conditional bound.', 'Lấy supremum dưới cận có điều kiện chung.'), B('States the measurability/separability role.', 'Nêu vai trò đo được/tách được.')],
  B('Uses a pointwise expectation identity without justifying the supremum.', 'Dùng đẳng thức kỳ vọng từng điểm mà không biện minh supremum.'));
deepenExercise(86, 2,
  B(String.raw`Starting from the ghost-sample difference, prove the Rademacher-sign inequality E sup_f|P_nf−P′_nf|≤2E sup_f|n⁻¹Σ_iσ_if(Z_i)|. State why the signs may be inserted.`, String.raw`Từ hiệu mẫu phụ, chứng minh E sup_f|P_nf−P′_nf|≤2E sup_f|n⁻¹Σ_iσ_if(Z_i)|. Nêu vì sao có thể thêm dấu Rademacher.`),
  B(String.raw`Independently swap Z_i and Z′_i; each pair is exchangeable, so its difference changes sign without changing its law.`, String.raw`Đổi độc lập Z_i và Z′_i; mỗi cặp hoán đổi được nên hiệu đổi dấu mà luật không đổi.`),
  B(String.raw`For independent Rademacher σ_i, exchangeability gives equality in distribution between Σ(f(Z_i)−f(Z′_i)) and Σσ_i(f(Z_i)−f(Z′_i)), jointly for all f. Then sup_f|A_f−B_f|≤sup_f|A_f|+sup_f|B_f|. Taking expectations, the two terms have the same law, each equal to E sup_f|n⁻¹Σσ_if(Z_i)|. This yields the factor 2. Absolute suprema are retained throughout, matching the W87 complexity convention.`, String.raw`Với σ_i Rademacher độc lập, tính hoán đổi cho hai tổng có cùng luật, đồng thời cho mọi f: Σ(f(Z_i)−f(Z′_i)) và Σσ_i(f(Z_i)−f(Z′_i)). Ta có sup_f|A_f−B_f|≤sup_f|A_f|+sup_f|B_f|. Lấy kỳ vọng, hai hạng cùng luật và mỗi hạng bằng E sup_f|n⁻¹Σσ_if(Z_i)|. Thu được hệ số 2. Giữ supremum trị tuyệt đối xuyên suốt, khớp quy ước W87.`),
  [B('Uses pairwise exchangeability for independent sign flips.', 'Dùng tính hoán đổi từng cặp cho dấu độc lập.'), B('Applies the triangle inequality to the two sample sums.', 'Áp bất đẳng thức tam giác cho hai tổng mẫu.'), B('Uses identical laws to obtain the factor 2.', 'Dùng cùng luật để ra hệ số 2.'), B('Retains absolute supremum and matches the W87 definition.', 'Giữ supremum tuyệt đối và khớp định nghĩa W87.')],
  B('Inserts signs without exchangeability or drops absolute values.', 'Thêm dấu không dựa hoán đổi hoặc bỏ trị tuyệt đối.'));
deepenExercise(86, 3,
  B(String.raw`For n=4 and F={0,(1,1,1,1)}, compute E_σ max(0,Σ_iσ_i) and the empirical Rademacher complexity. Enumerate the possible sign sums with their probabilities.`, String.raw`Với n=4, F={0,(1,1,1,1)}, tính E_σ max(0,Σ_iσ_i) và độ phức tạp Rademacher thực nghiệm. Liệt kê tổng dấu có thể cùng xác suất.`),
  B(String.raw`The sum is 4,2,0,−2,−4 with probabilities 1,4,6,4,1 over 16; only positive sums contribute.`, String.raw`Tổng là 4,2,0,−2,−4 với xác suất 1,4,6,4,1 trên 16; chỉ tổng dương đóng góp.`),
  B(String.raw`The supremum is max(0,S), S=Σσ_i. Its expectation is [4·1+2·4]/16=12/16=.75. By definition the empirical complexity divides by n=4, giving .75/4=3/16=.1875. The zero function makes the supremum nonnegative; omitting the all-negative outcomes from the denominator would be an enumeration error.`, String.raw`Supremum là max(0,S), S=Σσ_i. Kỳ vọng [4·1+2·4]/16=12/16=.75. Theo định nghĩa, độ phức tạp thực nghiệm chia cho n=4, cho .75/4=3/16=.1875. Hàm zero làm supremum không âm; bỏ các trường hợp âm khỏi mẫu số là sai khi liệt kê.`),
  [B('Lists all five sign sums.', 'Liệt kê đủ năm tổng dấu.'), B('Uses correct binomial multiplicities.', 'Dùng đúng hệ số nhị thức.'), B('Computes the positive-part expectation .75.', 'Tính kỳ vọng phần dương .75.'), B('Divides by n to obtain 3/16.', 'Chia n để được 3/16.')],
  B('Reports 1/4 by miscounting the positive-part expectation.', 'Báo 1/4 do đếm sai kỳ vọng phần dương.'));
deepenExercise(86, 4,
  B(String.raw`Pointwise convergence holds for each fixed θ∈[0,1] on an expanding grid Θ_n chosen after observing data. Explain why the fixed-θ law of large numbers does not justify the selected θ̂_n, and state a valid uniform or sieve route.`, String.raw`Hội tụ từng điểm đúng với mỗi θ cố định trên lưới Θ_n mở rộng được chọn sau khi xem dữ liệu. Giải thích vì sao luật số lớn điểm-cố định không biện minh θ̂_n đã chọn, rồi nêu cách đồng đều hoặc sieve hợp lệ.`),
  B(String.raw`A data-dependent index can target whichever coordinate has the largest noise; control the supremum over all candidates.`, String.raw`Chỉ số phụ thuộc dữ liệu có thể chọn tọa độ nhiễu lớn nhất; cần khống chế supremum trên mọi ứng viên.`),
  B(String.raw`Pointwise convergence fixes θ before sampling, whereas θ̂_n is selected using the same fluctuations, so no single fixed-θ statement controls its error. A valid route is a uniform law over each Θ_n with complexity/concentration term tending to zero; another is a sieve Θ_n with uniform stochastic control on the sieve plus a separate approximation-bias argument for the target. Sample splitting can also select on one sample and evaluate independently, but changes the analysis and may reduce data efficiency.`, String.raw`Hội tụ điểm-cố định chốt θ trước lấy mẫu, còn θ̂_n chọn từ chính dao động đó nên không phát biểu nào ở θ cố định chặn được lỗi đã chọn. Cách hợp lệ là luật đều trên từng Θ_n với hạng độ phức tạp/concentration tiến về 0; hoặc sieve Θ_n có khống chế ngẫu nhiên đều cộng lập luận bias xấp xỉ riêng cho target. Tách mẫu cũng có thể chọn trên mẫu này và đánh giá độc lập trên mẫu kia, nhưng đổi phân tích và có thể giảm hiệu quả dữ liệu.`),
  [B('Distinguishes fixed from data-selected parameters.', 'Phân biệt tham số cố định và tham số chọn theo dữ liệu.'), B('Names a uniform complexity-controlled route.', 'Nêu cách đều có kiểm soát độ phức tạp.'), B('Separates sieve approximation from stochastic error.', 'Tách xấp xỉ sieve khỏi lỗi ngẫu nhiên.'), B('States a valid alternative and its tradeoff.', 'Nêu lựa chọn hợp lệ và đánh đổi.')],
  B('Applies a fixed-θ law after selecting θ on the same observations.', 'Áp luật θ cố định sau khi chọn θ trên cùng dữ liệu.'));
deepenExercise(86, 5,
  B(String.raw`Let X_i be IID from a nonatomic distribution on [0,1], and let Y_i be IID Bernoulli(1/2), independent of all inputs. Construct a sample-memorizing learner with zero training error and fresh-example 0–1 error 1/2. Explain why a fresh independent X is almost surely outside the finite training set.`, String.raw`Cho X_i IID theo phân phối không nguyên tử trên [0,1], Y_i IID Bernoulli(1/2), độc lập với mọi input. Dựng bộ học ghi nhớ mẫu có lỗi huấn luyện 0 và lỗi 0–1 trên mẫu mới 1/2. Giải thích vì sao X độc lập mới hầu như chắc chắn ngoài tập huấn luyện hữu hạn.`),
  B(String.raw`Memorize f_S(X_i)=Y_i and predict 0 elsewhere. Nonatomicity gives P(X_new=X_i)=0 for each i; a finite union still has probability zero.`, String.raw`Ghi nhớ f_S(X_i)=Y_i và dự báo 0 nơi khác. Tính không nguyên tử cho P(X_mới=X_i)=0 với từng i; hợp hữu hạn vẫn có xác suất 0.`),
  B(String.raw`Define f_S(x)=Y_i if x=X_i for a training index i (ties have probability zero, and may be resolved by the smallest index), and f_S(x)=0 otherwise. Empirical 0–1 risk is exactly zero. For an independent fresh X with the same nonatomic law, P(X∈{X_1,…,X_n}|S)=0 by a finite union bound; hence f_S(X)=0 almost surely. Since fresh Y is independent Bernoulli(1/2), the fresh error probability is 1/2. The construction shows that zero training error alone lacks uniform capacity or stability control.`, String.raw`Đặt f_S(x)=Y_i nếu x=X_i với một chỉ số huấn luyện i (trùng điểm có xác suất 0, có thể chọn chỉ số nhỏ nhất), và f_S(x)=0 nơi khác. Risk 0–1 thực nghiệm đúng bằng 0. Với X mới độc lập cùng phân phối không nguyên tử, P(X∈{X_1,…,X_n}|S)=0 theo hợp hữu hạn; do đó f_S(X)=0 hầu như chắc chắn. Vì Y mới độc lập Bernoulli(1/2), xác suất lỗi mới là 1/2. Cấu tạo cho thấy lỗi huấn luyện bằng 0 không tự có khống chế capacity đều hay ổn định.`),
  [B('States nonatomic IID inputs and independent fair labels.', 'Nêu input IID không nguyên tử và nhãn công bằng độc lập.'), B('Defines a predictor with zero empirical error.', 'Định nghĩa predictor có lỗi thực nghiệm bằng 0.'), B('Uses finite-union probability zero for a fresh input.', 'Dùng xác suất hợp hữu hạn bằng 0 cho input mới.'), B('Computes fresh error 1/2 and names the missing control.', 'Tính lỗi mới 1/2 và nêu kiểm soát thiếu.')],
  B('Assumes fresh inputs differ without stating nonatomicity or input-label independence.', 'Giả sử input mới khác mà không nêu tính không nguyên tử hoặc độc lập input-nhãn.'));

// W87: absolute-complexity theorem, linear class, contraction, and excess-risk accounting.
deepenExercise(87, 1,
  B(String.raw`For F_B={x↦wᵀx:||w||₂≤B}, with fixed sample ||x_i||₂≤R, derive R̂_abs(F_B)≤BR/√n. Show where the dual norm and sign second moment enter.`, String.raw`Với F_B={x↦wᵀx:||w||₂≤B}, mẫu cố định ||x_i||₂≤R, suy R̂_abs(F_B)≤BR/√n. Chỉ rõ nơi dùng chuẩn đối ngẫu và moment bậc hai của dấu.`),
  B(String.raw`Move the supremum through wᵀΣσ_ix_i, then apply Cauchy–Schwarz to the expectation.`, String.raw`Đưa supremum qua wᵀΣσ_ix_i, rồi dùng Cauchy–Schwarz cho kỳ vọng.`),
  B(String.raw`R̂_abs=(1/n)E_σ sup_{||w||≤B}|wᵀΣσ_ix_i|=(B/n)E_σ||Σσ_ix_i||₂ by duality. Jensen/Cauchy–Schwarz bounds this by (B/n)√E||Σσ_ix_i||². Expand the square: cross terms vanish since Eσ_iσ_j=0 for i≠j, leaving Σ||x_i||²≤nR². Therefore R̂_abs≤(B/n)√(nR²)=BR/√n.`, String.raw`R̂_abs=(1/n)E_σ sup_{||w||≤B}|wᵀΣσ_ix_i|=(B/n)E_σ||Σσ_ix_i||₂ theo chuẩn đối ngẫu. Jensen/Cauchy–Schwarz chặn bởi (B/n)√E||Σσ_ix_i||². Khai triển bình phương: hạng chéo triệt vì Eσ_iσ_j=0 khi i≠j, còn Σ||x_i||²≤nR². Vậy R̂_abs≤(B/n)√(nR²)=BR/√n.`),
  [B('Uses ℓ₂ duality to take the supremum.', 'Dùng đối ngẫu ℓ₂ để lấy supremum.'), B('Applies Cauchy–Schwarz/Jensen to the sign expectation.', 'Áp Cauchy–Schwarz/Jensen cho kỳ vọng dấu.'), B('Expands the second moment and removes cross terms.', 'Khai triển moment hai và triệt hạng chéo.'), B('Uses the sample norm bound to obtain BR/√n.', 'Dùng cận chuẩn mẫu để được BR/√n.')],
  B('Bounds the norm by the average feature norm without the square root.', 'Chặn chuẩn bằng trung bình norm đặc trưng mà thiếu căn.') );
deepenExercise(87, 2,
  B(String.raw`Let g_f(z)=ℓ(f,z), and let f̂ be an exact empirical minimizer over a measurable class. For any ε>0 choose f_ε with R(f_ε)≤inf_F R+ε. Insert empirical risks to prove excess≤2 sup_g|R̂−R|+ε, then let ε↓0.`, String.raw`Cho g_f(z)=ℓ(f,z), f̂ là nghiệm tối thiểu thực nghiệm chính xác trên lớp đo được. Với ε>0 chọn f_ε có R(f_ε)≤inf_F R+ε. Chèn risk thực nghiệm để chứng minh excess≤2 sup_g|R̂−R|+ε rồi cho ε↓0.`),
  B(String.raw`Add and subtract R̂(f̂) and R̂(f_ε); the ERM middle difference is nonpositive.`, String.raw`Cộng trừ R̂(f̂), R̂(f_ε); hiệu ERM ở giữa không dương.`),
  B(String.raw`R(f̂)−inf_F R≤R(f̂)−R(f_ε)+ε=[R(f̂)−R̂(f̂)]+[R̂(f̂)−R̂(f_ε)]+[R̂(f_ε)−R(f_ε)]+ε. The middle term is ≤0 by empirical minimization and the first/third terms are each ≤sup_g|R−R̂|. Thus the bound holds for every ε>0; taking ε↓0 avoids assuming a population minimizer exists.`, String.raw`R(f̂)−inf_F R≤R(f̂)−R(f_ε)+ε=[R(f̂)−R̂(f̂)]+[R̂(f̂)−R̂(f_ε)]+[R̂(f_ε)−R(f_ε)]+ε. Hạng giữa ≤0 do tối thiểu thực nghiệm; hạng đầu/cuối mỗi hạng ≤sup_g|R−R̂|. Cận đúng với mọi ε>0; cho ε↓0 để tránh giả sử nghiệm population đạt được.`),
  [B('Chooses an ε-minimizer of population risk.', 'Chọn ε-minimizer của risk tổng thể.'), B('Inserts both empirical risks with correct signs.', 'Chèn hai risk thực nghiệm đúng dấu.'), B('Uses ERM to remove the middle term.', 'Dùng ERM loại hạng giữa.'), B('Lets ε vanish without assuming attainment.', 'Cho ε về 0 mà không giả sử đạt nghiệm.')],
  B('Assumes an argmin of population risk exists without justification.', 'Giả sử argmin risk tổng thể tồn tại mà không biện minh.') );
deepenExercise(87, 3,
  B(String.raw`Let ||w||₂≤B, ||x||₂≤R, |y|≤Y and ℓ_y(u)=(u−y)². Center the loss by ℓ_y(0), find its Lipschitz constant on |u|≤BR, and use the absolute contraction inequality plus the linear-class bound to give an expected ERM excess bound. State every factor used.`, String.raw`Cho ||w||₂≤B, ||x||₂≤R, |y|≤Y, ℓ_y(u)=(u−y)². Trừ ℓ_y(0), tìm hằng số Lipschitz trên |u|≤BR, dùng bất đẳng thức contraction tuyệt đối và cận lớp tuyến tính để chặn excess ERM kỳ vọng. Nêu từng hệ số.`),
  B(String.raw`The centered map ψ_y(u)=(u−y)²−y² has ψ_y(0)=0 and derivative 2(u−y). Absolute contraction contributes a factor 2.`, String.raw`Hàm ψ_y(u)=(u−y)²−y² có ψ_y(0)=0, đạo hàm 2(u−y). Contraction trị tuyệt đối thêm hệ số 2.`),
  B(String.raw`On |u|≤BR, |ψ′_y(u)|=2|u−y|≤2(BR+Y)=L. Centering changes no population-minus-empirical deviation. The absolute contraction inequality gives R̂_abs(ψ∘F)≤2L R̂_abs(F)≤2LBR/√n. W87 gives expected excess≤4E R̂_abs(loss class), hence ≤8LBR/√n=16BR(BR+Y)/√n. This is a valid, deliberately loose expectation bound only under the stated bounded prediction/label assumptions; it is not a high-probability statement.`, String.raw`Trên |u|≤BR, |ψ′_y(u)|=2|u−y|≤2(BR+Y)=L. Trừ hằng số không đổi độ lệch population–empirical. Bất đẳng thức contraction trị tuyệt đối cho R̂_abs(ψ∘F)≤2L R̂_abs(F)≤2LBR/√n. W87 cho excess kỳ vọng≤4E R̂_abs(lớp loss), nên ≤8LBR/√n=16BR(BR+Y)/√n. Đây là cận kỳ vọng hợp lệ nhưng cố ý lỏng, chỉ dưới giả thiết bị chặn đã nêu; không phải cận xác suất cao.`),
  [B('Centers the loss and bounds its derivative by L.', 'Trừ tâm loss và chặn đạo hàm bởi L.'), B('Applies absolute contraction with the stated factor 2.', 'Áp contraction trị tuyệt đối với hệ số 2 đã nêu.'), B('Substitutes the linear-class bound BR/√n.', 'Thế cận lớp tuyến tính BR/√n.'), B('Combines with the theorem factor 4 and limits the claim.', 'Kết hợp hệ số 4 của định lý và giới hạn claim.')],
  B('Uses the derivative bound without bounding predictions or labels.', 'Dùng cận đạo hàm mà không chặn dự báo/nhãn.') );
deepenExercise(87, 4,
  B(String.raw`For nested classes F₁⊂F₂, write an excess-risk bound as approximation error plus estimation complexity. Explain separately which term cannot worsen with nesting and why total risk need not improve.`, String.raw`Với lớp lồng F₁⊂F₂, viết cận excess risk thành lỗi xấp xỉ cộng độ phức tạp ước lượng. Tách riêng hạng nào không thể xấu hơn khi mở rộng lớp và vì sao risk tổng không nhất thiết giảm.`),
  B(String.raw`The infimum risk over a larger set can only decrease; its Rademacher complexity can increase.`, String.raw`Infimum risk trên tập lớn chỉ có thể giảm; độ phức tạp Rademacher có thể tăng.`),
  B(String.raw`For each class, a typical decomposition is inf_{f∈F}R(f)−R* plus the already normalized estimation term 4E R̂_abs(L∘F), and any optimization allowance. Since F₁⊂F₂, inf_{F₂}R≤inf_{F₁}R, so approximation cannot worsen. But the uniform complexity term need not decrease and may dominate the approximation gain. Therefore the displayed bound and realized test risk need not improve; this is not evidence about economic value.`, String.raw`Với mỗi lớp, phân rã điển hình là inf_{f∈F}R(f)−R* cộng hạng ước lượng đã chuẩn hóa 4E R̂_abs(L∘F), và dung sai tối ưu nếu có. Vì F₁⊂F₂ nên inf_{F₂}R≤inf_{F₁}R: lỗi xấp xỉ không thể tăng. Nhưng hạng độ phức tạp đều không nhất thiết giảm và có thể lớn hơn lợi ích xấp xỉ. Vì vậy cận và risk test quan sát được không nhất thiết cải thiện; đây không phải bằng chứng giá trị kinh tế.`),
  [B('Writes the approximation term.', 'Viết hạng xấp xỉ.'), B('Uses nesting to compare the infima.', 'Dùng tính lồng để so infimum.'), B('Explains complexity growth/estimation.', 'Giải thích tăng độ phức tạp/ước lượng.'), B('Separates bound, observed test risk and economic value.', 'Tách cận, risk test quan sát và giá trị kinh tế.')],
  B('Concludes the richer class must have lower total or test risk.', 'Kết luận lớp lớn hơn chắc chắn có risk tổng/test thấp hơn.'));
deepenExercise(87, 5,
  B(String.raw`For F_B with ||w||≤B, suppose one sample feature has ||x₁||=n while others are zero. Evaluate the sample-dependent bound B√(Σ||x_i||²)/n and explain why BR/√n is unavailable; give a valid repair.`, String.raw`Với F_B, ||w||≤B, giả sử một đặc trưng mẫu có ||x₁||=n còn lại bằng 0. Tính cận phụ thuộc mẫu B√(Σ||x_i||²)/n, giải thích vì sao không có BR/√n và nêu cách sửa hợp lệ.`),
  B(String.raw`The sum of squared feature norms is n², so its square root divided by n is 1.`, String.raw`Tổng bình phương norm đặc trưng là n², căn rồi chia n bằng 1.`),
  B(String.raw`Here R̂_abs=(B/n)E|σ₁ n|=B, so the sample-specific bound is B√(n²)/n=B, not O(BR/√n) with a fixed R independent of n. A uniform feature bound R would require R≥n and yield BR/√n=B√n, which is valid but loose. One may instead impose a justified uniform norm/moment assumption, clip features while stating the changed target, or report the sample-dependent bound; the unqualified 1/√n rate is invalid.`, String.raw`Ở đây R̂_abs=(B/n)E|σ₁n|=B, đúng với cận theo mẫu B√(n²)/n=B, không phải O(BR/√n) với R cố định theo n. Cận feature đều cần R≥n nên cho BR/√n=B√n, hợp lệ nhưng lỏng. Có thể áp giả thiết norm/moment đều có biện minh, cắt feature đồng thời nêu target đổi, hoặc báo cận phụ thuộc mẫu; rate 1/√n không điều kiện là sai.`),
  [B('Computes the sample-dependent bound.', 'Tính cận phụ thuộc mẫu.'), B('Identifies failure of a fixed feature-radius hypothesis.', 'Nhận diện giả thiết bán kính feature cố định bị hỏng.'), B('Gives a valid norm/moment or clipping repair.', 'Nêu cách sửa norm/moment hoặc clipping hợp lệ.'), B('Limits the resulting rate claim.', 'Giới hạn claim về tốc độ.')],
  B('Uses R independent of n despite ||x₁||=n.', 'Dùng R không phụ thuộc n dù ||x₁||=n.'));

// W88: separate objective approximation from empirical optimization; the signed population difference may be negative.
deepenExercise(88, 3,
  B(String.raw`Let J=R+λΩ and Ĵ=R̂+λΩ on finite F. Define f*=argmin_F J, f̂=argmin_F Ĵ and Ĵ(f̃)≤Ĵ(f̂)+ε_opt. Write an exact three-term decomposition of J(f̃)−inf J, then prove J(f̃)−J(f*)≤2 sup_F|R−R̂|+ε_opt.`, String.raw`Cho J=R+λΩ, Ĵ=R̂+λΩ trên F hữu hạn. Đặt f*=argmin_F J, f̂=argmin_F Ĵ, Ĵ(f̃)≤Ĵ(f̂)+ε_opt. Viết phân rã ba hạng chính xác của J(f̃)−inf J, rồi chứng minh J(f̃)−J(f*)≤2 sup_F|R−R̂|+ε_opt.`),
  B(String.raw`Add and subtract J(f*) and J(f̂) for the exact decomposition; use J−Ĵ=R−R̂ for the bound.`, String.raw`Cộng trừ J(f*) và J(f̂) để phân rã chính xác; dùng J−Ĵ=R−R̂ khi chặn.`),
  B(String.raw`The identity is J(f̃)−inf J=[J(f*)−inf J]+[J(f̂)−J(f*)]+[J(f̃)−J(f̂)]. The first term is class approximation; the second is estimation/selection and may have either sign; the third is also signed, not a nonnegative population optimization gap. For the bound, J(f̃)−J(f*)=[J−Ĵ](f̃)+[Ĵ(f̃)−Ĵ(f̂)]+[Ĵ−J](f̂)≤sup|R−R̂|+ε_opt+sup|R−R̂|. Penalty terms cancel in both deviations. Thus only the empirical gap is guaranteed nonnegative.`, String.raw`Đẳng thức là J(f̃)−inf J=[J(f*)−inf J]+[J(f̂)−J(f*)]+[J(f̃)−J(f̂)]. Hạng đầu là xấp xỉ lớp; hạng hai là ước lượng/chọn và có thể mang hai dấu; hạng ba cũng có thể âm, không phải gap tối ưu population không âm. Để chặn, J(f̃)−J(f*)=[J−Ĵ](f̃)+[Ĵ(f̃)−Ĵ(f̂)]+[Ĵ−J](f̂)≤sup|R−R̂|+ε_opt+sup|R−R̂|. Hạng penalty triệt trong hai độ lệch. Chỉ gap thực nghiệm được bảo đảm không âm.`),
  [B('Writes the exact telescoping decomposition.', 'Viết phân rã triệt tiêu chính xác.'), B('Identifies approximation and signed comparison terms.', 'Nhận diện xấp xỉ và hạng so sánh có dấu.'), B('Bounds both generalization deviations.', 'Chặn cả hai độ lệch tổng quát hóa.'), B('Adds ε_opt and notes penalty cancellation.', 'Cộng ε_opt và nêu penalty triệt tiêu.')],
  B('Claims J(f̃)−J(f̂) must be nonnegative in population risk.', 'Cho rằng J(f̃)−J(f̂) phải không âm theo risk population.'));

// W89–90: complete the projection/telescoping derivations and their transfer conditions.
deepenExercise(89, 2,
  B(String.raw`For closed convex K and u∈K, derive ||x_{t+1}−u||²≤||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||² from x_{t+1}=Π_K(x_t−ηg_t). State the projection property used.`, String.raw`Với K đóng lồi, u∈K, suy ||x_{t+1}−u||²≤||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||² từ x_{t+1}=Π_K(x_t−ηg_t). Nêu tính chất chiếu dùng.`),
  B(String.raw`Euclidean projection minimizes distance to every feasible point; then expand one squared norm.`, String.raw`Phép chiếu Euclidean gần mọi điểm khả thi nhất; sau đó khai triển một bình phương chuẩn.`),
  B(String.raw`Set y=x_t−ηg_t. Since u∈K and x_{t+1}=Π_K(y), projection optimality gives ||x_{t+1}−u||²≤||y−u||². Expand the right side as ||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||². Closed convexity ensures the Euclidean projection is well defined and unique. This is a pathwise inequality; expectation is not required.`, String.raw`Đặt y=x_t−ηg_t. Vì u∈K và x_{t+1}=Π_K(y), tính tối ưu phép chiếu cho ||x_{t+1}−u||²≤||y−u||². Khai triển vế phải thành ||x_t−u||²−2ηg_tᵀ(x_t−u)+η²||g_t||². Tính đóng lồi bảo đảm phép chiếu Euclidean xác định và duy nhất. Đây là bất đẳng thức theo từng đường đi; không cần kỳ vọng.`),
  [B('Invokes projection optimality for a feasible comparator.', 'Dùng tính tối ưu chiếu cho comparator khả thi.'), B('Substitutes y=x_t−ηg_t.', 'Thế y=x_t−ηg_t.'), B('Expands the square with the correct sign.', 'Khai triển bình phương đúng dấu.'), B('States the closed-convex/pathwise scope.', 'Nêu phạm vi đóng-lồi/theo đường đi.')],
  B('Assumes Π_K is nonexpansive but never anchors the comparator u.', 'Giả sử Π_K không giãn nhưng không dùng comparator u.'));
deepenExercise(89, 3,
  B(String.raw`Combine the one-step projection inequality with convexity f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Sum over t=1,…,T, telescope and use diameter D and ||g_t||≤G to prove Reg_T(u)≤D²/(2η)+ηG²T/2. Optimize η.`, String.raw`Kết hợp bất đẳng thức chiếu một bước với lồi f_t(x_t)−f_t(u)≤g_tᵀ(x_t−u). Cộng t=1,…,T, triệt tiêu và dùng đường kính D, ||g_t||≤G để chứng minh Reg_T(u)≤D²/(2η)+ηG²T/2. Tối ưu η.`),
  B(String.raw`Rearrange the squared-distance inequality to isolate ηg_tᵀ(x_t−u), then sum before substituting D,G.`, String.raw`Chuyển bất đẳng thức khoảng cách để cô lập ηg_tᵀ(x_t−u), rồi cộng trước khi thế D,G.`),
  B(String.raw`Rearrangement gives g_tᵀ(x_t−u)≤[a_t−a_{t+1}]/(2η)+η||g_t||²/2, where a_t=||x_t−u||². Convexity bounds each loss gap by this inner product. Summing yields Reg_T(u)≤[a₁−a_{T+1}]/(2η)+ηΣ||g_t||²/2≤D²/(2η)+ηG²T/2. Differentiate the bound: −D²/(2η²)+G²T/2=0, so η*=D/(G√T), and the two terms sum to DG√T. The comparator is fixed before the loss sequence is evaluated.`, String.raw`Chuyển vế được g_tᵀ(x_t−u)≤[a_t−a_{t+1}]/(2η)+η||g_t||²/2, với a_t=||x_t−u||². Tính lồi chặn mỗi gap loss bởi tích vô hướng này. Cộng lại: Reg_T(u)≤[a₁−a_{T+1}]/(2η)+ηΣ||g_t||²/2≤D²/(2η)+ηG²T/2. Lấy đạo hàm cận: −D²/(2η²)+G²T/2=0, nên η*=D/(G√T), hai hạng cộng thành DG√T. Comparator được cố định trước khi xét chuỗi loss.`),
  [B('Combines the convex loss inequality with the projection inner product.', 'Kết hợp bất đẳng thức loss lồi với tích vô hướng từ phép chiếu.'), B('Shows the potential difference and telescoping.', 'Nêu hiệu thế năng và triệt tiêu.'), B('Uses D and G for the stated bound.', 'Dùng D và G cho cận đã nêu.'), B('Optimizes the step size and states static comparator scope.', 'Tối ưu cỡ bước và nêu phạm vi comparator tĩnh.')],
  B('Drops η on the potential term or treats a changing comparator as fixed.', 'Bỏ η ở hạng thế năng hoặc coi comparator đổi là cố định.'));
deepenExercise(90, 2,
  B(String.raw`Assume each f_t is μ-strongly convex, ||g_t||≤G, projection onto closed convex K, and η_t=1/(μt). Combine strong convexity with the projection inequality and sum to prove Reg_T(u)≤(G²/(2μ))(1+log T). Show the distance terms cancel.`, String.raw`Giả sử f_t μ-lồi mạnh, ||g_t||≤G, chiếu lên K đóng lồi, η_t=1/(μt). Kết hợp lồi mạnh với bất đẳng thức chiếu, cộng để chứng minh Reg_T(u)≤(G²/(2μ))(1+log T). Chỉ rõ hạng khoảng cách triệt tiêu.`),
  B(String.raw`Use a_t=||x_t−u||². Strong convexity subtracts μa_t/2; projection contributes (a_t−a_{t+1})/(2η_t).`, String.raw`Đặt a_t=||x_t−u||². Lồi mạnh trừ μa_t/2; phép chiếu cộng (a_t−a_{t+1})/(2η_t).`),
  B(String.raw`Strong convexity gives gap_t≤g_tᵀ(x_t−u)−μa_t/2. Projection gives g_tᵀ(x_t−u)≤(a_t−a_{t+1})/(2η_t)+η_tG²/2. Substitute η_t=1/(μt): gap_t≤(μ/2)[(t−1)a_t−t a_{t+1}]+G²/(2μt). Summing t=1,…,T cancels every interior a_t term and leaves −μT a_{T+1}/2≤0. Finally H_T=Σ1/t≤1+logT, giving the result. No diameter term is needed for this indexing.`, String.raw`Lồi mạnh cho gap_t≤g_tᵀ(x_t−u)−μa_t/2. Phép chiếu cho g_tᵀ(x_t−u)≤(a_t−a_{t+1})/(2η_t)+η_tG²/2. Thế η_t=1/(μt): gap_t≤(μ/2)[(t−1)a_t−t a_{t+1}]+G²/(2μt). Cộng t=1,…,T triệt mọi a_t nội bộ, còn −μT a_{T+1}/2≤0. Cuối cùng H_T=Σ1/t≤1+logT, thu được cận. Với chỉ số này không cần hạng đường kính.`),
  [B('Uses strong convexity with the correct negative quadratic term.', 'Dùng lồi mạnh với hạng bình phương âm đúng.'), B('Substitutes η_t=1/(μt) correctly.', 'Thế đúng η_t=1/(μt).' ), B('Shows interior potential cancellation and terminal sign.', 'Chỉ rõ triệt thế năng nội bộ và dấu hạng cuối.'), B('Bounds the harmonic sum and states scope.', 'Chặn tổng điều hòa và nêu phạm vi.')],
  B('Treats boundedness of K as strong convexity of the losses.', 'Coi K bị chặn là loss lồi mạnh.'));
deepenExercise(90, 1,
  B(String.raw`For μ=2,G=3,D=.5,T=10 compute the strongly-convex logarithmic bound, the generic DG√T bound, and state which is numerically smaller at this horizon without claiming asymptotic dominance.`, String.raw`Với μ=2,G=3,D=.5,T=10, tính cận log lồi mạnh, cận tổng quát DG√T, rồi nêu cận nào nhỏ hơn tại horizon này mà không khẳng định ưu thế tiệm cận.`),
  B(String.raw`Substitute into (G²/(2μ))(1+logT); separately calculate DG√T.`, String.raw`Thế vào (G²/(2μ))(1+logT); tính riêng DG√T.`),
  B(String.raw`The logarithmic bound is (9/4)(1+ln10)+μD²/2 if retaining the theorem's optional startup term: ≈7.6808. The sharper schedule-specific proof above needs no diameter term and gives (9/4)(1+ln10)≈7.4308. The generic bound is .5·3·√10≈4.74, smaller at T=10. This finite-horizon comparison does not contradict eventual O(logT) versus O(√T); constants and the domain term matter.`, String.raw`Cận log có hạng khởi động tùy chọn là (9/4)(1+ln10)+μD²/2≈7.6808. Chứng minh theo lịch bước chặt hơn ở trên không cần hạng đường kính, cho (9/4)(1+ln10)≈7.4308. Cận tổng quát là .5·3·√10≈4.74, nhỏ hơn tại T=10. So sánh hữu hạn này không mâu thuẫn O(logT) so với O(√T) tiệm cận; hằng số và hạng miền có ý nghĩa.`),
  [B('Evaluates the schedule-specific logarithmic bound.', 'Tính cận log theo lịch bước.'), B('Optionally computes the stated diameter startup term.', 'Tính thêm hạng khởi động đường kính nếu dùng.'), B('Computes the generic square-root bound.', 'Tính cận căn tổng quát.'), B('Distinguishes finite-horizon values from asymptotic rates.', 'Phân biệt giá trị hữu hạn với tốc độ tiệm cận.')],
  B('Uses the prior incorrect logarithmic numerical value or claims log is always smaller.', 'Dùng giá trị log sai trước đó hoặc cho rằng log luôn nhỏ hơn.'));

// W81 sensor-offset exercise: a static latent-state filter can absorb a constant offset.
deepenExercise(81, 5,
  B(String.raw`A true static state is x=0 and y_t=x+5+v_t with IID v_t~N(0,1). A filter instead uses the static-state model y_t=θ+v_t, prior θ~N(0,1). Derive E[r_t] before update t, show it tends to zero, and explain why post-burn-in innovation histograms alone cannot identify the offset.`, String.raw`Trạng thái tĩnh thật x=0, y_t=x+5+v_t với v_t~N(0,1) IID. Bộ lọc dùng mô hình trạng thái tĩnh y_t=θ+v_t, prior θ~N(0,1). Suy E[r_t] trước cập nhật t, chứng minh tiến về 0, và giải thích vì sao histogram innovation sau burn-in không nhận diện được offset.`),
  B(String.raw`After t−1 unit-variance observations and unit prior precision, the posterior mean is m_{t−1}=Σ_{s<t}y_s/t.`, String.raw`Sau t−1 quan sát phương sai 1 và prior precision 1, posterior mean là m_{t−1}=Σ_{s<t}y_s/t.`),
  B(String.raw`The predictive mean is m_{t−1}=Σ_{s<t}y_s/t. Since E[y_s]=5, E[r_t]=E[y_t−m_{t−1}]=5−5(t−1)/t=5/t→0. The fitted latent level absorbs the constant sensor offset, so after burn-in the centered innovations can have an approximately standard-normal histogram despite the measurement equation being misspecified relative to the true x=0. Detecting absolute bias requires an anchored/known state, external calibration, or joint offset identifiability analysis; a residual histogram alone cannot separate state level from sensor offset.`, String.raw`Mean dự báo là m_{t−1}=Σ_{s<t}y_s/t. Vì E[y_s]=5 nên E[r_t]=E[y_t−m_{t−1}]=5−5(t−1)/t=5/t→0. Mức trạng thái khớp hấp thụ offset cảm biến hằng, nên sau burn-in innovation đã căn tâm có thể có histogram gần chuẩn dù phương trình đo sai so với x=0 thật. Muốn phát hiện bias tuyệt đối cần trạng thái neo/đã biết, hiệu chuẩn ngoài, hoặc phân tích nhận diện đồng thời offset; histogram residual riêng không phân biệt được mức trạng thái và offset cảm biến.`),
  [B('Derives the static-state posterior mean with correct precision.', 'Suy posterior mean trạng thái tĩnh đúng precision.'), B('Computes the expected innovation 5/t.', 'Tính kỳ vọng innovation 5/t.'), B('Explains absorption of offset by latent level.', 'Giải thích mức ẩn hấp thụ offset.'), B('Names an external identifiability/calibration requirement.', 'Nêu yêu cầu nhận diện/hiệu chuẩn bên ngoài.')],
  B('Claims settled innovations must retain mean 5 under every state model.', 'Cho rằng innovation ổn định phải giữ mean 5 với mọi mô hình trạng thái.'));

// Narrow W77 consistency to an exact, provable bounded finite-dependence case.
const w77 = weeks.find((candidate) => candidate.week === 77)!;
w77.theorems[0].statement = B(String.raw`For zero-padded finite data, Bartlett's estimator is PSD. Separately let Z_t be strictly stationary, centered, m-dependent for a fixed m, and |Z_t|≤B, with Ω=Σ_{|h|≤m}γ(h)>0. Define γ̂_h=n⁻¹Σ_{t=h+1}^n(Z_t−Z̄)(Z_{t−h}−Z̄), γ̂_{−h}=γ̂_h, and Ω̂_L=Σ_{|h|≤L}(1−|h|/(L+1))γ̂_h. If L_n→∞ and L_n³/n→0, then Ω̂_{L_n}→pΩ. General mixing-HAC consistency is deferred.`, String.raw`Với dữ liệu hữu hạn zero-padding, ước lượng Bartlett là PSD. Riêng cho Z_t dừng nghiêm ngặt, trung tâm, m-phụ thuộc với m cố định, |Z_t|≤B và Ω=Σ_{|h|≤m}γ(h)>0. Đặt γ̂_h=n⁻¹Σ_{t=h+1}^n(Z_t−Z̄)(Z_{t−h}−Z̄), γ̂_{−h}=γ̂_h, Ω̂_L=Σ_{|h|≤L}(1−|h|/(L+1))γ̂_h. Nếu L_n→∞ và L_n³/n→0 thì Ω̂_{L_n}→pΩ. Tính nhất quán HAC mixing tổng quát được để lại.`);
w77.theorems[0].proofStatus = 'proved';
w77.theorems[0].proof = B(String.raw`For scalar u_t with zero padding, expand [n(L+1)]⁻¹Σ_s(Σ_{j=0}^L u_{s−j})². Each pair at lag h occurs L+1−|h| times, so the expression equals the Bartlett sum Σ_{|h|≤L}(1−|h|/(L+1))γ̂_h, where γ̂_h=n⁻¹Σ_tu_tu_{t−h}. Each square is nonnegative; for a vector score test any a and replace u_t by aᵀz_t. For consistency first use true-centered Z_t products. With m fixed, γ(h)=0 for |h|>m, E γ̃_h=(1−h/n)γ(h), and weights for each fixed |h|≤m tend to one; therefore EΩ̃_L→Ω. For each h, Y_{t,h}=Z_tZ_{t−h} is bounded and (h+m)-dependent, so Var(γ̃_h)≤C B⁴(h+m+1)/n. Minkowski's inequality in L² gives SD(Σ_{h=0}^L w_hγ̃_h)≤Σ_h w_h SD(γ̃_h)=O(B² L^{3/2}/√n)→0 by L³/n→0; the negative lags double at most this order. Chebyshev yields Ω̃_L−EΩ̃_L→p0. Since Var(Z̄)=O(1/n), replacing the true mean by Z̄ changes each lag covariance by at most 2B|Z̄|+Z̄², so the weighted sum changes by O_p(L/√n)=o_p(1). Thus Ω̂_L→pΩ. This proves only the stated m-dependent special case, not a general α-mixing result.`, String.raw`Với u_t vô hướng thêm số 0 ngoài mẫu, khai triển [n(L+1)]⁻¹Σ_s(Σ_{j=0}^L u_{s−j})². Mỗi cặp lag h xuất hiện L+1−|h| lần nên biểu thức bằng tổng Bartlett Σ_{|h|≤L}(1−|h|/(L+1))γ̂_h, với γ̂_h=n⁻¹Σ_tu_tu_{t−h}. Mỗi bình phương không âm; với score vector thử mọi a và thay u_t bằng aᵀz_t. Để chứng minh nhất quán, trước hết dùng tích Z_t đã trừ mean thật. Với m cố định, γ(h)=0 khi |h|>m, Eγ̃_h=(1−h/n)γ(h), và trọng số mỗi |h|≤m cố định tiến về một; do đó EΩ̃_L→Ω. Với mỗi h, Y_{t,h}=Z_tZ_{t−h} bị chặn và (h+m)-phụ thuộc, nên Var(γ̃_h)≤CB⁴(h+m+1)/n. Bất đẳng thức Minkowski trong L² cho SD(Σ_{h=0}^L w_hγ̃_h)≤Σ_hw_hSD(γ̃_h)=O(B²L^{3/2}/√n)→0 nhờ L³/n→0; lag âm nhiều nhất nhân đôi bậc này. Chebyshev cho Ω̃_L−EΩ̃_L→p0. Vì Var(Z̄)=O(1/n), thay mean thật bằng Z̄ làm từng covariance lag đổi không quá 2B|Z̄|+Z̄², nên tổng có trọng số đổi O_p(L/√n)=o_p(1). Vậy Ω̂_L→pΩ. Đây chỉ chứng minh trường hợp m-phụ thuộc đã nêu, không phải kết quả α-mixing tổng quát.`);
w77.reading[0].section = 'Newey–West Theorem 1 (finite-sample Bartlett PSD); bounded finite-dependent consistency proof is derived in this lesson.';
w77.reading.push({ sourceId: 'o-hansen-hac', section: 'Hansen (1992), pp. 967–972; optional primary reference for general kernel covariance consistency, not the special-case theorem proved here.', purpose: B('Compare the selected finite-dependent proof with a classic general HAC reference; the broader result is a sourced extension, not a hidden hypothesis.', 'Đối chiếu chứng minh hữu hạn-phụ-thuộc đã chọn với tài liệu HAC tổng quát kinh điển; kết quả rộng hơn chỉ là mở rộng có dẫn nguồn, không phải giả thiết ẩn.'), required: false });
w77.definitions = B(String.raw`For centered scores Z_t, γ(h)=E[Z_tZ_{t−h}]. A sequence is m-dependent if σ(Z_s:s≤t) is independent of σ(Z_s:s≥t+m+1) for every t. Thus γ(h)=0 for |h|>m, but the definition is stronger than zero covariance. Bartlett HAC uses tapered sample lag covariances to estimate Ω=Σ_hγ(h).`, String.raw`Với score Z_t đã trừ tâm, γ(h)=E[Z_tZ_{t−h}]. Chuỗi m-phụ thuộc nếu σ(Z_s:s≤t) độc lập σ(Z_s:s≥t+m+1) với mọi t. Do đó γ(h)=0 khi |h|>m, nhưng định nghĩa mạnh hơn covariance bằng không. HAC Bartlett dùng covariance mẫu có taper để ước lượng Ω=Σ_hγ(h).`);
w77.theorems[0].sourceSection = 'Newey–West (1987), Theorem 1 (Bartlett PSD); the stated bounded m-dependent consistency result is proved fully in this lesson.';

// Keep the KL support argument mathematically valid when the forecast density vanishes off truth support.
const w82 = weeks.find((candidate) => candidate.week === 82)!;
w82.theorems[0].proof = B(String.raw`Subtract the expected log losses to obtain KL(q||p)=∫_A q log(q/p), A={y:q(y)>0}. If p=0 on a positive-q subset, the KL and forecast loss are infinite. Otherwise −log(p/q)≥1−p/q on A, so KL≥∫_A q−∫_A p=1−∫_A p≥0. Equality requires p=q q-almost everywhere on A and ∫_A p=1, so p has no mass outside A; the densities then agree almost everywhere. This support-restricted integral is necessary: replacing ∫_A p by ∫p=1 without p≪q is invalid.`, String.raw`Lấy hiệu kỳ vọng log loss được KL(q||p)=∫_A q log(q/p), A={y:q(y)>0}. Nếu p=0 trên tập con có q-mass dương thì KL và forecast loss vô hạn. Nếu không, −log(p/q)≥1−p/q trên A, nên KL≥∫_A q−∫_A p=1−∫_A p≥0. Dấu bằng yêu cầu p=q q-hầu khắp theo q trên A và ∫_A p=1, tức p không có khối lượng ngoài A; do đó hai mật độ trùng nhau hầu khắp nơi. Giới hạn tích phân trên A là thiết yếu: thay ∫_A p bằng ∫p=1 khi chưa có p≪q là sai.`);

// W87's theorem, exercises and W86 all use the same absolute-complexity convention.
const w87 = weeks.find((candidate) => candidate.week === 87)!;
w87.definitions = B(String.raw`For a measurable loss class G={z↦ℓ(f,z)}, define absolute empirical Rademacher complexity R̂_abs(G)=E_σ sup_{g∈G}|n⁻¹Σ_{i=1}^nσ_i g(Z_i)|, where σ_i are independent Rademacher signs.`, String.raw`Với lớp loss đo được G={z↦ℓ(f,z)}, định nghĩa độ phức tạp Rademacher thực nghiệm trị tuyệt đối R̂_abs(G)=E_σ sup_{g∈G}|n⁻¹Σ_{i=1}^nσ_i g(Z_i)|, trong đó σ_i là các dấu Rademacher độc lập.`);
w87.theorems[0].statement = B(String.raw`Let Z_i be IID, G a measurable loss class with integrable members and finite expected uniform deviations, and f̂ a measurable empirical ε_n-minimizer satisfying P_n g_f̂≤inf_{g∈G}P_ng+ε_n, where ε_n≥0 and Eε_n<∞. Then E[R(f̂)−inf_{g∈G}R(g)]≤4E R̂_abs(G)+Eε_n. No population minimizer need attain the infimum: compare to a population ε-minimizer and let ε↓0. This is an expectation bound, not a tail guarantee.`, String.raw`Cho Z_i IID, G là lớp loss đo được với hàm khả tích và độ lệch đều kỳ vọng hữu hạn, f̂ là empirical ε_n-minimizer đo được thỏa P_n g_f̂≤inf_{g∈G}P_ng+ε_n, trong đó ε_n≥0 và Eε_n<∞. Khi đó E[R(f̂)−inf_{g∈G}R(g)]≤4E R̂_abs(G)+Eε_n. Nghiệm population có thể không đạt infimum: so với ε-minimizer population rồi cho ε↓0. Đây là cận kỳ vọng, không phải cận đuôi.`);
w87.theorems[0].proof = B(String.raw`For any ε>0 choose a population ε-minimizer g_ε with Pg_ε≤inf_G Pg+ε. Insert empirical risks: P g_f̂−inf_G Pg≤(P−P_n)g_f̂+[P_ng_f̂−P_ng_ε]+(P_n−P)g_ε+ε. The empirical middle term is at most ε_n; hence the deviation is bounded by 2 sup_{g∈G}|(P_n−P)g|+ε_n+ε. Let ε↓0 and take expectations. Absolute symmetrization with an independent ghost sample and Jensen's inequality for the conditional sign expectation yield E sup_g|(P_n−P)g|≤2E R̂_abs(G), giving factor four. An exact empirical minimizer has ε_n=0. No concentration inequality has been applied, so the conclusion remains in expectation.`, String.raw`Với ε>0 chọn population ε-minimizer g_ε có Pg_ε≤inf_G Pg+ε. Chèn risk thực nghiệm: P g_f̂−inf_G Pg≤(P−P_n)g_f̂+[P_ng_f̂−P_ng_ε]+(P_n−P)g_ε+ε. Hạng thực nghiệm giữa không quá ε_n; vì vậy độ lệch bị chặn bởi 2 sup_{g∈G}|(P_n−P)g|+ε_n+ε. Cho ε↓0 rồi lấy kỳ vọng. Symmetrization trị tuyệt đối với ghost sample độc lập và Jensen cho kỳ vọng conditional sign cho E sup_g|(P_n−P)g|≤2E R̂_abs(G), sinh hệ số bốn. ERM thực nghiệm chính xác có ε_n=0. Không dùng bất đẳng thức concentration nên kết luận chỉ là kỳ vọng.`);

// W78 uses an explicit bounded IID case, so the theorem has fully checkable hypotheses.
const w78 = weeks.find((candidate) => candidate.week === 78)!;
w78.theorems[0].statement = B(String.raw`Let X_1,…,X_n be IID with |X_i|≤B and Var(X_i)=σ²>0. The moving-block bootstrap with block length b=1 is the ordinary empirical bootstrap: conditionally draw X_1*,…,X_n* IID from the empirical distribution. Then the conditional distribution of √n(X̄*−X̄) converges in probability to N(0,σ²), the same limit as √n(X̄−μ). This exact selected case shows b_n→∞ is not universally necessary; the general dependent-series theorem is deferred.`, String.raw`Cho X_1,…,X_n IID, |X_i|≤B và Var(X_i)=σ²>0. Moving-block bootstrap với độ dài b=1 chính là bootstrap thực nghiệm thường: có điều kiện theo dữ liệu, lấy X_1*,…,X_n* IID từ phân phối thực nghiệm. Khi đó phân phối có điều kiện của √n(X̄*−X̄) hội tụ theo xác suất tới N(0,σ²), cùng giới hạn với √n(X̄−μ). Trường hợp chọn chính xác này cho thấy b_n→∞ không phải điều kiện cần phổ quát; định lý chuỗi phụ thuộc tổng quát được để lại.`);
w78.theorems[0].proofStatus = 'proved';
w78.theorems[0].proof = B(String.raw`The ordinary CLT gives √n(X̄−μ)⇒N(0,σ²). Given the data, bootstrap observations are IID from the empirical law, whose variance s_n²→σ² almost surely by the strong law. Their centered absolute values are bounded by 2B; hence for every ε>0 the conditional Lindeberg condition is exactly zero once 2B≤ε√n. The conditional triangular-array CLT therefore gives P*(√n(X̄*−X̄)≤x)→N(0,σ²)((−∞,x]) in probability at every x, and continuity of the Gaussian cdf upgrades this to uniform cdf convergence. Thus b=1 works in this IID case. Under dependence, this proof fails because resampled rows destroy serial clusters; increasing blocks can preserve local order under stronger model-specific assumptions, but those general results are outside this theorem.`, String.raw`CLT thông thường cho √n(X̄−μ)⇒N(0,σ²). Có điều kiện theo dữ liệu, quan sát bootstrap IID từ luật thực nghiệm, có phương sai s_n²→σ² hầu chắc chắn theo luật mạnh. Trị tuyệt đối đã trừ mean của bootstrap bị chặn bởi 2B; do đó với mọi ε>0, điều kiện Lindeberg có điều kiện bằng 0 khi 2B≤ε√n. CLT mảng tam giác có điều kiện cho P*(√n(X̄*−X̄)≤x)→N(0,σ²)((−∞,x]) theo xác suất tại mỗi x; tính liên tục của hàm phân phối chuẩn nâng hội tụ lên đều. Vậy b=1 hợp lệ trong trường hợp IID này. Dưới phụ thuộc, chứng minh thất bại vì lấy lại từng hàng phá cụm chuỗi; block tăng có thể giữ thứ tự cục bộ dưới giả thiết mô hình mạnh hơn, nhưng định lý tổng quát ấy nằm ngoài định lý này.`);
w78.theorems[0].sourceId = 'o-cmu705';
w78.theorems[0].sourceSection = 'Lectures 26–27 (bootstrap); the bounded IID empirical-bootstrap special case is proved here.';
w78.reading[0].sourceId = 'o-cmu705';
w78.reading[0].section = 'Lectures 26–27 (bootstrap); conditional IID mean theorem proved in the lesson.';
w78.definitions = B(String.raw`For Z_1,…,Z_n, an overlapping moving-block bootstrap of length b uses N=n−b+1 blocks S_j=Σ_{t=j}^{j+b−1}Z_t, j=1,…,N. Draw k=floor(n/b) block starts independently and uniformly from {1,…,N}, concatenate their blocks to obtain kb observations, and report their mean Z̄*. The conditional bootstrap law is given the observed series. Resampling keeps within-block order but breaks dependence at block joins. For paired forecast comparison, d_t=ℓ_{A,t}−ℓ_{B,t} is the target series; pairing does not imply independence.`, String.raw`Với Z_1,…,Z_n, moving-block bootstrap chồng lấn dài b dùng N=n−b+1 block S_j=Σ_{t=j}^{j+b−1}Z_t, j=1,…,N. Lấy k=floor(n/b) điểm đầu block độc lập, đều từ {1,…,N}, ghép thành kb quan sát và tính trung bình Z̄*. Luật bootstrap có điều kiện theo chuỗi quan sát. Tái lấy mẫu giữ thứ tự trong block nhưng cắt phụ thuộc tại mối nối. So sánh dự báo paired dùng chuỗi đích d_t=ℓ_{A,t}−ℓ_{B,t}; ghép cặp không hàm ý độc lập.`);
w78.theorems[0].statement = B(String.raw`Let Z_t be centered, strictly stationary, m-dependent for a fixed m, |Z_t|≤B, and Ω=Σ_{h∈Z}γ(h)>0. Let b=b_n→∞ with b_n³/n→0; form the overlapping blocks S_j above and draw k=floor(n/b) IID block starts conditionally on the data. Then sup_x|P*(√(kb)(Z̄*−Z̄_n)≤x)−Φ(x/√Ω)|→p0. Since kb/n→1, this estimates the same N(0,Ω) limit as √n Z̄_n. The conditions are a transparent sufficient regime for this bounded finite-dependent case; b→∞ is not universally necessary, as the IID b=1 boundary case shows.`, String.raw`Cho Z_t đã trừ trung bình, dừng nghiêm ngặt, m-phụ thuộc với m cố định, |Z_t|≤B và Ω=Σ_{h∈Z}γ(h)>0. Chọn b=b_n→∞, b_n³/n→0; lập block chồng lấn S_j như trên và có điều kiện theo dữ liệu lấy k=floor(n/b) điểm đầu block IID. Khi đó sup_x|P*(√(kb)(Z̄*−Z̄_n)≤x)−Φ(x/√Ω)|→p0. Vì kb/n→1, đây ước lượng cùng giới hạn N(0,Ω) với √n Z̄_n. Điều kiện là chế độ đủ minh bạch cho trường hợp hữu hạn-phụ-thuộc bị chặn; b→∞ không cần phổ quát, như trường hợp biên IID b=1.`);
w78.theorems[0].proofStatus = 'proved';
w78.theorems[0].proof = B(String.raw`First, the finite-dependent CLT applies to centered stationary m-dependent variables with finite 2+δ moment and Ω>0; here boundedness supplies every moment and α(h)=0 for h>m, so W76's stated CLT hypotheses hold. For a block sum S_j, E(S_j²/b)=Σ_{|h|<b}(1−|h|/b)γ(h)→Ω, since γ(h)=0 for |h|>m. Set A_n=(Nb)⁻¹Σ_{j=1}^N S_j². Each S_j² is bounded by b²B², and the block-square sequence is (b+m)-dependent. Counting O(N(b+m)) nonzero covariance pairs gives Var(A_n)≤C b³/n→0; therefore A_n→pΩ. The empirical block mean bias obeys |N⁻¹Σ_j S_j/b−Z̄_n|≤C B b/n by counting the O(b) edge observations with unequal block multiplicities. As Z̄_n=O_p(n⁻¹/²), b( N⁻¹Σ_j S_j/b )²=o_p(1) under b³/n→0. Hence Var_*(S_I)/b=A_n−b(N⁻¹Σ_jS_j/b)²→pΩ. Given the data, the k sampled block sums are IID, and |S_I−E_*S_I|≤2bB. Since kb∼n and b³/n→0, 2bB/√(kb)→0, so the conditional Lindeberg condition holds. The conditional triangular-array CLT yields √(kb)(Z̄*−E_*Z̄*)⇒_*N(0,Ω) in probability. Finally √n|E_*Z̄*−Z̄_n|≤C B b/√n→0, and kb/n→1; Slutsky transfers the conditional limit to centering at Z̄_n and scaling by √(kb). This proves the stated case only; no general mixing block-bootstrap theorem is asserted.`, String.raw`Trước hết, CLT hữu hạn-phụ-thuộc áp dụng cho biến dừng trung tâm m-phụ-thuộc có moment 2+δ hữu hạn và Ω>0; ở đây bị chặn nên mọi moment hữu hạn và α(h)=0 khi h>m, do đó thỏa giả thiết CLT đã nêu ở W76. Với tổng block S_j, E(S_j²/b)=Σ_{|h|<b}(1−|h|/b)γ(h)→Ω vì γ(h)=0 khi |h|>m. Đặt A_n=(Nb)⁻¹Σ_{j=1}^N S_j². Mỗi S_j² bị chặn bởi b²B² và chuỗi bình phương block là (b+m)-phụ thuộc. Đếm O(N(b+m)) cặp covariance khác không cho Var(A_n)≤C b³/n→0; do đó A_n→pΩ. Sai lệch trung bình block thực nghiệm thỏa |N⁻¹Σ_j S_j/b−Z̄_n|≤C B b/n do đếm O(b) quan sát biên có số lần xuất hiện không đều. Vì Z̄_n=O_p(n⁻¹/²), b( N⁻¹Σ_j S_j/b )²=o_p(1) theo b³/n→0. Vậy Var_*(S_I)/b=A_n−b(N⁻¹Σ_jS_j/b)²→pΩ. Có điều kiện theo dữ liệu, k tổng block lấy mẫu IID và |S_I−E_*S_I|≤2bB. Vì kb∼n và b³/n→0, 2bB/√(kb)→0, nên thỏa Lindeberg có điều kiện. CLT mảng tam giác có điều kiện cho √(kb)(Z̄*−E_*Z̄*)⇒_*N(0,Ω) theo xác suất. Cuối cùng √n|E_*Z̄*−Z̄_n|≤C B b/√n→0 và kb/n→1; Slutsky chuyển giới hạn có điều kiện sang tâm Z̄_n và hệ số √(kb). Đây chỉ chứng minh trường hợp đã nêu; không khẳng định định lý bootstrap block mixing tổng quát.`);
